CREATE TABLE farmers (farmer_id INT PRIMARY KEY, farmer_name VARCHAR(100));
CREATE TABLE fields (field_id INT PRIMARY KEY, farmer_id INT, area_ha DECIMAL(10,2));
CREATE TABLE crops (crop_id INT PRIMARY KEY, field_id INT, crop_name VARCHAR(100), season VARCHAR(20));
CREATE TABLE harvests (harvest_id INT PRIMARY KEY, crop_id INT, yield_tons DECIMAL(10,2), harvest_date DATE);
CREATE TABLE tractors (tractor_id INT PRIMARY KEY, farmer_id INT, model VARCHAR(80));
CREATE TABLE maintenance_logs (log_id INT PRIMARY KEY, tractor_id INT, mechanic_id INT, season VARCHAR(20), cost DECIMAL(10,2), service_date DATE);
CREATE TABLE mechanics (mechanic_id INT PRIMARY KEY, mechanic_name VARCHAR(100), shop_id INT);
CREATE TABLE repair_shops (shop_id INT PRIMARY KEY, shop_name VARCHAR(100), city VARCHAR(80));
CREATE TABLE fertilizers (fertilizer_id INT PRIMARY KEY, fertilizer_name VARCHAR(100), supplier_id INT);
CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(100));
CREATE TABLE applications (application_id INT PRIMARY KEY, fertilizer_id INT, field_id INT, season VARCHAR(20), amount_kg DECIMAL(10,2));
CREATE TABLE silos (silo_id INT PRIMARY KEY, silo_name VARCHAR(100), capacity_tons DECIMAL(10,2));
CREATE TABLE storage_logs (storage_id INT PRIMARY KEY, silo_id INT, crop_id INT, distributor_id INT, season VARCHAR(20), shipped_tons DECIMAL(10,2));
CREATE TABLE distributors (distributor_id INT PRIMARY KEY, distributor_name VARCHAR(100));
CREATE TABLE metric_farmer_yield (season VARCHAR(20), farmer_name VARCHAR(100), crop_count INT, total_yield DECIMAL(12,2));
CREATE TABLE metric_machinery_service (season VARCHAR(20), model VARCHAR(80), mechanic_name VARCHAR(100), shop_name VARCHAR(100), city VARCHAR(80), services INT, total_cost DECIMAL(12,2));
CREATE TABLE metric_chemical_usage (season VARCHAR(20), fertilizer_name VARCHAR(100), supplier_name VARCHAR(100), total_kg DECIMAL(12,2), kg_per_ha DECIMAL(12,4));
CREATE TABLE metric_outbound_shipment (season VARCHAR(20), silo_name VARCHAR(100), crop_name VARCHAR(100), distributor_name VARCHAR(100), shipments INT, shipped_tons DECIMAL(12,2));

DELIMITER $$

CREATE PROCEDURE evaluate(IN p_season VARCHAR(20))
BEGIN
    DECLARE v_completed INT DEFAULT 0;
    SELECT COUNT(*) INTO v_completed
    FROM crops AS c
    INNER JOIN harvests AS h ON h.crop_id = c.crop_id
    WHERE c.season = p_season;
    IF v_completed = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'season has no completed harvest records';
    END IF;

    DELETE FROM metric_farmer_yield WHERE season = p_season;
    DELETE FROM metric_machinery_service WHERE season = p_season;
    DELETE FROM metric_chemical_usage WHERE season = p_season;
    DELETE FROM metric_outbound_shipment WHERE season = p_season;

    INSERT INTO metric_farmer_yield (season, farmer_name, crop_count, total_yield)
    SELECT c.season, f.farmer_name, COUNT(DISTINCT c.crop_id), SUM(h.yield_tons)
    FROM crops AS c
    INNER JOIN fields AS fl ON fl.field_id = c.field_id
    INNER JOIN farmers AS f ON f.farmer_id = fl.farmer_id
    INNER JOIN harvests AS h ON h.crop_id = c.crop_id
    WHERE c.season = p_season
    GROUP BY c.season, f.farmer_name;

    INSERT INTO metric_machinery_service (season, model, mechanic_name, shop_name, city, services, total_cost)
    SELECT ml.season, t.model, m.mechanic_name, rs.shop_name, rs.city, COUNT(*), SUM(ml.cost)
    FROM maintenance_logs AS ml
    INNER JOIN tractors AS t ON t.tractor_id = ml.tractor_id
    INNER JOIN mechanics AS m ON m.mechanic_id = ml.mechanic_id
    INNER JOIN repair_shops AS rs ON rs.shop_id = m.shop_id
    WHERE ml.season = p_season
    GROUP BY ml.season, t.model, m.mechanic_name, rs.shop_name, rs.city;

    INSERT INTO metric_chemical_usage (season, fertilizer_name, supplier_name, total_kg, kg_per_ha)
    SELECT a.season, fz.fertilizer_name, s.supplier_name, SUM(a.amount_kg),
           SUM(a.amount_kg) / NULLIF(SUM(fl.area_ha), 0)
    FROM applications AS a
    INNER JOIN fertilizers AS fz ON fz.fertilizer_id = a.fertilizer_id
    INNER JOIN suppliers AS s ON s.supplier_id = fz.supplier_id
    INNER JOIN fields AS fl ON fl.field_id = a.field_id
    WHERE a.season = p_season
    GROUP BY a.season, fz.fertilizer_name, s.supplier_name;

    INSERT INTO metric_outbound_shipment (season, silo_name, crop_name, distributor_name, shipments, shipped_tons)
    SELECT sl.season, si.silo_name, c.crop_name, d.distributor_name, COUNT(*), SUM(sl.shipped_tons)
    FROM storage_logs AS sl
    INNER JOIN silos AS si ON si.silo_id = sl.silo_id
    INNER JOIN crops AS c ON c.crop_id = sl.crop_id
    INNER JOIN distributors AS d ON d.distributor_id = sl.distributor_id
    WHERE sl.season = p_season
    GROUP BY sl.season, si.silo_name, c.crop_name, d.distributor_name;
END$$

DELIMITER ;

CALL evaluate('autumn');

SELECT farmer_name, crop_count, total_yield
FROM metric_farmer_yield
WHERE season = 'autumn'
ORDER BY total_yield DESC;

SELECT model, mechanic_name, shop_name, city, services, total_cost
FROM metric_machinery_service
WHERE season = 'autumn'
ORDER BY total_cost DESC;

SELECT fertilizer_name, supplier_name, total_kg, kg_per_ha
FROM metric_chemical_usage
WHERE season = 'autumn'
ORDER BY kg_per_ha DESC;

SELECT silo_name, crop_name, distributor_name, shipments, shipped_tons
FROM metric_outbound_shipment
WHERE season = 'autumn'
ORDER BY shipped_tons DESC;

