CREATE TABLE officers (officer_id INT PRIMARY KEY, officer_name VARCHAR(60), badge VARCHAR(12), precinct INT, vehicle_id INT);
CREATE TABLE patrol_vehicles (vehicle_id INT PRIMARY KEY, unit_code VARCHAR(12), mileage INT);
CREATE TABLE suspects (suspect_id INT PRIMARY KEY, suspect_name VARCHAR(60), dob DATE);
CREATE TABLE incidents (incident_id INT PRIMARY KEY, officer_id INT, suspect_id INT, charge VARCHAR(80), occurred_at DATETIME);
CREATE TABLE detectives (detective_id INT PRIMARY KEY, detective_name VARCHAR(60), precinct INT, rank_title VARCHAR(30));
CREATE TABLE case_files (case_id INT PRIMARY KEY, detective_id INT, case_title VARCHAR(80), opened_on DATE, status VARCHAR(20));
CREATE TABLE evidence (evidence_id INT PRIMARY KEY, case_id INT, lab_id INT, item_desc VARCHAR(80), submitted_on DATE);
CREATE TABLE crime_labs (lab_id INT PRIMARY KEY, lab_name VARCHAR(60), backlog_days INT);
CREATE TABLE dispatch_calls (call_id INT PRIMARY KEY, officer_id INT, complainant_id INT, call_type VARCHAR(40), received_at DATETIME, arrived_at DATETIME);
CREATE TABLE shift_rosters (roster_id INT PRIMARY KEY, officer_id INT, shift_date DATE, shift_name VARCHAR(20));
CREATE TABLE complainants (complainant_id INT PRIMARY KEY, complainant_name VARCHAR(60), phone VARCHAR(20));
CREATE TABLE citations (citation_id INT PRIMARY KEY, driver_id INT, vehicle_id INT, magistrate_id INT, violation VARCHAR(60), fine DECIMAL(8,2), issued_on DATE);
CREATE TABLE drivers (driver_id INT PRIMARY KEY, driver_name VARCHAR(60), license_no VARCHAR(20), precinct INT);
CREATE TABLE registered_vehicles (vehicle_id INT PRIMARY KEY, plate VARCHAR(12), make VARCHAR(30));
CREATE TABLE magistrates (magistrate_id INT PRIMARY KEY, magistrate_name VARCHAR(60), courtroom VARCHAR(10));

CREATE TABLE arrest_log (precinct INT, officer_name VARCHAR(60), unit_code VARCHAR(12), suspect_name VARCHAR(60), charge VARCHAR(80), occurred_at DATETIME);
CREATE TABLE forensic_tracker (precinct INT, detective_name VARCHAR(60), case_title VARCHAR(80), item_desc VARCHAR(80), lab_name VARCHAR(60), backlog_days INT);
CREATE TABLE response_review (precinct INT, officer_name VARCHAR(60), shift_name VARCHAR(20), complainant_name VARCHAR(60), call_type VARCHAR(40), response_minutes INT);
CREATE TABLE court_docket (precinct INT, driver_name VARCHAR(60), plate VARCHAR(12), violation VARCHAR(60), fine DECIMAL(8,2), courtroom VARCHAR(10), magistrate_name VARCHAR(60));

DELIMITER //

CREATE PROCEDURE patrol_briefing(IN p_precinct INT)
BEGIN
    SELECT a.officer_name, COUNT(*) AS arrests, AVG(r.response_minutes) AS avg_response
    FROM arrest_log AS a
    JOIN response_review AS r ON r.officer_name = a.officer_name AND r.precinct = a.precinct
    WHERE a.precinct = p_precinct
    GROUP BY a.officer_name;

    SELECT l.lab_name, l.backlog_days, COUNT(*) AS pending_items
    FROM crime_labs AS l
    JOIN evidence AS e ON e.lab_id = l.lab_id
    JOIN case_files AS c ON c.case_id = e.case_id
    JOIN detectives AS d ON d.detective_id = c.detective_id
    WHERE d.precinct = p_precinct
      AND c.status = 'OPEN'
    GROUP BY l.lab_name, l.backlog_days;
END //

CREATE PROCEDURE patrol(IN p_precinct INT)
BEGIN
    INSERT INTO arrest_log (precinct, officer_name, unit_code, suspect_name, charge, occurred_at)
    SELECT o.precinct, o.officer_name, v.unit_code, s.suspect_name, i.charge, i.occurred_at
    FROM officers AS o
    JOIN incidents AS i ON i.officer_id = o.officer_id
    JOIN suspects AS s ON s.suspect_id = i.suspect_id
    JOIN patrol_vehicles AS v ON v.vehicle_id = o.vehicle_id
    WHERE o.precinct = p_precinct;

    INSERT INTO forensic_tracker (precinct, detective_name, case_title, item_desc, lab_name, backlog_days)
    SELECT d.precinct, d.detective_name, c.case_title, e.item_desc, l.lab_name, l.backlog_days
    FROM detectives AS d
    JOIN case_files AS c ON c.detective_id = d.detective_id
    JOIN evidence AS e ON e.case_id = c.case_id
    JOIN crime_labs AS l ON l.lab_id = e.lab_id
    WHERE d.precinct = p_precinct
      AND c.status = 'OPEN';

    INSERT INTO response_review (precinct, officer_name, shift_name, complainant_name, call_type, response_minutes)
    SELECT o.precinct, o.officer_name, r.shift_name, cp.complainant_name, dc.call_type,
           TIMESTAMPDIFF(MINUTE, dc.received_at, dc.arrived_at)
    FROM dispatch_calls AS dc
    JOIN officers AS o ON o.officer_id = dc.officer_id
    JOIN shift_rosters AS r ON r.officer_id = o.officer_id
    JOIN complainants AS cp ON cp.complainant_id = dc.complainant_id
    WHERE o.precinct = p_precinct
      AND r.shift_date = DATE(dc.received_at);

    INSERT INTO court_docket (precinct, driver_name, plate, violation, fine, courtroom, magistrate_name)
    SELECT dr.precinct, dr.driver_name, rv.plate, ct.violation, ct.fine, mg.courtroom, mg.magistrate_name
    FROM citations AS ct
    JOIN drivers AS dr ON dr.driver_id = ct.driver_id
    JOIN registered_vehicles AS rv ON rv.vehicle_id = ct.vehicle_id
    JOIN magistrates AS mg ON mg.magistrate_id = ct.magistrate_id
    WHERE dr.precinct = p_precinct
      AND ct.issued_on = CURRENT_DATE;
END //

DELIMITER ;

CALL patrol(9);
CALL patrol_briefing(9);

SELECT driver_name, violation, courtroom, magistrate_name FROM court_docket WHERE precinct = 9;

