DROP PROCEDURE IF EXISTS dispatch;
DROP FUNCTION IF EXISTS shift_is_scheduled;

CREATE TABLE IF NOT EXISTS shift_dropoff_log (shift_code VARCHAR(20), taxi_plate VARCHAR(20), driver_name VARCHAR(80), zone_name VARCHAR(80), fare_amount DECIMAL(10,2), dropoff_time DATETIME);
CREATE TABLE IF NOT EXISTS shift_service_log (shift_code VARCHAR(20), mechanic_name VARCHAR(80), garage_name VARCHAR(80), taxi_plate VARCHAR(20), part_name VARCHAR(80), part_cost DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS shift_radio_audit (shift_code VARCHAR(20), dispatcher_name VARCHAR(80), driver_name VARCHAR(80), manager_name VARCHAR(80), call_time DATETIME, acknowledged TINYINT);
CREATE TABLE IF NOT EXISTS shift_satisfaction (shift_code VARCHAR(20), driver_name VARCHAR(80), agent_name VARCHAR(80), trips_rated INT, avg_score DECIMAL(5,2));

DELIMITER $$

CREATE FUNCTION shift_is_scheduled(shift VARCHAR(20)) RETURNS TINYINT
READS SQL DATA
BEGIN
    DECLARE scheduled TINYINT;
    SELECT COUNT(*) > 0 INTO scheduled
    FROM shifts AS sh, depots AS dp
    WHERE dp.depot_id = sh.depot_id AND sh.shift_code = shift;
    RETURN scheduled;
END$$

CREATE PROCEDURE dispatch(IN shift VARCHAR(20))
BEGIN
    IF shift_is_scheduled(shift) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'unknown shift code';
    END IF;

    DELETE FROM shift_dropoff_log  WHERE shift_code = shift;
    DELETE FROM shift_service_log  WHERE shift_code = shift;
    DELETE FROM shift_radio_audit  WHERE shift_code = shift;
    DELETE FROM shift_satisfaction WHERE shift_code = shift;

    INSERT INTO shift_dropoff_log (shift_code, taxi_plate, driver_name, zone_name, fare_amount, dropoff_time)
    SELECT shift, tx.plate, dr.full_name, zn.zone_name, ft.fare_amount, ft.dropoff_time
    FROM fare_trips AS ft, taxis AS tx, drivers AS dr, city_zones AS zn
    WHERE tx.taxi_id = ft.taxi_id AND dr.driver_id = ft.driver_id AND zn.zone_id = ft.dropoff_zone_id AND ft.shift_code = shift AND ft.status = 'completed';

    INSERT INTO shift_service_log (shift_code, mechanic_name, garage_name, taxi_plate, part_name, part_cost)
    SELECT shift, mc.full_name, gr.garage_name, tx.plate, pt.part_name, pt.unit_cost
    FROM service_jobs AS sj, mechanics AS mc, garages AS gr, taxis AS tx, replacement_parts AS pt
    WHERE mc.mechanic_id = sj.mechanic_id AND gr.garage_id = mc.garage_id AND tx.taxi_id = sj.taxi_id AND pt.part_id = sj.part_id AND sj.shift_code = shift;

    INSERT INTO shift_radio_audit (shift_code, dispatcher_name, driver_name, manager_name, call_time, acknowledged)
    SELECT shift, ds.full_name, dr.full_name, fm.full_name, rc.call_time, rc.acknowledged
    FROM radio_calls AS rc, dispatchers AS ds, drivers AS dr, fleet_managers AS fm
    WHERE ds.dispatcher_id = rc.dispatcher_id AND dr.driver_id = rc.driver_id AND fm.manager_id = dr.manager_id AND rc.shift_code = shift;

    INSERT INTO shift_satisfaction (shift_code, driver_name, agent_name, trips_rated, avg_score)
    SELECT shift, dr.full_name, ag.full_name, COUNT(*), AVG(pr.score)
    FROM passenger_ratings AS pr, fare_trips AS ft, drivers AS dr, service_agents AS ag
    WHERE ft.trip_id = pr.trip_id AND dr.driver_id = ft.driver_id AND ag.agent_id = pr.handled_by_agent_id AND ft.shift_code = shift
    GROUP BY dr.full_name, ag.full_name;

    SELECT dl.driver_name, COUNT(*) AS dropoffs, SUM(dl.fare_amount) AS fares, MAX(st.avg_score) AS score
    FROM shift_dropoff_log AS dl, shift_satisfaction AS st
    WHERE st.shift_code = dl.shift_code AND st.driver_name = dl.driver_name AND dl.shift_code = shift
    GROUP BY dl.driver_name;
END$$

DELIMITER ;

CALL dispatch('morning');

