    WHERE p.milestone = milestone AND sv.environment = 'production';

    INSERT INTO QM_Scorecard (project_name, resolved_defects, enhancements, rollouts)
    SELECT b.project_name, b.total, e.total, r.total
    FROM (SELECT project_name, COUNT(*) AS total FROM QM_ResolvedDefects GROUP BY project_name) AS b
    INNER JOIN (SELECT project_name, COUNT(*) AS total FROM QM_Enhancements GROUP BY project_name) AS e
        ON e.project_name = b.project_name
