CREATE TABLE Bands (band_id INT PRIMARY KEY, band_name VARCHAR(60), genre VARCHAR(30));
CREATE TABLE StageManagers (manager_id INT PRIMARY KEY, full_name VARCHAR(60), radio_channel VARCHAR(10));
CREATE TABLE Stages (stage_id INT PRIMARY KEY, stage_name VARCHAR(40), manager_id INT);
CREATE TABLE Setlists (setlist_id INT PRIMARY KEY, band_id INT, stage_id INT, perform_date DATE, start_time TIME, duration_min INT);
CREATE TABLE AudioTechnicians (tech_id INT PRIMARY KEY, tech_name VARCHAR(60), console VARCHAR(30));
CREATE TABLE EquipmentRentals (rental_id INT PRIMARY KEY, item_name VARCHAR(50), supplier VARCHAR(50));
CREATE TABLE SoundChecks (check_id INT PRIMARY KEY, tech_id INT, band_id INT, rental_id INT, check_date DATE, check_time TIME);
CREATE TABLE SafetyOfficers (officer_id INT PRIMARY KEY, officer_name VARCHAR(60), certificate VARCHAR(20));
CREATE TABLE FestivalZones (zone_id INT PRIMARY KEY, zone_name VARCHAR(40), officer_id INT, capacity INT);
CREATE TABLE FoodVendors (vendor_id INT PRIMARY KEY, vendor_name VARCHAR(60), zone_id INT, cuisine VARCHAR(30));
CREATE TABLE HealthInspections (inspection_id INT PRIMARY KEY, vendor_id INT, inspect_date DATE, result VARCHAR(10), score INT);
CREATE TABLE CrowdControllers (controller_id INT PRIMARY KEY, controller_name VARCHAR(60), sector VARCHAR(20));
CREATE TABLE SecurityGuards (guard_id INT PRIMARY KEY, guard_name VARCHAR(60), zone_id INT, shift VARCHAR(10));
CREATE TABLE IncidentLogs (log_id INT PRIMARY KEY, guard_id INT, controller_id INT, log_date DATE, severity VARCHAR(10), note VARCHAR(120));

DELIMITER $$
CREATE FUNCTION concert_program_size(day DATE) RETURNS INT READS SQL DATA
BEGIN
    DECLARE slots INT;
    SELECT COUNT(*) INTO slots
    FROM Setlists AS SL
    INNER JOIN Stages AS ST ON ST.stage_id = SL.stage_id
    INNER JOIN StageManagers AS SM ON SM.manager_id = ST.manager_id
    WHERE SL.perform_date = day;
    RETURN slots;
END$$

CREATE FUNCTION zone_cleared_stalls(day DATE, zone INT) RETURNS INT READS SQL DATA
BEGIN
    DECLARE stalls INT;
    SELECT COUNT(*) INTO stalls
    FROM HealthInspections AS HI
    INNER JOIN FoodVendors AS FV ON FV.vendor_id = HI.vendor_id
    WHERE HI.inspect_date = day AND HI.result = 'PASSED' AND FV.zone_id = zone;
    RETURN stalls;
END$$

CREATE PROCEDURE concert(IN day DATE)
BEGIN
    IF concert_program_size(day) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No staffed performances scheduled for this day';
    END IF;
    SELECT SL.start_time, SL.duration_min, B.band_name, B.genre,
           ST.stage_name, SM.full_name AS stage_manager, SM.radio_channel
    FROM Setlists AS SL
    INNER JOIN Bands AS B ON B.band_id = SL.band_id
    INNER JOIN Stages AS ST ON ST.stage_id = SL.stage_id
    INNER JOIN StageManagers AS SM ON SM.manager_id = ST.manager_id
    WHERE SL.perform_date = day
    ORDER BY SL.start_time, ST.stage_name;
    SELECT SC.check_time, AT.tech_name, AT.console,
           B.band_name, ER.item_name, ER.supplier
    FROM SoundChecks AS SC
    INNER JOIN AudioTechnicians AS AT ON AT.tech_id = SC.tech_id
    INNER JOIN Bands AS B ON B.band_id = SC.band_id
    INNER JOIN EquipmentRentals AS ER ON ER.rental_id = SC.rental_id
    WHERE SC.check_date = day
    ORDER BY SC.check_time, AT.tech_name;
    SELECT FV.vendor_name, FV.cuisine, FZ.zone_name,
           SO.officer_name AS safety_officer, HI.score
    FROM HealthInspections AS HI
    INNER JOIN FoodVendors AS FV ON FV.vendor_id = HI.vendor_id
    INNER JOIN FestivalZones AS FZ ON FZ.zone_id = FV.zone_id
    INNER JOIN SafetyOfficers AS SO ON SO.officer_id = FZ.officer_id
    WHERE HI.inspect_date = day AND HI.result = 'PASSED'
    ORDER BY FZ.zone_name, FV.vendor_name;
    SELECT FZ.zone_name, FZ.capacity, SG.guard_name, SG.shift,
           CC.controller_name, CC.sector, COUNT(*) AS incident_count,
           MAX(IL.severity) AS worst_severity,
           zone_cleared_stalls(day, FZ.zone_id) AS cleared_stalls
    FROM IncidentLogs AS IL
    INNER JOIN SecurityGuards AS SG ON SG.guard_id = IL.guard_id
    INNER JOIN FestivalZones AS FZ ON FZ.zone_id = SG.zone_id
    INNER JOIN CrowdControllers AS CC ON CC.controller_id = IL.controller_id
    WHERE IL.log_date = day
    GROUP BY FZ.zone_id, FZ.zone_name, FZ.capacity, SG.guard_name, SG.shift, CC.controller_name, CC.sector
    ORDER BY incident_count DESC, FZ.zone_name;
END$$
DELIMITER ;

