CREATE TABLE stations (station_id INT PRIMARY KEY, station_name TEXT NOT NULL);
CREATE TABLE mentors (mentor_id INT PRIMARY KEY, mentor_name TEXT NOT NULL);
CREATE TABLE chefs (chef_id INT PRIMARY KEY, chef_name TEXT NOT NULL, station_id INT, mentor_id INT);
CREATE TABLE dishes (dish_id INT PRIMARY KEY, chef_id INT, dish_name TEXT NOT NULL, episode INT NOT NULL);
CREATE TABLE critics (critic_id INT PRIMARY KEY, outlet TEXT NOT NULL);
CREATE TABLE judges (judge_id INT PRIMARY KEY, judge_name TEXT NOT NULL, critic_id INT);
CREATE TABLE scorecards (card_id INT PRIMARY KEY, judge_id INT, dish_id INT, flavor_score NUMERIC(4,1));
CREATE TABLE inventory_managers (manager_id INT PRIMARY KEY, manager_name TEXT NOT NULL);
CREATE TABLE ingredients (ingredient_id INT PRIMARY KEY, ingredient_name TEXT NOT NULL, is_exotic BOOLEAN NOT NULL, manager_id INT);
CREATE TABLE checkout_logs (log_id INT PRIMARY KEY, ingredient_id INT, chef_id INT, quantity NUMERIC(8,2), episode INT NOT NULL);
CREATE TABLE directors (director_id INT PRIMARY KEY, director_name TEXT NOT NULL);
CREATE TABLE camera_operators (operator_id INT PRIMARY KEY, operator_name TEXT NOT NULL, director_id INT);
CREATE TABLE segments (segment_id INT PRIMARY KEY, operator_id INT, station_id INT, episode INT NOT NULL, duration_min INT);

CREATE TABLE final_plates (episode INT, dish_id INT, dish_name TEXT, chef_name TEXT, station_name TEXT, mentor_name TEXT);
CREATE TABLE flavor_ratings (episode INT, dish_id INT, dish_name TEXT, judge_name TEXT, outlet TEXT, avg_flavor NUMERIC(5,2));
CREATE TABLE exotic_supply_audit (episode INT, ingredient_name TEXT, chef_name TEXT, manager_name TEXT, total_quantity NUMERIC(10,2));
CREATE TABLE broadcast_footage (episode INT, segment_id INT, operator_name TEXT, station_name TEXT, director_name TEXT, duration_min INT);
CREATE TABLE chef_leaderboard (episode INT, chef_name TEXT, station_name TEXT, plates INT, avg_flavor NUMERIC(5,2));

CREATE VIEW exotic_checkouts AS
SELECT l.episode, l.chef_id, l.quantity, i.ingredient_name, i.manager_id
FROM checkout_logs AS l
JOIN ingredients AS i ON l.ingredient_id = i.ingredient_id
WHERE i.is_exotic;

CREATE PROCEDURE score(episode INT)
LANGUAGE SQL
AS $$
    DELETE FROM final_plates WHERE final_plates.episode = $1;
    DELETE FROM flavor_ratings WHERE flavor_ratings.episode = $1;
    DELETE FROM exotic_supply_audit WHERE exotic_supply_audit.episode = $1;
    DELETE FROM broadcast_footage WHERE broadcast_footage.episode = $1;

    INSERT INTO final_plates (episode, dish_id, dish_name, chef_name, station_name, mentor_name)
    SELECT d.episode, d.dish_id, d.dish_name, c.chef_name, st.station_name, m.mentor_name
    FROM dishes AS d
    JOIN chefs AS c ON d.chef_id = c.chef_id
    JOIN stations AS st ON c.station_id = st.station_id
    JOIN mentors AS m ON c.mentor_id = m.mentor_id
    WHERE d.episode = $1;

    INSERT INTO flavor_ratings (episode, dish_id, dish_name, judge_name, outlet, avg_flavor)
    SELECT d.episode, d.dish_id, d.dish_name, j.judge_name, cr.outlet, AVG(sc.flavor_score)
    FROM scorecards AS sc
    JOIN dishes AS d ON sc.dish_id = d.dish_id
    JOIN judges AS j ON sc.judge_id = j.judge_id
    JOIN critics AS cr ON j.critic_id = cr.critic_id
    WHERE d.episode = $1
    GROUP BY d.episode, d.dish_id, d.dish_name, j.judge_name, cr.outlet;

    INSERT INTO exotic_supply_audit (episode, ingredient_name, chef_name, manager_name, total_quantity)
    SELECT ec.episode, ec.ingredient_name, c.chef_name, im.manager_name, SUM(ec.quantity)
    FROM exotic_checkouts AS ec
    JOIN chefs AS c ON ec.chef_id = c.chef_id
    JOIN inventory_managers AS im ON ec.manager_id = im.manager_id
    WHERE ec.episode = $1
    GROUP BY ec.episode, ec.ingredient_name, c.chef_name, im.manager_name;

    INSERT INTO broadcast_footage (episode, segment_id, operator_name, station_name, director_name, duration_min)
    SELECT s.episode, s.segment_id, o.operator_name, st.station_name, dr.director_name, s.duration_min
    FROM segments AS s
    JOIN camera_operators AS o ON s.operator_id = o.operator_id
    JOIN stations AS st ON s.station_id = st.station_id
    JOIN directors AS dr ON o.director_id = dr.director_id
    WHERE s.episode = $1
    ORDER BY s.segment_id;
$$;

CREATE PROCEDURE rank_chefs(episode INT)
LANGUAGE SQL
AS $$
    DELETE FROM chef_leaderboard WHERE chef_leaderboard.episode = $1;

    INSERT INTO chef_leaderboard (episode, chef_name, station_name, plates, avg_flavor)
    SELECT fp.episode, fp.chef_name, fp.station_name, COUNT(DISTINCT fp.dish_id), AVG(fr.avg_flavor)
    FROM final_plates AS fp
    JOIN flavor_ratings AS fr ON fp.dish_id = fr.dish_id
    WHERE fp.episode = $1
    GROUP BY fp.episode, fp.chef_name, fp.station_name;
$$;

CALL score(5);
