CREATE PROCEDURE score(episode INT)
LANGUAGE SQL
AS $$
    DELETE FROM final_plates WHERE final_plates.episode = $1;
    DELETE FROM flavor_ratings WHERE flavor_ratings.episode = $1;
    DELETE FROM exotic_supply_audit WHERE exotic_supply_audit.episode = $1;
    DELETE FROM broadcast_footage WHERE broadcast_footage.episode = $1;

    INSERT INTO final_plates (episode, dish_id, dish_name, chef_name, station_name, mentor_name)
    SELECT d.episode, d.dish_id, d.dish_name, c.chef_name, st.station_name, m.mentor_name
    FROM dishes AS d, chefs AS c, stations AS st, mentors AS m
    WHERE d.chef_id = c.chef_id
    AND c.station_id = st.station_id
    AND c.mentor_id = m.mentor_id
    AND d.episode = $1;

    INSERT INTO flavor_ratings (episode, dish_id, dish_name, judge_name, outlet, avg_flavor)
    SELECT d.episode, d.dish_id, d.dish_name, j.judge_name, cr.outlet, AVG(sc.flavor_score)
    FROM scorecards AS sc, dishes AS d, judges AS j, critics AS cr
    WHERE sc.dish_id = d.dish_id
    AND sc.judge_id = j.judge_id
    AND j.critic_id = cr.critic_id
    AND d.episode = $1
    GROUP BY d.episode, d.dish_id, d.dish_name, j.judge_name, cr.outlet;

    INSERT INTO exotic_supply_audit (episode, ingredient_name, chef_name, manager_name, total_quantity)
    SELECT ec.episode, ec.ingredient_name, c.chef_name, im.manager_name, SUM(ec.quantity)
    FROM exotic_checkouts AS ec, chefs AS c, inventory_managers AS im
    WHERE ec.chef_id = c.chef_id
    AND ec.manager_id = im.manager_id
    AND ec.episode = $1
    GROUP BY ec.episode, ec.ingredient_name, c.chef_name, im.manager_name;

    INSERT INTO broadcast_footage (episode, segment_id, operator_name, station_name, director_name, duration_min)
    SELECT s.episode, s.segment_id, o.operator_name, st.station_name, dr.director_name, s.duration_min
    FROM segments AS s, camera_operators AS o, stations AS st, directors AS dr
    WHERE s.operator_id = o.operator_id
    AND s.station_id = st.station_id
    AND o.director_id = dr.director_id
    AND s.episode = $1
    ORDER BY s.segment_id;
$$;

