CREATE TABLE Leases (
    lease_id INTEGER PRIMARY KEY, suite_id INTEGER NOT NULL, tenant_id INTEGER NOT NULL,
    agent_id INTEGER, lease_term VARCHAR(40) NOT NULL, annual_rent DECIMAL(12,2) NOT NULL,
    status VARCHAR(20) NOT NULL
);
CREATE TABLE Contractors (
    contractor_id INTEGER PRIMARY KEY, company_name VARCHAR(120) NOT NULL, trade VARCHAR(40) NOT NULL
);
CREATE TABLE ServiceRequests (
    request_id INTEGER PRIMARY KEY, suite_id INTEGER NOT NULL, contractor_id INTEGER,
    reported_on DATE NOT NULL, description VARCHAR(200) NOT NULL, priority VARCHAR(16) NOT NULL
);

CREATE VIEW ActiveLeaseOverview AS
SELECT L.lease_id, L.lease_term, S.suite_number, B.address, T.company_name, L.annual_rent
FROM Leases AS L
JOIN Suites AS S ON L.suite_id = S.suite_id
JOIN Buildings AS B ON S.building_id = B.building_id
JOIN Tenants AS T ON L.tenant_id = T.tenant_id
WHERE L.status = 'ACTIVE';

CREATE VIEW ManagementAssignments AS
SELECT R.request_id, R.reported_on, R.description, R.priority, S.suite_number,
       PM.manager_name, PM.office_phone, C.company_name AS contractor, C.trade
FROM ServiceRequests AS R
JOIN Suites AS S ON R.suite_id = S.suite_id
JOIN PropertyManagers AS PM ON S.manager_id = PM.manager_id
JOIN Contractors AS C ON R.contractor_id = C.contractor_id;

CREATE VIEW BrokerageCommissions AS
SELECT L.lease_id, AG.agency_name, A.agent_name, A.license_no, RG.region_name, RG.market_tier,
       ROUND(L.annual_rent * AG.commission_pct / 100, 2) AS commission_due
FROM Leases AS L
JOIN Agents AS A ON L.agent_id = A.agent_id
JOIN Agencies AS AG ON A.agency_id = AG.agency_id
JOIN Suites AS S ON L.suite_id = S.suite_id
JOIN Buildings AS B ON S.building_id = B.building_id
JOIN Regions AS RG ON B.region_id = RG.region_id
WHERE L.status = 'FINALIZED';

SELECT T.company_name, COUNT(*) AS lease_count, SUM(L.annual_rent) AS billed_rent
FROM Tenants AS T
JOIN Leases AS L ON T.tenant_id = L.tenant_id
WHERE L.status IN ('ACTIVE', 'FINALIZED')
GROUP BY T.company_name
ORDER BY billed_rent DESC;

SELECT RG.region_name, B.address, S.suite_number, S.floor_area
FROM Suites AS S
JOIN Buildings AS B ON S.building_id = B.building_id
JOIN Regions AS RG ON B.region_id = RG.region_id
WHERE S.suite_id NOT IN (SELECT suite_id FROM Leases WHERE status = 'ACTIVE')
ORDER BY RG.region_name, B.address;

SELECT PM.manager_name, COUNT(R.request_id) AS open_requests
FROM PropertyManagers AS PM
JOIN Suites AS S ON PM.manager_id = S.manager_id
JOIN ServiceRequests AS R ON S.suite_id = R.suite_id
GROUP BY PM.manager_name
ORDER BY open_requests DESC;

SELECT lease_term, suite_number, address, company_name
FROM ActiveLeaseOverview
ORDER BY address, suite_number;

SELECT manager_name, suite_number, description, contractor, trade
FROM ManagementAssignments
WHERE priority = 'HIGH'
ORDER BY manager_name, reported_on;

SELECT region_name, agency_name, SUM(commission_due) AS total_commission
FROM BrokerageCommissions
GROUP BY region_name, agency_name
ORDER BY total_commission DESC;

