CREATE TABLE Species (species_id INTEGER PRIMARY KEY, scientific_name VARCHAR(120) NOT NULL, family VARCHAR(60));
CREATE TABLE Botanists (botanist_id INTEGER PRIMARY KEY, botanist_name VARCHAR(80) NOT NULL, specialty VARCHAR(60));
CREATE TABLE Zones (zone_id INTEGER PRIMARY KEY, zone_name VARCHAR(60) NOT NULL, climate VARCHAR(40) NOT NULL, botanist_id INTEGER REFERENCES Botanists(botanist_id));
CREATE TABLE Specimens (specimen_id INTEGER PRIMARY KEY, species_id INTEGER REFERENCES Species(species_id), zone_id INTEGER REFERENCES Zones(zone_id), age_years INTEGER, accession_date DATE);
CREATE TABLE Suppliers (supplier_id INTEGER PRIMARY KEY, supplier_name VARCHAR(80) NOT NULL, country VARCHAR(60));
CREATE TABLE QuarantineFacilities (facility_id INTEGER PRIMARY KEY, facility_name VARCHAR(80) NOT NULL, capacity INTEGER);
CREATE TABLE ImportPermits (permit_id INTEGER PRIMARY KEY, permit_code VARCHAR(40) NOT NULL, issue_date DATE, expiry_date DATE);
CREATE TABLE Acquisitions (acquisition_id INTEGER PRIMARY KEY, specimen_id INTEGER REFERENCES Specimens(specimen_id), supplier_id INTEGER REFERENCES Suppliers(supplier_id), facility_id INTEGER REFERENCES QuarantineFacilities(facility_id), permit_id INTEGER REFERENCES ImportPermits(permit_id), released_on DATE);
CREATE TABLE SoilTreatments (treatment_id INTEGER PRIMARY KEY, treatment_name VARCHAR(80) NOT NULL, ph_target DECIMAL(3,1));
CREATE TABLE MaintenanceStaff (staff_id INTEGER PRIMARY KEY, staff_name VARCHAR(80) NOT NULL, shift VARCHAR(20));
CREATE TABLE SoilTreatmentLogs (log_id INTEGER PRIMARY KEY, zone_id INTEGER REFERENCES Zones(zone_id), treatment_id INTEGER REFERENCES SoilTreatments(treatment_id), staff_id INTEGER REFERENCES MaintenanceStaff(staff_id), applied_on DATE, volume_litres DECIMAL(8,2));

CREATE VIEW CurrentCollection AS
SELECT sp.specimen_id, sp.age_years, s.scientific_name, s.family, z.zone_name, z.climate, b.botanist_name
FROM Specimens AS sp
INNER JOIN Species AS s ON sp.species_id = s.species_id
INNER JOIN Zones AS z ON sp.zone_id = z.zone_id
INNER JOIN Botanists AS b ON z.botanist_id = b.botanist_id;

CREATE VIEW AcquisitionHistory AS
SELECT a.acquisition_id, a.released_on, sp.specimen_id, sp.accession_date, sup.supplier_name, sup.country,
       qf.facility_name, qf.capacity, ip.permit_code, ip.issue_date, ip.expiry_date
FROM Acquisitions AS a
INNER JOIN Specimens AS sp ON a.specimen_id = sp.specimen_id
INNER JOIN Suppliers AS sup ON a.supplier_id = sup.supplier_id
INNER JOIN QuarantineFacilities AS qf ON a.facility_id = qf.facility_id
INNER JOIN ImportPermits AS ip ON a.permit_id = ip.permit_id;

CREATE VIEW CareLogs AS
SELECT l.log_id, l.applied_on, l.volume_litres, z.zone_name, z.climate, t.treatment_name, t.ph_target,
       ms.staff_name, ms.shift
FROM SoilTreatmentLogs AS l
INNER JOIN Zones AS z ON l.zone_id = z.zone_id
INNER JOIN SoilTreatments AS t ON l.treatment_id = t.treatment_id
INNER JOIN MaintenanceStaff AS ms ON l.staff_id = ms.staff_id;

SELECT c.specimen_id, c.scientific_name, c.botanist_name, a.supplier_name, a.country, a.permit_code, a.expiry_date
FROM CurrentCollection AS c
INNER JOIN AcquisitionHistory AS a ON c.specimen_id = a.specimen_id
WHERE a.expiry_date < DATE '2027-01-01'
ORDER BY a.expiry_date, c.scientific_name;

SELECT b.botanist_name, b.specialty, z.zone_name, z.climate, COUNT(sp.specimen_id) AS specimen_count,
       AVG(sp.age_years) AS mean_age_years
FROM Botanists AS b
INNER JOIN Zones AS z ON b.botanist_id = z.botanist_id
INNER JOIN Specimens AS sp ON z.zone_id = sp.zone_id
GROUP BY b.botanist_name, b.specialty, z.zone_name, z.climate
ORDER BY specimen_count DESC, b.botanist_name;

SELECT ms.staff_name, ms.shift, t.treatment_name, t.ph_target, SUM(l.volume_litres) AS litres_applied,
       MAX(l.applied_on) AS last_applied
FROM MaintenanceStaff AS ms
INNER JOIN SoilTreatmentLogs AS l ON ms.staff_id = l.staff_id
INNER JOIN SoilTreatments AS t ON l.treatment_id = t.treatment_id
GROUP BY ms.staff_name, ms.shift, t.treatment_name, t.ph_target
ORDER BY last_applied DESC;

