    ledger_id INTEGER REFERENCES PointsLedgers(ledger_id),
    redemption_date DATE NOT NULL, point_cost INTEGER NOT NULL);

CREATE VIEW ActiveLongSessions AS
SELECT T.table_number, G.game_name, P.publisher_name
FROM GameSessions AS S
INNER JOIN CafeTables AS T ON S.table_id = T.table_id
INNER JOIN GameTitles AS G ON S.game_id = G.game_id
INNER JOIN Publishers AS P ON G.publisher_id = P.publisher_id
WHERE S.status = 'active' AND S.duration_minutes > 60;

CREATE VIEW PreparedSnackOrders AS
SELECT C.tab_date, M.item_name, K.station_code
FROM OrderItems AS O
INNER JOIN CustomerTabs AS C ON O.tab_id = C.tab_id
INNER JOIN MenuItems AS M ON O.menu_item_id = M.menu_item_id
INNER JOIN KitchenStations AS K ON M.station_id = K.station_id
WHERE O.prep_state = 'prepared' AND M.category = 'snack';

CREATE VIEW LoyaltyRewardRedemptions AS
SELECT A.patron_name, W.tier_name, R.redemption_date
FROM Redemptions AS R
INNER JOIN PointsLedgers AS L ON R.ledger_id = L.ledger_id
INNER JOIN PatronAccounts AS A ON L.patron_id = A.patron_id
INNER JOIN RewardTiers AS W ON L.tier_id = W.tier_id
WHERE R.point_cost > 50;

CREATE VIEW SnackStationLoad AS
SELECT K.station_code, COUNT(*) AS prepared_items
FROM KitchenStations AS K
INNER JOIN MenuItems AS M ON K.station_id = M.station_id
INNER JOIN OrderItems AS O ON M.menu_item_id = O.menu_item_id
WHERE M.category = 'snack' AND O.prep_state = 'prepared'
GROUP BY K.station_code;

CREATE VIEW PublisherPlayTime AS
SELECT P.publisher_name, SUM(S.duration_minutes) AS minutes_played
FROM Publishers AS P
INNER JOIN GameTitles AS G ON P.publisher_id = G.publisher_id
INNER JOIN GameSessions AS S ON G.game_id = S.game_id
WHERE S.status = 'active'
GROUP BY P.publisher_name;

