CREATE TABLE Publishers (publisher_id INTEGER PRIMARY KEY, publisher_name VARCHAR(80) NOT NULL);

CREATE TABLE GameTitles (game_id INTEGER PRIMARY KEY, game_name VARCHAR(80) NOT NULL,
    publisher_id INTEGER REFERENCES Publishers(publisher_id));

CREATE TABLE CafeTables (table_id INTEGER PRIMARY KEY, table_number INTEGER NOT NULL);

CREATE TABLE GameSessions (session_id INTEGER PRIMARY KEY,
    table_id INTEGER REFERENCES CafeTables(table_id),
    game_id INTEGER REFERENCES GameTitles(game_id),
    status VARCHAR(20) NOT NULL, duration_minutes INTEGER NOT NULL);

CREATE TABLE KitchenStations (station_id INTEGER PRIMARY KEY, station_code VARCHAR(20) NOT NULL);

CREATE TABLE MenuItems (menu_item_id INTEGER PRIMARY KEY, item_name VARCHAR(80) NOT NULL,
    category VARCHAR(30) NOT NULL, station_id INTEGER REFERENCES KitchenStations(station_id));

CREATE TABLE CustomerTabs (tab_id INTEGER PRIMARY KEY, tab_date DATE NOT NULL);

CREATE TABLE OrderItems (order_item_id INTEGER PRIMARY KEY,
    tab_id INTEGER REFERENCES CustomerTabs(tab_id),
    menu_item_id INTEGER REFERENCES MenuItems(menu_item_id), prep_state VARCHAR(20) NOT NULL);

CREATE TABLE PatronAccounts (patron_id INTEGER PRIMARY KEY, patron_name VARCHAR(80) NOT NULL);

CREATE TABLE RewardTiers (tier_id INTEGER PRIMARY KEY, tier_name VARCHAR(40) NOT NULL);

CREATE TABLE PointsLedgers (ledger_id INTEGER PRIMARY KEY,
    patron_id INTEGER REFERENCES PatronAccounts(patron_id),
    tier_id INTEGER REFERENCES RewardTiers(tier_id), balance_points INTEGER NOT NULL);

CREATE TABLE Redemptions (redemption_id INTEGER PRIMARY KEY,
    ledger_id INTEGER REFERENCES PointsLedgers(ledger_id),
    redemption_date DATE NOT NULL, point_cost INTEGER NOT NULL);

CREATE VIEW ActiveLongSessions AS
SELECT T.table_number, G.game_name, P.publisher_name
FROM GameSessions AS S, CafeTables AS T, GameTitles AS G, Publishers AS P
WHERE S.table_id = T.table_id AND S.game_id = G.game_id AND G.publisher_id = P.publisher_id AND S.status = 'active' AND S.duration_minutes > 60;

CREATE VIEW PreparedSnackOrders AS
SELECT C.tab_date, M.item_name, K.station_code
FROM OrderItems AS O, CustomerTabs AS C, MenuItems AS M, KitchenStations AS K
WHERE O.tab_id = C.tab_id AND O.menu_item_id = M.menu_item_id AND M.station_id = K.station_id AND O.prep_state = 'prepared' AND M.category = 'snack';

CREATE VIEW LoyaltyRewardRedemptions AS
SELECT A.patron_name, W.tier_name, R.redemption_date
FROM Redemptions AS R, PointsLedgers AS L, PatronAccounts AS A, RewardTiers AS W
WHERE R.ledger_id = L.ledger_id AND L.patron_id = A.patron_id AND L.tier_id = W.tier_id AND R.point_cost > 50;

CREATE VIEW SnackStationLoad AS
SELECT K.station_code, COUNT(*) AS prepared_items
FROM KitchenStations AS K, MenuItems AS M, OrderItems AS O
WHERE K.station_id = M.station_id AND M.menu_item_id = O.menu_item_id AND M.category = 'snack' AND O.prep_state = 'prepared'
GROUP BY K.station_code;

CREATE VIEW PublisherPlayTime AS
SELECT P.publisher_name, SUM(S.duration_minutes) AS minutes_played
FROM Publishers AS P, GameTitles AS G, GameSessions AS S
WHERE P.publisher_id = G.publisher_id AND G.game_id = S.game_id AND S.status = 'active'
GROUP BY P.publisher_name;

