CREATE TABLE Pets (
    pet_id        INTEGER PRIMARY KEY,
    pet_name      TEXT    NOT NULL,
    diet_plan_id  INTEGER NOT NULL
);
CREATE TABLE DietPlans (
    diet_plan_id  INTEGER PRIMARY KEY,
    diet_type     TEXT    NOT NULL
);
CREATE TABLE Stays (
    stay_id     INTEGER PRIMARY KEY,
    pet_id      INTEGER NOT NULL,
    start_date  DATE    NOT NULL
);
CREATE TABLE FeedingLogs (
    log_id        INTEGER PRIMARY KEY,
    stay_id       INTEGER NOT NULL,
    diet_plan_id  INTEGER NOT NULL,
    feeding_time  TIME
);

CREATE VIEW PetDietProfile AS
SELECT P.pet_id, P.pet_name, D.diet_plan_id, D.diet_type
FROM Pets AS P
JOIN DietPlans AS D ON D.diet_plan_id = P.diet_plan_id;

CREATE VIEW DailyCareRoutine AS
SELECT G.pet_name, S.start_date, F.feeding_time
FROM PetDietProfile AS G
JOIN Stays AS S ON S.pet_id = G.pet_id
JOIN FeedingLogs AS F ON F.stay_id = S.stay_id AND F.diet_plan_id = G.diet_plan_id
WHERE G.diet_type = 'hypoallergenic'
  AND F.feeding_time IS NOT NULL;

CREATE TABLE Veterinarians (
    vet_id    INTEGER PRIMARY KEY,
    vet_name  TEXT    NOT NULL
);
CREATE TABLE Medications (
    medication_id    INTEGER PRIMARY KEY,
    medication_name  TEXT    NOT NULL,
    vet_id           INTEGER NOT NULL
);
CREATE TABLE Staff (
    staff_id    INTEGER PRIMARY KEY,
    staff_name  TEXT    NOT NULL
);
CREATE TABLE Administrations (
    administration_id  INTEGER PRIMARY KEY,
    medication_id      INTEGER NOT NULL,
    staff_id           INTEGER,
    dose_status        TEXT    NOT NULL,
    severity           TEXT    NOT NULL
);

CREATE VIEW PrescribedMedications AS
SELECT V.vet_name, M.medication_id, M.medication_name
FROM Veterinarians AS V
JOIN Medications AS M ON M.vet_id = V.vet_id;

CREATE VIEW MedicalAdministrations AS
SELECT X.vet_name, X.medication_name, T.staff_name
FROM PrescribedMedications AS X
JOIN Administrations AS A ON A.medication_id = X.medication_id
JOIN Staff AS T ON T.staff_id = A.staff_id
WHERE A.dose_status = 'administered'
  AND A.severity = 'critical';

CREATE TABLE KennelUnits (
    unit_id      INTEGER PRIMARY KEY,
    unit_number  TEXT    NOT NULL
);
CREATE TABLE SanitationSupplies (
    supply_id    INTEGER PRIMARY KEY,
    supply_name  TEXT    NOT NULL
);
CREATE TABLE Supervisors (
    supervisor_id    INTEGER PRIMARY KEY,
    supervisor_name  TEXT    NOT NULL,
    shift_id         INTEGER NOT NULL
);
CREATE TABLE CleaningTasks (
    task_id       INTEGER PRIMARY KEY,
    unit_id       INTEGER NOT NULL,
    supply_id     INTEGER NOT NULL,
    shift_id      INTEGER NOT NULL,
    completed_at  TIME
);

CREATE VIEW UnitCleaningTasks AS
SELECT K.unit_number, C.completed_at, C.shift_id, L.supply_name
FROM KennelUnits AS K
JOIN CleaningTasks AS C ON C.unit_id = K.unit_id
JOIN SanitationSupplies AS L ON L.supply_id = C.supply_id;

CREATE VIEW KennelMaintenance AS
SELECT U.unit_number, U.completed_at, R.supervisor_name
FROM UnitCleaningTasks AS U
JOIN Supervisors AS R ON R.shift_id = U.shift_id
WHERE U.supply_name = 'bleach'
  AND U.completed_at IS NOT NULL;

SELECT pet_name, start_date, feeding_time FROM DailyCareRoutine ORDER BY start_date, feeding_time;
SELECT vet_name, medication_name, staff_name FROM MedicalAdministrations ORDER BY vet_name, medication_name;
SELECT unit_number, completed_at, supervisor_name FROM KennelMaintenance ORDER BY unit_number, completed_at;

