CREATE TABLE VineyardBlocks (BlockID INTEGER PRIMARY KEY, BlockIdentifier VARCHAR(20), VarietalID INTEGER);
CREATE TABLE GrapeVarietals (VarietalID INTEGER PRIMARY KEY, VarietalName VARCHAR(50), GrapeColor VARCHAR(20));
CREATE TABLE HarvestBins (BinID INTEGER PRIMARY KEY, BlockID INTEGER, CrewID INTEGER, PickStatus VARCHAR(20));
CREATE TABLE PickingCrews (CrewID INTEGER PRIMARY KEY, CrewLeadName VARCHAR(50));
CREATE TABLE FermentationTanks (TankID INTEGER PRIMARY KEY, TankNumber VARCHAR(20));
CREATE TABLE BatchRecords (BatchID INTEGER PRIMARY KEY, TankID INTEGER, YeastID INTEGER, BatchDate VARCHAR(20));
CREATE TABLE YeastStrains (YeastID INTEGER PRIMARY KEY, StrainName VARCHAR(50));
CREATE TABLE TemperatureLogs (LogID INTEGER PRIMARY KEY, BatchID INTEGER, RecordedTemp DECIMAL(5,2));
CREATE TABLE BottleInventories (BottleID INTEGER PRIMARY KEY, BottleSize VARCHAR(20));
CREATE TABLE LabelDesigns (LabelID INTEGER PRIMARY KEY, LabelName VARCHAR(50));
CREATE TABLE PackagingRuns (RunID INTEGER PRIMARY KEY, BottleID INTEGER, LabelID INTEGER, PalletID INTEGER, RunStatus VARCHAR(20));
CREATE TABLE ShippingPallets (PalletID INTEGER PRIMARY KEY, PalletDestination VARCHAR(50), ShipmentType VARCHAR(20));

CREATE VIEW RedGrapeHarvestPicks AS
SELECT VB.BlockIdentifier, GV.VarietalName, PC.CrewLeadName
FROM VineyardBlocks AS VB
JOIN GrapeVarietals AS GV ON VB.VarietalID = GV.VarietalID
JOIN HarvestBins AS HB ON HB.BlockID = VB.BlockID
JOIN PickingCrews AS PC ON HB.CrewID = PC.CrewID
WHERE GV.GrapeColor = 'Red'
  AND HB.PickStatus = 'Completed';

CREATE VIEW HotFermentationBatches AS
SELECT FT.TankNumber, BR.BatchDate, TL.RecordedTemp
FROM FermentationTanks AS FT
JOIN BatchRecords AS BR ON BR.TankID = FT.TankID
JOIN YeastStrains AS YS ON BR.YeastID = YS.YeastID
JOIN TemperatureLogs AS TL ON TL.BatchID = BR.BatchID
WHERE TL.RecordedTemp > 80;

CREATE VIEW ExportBottlingRuns AS
SELECT BI.BottleSize, LD.LabelName, SP.PalletDestination
FROM PackagingRuns AS PR
JOIN BottleInventories AS BI ON PR.BottleID = BI.BottleID
JOIN LabelDesigns AS LD ON PR.LabelID = LD.LabelID
JOIN ShippingPallets AS SP ON PR.PalletID = SP.PalletID
WHERE PR.RunStatus = 'Completed'
  AND SP.ShipmentType = 'Export';

