-- Bins filled by each crew lead, broken down by varietal.
SELECT PC.CrewLeadName, GV.VarietalName, COUNT(*) AS BinCount
FROM HarvestBins AS HB
JOIN VineyardBlocks AS VB ON HB.BlockID = VB.BlockID
JOIN GrapeVarietals AS GV ON VB.VarietalID = GV.VarietalID
JOIN PickingCrews AS PC ON HB.CrewID = PC.CrewID
GROUP BY PC.CrewLeadName, GV.VarietalName;

-- Peak fermentation temperature reached by each strain in each tank.
SELECT YS.StrainName, FT.TankNumber, MAX(TL.RecordedTemp) AS PeakTemp
FROM BatchRecords AS BR
JOIN YeastStrains AS YS ON BR.YeastID = YS.YeastID
JOIN FermentationTanks AS FT ON BR.TankID = FT.TankID
JOIN TemperatureLogs AS TL ON TL.BatchID = BR.BatchID
GROUP BY YS.StrainName, FT.TankNumber;

-- Packaging volume per destination, bottle size and label.
SELECT SP.PalletDestination, BI.BottleSize, LD.LabelName, COUNT(*) AS RunCount
FROM PackagingRuns AS PR
JOIN ShippingPallets AS SP ON PR.PalletID = SP.PalletID
JOIN BottleInventories AS BI ON PR.BottleID = BI.BottleID
JOIN LabelDesigns AS LD ON PR.LabelID = LD.LabelID
GROUP BY SP.PalletDestination, BI.BottleSize, LD.LabelName;

