CREATE TABLE plays (play_id INTEGER PRIMARY KEY, play_name VARCHAR(80) NOT NULL);

CREATE TABLE show_dates (show_id INTEGER PRIMARY KEY,
    play_id INTEGER NOT NULL REFERENCES plays(play_id),
    show_date VARCHAR(20) NOT NULL, time_of_day VARCHAR(10) NOT NULL);

CREATE TABLE cast_members (member_id INTEGER PRIMARY KEY, member_name VARCHAR(60) NOT NULL);

CREATE TABLE costumes (costume_id INTEGER PRIMARY KEY, costume_desc VARCHAR(80) NOT NULL);

CREATE TABLE roles (role_id INTEGER PRIMARY KEY,
    show_id INTEGER NOT NULL REFERENCES show_dates(show_id),
    member_id INTEGER NOT NULL REFERENCES cast_members(member_id),
    costume_id INTEGER NOT NULL REFERENCES costumes(costume_id),
    role_desc VARCHAR(60) NOT NULL);

CREATE TABLE seamstresses (seamstress_id INTEGER PRIMARY KEY, seamstress_name VARCHAR(60) NOT NULL);

CREATE TABLE alterations (alteration_id INTEGER PRIMARY KEY,
    costume_id INTEGER NOT NULL REFERENCES costumes(costume_id),
    seamstress_id INTEGER NOT NULL REFERENCES seamstresses(seamstress_id),
    status VARCHAR(20) NOT NULL, extra_fabric CHAR(1) NOT NULL);

CREATE TABLE fittings (fitting_id INTEGER PRIMARY KEY,
    alteration_id INTEGER NOT NULL REFERENCES alterations(alteration_id),
    fitting_date VARCHAR(20) NOT NULL);

CREATE TABLE seats (seat_id INTEGER PRIMARY KEY, seat_number VARCHAR(10) NOT NULL);

CREATE TABLE patrons (patron_id INTEGER PRIMARY KEY, patron_name VARCHAR(60) NOT NULL);

CREATE TABLE discount_codes (code_id INTEGER PRIMARY KEY, code_type VARCHAR(20) NOT NULL,
    discount_value DECIMAL(6,2) NOT NULL);

CREATE TABLE ticket_purchases (purchase_id INTEGER PRIMARY KEY,
    show_id INTEGER NOT NULL REFERENCES show_dates(show_id),
    seat_id INTEGER NOT NULL REFERENCES seats(seat_id),
    patron_id INTEGER NOT NULL REFERENCES patrons(patron_id),
    code_id INTEGER NOT NULL REFERENCES discount_codes(code_id),
    sale_status VARCHAR(20) NOT NULL);

CREATE VIEW evening_cast_assignments AS
SELECT p.play_name, s.show_date, cm.member_name, r.role_desc
FROM plays AS p
JOIN show_dates AS s ON s.play_id = p.play_id
JOIN roles AS r ON r.show_id = s.show_id
JOIN cast_members AS cm ON cm.member_id = r.member_id
WHERE s.time_of_day = 'evening';

CREATE VIEW completed_fabric_alterations AS
SELECT c.costume_desc, sm.seamstress_name, f.fitting_date
FROM costumes AS c
JOIN alterations AS a ON a.costume_id = c.costume_id
JOIN seamstresses AS sm ON sm.seamstress_id = a.seamstress_id
JOIN fittings AS f ON f.alteration_id = a.alteration_id
WHERE a.status = 'completed' AND a.extra_fabric = 'Y';

CREATE VIEW role_wardrobe_owners AS
SELECT r.role_desc, c.costume_desc, sm.seamstress_name, a.status
FROM roles AS r
JOIN costumes AS c ON c.costume_id = r.costume_id
JOIN alterations AS a ON a.costume_id = c.costume_id
JOIN seamstresses AS sm ON sm.seamstress_id = a.seamstress_id;

CREATE VIEW student_discount_sales AS
SELECT st.seat_number, pt.patron_name, dc.discount_value
FROM seats AS st
JOIN ticket_purchases AS tp ON tp.seat_id = st.seat_id
JOIN patrons AS pt ON pt.patron_id = tp.patron_id
JOIN discount_codes AS dc ON dc.code_id = tp.code_id
WHERE tp.sale_status = 'finalized' AND dc.code_type = 'student';

SELECT p.play_name, s.show_date, st.seat_number, pt.patron_name, dc.discount_value
FROM ticket_purchases AS tp
JOIN show_dates AS s ON s.show_id = tp.show_id
JOIN plays AS p ON p.play_id = s.play_id
JOIN seats AS st ON st.seat_id = tp.seat_id
JOIN patrons AS pt ON pt.patron_id = tp.patron_id
JOIN discount_codes AS dc ON dc.code_id = tp.code_id
WHERE tp.sale_status = 'finalized'
ORDER BY s.show_date, st.seat_number;

SELECT play_name, show_date, member_name, role_desc FROM evening_cast_assignments;

SELECT costume_desc, seamstress_name, fitting_date FROM completed_fabric_alterations;

SELECT role_desc, costume_desc, seamstress_name FROM role_wardrobe_owners WHERE status = 'completed';

SELECT seat_number, patron_name, discount_value FROM student_discount_sales;

