CREATE TABLE TournamentEvents (
    event_id INTEGER PRIMARY KEY, event_name VARCHAR(80) NOT NULL);

CREATE TABLE FightingRings (
    ring_id INTEGER PRIMARY KEY, ring_number INTEGER NOT NULL,
    event_id INTEGER NOT NULL REFERENCES TournamentEvents(event_id));

CREATE TABLE MatchSchedules (
    match_id INTEGER PRIMARY KEY, schedule_time VARCHAR(20) NOT NULL,
    round_name VARCHAR(30) NOT NULL,
    ring_id INTEGER NOT NULL REFERENCES FightingRings(ring_id));

CREATE VIEW RingMatchSchedule AS
SELECT MS.match_id, TE.event_name, FR.ring_number, MS.schedule_time, MS.round_name
FROM TournamentEvents AS TE
JOIN FightingRings AS FR ON FR.event_id = TE.event_id
JOIN MatchSchedules AS MS ON MS.ring_id = FR.ring_id;

CREATE TABLE Referees (
    referee_id INTEGER PRIMARY KEY, referee_name VARCHAR(60) NOT NULL);

CREATE TABLE RefereeAssignments (
    assignment_id INTEGER PRIMARY KEY,
    match_id INTEGER NOT NULL REFERENCES MatchSchedules(match_id),
    referee_id INTEGER NOT NULL REFERENCES Referees(referee_id));

CREATE VIEW FinalRoundBrackets AS
SELECT RMS.event_name, RMS.ring_number, RMS.schedule_time, RF.referee_name
FROM RingMatchSchedule AS RMS
JOIN RefereeAssignments AS RA ON RA.match_id = RMS.match_id
JOIN Referees AS RF ON RF.referee_id = RA.referee_id
WHERE RMS.round_name = 'final';

CREATE TABLE Athletes (
    athlete_id INTEGER PRIMARY KEY, athlete_name VARCHAR(60) NOT NULL);

CREATE TABLE BeltRanks (
    belt_id INTEGER PRIMARY KEY, belt_color VARCHAR(20) NOT NULL);

CREATE TABLE GradingSessions (
    session_id INTEGER PRIMARY KEY, result VARCHAR(20) NOT NULL,
    athlete_id INTEGER NOT NULL REFERENCES Athletes(athlete_id),
    belt_id INTEGER NOT NULL REFERENCES BeltRanks(belt_id));

CREATE VIEW AthleteGradingResults AS
SELECT GS.session_id, A.athlete_name, BR.belt_color, GS.result
FROM Athletes AS A
JOIN GradingSessions AS GS ON GS.athlete_id = A.athlete_id
JOIN BeltRanks AS BR ON BR.belt_id = GS.belt_id;

CREATE TABLE JudgingPanels (
    panel_id INTEGER PRIMARY KEY, chairperson VARCHAR(60) NOT NULL,
    session_id INTEGER NOT NULL REFERENCES GradingSessions(session_id));

CREATE VIEW BlackBeltAchievements AS
SELECT AGR.athlete_name, AGR.belt_color, JP.chairperson
FROM AthleteGradingResults AS AGR
JOIN JudgingPanels AS JP ON JP.session_id = AGR.session_id
WHERE AGR.belt_color = 'black' AND AGR.result = 'pass';

CREATE TABLE ProtectiveEquipment (
    equipment_id INTEGER PRIMARY KEY, equipment_type VARCHAR(40) NOT NULL);

CREATE TABLE SizingCharts (
    size_id INTEGER PRIMARY KEY, size_category VARCHAR(20) NOT NULL,
    equipment_id INTEGER NOT NULL REFERENCES ProtectiveEquipment(equipment_id));

CREATE TABLE InventoryAudits (
    audit_id INTEGER PRIMARY KEY, counted_units INTEGER NOT NULL,
    size_id INTEGER NOT NULL REFERENCES SizingCharts(size_id));

CREATE VIEW GearSizeAudits AS
SELECT IA.audit_id, PE.equipment_type, SC.size_category
FROM ProtectiveEquipment AS PE
JOIN SizingCharts AS SC ON SC.equipment_id = PE.equipment_id
JOIN InventoryAudits AS IA ON IA.size_id = SC.size_id;

CREATE TABLE SupplierShipments (
    shipment_id INTEGER PRIMARY KEY, shipment_date VARCHAR(20) NOT NULL,
    origin_scope VARCHAR(20) NOT NULL,
    audit_id INTEGER NOT NULL REFERENCES InventoryAudits(audit_id));

CREATE VIEW InternationalGearShipments AS
SELECT GSA.equipment_type, GSA.size_category, SS.shipment_date
FROM GearSizeAudits AS GSA
JOIN SupplierShipments AS SS ON SS.audit_id = GSA.audit_id
WHERE SS.origin_scope = 'international';

SELECT event_name, ring_number, schedule_time, referee_name FROM FinalRoundBrackets;
SELECT athlete_name, belt_color, chairperson FROM BlackBeltAchievements;
SELECT equipment_type, size_category, shipment_date FROM InternationalGearShipments;

