CREATE TABLE dive_sites (site_id INTEGER PRIMARY KEY, site_name TEXT, max_depth_feet INTEGER);
CREATE TABLE boat_charters (charter_id INTEGER PRIMARY KEY, vessel_name TEXT);
CREATE TABLE dive_masters (master_id INTEGER PRIMARY KEY, master_name TEXT);
CREATE TABLE excursions (excursion_id INTEGER PRIMARY KEY, site_id INTEGER, charter_id INTEGER, master_id INTEGER, excursion_date TEXT);
