CREATE TABLE student_divers (diver_id INTEGER PRIMARY KEY, diver_name TEXT);
CREATE TABLE rental_regulators (regulator_id INTEGER PRIMARY KEY, serial_number TEXT);
CREATE TABLE oxygen_tanks (tank_id INTEGER PRIMARY KEY, capacity TEXT, gas_mix TEXT);
CREATE TABLE safety_check_logs (log_id INTEGER PRIMARY KEY, diver_id INTEGER, regulator_id INTEGER, tank_id INTEGER, checked_at TEXT);
CREATE TABLE issuing_agencies (agency_id INTEGER PRIMARY KEY, agency_name TEXT);
CREATE TABLE training_courses (course_id INTEGER PRIMARY KEY, course_name TEXT, agency_id INTEGER);
CREATE TABLE written_exams (exam_id INTEGER PRIMARY KEY, course_id INTEGER, diver_id INTEGER, score INTEGER);
CREATE TABLE practical_evaluations (evaluation_id INTEGER PRIMARY KEY, exam_id INTEGER, result TEXT);

CREATE VIEW deep_open_water_dives AS
SELECT ds.site_name, bc.vessel_name AS charter_vessel, dm.master_name AS dive_master, ex.excursion_date
FROM excursions AS ex
JOIN dive_sites AS ds ON ex.site_id = ds.site_id
JOIN boat_charters AS bc ON ex.charter_id = bc.charter_id
JOIN dive_masters AS dm ON ex.master_id = dm.master_id
WHERE ds.max_depth_feet > 60;

CREATE VIEW student_enriched_air_equipment AS
SELECT sd.diver_name, rr.serial_number AS regulator_serial, ot.capacity AS tank_capacity, scl.checked_at AS check_timestamp
FROM safety_check_logs AS scl
JOIN student_divers AS sd ON scl.diver_id = sd.diver_id
JOIN rental_regulators AS rr ON scl.regulator_id = rr.regulator_id
JOIN oxygen_tanks AS ot ON scl.tank_id = ot.tank_id
WHERE ot.gas_mix = 'Enriched Air';

CREATE VIEW certification_processing AS
SELECT tc.course_name, we.score AS exam_score, pe.result AS evaluation_result, ia.agency_name
FROM written_exams AS we
JOIN training_courses AS tc ON we.course_id = tc.course_id
JOIN practical_evaluations AS pe ON pe.exam_id = we.exam_id
JOIN issuing_agencies AS ia ON tc.agency_id = ia.agency_id
WHERE we.score > 90;

CREATE VIEW excursion_manifest AS
SELECT ex.excursion_id, sd.diver_name, ds.site_name, ex.excursion_date
FROM bookings AS bk
JOIN excursions AS ex ON bk.excursion_id = ex.excursion_id
JOIN student_divers AS sd ON bk.diver_id = sd.diver_id
JOIN dive_sites AS ds ON ex.site_id = ds.site_id;

CREATE VIEW deep_dive_gear_readiness AS
SELECT m.diver_name, m.site_name, m.excursion_date, e.regulator_serial, e.tank_capacity, e.check_timestamp
FROM excursion_manifest AS m
JOIN student_enriched_air_equipment AS e ON m.diver_name = e.diver_name;

