CREATE VIEW kiln_firing_tracker AS
SELECT ku.kiln_number, fs.schedule_date, pp.piece_description, sm.member_name
FROM kiln_units AS ku
JOIN firing_schedules AS fs ON fs.kiln_id = ku.kiln_id
JOIN pottery_pieces AS pp ON pp.schedule_id = fs.schedule_id
JOIN studio_members AS sm ON sm.member_id = pp.member_id
WHERE pp.glaze_type = 'high fire';

CREATE VIEW clay_inventory_detail AS
SELECT ct.clay_name, sd.delivery_date, sb.bin_location, ul.usage_amount
FROM clay_types AS ct
JOIN supplier_deliveries AS sd ON sd.clay_id = ct.clay_id
JOIN storage_bins AS sb ON sb.delivery_id = sd.delivery_id
JOIN usage_logs AS ul ON ul.bin_id = sb.bin_id
WHERE ct.clay_name = 'porcelain';

CREATE VIEW workshop_event_manager AS
SELECT ga.artist_name, ws.session_topic, pr.receipt_amount
FROM guest_artists AS ga
JOIN workshop_sessions AS ws ON ws.artist_id = ga.artist_id
JOIN registration_lists AS rl ON rl.session_id = ws.session_id
JOIN payment_receipts AS pr ON pr.registration_id = rl.registration_id
WHERE rl.attendee_count > 50;

