CREATE TABLE TargetLanes (lane_id INTEGER PRIMARY KEY, lane_number INTEGER NOT NULL);
CREATE TABLE ReservationBlocks (block_id INTEGER PRIMARY KEY, lane_id INTEGER, member_id INTEGER,
    coach_id INTEGER, block_time TEXT NOT NULL, duration_hours REAL NOT NULL);

CREATE TABLE Bowstrings (string_id INTEGER PRIMARY KEY, string_type TEXT NOT NULL);
CREATE TABLE RentalBows (bow_id INTEGER PRIMARY KEY, bow_model TEXT NOT NULL, string_id INTEGER);
CREATE TABLE ArmoryTechnicians (technician_id INTEGER PRIMARY KEY, technician_name TEXT NOT NULL);
CREATE TABLE TensionTests (test_id INTEGER PRIMARY KEY, bow_id INTEGER, technician_id INTEGER,
    tension_lbs REAL NOT NULL);

CREATE TABLE TournamentRounds (round_id INTEGER PRIMARY KEY, round_name TEXT NOT NULL);
CREATE TABLE TargetFaces (face_id INTEGER PRIMARY KEY, target_size TEXT NOT NULL);
CREATE TABLE ScoringJudges (judge_id INTEGER PRIMARY KEY, judge_name TEXT NOT NULL);
CREATE TABLE ArrowVolleys (volley_id INTEGER PRIMARY KEY, round_id INTEGER, face_id INTEGER,
    judge_id INTEGER, volley_score INTEGER NOT NULL, is_bullseye INTEGER NOT NULL);

CREATE VIEW LaneReservationDetails AS
SELECT RB.block_id, TL.lane_number, RB.block_time, CM.member_name, RB.coach_id, RB.duration_hours
FROM ReservationBlocks AS RB JOIN TargetLanes AS TL ON TL.lane_id = RB.lane_id
JOIN ClubMembers AS CM ON CM.member_id = RB.member_id;

CREATE VIEW LongLaneReservations AS
SELECT LRD.lane_number, LRD.block_time, LRD.member_name, CS.coach_name
FROM LaneReservationDetails AS LRD JOIN CoachingStaff AS CS ON CS.coach_id = LRD.coach_id
WHERE LRD.duration_hours > 2;

CREATE VIEW BowStringAssemblies AS
SELECT RBW.bow_id, RBW.bow_model, BS.string_type
FROM RentalBows AS RBW JOIN Bowstrings AS BS ON BS.string_id = RBW.string_id;

CREATE VIEW LowTensionBowChecks AS
SELECT BSA.bow_model, BSA.string_type, AT.technician_name, TT.tension_lbs
FROM TensionTests AS TT JOIN BowStringAssemblies AS BSA ON BSA.bow_id = TT.bow_id
JOIN ArmoryTechnicians AS AT ON AT.technician_id = TT.technician_id
WHERE TT.tension_lbs < 30;

CREATE VIEW VolleyTargetRounds AS
SELECT AV.volley_id, TR.round_name, TF.target_size, AV.volley_score, AV.judge_id, AV.is_bullseye
FROM ArrowVolleys AS AV JOIN TournamentRounds AS TR ON TR.round_id = AV.round_id
JOIN TargetFaces AS TF ON TF.face_id = AV.face_id;

CREATE VIEW BullseyeVolleyScores AS
SELECT VTR.round_name, VTR.target_size, VTR.volley_score, SJ.judge_name
FROM VolleyTargetRounds AS VTR JOIN ScoringJudges AS SJ ON SJ.judge_id = VTR.judge_id
WHERE VTR.is_bullseye = 1 AND VTR.volley_score = 50;

