CREATE TABLE Choreographers (choreographer_id INTEGER PRIMARY KEY, choreographer_name VARCHAR(60) NOT NULL);
CREATE TABLE Rooms (room_id INTEGER PRIMARY KEY, room_name VARCHAR(40) NOT NULL);
CREATE TABLE RehearsalSlots (slot_id INTEGER PRIMARY KEY, slot_time VARCHAR(20) NOT NULL);
CREATE TABLE Routines (routine_id INTEGER PRIMARY KEY, routine_name VARCHAR(60) NOT NULL, style VARCHAR(30) NOT NULL,
    choreographer_id INTEGER REFERENCES Choreographers(choreographer_id), room_id INTEGER REFERENCES Rooms(room_id),
    slot_id INTEGER REFERENCES RehearsalSlots(slot_id));
CREATE TABLE MeasurementCharts (chart_id INTEGER PRIMARY KEY, size_category VARCHAR(20) NOT NULL);
CREATE TABLE Dancers (dancer_id INTEGER PRIMARY KEY, dancer_name VARCHAR(60) NOT NULL,
    chart_id INTEGER REFERENCES MeasurementCharts(chart_id));
CREATE TABLE ShippingManifests (manifest_id INTEGER PRIMARY KEY, shipping_date VARCHAR(20) NOT NULL);
CREATE TABLE CostumeOrders (order_id INTEGER PRIMARY KEY, dancer_id INTEGER REFERENCES Dancers(dancer_id),
    delivery_type VARCHAR(20) NOT NULL, manifest_id INTEGER REFERENCES ShippingManifests(manifest_id));
CREATE TABLE StageSections (section_id INTEGER PRIMARY KEY, section_name VARCHAR(40) NOT NULL);
CREATE TABLE ColorGels (gel_id INTEGER PRIMARY KEY, gel_color VARCHAR(20) NOT NULL);
CREATE TABLE ControlCues (cue_id INTEGER PRIMARY KEY, cue_timing VARCHAR(20) NOT NULL);
CREATE TABLE LightingFixtures (fixture_id INTEGER PRIMARY KEY, section_id INTEGER REFERENCES StageSections(section_id),
    fixture_type VARCHAR(30) NOT NULL, gel_id INTEGER REFERENCES ColorGels(gel_id),
    cue_id INTEGER REFERENCES ControlCues(cue_id));

CREATE VIEW RehearsalSchedule AS
SELECT R.routine_name, C.choreographer_name, M.room_name, S.slot_time
FROM Routines AS R
INNER JOIN Choreographers AS C ON R.choreographer_id = C.choreographer_id
INNER JOIN Rooms AS M ON R.room_id = M.room_id
INNER JOIN RehearsalSlots AS S ON R.slot_id = S.slot_id
WHERE R.style = 'tap';

CREATE VIEW CostumeDistribution AS
SELECT D.dancer_name, H.size_category, F.shipping_date
FROM CostumeOrders AS O
INNER JOIN Dancers AS D ON O.dancer_id = D.dancer_id
INNER JOIN MeasurementCharts AS H ON D.chart_id = H.chart_id
INNER JOIN ShippingManifests AS F ON O.manifest_id = F.manifest_id
WHERE O.delivery_type = 'rush';

CREATE VIEW StageLightingPlan AS
SELECT T.section_name, L.fixture_type, G.gel_color, Q.cue_timing
FROM LightingFixtures AS L
INNER JOIN StageSections AS T ON L.section_id = T.section_id
INNER JOIN ColorGels AS G ON L.gel_id = G.gel_id
INNER JOIN ControlCues AS Q ON L.cue_id = Q.cue_id
WHERE G.gel_color = 'blue';

CREATE VIEW RoomBookingConflicts AS
SELECT M.room_name, S.slot_time, A.routine_name AS first_routine, B.routine_name AS second_routine
FROM Routines AS A
INNER JOIN Routines AS B ON A.room_id = B.room_id AND A.slot_id = B.slot_id AND A.routine_id < B.routine_id
INNER JOIN Rooms AS M ON A.room_id = M.room_id
INNER JOIN RehearsalSlots AS S ON A.slot_id = S.slot_id;

CREATE VIEW GelUsageBySection AS
SELECT T.section_name, G.gel_color, COUNT(L.fixture_id) AS fixture_count
FROM LightingFixtures AS L
INNER JOIN StageSections AS T ON L.section_id = T.section_id
INNER JOIN ColorGels AS G ON L.gel_id = G.gel_id
GROUP BY T.section_name, G.gel_color;

