CREATE TABLE arena_maps (map_id INTEGER PRIMARY KEY, map_name VARCHAR(60) NOT NULL);
CREATE TABLE game_modes (mode_id INTEGER PRIMARY KEY, mode_description VARCHAR(80) NOT NULL);
CREATE TABLE teams (team_id INTEGER PRIMARY KEY, team_name VARCHAR(60) NOT NULL);
CREATE TABLE referees (referee_id INTEGER PRIMARY KEY, referee_name VARCHAR(60) NOT NULL);
CREATE TABLE matches (match_id INTEGER PRIMARY KEY, map_id INTEGER REFERENCES arena_maps (map_id), mode_id INTEGER REFERENCES game_modes (mode_id), team_id INTEGER REFERENCES teams (team_id), referee_id INTEGER REFERENCES referees (referee_id), start_time TIMESTAMP);
CREATE TABLE markers (marker_id INTEGER PRIMARY KEY, marker_serial VARCHAR(40) NOT NULL);
CREATE TABLE air_tanks (tank_id INTEGER PRIMARY KEY, marker_id INTEGER REFERENCES markers (marker_id), tank_capacity VARCHAR(30) NOT NULL, tank_class VARCHAR(30) NOT NULL);
CREATE TABLE technicians (technician_id INTEGER PRIMARY KEY, technician_name VARCHAR(60) NOT NULL);
CREATE TABLE pressure_tests (test_id INTEGER PRIMARY KEY, tank_id INTEGER REFERENCES air_tanks (tank_id), technician_id INTEGER REFERENCES technicians (technician_id), test_date DATE);
CREATE TABLE snack_bars (bar_id INTEGER PRIMARY KEY, bar_location VARCHAR(60) NOT NULL);
CREATE TABLE menu_items (item_id INTEGER PRIMARY KEY, bar_id INTEGER REFERENCES snack_bars (bar_id), item_name VARCHAR(60) NOT NULL, item_category VARCHAR(40) NOT NULL);
CREATE TABLE cashier_shifts (shift_id INTEGER PRIMARY KEY, shift_operator VARCHAR(60) NOT NULL);
CREATE TABLE purchases (purchase_id INTEGER PRIMARY KEY, item_id INTEGER REFERENCES menu_items (item_id), shift_id INTEGER REFERENCES cashier_shifts (shift_id), sold_at TIMESTAMP);

CREATE VIEW match_schedule_detail AS
SELECT am.map_name, gm.mode_description, t.team_name, r.referee_name
FROM matches AS m
INNER JOIN arena_maps AS am ON am.map_id = m.map_id
INNER JOIN game_modes AS gm ON gm.mode_id = m.mode_id
INNER JOIN teams AS t ON t.team_id = m.team_id
INNER JOIN referees AS r ON r.referee_id = m.referee_id
WHERE gm.mode_description = 'capture the flag';

CREATE VIEW referee_map_load AS
SELECT r.referee_name, am.map_name, COUNT(m.match_id) AS assigned_matches
FROM matches AS m
INNER JOIN referees AS r ON r.referee_id = m.referee_id
INNER JOIN arena_maps AS am ON am.map_id = m.map_id
GROUP BY r.referee_name, am.map_name;

CREATE VIEW marker_maintenance_detail AS
SELECT mk.marker_serial, at.tank_capacity, tc.technician_name
FROM pressure_tests AS pt
INNER JOIN air_tanks AS at ON at.tank_id = pt.tank_id
INNER JOIN markers AS mk ON mk.marker_id = at.marker_id
INNER JOIN technicians AS tc ON tc.technician_id = pt.technician_id
WHERE at.tank_class = 'high pressure';

CREATE VIEW technician_test_volume AS
SELECT tc.technician_name, at.tank_class, COUNT(DISTINCT pt.tank_id) AS tanks_tested
FROM pressure_tests AS pt
INNER JOIN technicians AS tc ON tc.technician_id = pt.technician_id
INNER JOIN air_tanks AS at ON at.tank_id = pt.tank_id
GROUP BY tc.technician_name, at.tank_class;

CREATE VIEW concession_sales_detail AS
SELECT sb.bar_location, mi.item_name, cs.shift_operator
FROM purchases AS p
INNER JOIN menu_items AS mi ON mi.item_id = p.item_id
INNER JOIN snack_bars AS sb ON sb.bar_id = mi.bar_id
INNER JOIN cashier_shifts AS cs ON cs.shift_id = p.shift_id
WHERE mi.item_category = 'energy drink';

CREATE VIEW bar_category_sales AS
SELECT sb.bar_location, mi.item_category, COUNT(p.purchase_id) AS sold_units
FROM purchases AS p
INNER JOIN menu_items AS mi ON mi.item_id = p.item_id
INNER JOIN snack_bars AS sb ON sb.bar_id = mi.bar_id
GROUP BY sb.bar_location, mi.item_category;

