CREATE TABLE WindTunnels (tunnel_id INTEGER PRIMARY KEY, tunnel_name VARCHAR(50) NOT NULL);
CREATE TABLE FlightBlocks (block_id INTEGER PRIMARY KEY, tunnel_id INTEGER REFERENCES WindTunnels(tunnel_id), block_time VARCHAR(20) NOT NULL, focus VARCHAR(40) NOT NULL);
CREATE TABLE Flyers (flyer_id INTEGER PRIMARY KEY, flyer_name VARCHAR(50) NOT NULL, block_id INTEGER REFERENCES FlightBlocks(block_id));
CREATE TABLE SafetyInstructors (instructor_id INTEGER PRIMARY KEY, instructor_name VARCHAR(50) NOT NULL, block_id INTEGER REFERENCES FlightBlocks(block_id));

CREATE VIEW AdvancedManeuverSessions AS
SELECT T.tunnel_name, B.block_time, F.flyer_name, I.instructor_name
FROM WindTunnels AS T
JOIN FlightBlocks AS B ON T.tunnel_id = B.tunnel_id
JOIN Flyers AS F ON F.block_id = B.block_id
JOIN SafetyInstructors AS I ON I.block_id = B.block_id
WHERE B.focus = 'advanced maneuvers';

CREATE VIEW TunnelBlockStaffing AS
SELECT T.tunnel_name, B.block_time, COUNT(DISTINCT F.flyer_id) AS flyer_count, COUNT(DISTINCT I.instructor_id) AS instructor_count
FROM WindTunnels AS T
JOIN FlightBlocks AS B ON T.tunnel_id = B.tunnel_id
JOIN Flyers AS F ON F.block_id = B.block_id
JOIN SafetyInstructors AS I ON I.block_id = B.block_id
GROUP BY T.tunnel_name, B.block_time;

CREATE TABLE CleaningServices (service_id INTEGER PRIMARY KEY, service_name VARCHAR(50) NOT NULL);
CREATE TABLE LaundryBatches (batch_id INTEGER PRIMARY KEY, batch_date VARCHAR(20) NOT NULL, service_id INTEGER REFERENCES CleaningServices(service_id));
CREATE TABLE FlightSuits (suit_id INTEGER PRIMARY KEY, suit_size VARCHAR(20) NOT NULL, batch_id INTEGER REFERENCES LaundryBatches(batch_id));
CREATE TABLE InspectionReports (report_id INTEGER PRIMARY KEY, suit_id INTEGER REFERENCES FlightSuits(suit_id), report_status VARCHAR(40) NOT NULL);

CREATE VIEW TearRepairSuitInventory AS
SELECT S.suit_size, L.batch_date, C.service_name, R.report_status
FROM FlightSuits AS S
JOIN LaundryBatches AS L ON S.batch_id = L.batch_id
JOIN CleaningServices AS C ON L.service_id = C.service_id
JOIN InspectionReports AS R ON R.suit_id = S.suit_id
WHERE R.report_status = 'tear repair';

CREATE VIEW BatchInspectionSummary AS
SELECT C.service_name, L.batch_date, COUNT(R.report_id) AS report_count
FROM LaundryBatches AS L
JOIN CleaningServices AS C ON L.service_id = C.service_id
JOIN FlightSuits AS S ON S.batch_id = L.batch_id
JOIN InspectionReports AS R ON R.suit_id = S.suit_id
GROUP BY C.service_name, L.batch_date;

CREATE TABLE CoolingSystems (cooling_id INTEGER PRIMARY KEY, cooling_type VARCHAR(30) NOT NULL);
CREATE TABLE TurbineEngines (engine_id INTEGER PRIMARY KEY, engine_model VARCHAR(40) NOT NULL, cooling_id INTEGER REFERENCES CoolingSystems(cooling_id));
CREATE TABLE MechanicalEngineers (engineer_id INTEGER PRIMARY KEY, engineer_name VARCHAR(50) NOT NULL);
CREATE TABLE DiagnosticTests (test_id INTEGER PRIMARY KEY, engine_id INTEGER REFERENCES TurbineEngines(engine_id), engineer_id INTEGER REFERENCES MechanicalEngineers(engineer_id), reading VARCHAR(40) NOT NULL);

CREATE VIEW HighTemperatureGeneratorChecks AS
SELECT E.engine_model, C.cooling_type, M.engineer_name
FROM TurbineEngines AS E
JOIN CoolingSystems AS C ON E.cooling_id = C.cooling_id
JOIN DiagnosticTests AS D ON D.engine_id = E.engine_id
JOIN MechanicalEngineers AS M ON D.engineer_id = M.engineer_id
WHERE D.reading = 'high temperature';

CREATE VIEW EngineerDiagnosticLoad AS
SELECT M.engineer_name, E.engine_model, COUNT(D.test_id) AS test_count
FROM MechanicalEngineers AS M
JOIN DiagnosticTests AS D ON D.engineer_id = M.engineer_id
JOIN TurbineEngines AS E ON D.engine_id = E.engine_id
GROUP BY M.engineer_name, E.engine_model;

