CREATE TABLE ProjectionDomes (dome_id INTEGER PRIMARY KEY, dome_name VARCHAR(60) NOT NULL);
CREATE TABLE Presentations (presentation_id INTEGER PRIMARY KEY, title VARCHAR(80) NOT NULL, topic VARCHAR(40) NOT NULL);
CREATE TABLE Astronomers (astronomer_id INTEGER PRIMARY KEY, astronomer_name VARCHAR(60) NOT NULL);
CREATE TABLE ShowTimes (
    show_id         INTEGER PRIMARY KEY,
    dome_id         INTEGER NOT NULL REFERENCES ProjectionDomes(dome_id),
    presentation_id INTEGER NOT NULL REFERENCES Presentations(presentation_id),
    astronomer_id   INTEGER NOT NULL REFERENCES Astronomers(astronomer_id),
    show_time       VARCHAR(20) NOT NULL
);

CREATE VIEW BlackHoleShowSchedule AS
SELECT D.dome_name, P.title, A.astronomer_name, S.show_time
FROM ShowTimes AS S
JOIN ProjectionDomes AS D ON S.dome_id = D.dome_id
JOIN Presentations AS P ON S.presentation_id = P.presentation_id
JOIN Astronomers AS A ON S.astronomer_id = A.astronomer_id
WHERE P.topic = 'black holes';

CREATE VIEW FullShowSchedule AS
SELECT D.dome_name, P.title, P.topic, A.astronomer_name, S.show_time
FROM ShowTimes AS S
JOIN ProjectionDomes AS D ON S.dome_id = D.dome_id
JOIN Presentations AS P ON S.presentation_id = P.presentation_id
JOIN Astronomers AS A ON S.astronomer_id = A.astronomer_id;

CREATE VIEW AstronomerShowLoad AS
SELECT A.astronomer_name, COUNT(*) AS show_count
FROM ShowTimes AS S
JOIN Astronomers AS A ON S.astronomer_id = A.astronomer_id
GROUP BY A.astronomer_name;

CREATE TABLE CoolingPumps (pump_id INTEGER PRIMARY KEY, pump_status VARCHAR(20) NOT NULL);
CREATE TABLE OpticalTechnicians (technician_id INTEGER PRIMARY KEY, technician_name VARCHAR(60) NOT NULL);
CREATE TABLE LaserModules (
    module_id     INTEGER PRIMARY KEY,
    serial_number VARCHAR(30) NOT NULL,
    pump_id       INTEGER NOT NULL REFERENCES CoolingPumps(pump_id)
);
CREATE TABLE AlignmentCalibrations (
    calibration_id INTEGER PRIMARY KEY,
    module_id      INTEGER NOT NULL REFERENCES LaserModules(module_id),
    technician_id  INTEGER NOT NULL REFERENCES OpticalTechnicians(technician_id),
    issue_fixed    VARCHAR(40) NOT NULL
);

CREATE VIEW MisalignmentMaintenance AS
SELECT M.serial_number, CP.pump_status, T.technician_name
FROM AlignmentCalibrations AS C
JOIN LaserModules AS M ON C.module_id = M.module_id
JOIN CoolingPumps AS CP ON M.pump_id = CP.pump_id
JOIN OpticalTechnicians AS T ON C.technician_id = T.technician_id
WHERE C.issue_fixed = 'misalignment';

CREATE VIEW ModulesWithFailingPumps AS
SELECT M.serial_number, CP.pump_status
FROM LaserModules AS M
JOIN CoolingPumps AS CP ON M.pump_id = CP.pump_id
WHERE CP.pump_status <> 'active';

CREATE TABLE VisitingSchools (
    school_id    INTEGER PRIMARY KEY,
    school_name  VARCHAR(80) NOT NULL,
    school_level VARCHAR(20) NOT NULL
);
CREATE TABLE BookingInvoices (invoice_id INTEGER PRIMARY KEY, invoice_amount DECIMAL(10,2) NOT NULL);
CREATE TABLE EducationalGuides (guide_id INTEGER PRIMARY KEY, guide_name VARCHAR(60) NOT NULL);
CREATE TABLE ChaperoneLists (
    list_id         INTEGER PRIMARY KEY,
    school_id       INTEGER NOT NULL REFERENCES VisitingSchools(school_id),
    invoice_id      INTEGER NOT NULL REFERENCES BookingInvoices(invoice_id),
    guide_id        INTEGER NOT NULL REFERENCES EducationalGuides(guide_id),
    chaperone_count INTEGER NOT NULL
);

CREATE VIEW ElementarySchoolVisits AS
SELECT VS.school_name, BI.invoice_amount, EG.guide_name
FROM ChaperoneLists AS CL
JOIN VisitingSchools AS VS ON CL.school_id = VS.school_id
JOIN BookingInvoices AS BI ON CL.invoice_id = BI.invoice_id
JOIN EducationalGuides AS EG ON CL.guide_id = EG.guide_id
WHERE VS.school_level = 'elementary';

SELECT dome_name, title, astronomer_name, show_time FROM BlackHoleShowSchedule;
SELECT serial_number, pump_status, technician_name FROM MisalignmentMaintenance;
SELECT school_name, invoice_amount, guide_name FROM ElementarySchoolVisits;
SELECT dome_name, title, show_time FROM FullShowSchedule ORDER BY dome_name, show_time;
SELECT astronomer_name, show_count FROM AstronomerShowLoad ORDER BY show_count DESC;
SELECT serial_number, pump_status FROM ModulesWithFailingPumps;

