CREATE TABLE CityStops (stop_id INTEGER PRIMARY KEY, city_name VARCHAR(60) NOT NULL);
CREATE TABLE TheaterHalls (hall_id INTEGER PRIMARY KEY, stop_id INTEGER NOT NULL REFERENCES CityStops (stop_id), capacity INTEGER NOT NULL);
CREATE TABLE Promoters (promoter_id INTEGER PRIMARY KEY, promoter_name VARCHAR(60) NOT NULL);
CREATE TABLE Contracts (contract_id INTEGER PRIMARY KEY, hall_id INTEGER NOT NULL REFERENCES TheaterHalls (hall_id), promoter_id INTEGER NOT NULL REFERENCES Promoters (promoter_id), guarantee VARCHAR(30) NOT NULL);

CREATE VIEW PerformanceVenues AS
SELECT cs.city_name, th.capacity, p.promoter_name
FROM Contracts AS c
JOIN TheaterHalls AS th ON th.hall_id = c.hall_id
JOIN CityStops AS cs ON cs.stop_id = th.stop_id
JOIN Promoters AS p ON p.promoter_id = c.promoter_id
WHERE c.guarantee = 'sold out';

