CREATE TABLE FlowerVarieties (flower_id INTEGER PRIMARY KEY, flower_type VARCHAR(60) NOT NULL, is_exotic CHAR(1) NOT NULL);
CREATE TABLE VaseInventory (vase_id INTEGER PRIMARY KEY, vase_style VARCHAR(60) NOT NULL, on_hand INTEGER NOT NULL);
CREATE TABLE DesignSpecialists (specialist_id INTEGER PRIMARY KEY, specialist_name VARCHAR(60) NOT NULL);
CREATE TABLE FloralDesigns (
    design_id     INTEGER PRIMARY KEY,
    design_name   VARCHAR(60) NOT NULL,
    flower_id     INTEGER NOT NULL,
    vase_id       INTEGER NOT NULL,
    specialist_id INTEGER NOT NULL
);

CREATE VIEW CustomArrangements AS
SELECT d.design_name, f.flower_type, v.vase_style, s.specialist_name
FROM FloralDesigns AS d
JOIN FlowerVarieties AS f ON d.flower_id = f.flower_id
JOIN VaseInventory AS v ON d.vase_id = v.vase_id
JOIN DesignSpecialists AS s ON d.specialist_id = s.specialist_id
WHERE f.is_exotic = 'Y' AND f.flower_type = 'exotic orchids';

CREATE VIEW ExoticVaseShortages AS
SELECT v.vase_style, v.on_hand, COUNT(*) AS designs_waiting
FROM VaseInventory AS v
JOIN FloralDesigns AS d ON v.vase_id = d.vase_id
JOIN FlowerVarieties AS f ON d.flower_id = f.flower_id
WHERE f.is_exotic = 'Y'
GROUP BY v.vase_style, v.on_hand
HAVING COUNT(*) > v.on_hand;

CREATE TABLE HiredDrivers (driver_id INTEGER PRIMARY KEY, driver_name VARCHAR(60) NOT NULL);
CREATE TABLE DeliveryVans (van_id INTEGER PRIMARY KEY, van_plate VARCHAR(20) NOT NULL, driver_id INTEGER NOT NULL);
CREATE TABLE RouteMaps (route_id INTEGER PRIMARY KEY, route_name VARCHAR(60) NOT NULL, van_id INTEGER NOT NULL);
CREATE TABLE OrderDestinations (destination_id INTEGER PRIMARY KEY, route_id INTEGER NOT NULL, district VARCHAR(60) NOT NULL);

CREATE VIEW DowntownRoutes AS
SELECT DISTINCT v.van_plate, r.route_name, h.driver_name
FROM DeliveryVans AS v
JOIN RouteMaps AS r ON v.van_id = r.van_id
JOIN OrderDestinations AS o ON r.route_id = o.route_id
JOIN HiredDrivers AS h ON v.driver_id = h.driver_id
WHERE o.district = 'downtown';

CREATE VIEW RouteStopCounts AS
SELECT r.route_name, h.driver_name, COUNT(o.destination_id) AS stops
FROM RouteMaps AS r
JOIN DeliveryVans AS v ON r.van_id = v.van_id
JOIN HiredDrivers AS h ON v.driver_id = h.driver_id
JOIN OrderDestinations AS o ON r.route_id = o.route_id
GROUP BY r.route_name, h.driver_name;

CREATE TABLE SupplierFarms (farm_id INTEGER PRIMARY KEY, farm_name VARCHAR(60) NOT NULL, country VARCHAR(60) NOT NULL);
CREATE TABLE ReceivingManagers (manager_id INTEGER PRIMARY KEY, manager_name VARCHAR(60) NOT NULL);
CREATE TABLE BulkShipments (
    shipment_id   INTEGER PRIMARY KEY,
    farm_id       INTEGER NOT NULL,
    shipment_date DATE NOT NULL,
    is_overseas   CHAR(1) NOT NULL
);
CREATE TABLE QualityInspections (
    inspection_id INTEGER PRIMARY KEY,
    shipment_id   INTEGER NOT NULL,
    manager_id    INTEGER NOT NULL,
    passed        CHAR(1) NOT NULL
);

CREATE VIEW OverseasSourcing AS
SELECT f.farm_name, b.shipment_date, m.manager_name
FROM SupplierFarms AS f
JOIN BulkShipments AS b ON f.farm_id = b.farm_id
JOIN QualityInspections AS q ON b.shipment_id = q.shipment_id
JOIN ReceivingManagers AS m ON q.manager_id = m.manager_id
WHERE b.is_overseas = 'Y';

CREATE VIEW RejectedOverseasShipments AS
SELECT f.farm_name, f.country, b.shipment_date, m.manager_name
FROM BulkShipments AS b
JOIN SupplierFarms AS f ON b.farm_id = f.farm_id
JOIN QualityInspections AS q ON b.shipment_id = q.shipment_id
JOIN ReceivingManagers AS m ON q.manager_id = m.manager_id
WHERE b.is_overseas = 'Y' AND q.passed = 'N';

SELECT design_name, flower_type, vase_style, specialist_name FROM CustomArrangements;
SELECT vase_style, on_hand, designs_waiting FROM ExoticVaseShortages;
SELECT van_plate, route_name, driver_name FROM DowntownRoutes;
SELECT route_name, driver_name, stops FROM RouteStopCounts ORDER BY stops DESC;
SELECT farm_name, shipment_date, manager_name FROM OverseasSourcing;
SELECT farm_name, country, shipment_date, manager_name FROM RejectedOverseasShipments;

