FROM BookedSessions AS bs
JOIN ArtistStations AS st ON st.station_id = bs.station_id
JOIN ClientFiles AS cf ON cf.client_id = bs.client_id
JOIN DesignPortfolios AS dp ON dp.design_id = bs.design_id
