CREATE TABLE Categories (category_id INTEGER PRIMARY KEY, category_name VARCHAR(50) NOT NULL);
CREATE TABLE Bakeries (bakery_id INTEGER PRIMARY KEY, bakery_name VARCHAR(50) NOT NULL);
CREATE TABLE DisplayTables (table_id INTEGER PRIMARY KEY, table_number VARCHAR(20) NOT NULL);
CREATE TABLE Judges (judge_id INTEGER PRIMARY KEY, judge_name VARCHAR(50) NOT NULL);
CREATE TABLE Entries (
    entry_id    INTEGER PRIMARY KEY,
    category_id INTEGER REFERENCES Categories(category_id),
    bakery_id   INTEGER REFERENCES Bakeries(bakery_id),
    table_id    INTEGER REFERENCES DisplayTables(table_id),
    judge_id    INTEGER REFERENCES Judges(judge_id)
);

CREATE VIEW v_wedding_cake_entries AS
SELECT c.category_name, b.bakery_name, d.table_number, j.judge_name
FROM Entries AS e
JOIN Categories AS c ON e.category_id = c.category_id
JOIN Bakeries AS b ON e.bakery_id = b.bakery_id
JOIN DisplayTables AS d ON e.table_id = d.table_id
JOIN Judges AS j ON e.judge_id = j.judge_id
WHERE c.category_name = 'wedding cake';

CREATE TABLE Frostings (frosting_id INTEGER PRIMARY KEY, flavor VARCHAR(50) NOT NULL);
CREATE TABLE Colorings (coloring_id INTEGER PRIMARY KEY, shade VARCHAR(50) NOT NULL);
CREATE TABLE Supervisors (supervisor_id INTEGER PRIMARY KEY, supervisor_name VARCHAR(50) NOT NULL);
CREATE TABLE MixingStations (
    station_id      INTEGER PRIMARY KEY,
    frosting_id     INTEGER REFERENCES Frostings(frosting_id),
    coloring_id     INTEGER REFERENCES Colorings(coloring_id),
    supervisor_id   INTEGER REFERENCES Supervisors(supervisor_id),
    ingredient_type VARCHAR(30) NOT NULL
);

CREATE VIEW v_vegan_ingredient_sourcing AS
SELECT f.flavor, col.shade, s.supervisor_name
FROM MixingStations AS m
JOIN Frostings AS f ON m.frosting_id = f.frosting_id
JOIN Colorings AS col ON m.coloring_id = col.coloring_id
JOIN Supervisors AS s ON m.supervisor_id = s.supervisor_id
WHERE m.ingredient_type = 'vegan';

CREATE TABLE Tickets (ticket_id INTEGER PRIMARY KEY, ticket_number VARCHAR(20) NOT NULL);
CREATE TABLE Scanners (scanner_id INTEGER PRIMARY KEY, scanner_code VARCHAR(20) NOT NULL);
CREATE TABLE Clerks (clerk_id INTEGER PRIMARY KEY, clerk_name VARCHAR(50) NOT NULL);
CREATE TABLE EventSchedule (schedule_id INTEGER PRIMARY KEY, final_hour_start TIMESTAMP NOT NULL, final_hour_end TIMESTAMP NOT NULL);
CREATE TABLE Ballots (
    ballot_id    INTEGER PRIMARY KEY,
    ticket_id    INTEGER REFERENCES Tickets(ticket_id),
    scanner_id   INTEGER REFERENCES Scanners(scanner_id),
    clerk_id     INTEGER REFERENCES Clerks(clerk_id),
    schedule_id  INTEGER REFERENCES EventSchedule(schedule_id),
    choice       VARCHAR(50) NOT NULL,
    submitted_at TIMESTAMP NOT NULL
);

CREATE VIEW v_final_hour_votes AS
SELECT t.ticket_number, bal.choice, cl.clerk_name
FROM Ballots AS bal
JOIN Tickets AS t ON bal.ticket_id = t.ticket_id
JOIN Scanners AS sc ON bal.scanner_id = sc.scanner_id
JOIN Clerks AS cl ON bal.clerk_id = cl.clerk_id
JOIN EventSchedule AS es ON bal.schedule_id = es.schedule_id
WHERE bal.submitted_at >= es.final_hour_start AND bal.submitted_at < es.final_hour_end;

CREATE VIEW v_wedding_cake_vote_counts AS
SELECT w.bakery_name, w.table_number, COUNT(*) AS vote_count
FROM v_wedding_cake_entries AS w
JOIN v_final_hour_votes AS v ON v.choice = w.bakery_name
GROUP BY w.bakery_name, w.table_number;

CREATE VIEW v_scanner_workload AS
SELECT sc.scanner_code, cl.clerk_name, COUNT(*) AS ballots_scanned
FROM Ballots AS bal
JOIN Scanners AS sc ON bal.scanner_id = sc.scanner_id
JOIN Clerks AS cl ON bal.clerk_id = cl.clerk_id
GROUP BY sc.scanner_code, cl.clerk_name;

