CREATE TABLE regions (region_id INT PRIMARY KEY, region_name VARCHAR(60));
CREATE TABLE laboratories (lab_id INT PRIMARY KEY, lab_name VARCHAR(60));
CREATE TABLE reef_zones (zone_id INT PRIMARY KEY, zone_name VARCHAR(60));
CREATE TABLE species (species_id INT PRIMARY KEY, species_name VARCHAR(60));
CREATE TABLE biologists (biologist_id INT PRIMARY KEY, first_name VARCHAR(40), last_name VARCHAR(40));
CREATE TABLE technicians (technician_id INT PRIMARY KEY, first_name VARCHAR(40), last_name VARCHAR(40));
CREATE TABLE equipment (equipment_id INT PRIMARY KEY, model VARCHAR(60));
CREATE TABLE sensor_deployments (deployment_id INT PRIMARY KEY, zone_id INT, reading_value DECIMAL(6,2),
    FOREIGN KEY (zone_id) REFERENCES reef_zones(zone_id));
CREATE TABLE field_observations (observation_id INT PRIMARY KEY, biologist_id INT, species_id INT, deployment_id INT,
    season VARCHAR(20), FOREIGN KEY (biologist_id) REFERENCES biologists(biologist_id),
    FOREIGN KEY (species_id) REFERENCES species(species_id),
    FOREIGN KEY (deployment_id) REFERENCES sensor_deployments(deployment_id));
CREATE TABLE maintenance_logs (log_id INT PRIMARY KEY, equipment_id INT, technician_id INT, calibration_date DATE,
    season VARCHAR(20), FOREIGN KEY (equipment_id) REFERENCES equipment(equipment_id),
    FOREIGN KEY (technician_id) REFERENCES technicians(technician_id));
CREATE TABLE lab_assignments (assignment_id INT PRIMARY KEY, technician_id INT, lab_id INT, region_id INT,
    FOREIGN KEY (technician_id) REFERENCES technicians(technician_id),
    FOREIGN KEY (lab_id) REFERENCES laboratories(lab_id), FOREIGN KEY (region_id) REFERENCES regions(region_id));

CREATE VIEW zone_readings AS SELECT d.deployment_id, z.zone_name, d.reading_value
    FROM sensor_deployments AS d
    INNER JOIN reef_zones AS z ON z.zone_id = d.zone_id;

CREATE VIEW lab_postings AS SELECT a.technician_id, l.lab_name, r.region_name
    FROM lab_assignments AS a
    INNER JOIN laboratories AS l ON l.lab_id = a.lab_id
    INNER JOIN regions AS r ON r.region_id = a.region_id;

DELIMITER //
CREATE FUNCTION observation_rows(p_season VARCHAR(20)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE n INT;
    SELECT COUNT(*) INTO n FROM field_observations AS o
    INNER JOIN biologists AS b ON b.biologist_id = o.biologist_id
    INNER JOIN species AS sp ON sp.species_id = o.species_id
    INNER JOIN zone_readings AS zr ON zr.deployment_id = o.deployment_id
    WHERE o.season = p_season;
    RETURN n;
END //

CREATE FUNCTION calibration_rows(p_season VARCHAR(20)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE n INT;
    SELECT COUNT(*) INTO n FROM maintenance_logs AS m
    INNER JOIN equipment AS e ON e.equipment_id = m.equipment_id
    INNER JOIN technicians AS t ON t.technician_id = m.technician_id
    INNER JOIN lab_postings AS lp ON lp.technician_id = t.technician_id
    WHERE m.season = p_season;
    RETURN n;
END //

CREATE PROCEDURE summarize(IN p_season VARCHAR(20))
BEGIN
    IF observation_rows(p_season) = 0 AND calibration_rows(p_season) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'no linked records for the requested season';
    END IF;

    SELECT CONCAT(b.first_name, ' ', b.last_name) AS biologist_name, zr.zone_name, sp.species_name, zr.reading_value
    FROM field_observations AS o
    INNER JOIN biologists AS b ON b.biologist_id = o.biologist_id
    INNER JOIN species AS sp ON sp.species_id = o.species_id
    INNER JOIN zone_readings AS zr ON zr.deployment_id = o.deployment_id
    WHERE o.season = p_season
    ORDER BY biologist_name, zr.zone_name, sp.species_name;

    SELECT e.model, CONCAT(t.first_name, ' ', t.last_name) AS technician_name, m.calibration_date, lp.lab_name
    FROM maintenance_logs AS m
    INNER JOIN equipment AS e ON e.equipment_id = m.equipment_id
    INNER JOIN technicians AS t ON t.technician_id = m.technician_id
    INNER JOIN lab_postings AS lp ON lp.technician_id = t.technician_id
    WHERE m.season = p_season
    ORDER BY e.model, m.calibration_date, lp.region_name;
END //
DELIMITER ;

