CREATE TABLE Parts (part_id INT PRIMARY KEY, part_name VARCHAR(80) NOT NULL, material_id INT NOT NULL);
CREATE TABLE CaliberParts (caliber_id INT NOT NULL, part_id INT NOT NULL, quantity INT NOT NULL, PRIMARY KEY (caliber_id, part_id));
CREATE TABLE Clients (client_id INT PRIMARY KEY, client_name VARCHAR(80) NOT NULL);
CREATE TABLE TimepieceModels (model_id INT PRIMARY KEY, model_name VARCHAR(80) NOT NULL);
CREATE TABLE Technicians (technician_id INT PRIMARY KEY, technician_name VARCHAR(80) NOT NULL);
CREATE TABLE Inspectors (inspector_id INT PRIMARY KEY, inspector_name VARCHAR(80) NOT NULL);
CREATE TABLE RepairTickets (ticket_id INT PRIMARY KEY, client_id INT NOT NULL, model_id INT NOT NULL, technician_id INT NOT NULL, ticket_year INT NOT NULL);
CREATE TABLE InspectionCertificates (certificate_id INT PRIMARY KEY, ticket_id INT NOT NULL, inspector_id INT NOT NULL);

CREATE VIEW PartSourcing AS
SELECT P.part_id, P.part_name, M.material_type, S.supplier_name
FROM Parts AS P, Materials AS M, Suppliers AS S
WHERE M.material_id = P.material_id
AND S.supplier_id = M.supplier_id;

CREATE VIEW CaliberBillOfMaterials AS
SELECT CP.caliber_id, CP.quantity, PS.part_name, PS.material_type, PS.supplier_name
FROM CaliberParts AS CP, PartSourcing AS PS
WHERE PS.part_id = CP.part_id;

CREATE VIEW TaskAssignments AS
SELECT T.task_id, T.task_year, T.caliber_id, W.watchmaker_name, C.designation
FROM AssemblyTasks AS T, Watchmakers AS W, Calibers AS C
WHERE W.watchmaker_id = T.watchmaker_id
AND C.caliber_id = T.caliber_id;

CREATE VIEW TicketDetails AS
SELECT R.ticket_id, R.ticket_year, CL.client_name, TM.model_name, TE.technician_name
FROM RepairTickets AS R, Clients AS CL, TimepieceModels AS TM, Technicians AS TE
WHERE CL.client_id = R.client_id
AND TM.model_id = R.model_id
AND TE.technician_id = R.technician_id;

CREATE VIEW CertifiedInspections AS
SELECT IC.ticket_id, I.inspector_name
FROM InspectionCertificates AS IC, Inspectors AS I
WHERE I.inspector_id = IC.inspector_id;

DELIMITER $$
CREATE PROCEDURE inventory(IN report_year INT)
BEGIN
    SELECT TA.watchmaker_name, TA.designation, BOM.part_name, BOM.material_type, BOM.supplier_name
    FROM TaskAssignments AS TA, CaliberBillOfMaterials AS BOM
    WHERE BOM.caliber_id = TA.caliber_id
    AND TA.task_year = report_year
    ORDER BY TA.watchmaker_name, TA.designation, BOM.part_name;

    SELECT TD.client_name, TD.model_name, TD.technician_name, CI.inspector_name
    FROM TicketDetails AS TD, CertifiedInspections AS CI
    WHERE CI.ticket_id = TD.ticket_id
    AND TD.ticket_year = report_year
    ORDER BY TD.client_name, TD.model_name;
END$$
DELIMITER ;

CALL inventory(2022);

DROP VIEW IF EXISTS v_cave_sensors;
CREATE VIEW v_cave_sensors AS
SELECT c.cave_id,
       c.cave_name,
       c.region,
       s.model AS sensor_model
FROM aging_caves AS c, humidity_sensors AS s
WHERE s.cave_id = c.cave_id;

DROP VIEW IF EXISTS v_delivery_logistics;
CREATE VIEW v_delivery_logistics AS
SELECT d.delivery_id,
       d.farm_id,
       dr.driver_name,
       v.vat_code
FROM daily_deliveries AS d, drivers AS dr, receiving_vats AS v
WHERE dr.driver_id = d.driver_id AND v.vat_id = d.vat_id;

DROP PROCEDURE IF EXISTS audit;
DELIMITER $$
CREATE PROCEDURE audit(IN in_region VARCHAR(100))
BEGIN
    DECLARE cheese_rows INT;
    DECLARE milk_rows INT;

    SELECT COUNT(*) INTO cheese_rows
    FROM production_batches AS pb, v_cave_sensors AS cs
    WHERE cs.cave_id = pb.cave_id AND cs.region = in_region;

    SELECT COUNT(*) INTO milk_rows
    FROM farms AS f, milk_suppliers AS ms
    WHERE ms.supplier_id = f.supplier_id AND ms.region = in_region;

    IF cheese_rows = 0 AND milk_rows = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'audit: no production or milk intake data for this region';
    END IF;

    SELECT cm.maker_name,
           pb.batch_code,
           cs.cave_name,
           cs.sensor_model,
           qi.inspector_name
    FROM cheesemakers AS cm, production_batches AS pb, v_cave_sensors AS cs, quality_inspections AS qi
    WHERE pb.maker_id = cm.maker_id AND cs.cave_id = pb.cave_id AND qi.batch_id = pb.batch_id AND cm.region = in_region
    ORDER BY cm.maker_name, pb.batch_code;

    SELECT ms.supplier_name,
           cb.breed_name,
           dl.driver_name,
           dl.vat_code
    FROM milk_suppliers AS ms, farms AS f, cow_breeds AS cb, v_delivery_logistics AS dl
    WHERE f.supplier_id = ms.supplier_id AND cb.breed_id = f.breed_id AND dl.farm_id = f.farm_id AND ms.region = in_region
    ORDER BY ms.supplier_name, dl.vat_code;
END$$
DELIMITER ;

CALL audit('Normandy');

