CREATE TABLE MakeupArtists (artist_id INT PRIMARY KEY, artist_name VARCHAR(60) NOT NULL);
CREATE TABLE Models (
    model_id   INT PRIMARY KEY,
    model_name VARCHAR(60) NOT NULL,
    artist_id  INT REFERENCES MakeupArtists(artist_id)
);
CREATE TABLE Designers (designer_id INT PRIMARY KEY, designer_name VARCHAR(60) NOT NULL);
CREATE TABLE Castings (
    casting_id  INT PRIMARY KEY,
    model_id    INT REFERENCES Models(model_id),
    designer_id INT REFERENCES Designers(designer_id)
);
CREATE TABLE Venues (venue_id INT PRIMARY KEY, venue_name VARCHAR(80) NOT NULL, city VARCHAR(60) NOT NULL);
CREATE TABLE Collections (
    collection_id   INT PRIMARY KEY,
    collection_name VARCHAR(80) NOT NULL,
    designer_id     INT REFERENCES Designers(designer_id),
    venue_id        INT REFERENCES Venues(venue_id)
);
CREATE TABLE Publications (publication_id INT PRIMARY KEY, publication_name VARCHAR(80) NOT NULL);
CREATE TABLE SecurityGuards (guard_id INT PRIMARY KEY, guard_name VARCHAR(60) NOT NULL);
CREATE TABLE SeatingZones (
    zone_id   INT PRIMARY KEY,
    zone_name VARCHAR(60) NOT NULL,
    venue_id  INT REFERENCES Venues(venue_id),
    guard_id  INT REFERENCES SecurityGuards(guard_id)
);
CREATE TABLE Photographers (photographer_id INT PRIMARY KEY, photographer_name VARCHAR(60) NOT NULL);
CREATE TABLE PressPasses (
    pass_id         INT PRIMARY KEY,
    photographer_id INT REFERENCES Photographers(photographer_id),
    publication_id  INT REFERENCES Publications(publication_id),
    zone_id         INT REFERENCES SeatingZones(zone_id)
);

CREATE VIEW casting_roster AS
SELECT M.model_id, M.model_name, D.designer_id, D.designer_name, A.artist_name
  FROM Models AS M
  JOIN Castings AS S ON S.model_id = M.model_id
  JOIN Designers AS D ON D.designer_id = S.designer_id
  JOIN MakeupArtists AS A ON A.artist_id = M.artist_id;

CREATE VIEW collection_schedule AS
SELECT C.collection_id, C.collection_name, C.designer_id, V.venue_name, V.city
  FROM Collections AS C
  JOIN Venues AS V ON V.venue_id = C.venue_id;

CREATE VIEW press_credentials AS
SELECT PP.pass_id, PP.zone_id, P.photographer_name, U.publication_name
  FROM PressPasses AS PP
  JOIN Photographers AS P ON P.photographer_id = PP.photographer_id
  JOIN Publications AS U ON U.publication_id = PP.publication_id;

CREATE VIEW zone_security AS
SELECT Z.zone_id, Z.zone_name, G.guard_name, V.city
  FROM SeatingZones AS Z
  JOIN SecurityGuards AS G ON G.guard_id = Z.guard_id
  JOIN Venues AS V ON V.venue_id = Z.venue_id;

DELIMITER //

CREATE PROCEDURE runway_manifest(IN p_city VARCHAR(60))
BEGIN
    SELECT R.model_name, R.designer_name, S.collection_name, S.venue_name, R.artist_name
      FROM casting_roster AS R
      JOIN collection_schedule AS S ON S.designer_id = R.designer_id
     WHERE S.city = p_city
     ORDER BY R.designer_name, R.model_name;
END //

CREATE PROCEDURE press_manifest(IN p_city VARCHAR(60))
BEGIN
    SELECT C.photographer_name, C.publication_name, Z.zone_name, Z.guard_name
      FROM press_credentials AS C
      JOIN zone_security AS Z ON Z.zone_id = C.zone_id
     WHERE Z.city = p_city
     ORDER BY C.publication_name, C.photographer_name;
END //

CREATE PROCEDURE `cast`(IN city VARCHAR(60))
BEGIN
    CALL runway_manifest(city);
    CALL press_manifest(city);
END //

DELIMITER ;

CALL `cast`('Paris');
CALL `cast`('Milan');

