CREATE TABLE BloodTypes (type_id INT PRIMARY KEY, type_name VARCHAR(20) NOT NULL);
CREATE TABLE Donors (donor_id INT PRIMARY KEY, donor_name VARCHAR(60) NOT NULL);
CREATE TABLE Phlebotomists (phlebotomist_id INT PRIMARY KEY, phlebotomist_name VARCHAR(60) NOT NULL);
CREATE TABLE CollectionDrives (drive_id INT PRIMARY KEY, location VARCHAR(80) NOT NULL, phlebotomist_id INT);
CREATE TABLE TestingLabs (lab_id INT PRIMARY KEY, lab_name VARCHAR(60) NOT NULL);
CREATE TABLE DonationEvents (event_id INT PRIMARY KEY, donor_id INT, type_id INT, drive_id INT, lab_id INT);
CREATE TABLE Hospitals (hospital_id INT PRIMARY KEY, hospital_name VARCHAR(80) NOT NULL);
CREATE TABLE Nurses (nurse_id INT PRIMARY KEY, nurse_name VARCHAR(60) NOT NULL);
CREATE TABLE BloodRequests (request_id INT PRIMARY KEY, hospital_id INT, type_id INT, nurse_id INT);
CREATE TABLE Couriers (courier_id INT PRIMARY KEY, courier_name VARCHAR(60) NOT NULL);
CREATE TABLE Vehicles (vehicle_id INT PRIMARY KEY, model VARCHAR(60) NOT NULL);
CREATE TABLE CourierDispatches (dispatch_id INT PRIMARY KEY, request_id INT, courier_id INT, vehicle_id INT);

CREATE VIEW DonorDonations AS
SELECT DE.event_id, D.donor_name, BT.type_name, DE.drive_id, DE.lab_id
FROM DonationEvents AS DE
INNER JOIN Donors AS D ON D.donor_id = DE.donor_id
INNER JOIN BloodTypes AS BT ON BT.type_id = DE.type_id;

CREATE VIEW DriveStaff AS
SELECT CD.drive_id, CD.location, P.phlebotomist_name
FROM CollectionDrives AS CD
INNER JOIN Phlebotomists AS P ON P.phlebotomist_id = CD.phlebotomist_id;

CREATE VIEW CollectionChain AS
SELECT DD.donor_name, DD.type_name, DS.location, DS.phlebotomist_name, TL.lab_name
FROM DonorDonations AS DD
INNER JOIN DriveStaff AS DS ON DS.drive_id = DD.drive_id
INNER JOIN TestingLabs AS TL ON TL.lab_id = DD.lab_id;

CREATE VIEW DispatchLogistics AS
SELECT CDS.request_id, C.courier_name, V.model
FROM CourierDispatches AS CDS
INNER JOIN Couriers AS C ON C.courier_id = CDS.courier_id
INNER JOIN Vehicles AS V ON V.vehicle_id = CDS.vehicle_id;

CREATE VIEW DeliveryChain AS
SELECT H.hospital_name, BT.type_name, DL.courier_name, DL.model, N.nurse_name
FROM BloodRequests AS BR
INNER JOIN BloodTypes AS BT ON BT.type_id = BR.type_id
INNER JOIN Hospitals AS H ON H.hospital_id = BR.hospital_id
INNER JOIN DispatchLogistics AS DL ON DL.request_id = BR.request_id
INNER JOIN Nurses AS N ON N.nurse_id = BR.nurse_id;

DELIMITER $$
CREATE PROCEDURE track(IN bloodtype VARCHAR(20))
BEGIN
    SELECT donor_name, type_name, location, phlebotomist_name, lab_name
    FROM CollectionChain
    WHERE type_name = bloodtype
    ORDER BY donor_name, location;

    SELECT hospital_name, courier_name, model, nurse_name
    FROM DeliveryChain
    WHERE type_name = bloodtype
    ORDER BY hospital_name, courier_name;
END$$
DELIMITER ;

CALL track('O-Negative');

