CREATE TABLE HistoricalEras (era_id INT PRIMARY KEY, era_name VARCHAR(60) NOT NULL);
CREATE TABLE MetalTypes (metal_id INT PRIMARY KEY, metal_name VARCHAR(60) NOT NULL);
CREATE TABLE MintCities (city_id INT PRIMARY KEY, city_name VARCHAR(80) NOT NULL);
CREATE TABLE Coins (
    coin_id   INT PRIMARY KEY,
    coin_name VARCHAR(80) NOT NULL,
    era_id    INT REFERENCES HistoricalEras(era_id),
    metal_id  INT REFERENCES MetalTypes(metal_id),
    city_id   INT REFERENCES MintCities(city_id)
);
CREATE TABLE Appraisers (appraiser_id INT PRIMARY KEY, appraiser_name VARCHAR(80) NOT NULL);
CREATE TABLE Evaluations (
    evaluation_id INT PRIMARY KEY,
    appraiser_id  INT REFERENCES Appraisers(appraiser_id),
    coin_id       INT REFERENCES Coins(coin_id),
    valuation     DECIMAL(12,2)
);
CREATE TABLE AuctionHouses (house_id INT PRIMARY KEY, house_name VARCHAR(80) NOT NULL);
CREATE TABLE Catalogers (cataloger_id INT PRIMARY KEY, cataloger_name VARCHAR(80) NOT NULL);
CREATE TABLE Bidders (bidder_id INT PRIMARY KEY, bidder_name VARCHAR(80) NOT NULL);
CREATE TABLE ShippingInsurancePolicies (
    policy_id     INT PRIMARY KEY,
    bidder_id     INT REFERENCES Bidders(bidder_id),
    provider_name VARCHAR(80) NOT NULL
);
CREATE TABLE SaleCatalogs (
    catalog_id        INT PRIMARY KEY,
    house_id          INT REFERENCES AuctionHouses(house_id),
    cataloger_id      INT REFERENCES Catalogers(cataloger_id),
    winning_bidder_id INT REFERENCES Bidders(bidder_id),
    era_id            INT REFERENCES HistoricalEras(era_id)
);

CREATE VIEW CoinProvenance AS
SELECT C.coin_id, C.coin_name, H.era_name, M.metal_name, T.city_name
FROM Coins AS C
JOIN HistoricalEras AS H ON C.era_id = H.era_id
JOIN MetalTypes AS M ON C.metal_id = M.metal_id
JOIN MintCities AS T ON C.city_id = T.city_id;

CREATE VIEW EvaluatedCoins AS
SELECT A.appraiser_name, P.coin_name, P.era_name, P.metal_name, P.city_name
FROM Appraisers AS A
JOIN Evaluations AS E ON A.appraiser_id = E.appraiser_id
JOIN CoinProvenance AS P ON E.coin_id = P.coin_id;

CREATE VIEW InsuredBidders AS
SELECT B.bidder_id, B.bidder_name, I.provider_name
FROM Bidders AS B
JOIN ShippingInsurancePolicies AS I ON B.bidder_id = I.bidder_id;

CREATE VIEW CatalogedSales AS
SELECT S.catalog_id, S.winning_bidder_id, S.era_id, AH.house_name, CG.cataloger_name
FROM AuctionHouses AS AH
JOIN SaleCatalogs AS S ON AH.house_id = S.house_id
JOIN Catalogers AS CG ON S.cataloger_id = CG.cataloger_id;

CREATE VIEW SaleParties AS
SELECT D.house_name, D.cataloger_name, IB.bidder_name, IB.provider_name, HE.era_name
FROM CatalogedSales AS D
JOIN InsuredBidders AS IB ON D.winning_bidder_id = IB.bidder_id
JOIN HistoricalEras AS HE ON D.era_id = HE.era_id;

DELIMITER //
CREATE PROCEDURE appraise(IN era VARCHAR(60))
BEGIN
    SELECT appraiser_name, coin_name, era_name, metal_name, city_name
    FROM EvaluatedCoins
    WHERE era_name = era
    ORDER BY appraiser_name, coin_name;

    SELECT house_name, cataloger_name, bidder_name, provider_name
    FROM SaleParties
    WHERE era_name = era
    ORDER BY house_name, bidder_name;
END //
DELIMITER ;

CALL appraise('Roman');

