CREATE TABLE Applicants (applicant_id INT PRIMARY KEY, full_name VARCHAR(120) NOT NULL);
CREATE TABLE VisaTypes (visa_type_id INT PRIMARY KEY, visa_type_name VARCHAR(80) NOT NULL);
CREATE TABLE Countries (country_id INT PRIMARY KEY, country_name VARCHAR(80) NOT NULL);
CREATE TABLE BackgroundCheckAgencies (agency_id INT PRIMARY KEY, agency_name VARCHAR(80) NOT NULL);
CREATE TABLE Officers (officer_id INT PRIMARY KEY, officer_name VARCHAR(120) NOT NULL,
    agency_id INT NOT NULL REFERENCES BackgroundCheckAgencies(agency_id));
CREATE TABLE VisaApplications (application_id INT PRIMARY KEY,
    applicant_id INT NOT NULL REFERENCES Applicants(applicant_id),
    visa_type_id INT NOT NULL REFERENCES VisaTypes(visa_type_id),
    destination_country_id INT NOT NULL REFERENCES Countries(country_id),
    officer_id INT NOT NULL REFERENCES Officers(officer_id));
CREATE TABLE RegionalDirectors (director_id INT PRIMARY KEY, director_name VARCHAR(120) NOT NULL);
CREATE TABLE Regions (region_id INT PRIMARY KEY, region_name VARCHAR(80) NOT NULL,
    director_id INT NOT NULL REFERENCES RegionalDirectors(director_id));
CREATE TABLE Consulates (consulate_id INT PRIMARY KEY, location_name VARCHAR(120) NOT NULL,
    region_id INT NOT NULL REFERENCES Regions(region_id),
    country_id INT NOT NULL REFERENCES Countries(country_id));
CREATE TABLE LocalStaff (staff_id INT PRIMARY KEY, staff_name VARCHAR(120) NOT NULL,
    consulate_id INT NOT NULL REFERENCES Consulates(consulate_id));
CREATE TABLE SecurityProtocols (protocol_id INT PRIMARY KEY, protocol_name VARCHAR(80) NOT NULL,
    consulate_id INT NOT NULL REFERENCES Consulates(consulate_id));

DELIMITER //
CREATE FUNCTION country_case_load(country VARCHAR(80)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total
    FROM VisaApplications AS VA
    JOIN Countries AS C ON C.country_id = VA.destination_country_id
    WHERE C.country_name = country;
    RETURN total;
END //

CREATE FUNCTION country_agency_coverage(country VARCHAR(80)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE total INT;
    SELECT COUNT(DISTINCT BCA.agency_id) INTO total
    FROM VisaApplications AS VA
    JOIN Countries AS C ON C.country_id = VA.destination_country_id
    JOIN Officers AS O ON O.officer_id = VA.officer_id
    JOIN BackgroundCheckAgencies AS BCA ON BCA.agency_id = O.agency_id
    WHERE C.country_name = country;
    RETURN total;
END //

CREATE FUNCTION country_consulate_load(country VARCHAR(80)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total
    FROM Consulates AS CO
    JOIN Countries AS C ON C.country_id = CO.country_id
    WHERE C.country_name = country;
    RETURN total;
END //

CREATE PROCEDURE report_applicant_cases(IN country VARCHAR(80))
BEGIN
    SELECT A.full_name, VT.visa_type_name, C.country_name, O.officer_name, BCA.agency_name
    FROM VisaApplications AS VA
    JOIN Applicants AS A ON A.applicant_id = VA.applicant_id
    JOIN VisaTypes AS VT ON VT.visa_type_id = VA.visa_type_id
    JOIN Countries AS C ON C.country_id = VA.destination_country_id
    JOIN Officers AS O ON O.officer_id = VA.officer_id
    JOIN BackgroundCheckAgencies AS BCA ON BCA.agency_id = O.agency_id
    WHERE C.country_name = country
    ORDER BY A.full_name, VT.visa_type_name;
END //

CREATE PROCEDURE report_consulate_oversight(IN country VARCHAR(80))
BEGIN
    SELECT CO.location_name, LS.staff_name, SP.protocol_name, RD.director_name
    FROM Consulates AS CO
    JOIN LocalStaff AS LS ON LS.consulate_id = CO.consulate_id
    JOIN SecurityProtocols AS SP ON SP.consulate_id = CO.consulate_id
    JOIN Regions AS R ON R.region_id = CO.region_id
    JOIN RegionalDirectors AS RD ON RD.director_id = R.director_id
    JOIN Countries AS HC ON HC.country_id = CO.country_id
    WHERE HC.country_name = country
    ORDER BY CO.location_name, LS.staff_name, SP.protocol_name;
END //

CREATE PROCEDURE process(IN country VARCHAR(80))
BEGIN
    IF country_case_load(country) = 0 AND country_consulate_load(country) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No immigration records for that country';
    END IF;
    SELECT country AS report_country,
           country_case_load(country) AS applications_on_file,
           country_agency_coverage(country) AS agencies_engaged,
           country_consulate_load(country) AS consulates_in_country;
    CALL report_applicant_cases(country);
    CALL report_consulate_oversight(country);
END //
DELIMITER ;

CALL process('Japan');

