    WHERE LS.consulate_id = CO.consulate_id
      AND SP.consulate_id = CO.consulate_id
      AND R.region_id = CO.region_id
      AND RD.director_id = R.director_id
      AND HC.country_id = CO.country_id
      AND HC.country_name = country
    ORDER BY CO.location_name, LS.staff_name, SP.protocol_name;
