CREATE TABLE Cutters (cutter_id INT PRIMARY KEY, cutter_name VARCHAR(60) NOT NULL);
CREATE TABLE MineOrigins (origin_id INT PRIMARY KEY, origin_name VARCHAR(60) NOT NULL);
CREATE TABLE RoughGemstones (rough_id INT PRIMARY KEY, gem_type VARCHAR(50) NOT NULL,
    origin_id INT REFERENCES MineOrigins(origin_id));
CREATE TABLE FacetPatterns (pattern_id INT PRIMARY KEY, pattern_name VARCHAR(60) NOT NULL);
CREATE TABLE CuttingJobs (job_id INT PRIMARY KEY, cutter_id INT REFERENCES Cutters(cutter_id),
    rough_id INT REFERENCES RoughGemstones(rough_id), pattern_id INT REFERENCES FacetPatterns(pattern_id));
CREATE TABLE Laboratories (lab_id INT PRIMARY KEY, lab_name VARCHAR(60) NOT NULL);
CREATE TABLE GradingCertificates (cert_id INT PRIMARY KEY, job_id INT REFERENCES CuttingJobs(job_id),
    lab_id INT REFERENCES Laboratories(lab_id));
CREATE TABLE RegionalDistributors (distributor_id INT PRIMARY KEY, distributor_name VARCHAR(60) NOT NULL);
CREATE TABLE JewelryBrands (brand_id INT PRIMARY KEY, brand_name VARCHAR(60) NOT NULL,
    distributor_id INT REFERENCES RegionalDistributors(distributor_id));
CREATE TABLE WholesaleBuyers (buyer_id INT PRIMARY KEY, buyer_name VARCHAR(60) NOT NULL,
    brand_id INT REFERENCES JewelryBrands(brand_id));
CREATE TABLE RetailStores (store_id INT PRIMARY KEY, store_name VARCHAR(60) NOT NULL,
    distributor_id INT REFERENCES RegionalDistributors(distributor_id));
CREATE TABLE CompletedGemstones (stone_id INT PRIMARY KEY, job_id INT REFERENCES CuttingJobs(job_id),
    gem_type VARCHAR(50) NOT NULL, buyer_id INT REFERENCES WholesaleBuyers(buyer_id));

CREATE VIEW v_rough_provenance AS
SELECT R.rough_id, R.gem_type, M.origin_name
FROM RoughGemstones AS R
INNER JOIN MineOrigins AS M ON M.origin_id = R.origin_id;

CREATE VIEW v_job_certification AS
SELECT G.job_id, L.lab_name
FROM GradingCertificates AS G
INNER JOIN Laboratories AS L ON L.lab_id = G.lab_id;

CREATE VIEW v_brand_distribution AS
SELECT B.brand_id, B.brand_name, D.distributor_id, D.distributor_name
FROM JewelryBrands AS B
INNER JOIN RegionalDistributors AS D ON D.distributor_id = B.distributor_id;

CREATE VIEW v_distributor_outlets AS
SELECT D.distributor_id, S.store_name
FROM RegionalDistributors AS D
INNER JOIN RetailStores AS S ON S.distributor_id = D.distributor_id;

DELIMITER //
CREATE PROCEDURE polish(IN gem VARCHAR(50))
BEGIN
    SELECT C.cutter_name, P.gem_type, P.origin_name, F.pattern_name, T.lab_name
    FROM Cutters AS C
    INNER JOIN CuttingJobs AS J ON J.cutter_id = C.cutter_id
    INNER JOIN v_rough_provenance AS P ON P.rough_id = J.rough_id
    INNER JOIN FacetPatterns AS F ON F.pattern_id = J.pattern_id
    INNER JOIN v_job_certification AS T ON T.job_id = J.job_id
    WHERE P.gem_type = gem
    ORDER BY C.cutter_name, T.lab_name;

    SELECT W.buyer_name, BD.brand_name, BD.distributor_name, O.store_name
    FROM CompletedGemstones AS CG
    INNER JOIN WholesaleBuyers AS W ON W.buyer_id = CG.buyer_id
    INNER JOIN v_brand_distribution AS BD ON BD.brand_id = W.brand_id
    INNER JOIN v_distributor_outlets AS O ON O.distributor_id = BD.distributor_id
    WHERE CG.gem_type = gem
    ORDER BY W.buyer_name, O.store_name;
END //
DELIMITER ;

CALL polish('Diamond');

