CREATE TABLE manufacturers (manufacturer_id INTEGER PRIMARY KEY, manufacturer_name VARCHAR(80) NOT NULL);

CREATE TABLE golfers (golfer_id INTEGER PRIMARY KEY, golfer_name VARCHAR(80) NOT NULL,
    manufacturer_id INTEGER REFERENCES manufacturers (manufacturer_id));

CREATE TABLE sponsors (sponsor_id INTEGER PRIMARY KEY, sponsor_name VARCHAR(80) NOT NULL);

CREATE TABLE courses (course_id INTEGER PRIMARY KEY, course_name VARCHAR(80) NOT NULL,
    sponsor_id INTEGER REFERENCES sponsors (sponsor_id));

CREATE TABLE caddies (caddie_id INTEGER PRIMARY KEY, caddie_name VARCHAR(80) NOT NULL);

CREATE TABLE entries (entry_id INTEGER PRIMARY KEY, tour_name VARCHAR(80) NOT NULL,
    golfer_id INTEGER REFERENCES golfers (golfer_id),
    course_id INTEGER REFERENCES courses (course_id),
    caddie_id INTEGER REFERENCES caddies (caddie_id));

CREATE TABLE networks (network_id INTEGER PRIMARY KEY, network_name VARCHAR(80) NOT NULL);

CREATE TABLE commentators (commentator_id INTEGER PRIMARY KEY, commentator_name VARCHAR(80) NOT NULL);

CREATE TABLE broadcast_rights (right_id INTEGER PRIMARY KEY, tour_name VARCHAR(80) NOT NULL,
    network_id INTEGER REFERENCES networks (network_id),
    commentator_id INTEGER REFERENCES commentators (commentator_id));

CREATE TABLE holes (hole_id INTEGER PRIMARY KEY, hole_location_name VARCHAR(80) NOT NULL);

CREATE TABLE camera_operators (operator_id INTEGER PRIMARY KEY, operator_name VARCHAR(80) NOT NULL,
    network_id INTEGER REFERENCES networks (network_id),
    hole_id INTEGER REFERENCES holes (hole_id));

CREATE VIEW golfer_equipment AS
SELECT g.golfer_id, g.golfer_name, m.manufacturer_name
FROM golfers AS g
INNER JOIN manufacturers AS m ON m.manufacturer_id = g.manufacturer_id;

CREATE VIEW sponsored_courses AS
SELECT c.course_id, c.course_name, s.sponsor_name
FROM courses AS c
INNER JOIN sponsors AS s ON s.sponsor_id = c.sponsor_id;

CREATE VIEW hole_assignments AS
SELECT co.operator_id, co.operator_name, co.network_id, h.hole_location_name
FROM camera_operators AS co
INNER JOIN holes AS h ON h.hole_id = co.hole_id;

CREATE VIEW broadcast_teams AS
SELECT br.tour_name, n.network_id, n.network_name, cm.commentator_name
FROM broadcast_rights AS br
INNER JOIN networks AS n ON n.network_id = br.network_id
INNER JOIN commentators AS cm ON cm.commentator_id = br.commentator_id;

CREATE PROCEDURE score (IN tour VARCHAR(80))
BEGIN
    SELECT ge.golfer_name, sc.course_name, sc.sponsor_name, cd.caddie_name, ge.manufacturer_name
    FROM entries AS e
    INNER JOIN golfer_equipment AS ge ON ge.golfer_id = e.golfer_id
    INNER JOIN sponsored_courses AS sc ON sc.course_id = e.course_id
    INNER JOIN caddies AS cd ON cd.caddie_id = e.caddie_id
    WHERE e.tour_name = tour
    ORDER BY ge.golfer_name;

    SELECT bt.network_name, bt.commentator_name, ha.operator_name, ha.hole_location_name
    FROM broadcast_teams AS bt
    INNER JOIN hole_assignments AS ha ON ha.network_id = bt.network_id
    WHERE bt.tour_name = tour
    ORDER BY bt.network_name, ha.operator_name;
END;

CALL score('Masters');

