CREATE TABLE FretWireTypes (fretwire_id INT PRIMARY KEY, fretwire_name VARCHAR(60) NOT NULL);
CREATE TABLE VarnishFinishes (finish_id INT PRIMARY KEY, finish_name VARCHAR(60) NOT NULL);
CREATE TABLE AcousticModels (model_id INT PRIMARY KEY, model_name VARCHAR(60) NOT NULL, species_id INT, fretwire_id INT);
CREATE TABLE BuildOrders (order_id INT PRIMARY KEY, luthier_id INT, model_id INT, finish_id INT);
CREATE TABLE Musicians (musician_id INT PRIMARY KEY, musician_name VARCHAR(60) NOT NULL);
CREATE TABLE SoldGuitars (sale_id INT PRIMARY KEY, order_id INT, musician_id INT);
