CREATE VIEW ModelBuildSpecs AS
SELECT AM.model_id, AM.model_name, WS.species_name, FW.fretwire_name
FROM AcousticModels AS AM
INNER JOIN WoodSpecies AS WS ON WS.species_id = AM.species_id
INNER JOIN FretWireTypes AS FW ON FW.fretwire_id = AM.fretwire_id;

CREATE VIEW BuildDetails AS
SELECT BO.order_id, L.luthier_name, MBS.model_name, MBS.species_name,
       MBS.fretwire_name, VF.finish_name
FROM Luthiers AS L
INNER JOIN BuildOrders AS BO ON BO.luthier_id = L.luthier_id
INNER JOIN ModelBuildSpecs AS MBS ON MBS.model_id = BO.model_id
INNER JOIN VarnishFinishes AS VF ON VF.finish_id = BO.finish_id;

CREATE VIEW VenueCrew AS
SELECT CV.venue_id, CV.venue_name, SE.engineer_name
FROM ConcertVenues AS CV
INNER JOIN SoundEngineers AS SE ON SE.engineer_id = CV.engineer_id;

CREATE VIEW PerformanceDetails AS
SELECT CP.musician_id, VC.venue_name, MM.microphone_name, VC.engineer_name
FROM ConcertPerformances AS CP
INNER JOIN VenueCrew AS VC ON VC.venue_id = CP.venue_id
INNER JOIN MicrophoneModels AS MM ON MM.microphone_id = CP.microphone_id;

CREATE VIEW GuitarOwnership AS
SELECT SG.sale_id, M.musician_id, M.musician_name, MBS.species_name
FROM SoldGuitars AS SG
INNER JOIN Musicians AS M ON M.musician_id = SG.musician_id
INNER JOIN BuildOrders AS BO ON BO.order_id = SG.order_id
