FROM Turbines AS T
INNER JOIN ExtractionWells AS W ON W.well_id = T.well_id
INNER JOIN GeologicalFaults AS F ON F.fault_id = W.fault_id
INNER JOIN HeatExchangers AS H ON H.exchanger_id = T.exchanger_id;

