FROM Engineers AS E
INNER JOIN ShiftLogs AS L ON L.engineer_id = E.engineer_id;

CREATE VIEW SensorLoggers AS
SELECT S.sensor_id, S.sensor_name, D.logger_model
FROM EmissionSensors AS S
INNER JOIN DataLoggers AS D ON D.logger_id = S.logger_id;

CREATE VIEW InspectorAgencies AS
SELECT I.inspector_id, I.inspector_name, A.agency_name, I.zone
FROM EnvironmentalInspectors AS I
INNER JOIN RegulatoryAgencies AS A ON A.agency_id = I.agency_id;

CREATE VIEW InspectorSensors AS
