CREATE PROCEDURE measure(IN in_zone VARCHAR(40))
BEGIN
    SELECT ET.engineer_name, TA.model_name, TA.well_name, TA.fault_name, TA.exchanger_name
    FROM EngineerTurbines AS ET
    INNER JOIN TurbineAssets AS TA ON TA.turbine_id = ET.turbine_id
    WHERE ET.zone = in_zone
    ORDER BY ET.engineer_name, TA.model_name;

    SELECT IR.inspector_name, SL.sensor_name, SL.logger_model, IR.agency_name
    FROM InspectorSensors AS IR
    INNER JOIN SensorLoggers AS SL ON SL.sensor_id = IR.sensor_id
    WHERE IR.zone = in_zone
    ORDER BY IR.inspector_name, SL.sensor_name;
END$$
DELIMITER ;

