CREATE TABLE DeckBrands (deck_brand_id INT PRIMARY KEY, brand_name VARCHAR(60) NOT NULL);

CREATE TABLE Skaters (skater_id INT PRIMARY KEY, skater_name VARCHAR(60) NOT NULL,
    deck_brand_id INT NOT NULL REFERENCES DeckBrands (deck_brand_id));

CREATE TABLE TrickCategories (trick_category_id INT PRIMARY KEY, category_name VARCHAR(60) NOT NULL);

CREATE TABLE RampObstacles (ramp_obstacle_id INT PRIMARY KEY, obstacle_name VARCHAR(60) NOT NULL);

CREATE TABLE Judges (judge_id INT PRIMARY KEY, judge_name VARCHAR(60) NOT NULL);

CREATE TABLE CompetitionRuns (run_id INT PRIMARY KEY,
    skater_id INT NOT NULL REFERENCES Skaters (skater_id),
    trick_category_id INT NOT NULL REFERENCES TrickCategories (trick_category_id),
    ramp_obstacle_id INT NOT NULL REFERENCES RampObstacles (ramp_obstacle_id),
    judge_id INT NOT NULL REFERENCES Judges (judge_id),
    tier VARCHAR(20) NOT NULL);

CREATE TABLE EditingStudios (studio_id INT PRIMARY KEY, studio_name VARCHAR(60) NOT NULL);

CREATE TABLE Events (event_id INT PRIMARY KEY, event_name VARCHAR(60) NOT NULL,
    tier VARCHAR(20) NOT NULL,
    studio_id INT NOT NULL REFERENCES EditingStudios (studio_id));

CREATE TABLE EnergyDrinkSponsors (sponsor_id INT PRIMARY KEY, sponsor_name VARCHAR(60) NOT NULL,
    event_id INT NOT NULL REFERENCES Events (event_id));

CREATE TABLE CameraLenses (lens_id INT PRIMARY KEY, lens_model VARCHAR(60) NOT NULL);

CREATE TABLE Videographers (videographer_id INT PRIMARY KEY, videographer_name VARCHAR(60) NOT NULL,
    event_id INT NOT NULL REFERENCES Events (event_id),
    lens_id INT NOT NULL REFERENCES CameraLenses (lens_id));

CREATE VIEW SkaterDecks AS
SELECT S.skater_id, S.skater_name, DB.brand_name
FROM Skaters AS S
INNER JOIN DeckBrands AS DB ON DB.deck_brand_id = S.deck_brand_id;

CREATE VIEW RunDetails AS
SELECT CR.run_id, CR.skater_id, CR.tier, TC.category_name, RO.obstacle_name, J.judge_name
FROM CompetitionRuns AS CR
INNER JOIN TrickCategories AS TC ON TC.trick_category_id = CR.trick_category_id
INNER JOIN RampObstacles AS RO ON RO.ramp_obstacle_id = CR.ramp_obstacle_id
INNER JOIN Judges AS J ON J.judge_id = CR.judge_id;

CREATE VIEW EventStudios AS
SELECT E.event_id, E.event_name, E.tier, ES.studio_name
FROM Events AS E
INNER JOIN EditingStudios AS ES ON ES.studio_id = E.studio_id;

CREATE VIEW CameraCrew AS
SELECT V.videographer_id, V.event_id, V.videographer_name, CL.lens_model
FROM Videographers AS V
INNER JOIN CameraLenses AS CL ON CL.lens_id = V.lens_id;

DELIMITER //

CREATE PROCEDURE judge (IN tier VARCHAR(20))
BEGIN
    SELECT SD.skater_name, RD.category_name, RD.obstacle_name, SD.brand_name, RD.judge_name
    FROM RunDetails AS RD
    INNER JOIN SkaterDecks AS SD ON SD.skater_id = RD.skater_id
    WHERE RD.tier = tier
    ORDER BY SD.skater_name, RD.category_name;

    SELECT SP.sponsor_name, CC.videographer_name, CC.lens_model, ES.studio_name
    FROM EnergyDrinkSponsors AS SP
    INNER JOIN EventStudios AS ES ON ES.event_id = SP.event_id
    INNER JOIN CameraCrew AS CC ON CC.event_id = ES.event_id
    WHERE ES.tier = tier
    ORDER BY SP.sponsor_name, CC.videographer_name;
END //

DELIMITER ;

