CREATE TABLE ClearingHouses (
    clearing_house_id INT PRIMARY KEY,
    house_name VARCHAR(80) NOT NULL
);
CREATE TABLE Attorneys (
    attorney_id INT PRIMARY KEY,
    attorney_name VARCHAR(80) NOT NULL
);
CREATE TABLE Frameworks (
    framework_id INT PRIMARY KEY,
    framework_name VARCHAR(80) NOT NULL
);
CREATE TABLE PenalCodes (
    penal_code_id INT PRIMARY KEY,
    code_name VARCHAR(80) NOT NULL
);
CREATE TABLE Exchanges (
    exchange_id INT PRIMARY KEY,
    exchange_name VARCHAR(80) NOT NULL,
    clearing_house_id INT REFERENCES ClearingHouses(clearing_house_id)
);
CREATE TABLE Assets (
    asset_id INT PRIMARY KEY,
    asset_name VARCHAR(80) NOT NULL
);
CREATE TABLE Strategies (
    strategy_id INT PRIMARY KEY,
    strategy_name VARCHAR(80) NOT NULL
);
CREATE TABLE Traders (
    trader_id INT PRIMARY KEY,
    trader_name VARCHAR(80) NOT NULL,
    attorney_id INT REFERENCES Attorneys(attorney_id)
);
CREATE TABLE Officers (
    officer_id INT PRIMARY KEY,
    officer_name VARCHAR(80) NOT NULL,
    framework_id INT REFERENCES Frameworks(framework_id)
);
CREATE TABLE ExecutionLogs (
    log_id INT PRIMARY KEY,
    trader_id INT REFERENCES Traders(trader_id),
    strategy_id INT REFERENCES Strategies(strategy_id),
    exchange_id INT REFERENCES Exchanges(exchange_id),
    asset_id INT REFERENCES Assets(asset_id)
);
CREATE TABLE ComplianceFlags (
    flag_id INT PRIMARY KEY,
    log_id INT REFERENCES ExecutionLogs(log_id),
    officer_id INT REFERENCES Officers(officer_id),
    penal_code_id INT REFERENCES PenalCodes(penal_code_id)
);

CREATE VIEW SettlementRoutes AS
SELECT X.exchange_id, X.exchange_name, C.house_name
FROM Exchanges AS X
JOIN ClearingHouses AS C ON C.clearing_house_id = X.clearing_house_id;

CREATE VIEW TraderDefense AS
SELECT T.trader_id, T.trader_name, D.attorney_name
FROM Traders AS T
JOIN Attorneys AS D ON D.attorney_id = T.attorney_id;

CREATE VIEW FlagReview AS
SELECT F.log_id, O.officer_name, R.framework_name, P.code_name
FROM ComplianceFlags AS F
JOIN Officers AS O ON O.officer_id = F.officer_id
JOIN Frameworks AS R ON R.framework_id = O.framework_id
JOIN PenalCodes AS P ON P.penal_code_id = F.penal_code_id;

DELIMITER $$
CREATE PROCEDURE audit(IN market VARCHAR(80))
BEGIN
    SELECT TD.trader_name, S.strategy_name, V.exchange_name, A.asset_name, V.house_name
    FROM ExecutionLogs AS L
    JOIN TraderDefense AS TD ON TD.trader_id = L.trader_id
    JOIN Strategies AS S ON S.strategy_id = L.strategy_id
    JOIN SettlementRoutes AS V ON V.exchange_id = L.exchange_id
    JOIN Assets AS A ON A.asset_id = L.asset_id
    WHERE V.exchange_name = market
    ORDER BY TD.trader_name, A.asset_name;

    SELECT FR.officer_name, FR.framework_name, FR.code_name, TD.attorney_name
    FROM ExecutionLogs AS L
    JOIN Exchanges AS X ON X.exchange_id = L.exchange_id
    JOIN FlagReview AS FR ON FR.log_id = L.log_id
    JOIN TraderDefense AS TD ON TD.trader_id = L.trader_id
    WHERE X.exchange_name = market
    ORDER BY FR.officer_name, FR.code_name;
END$$

CREATE PROCEDURE strategy_exposure(IN market VARCHAR(80))
BEGIN
    SELECT S.strategy_name, COUNT(*) AS flagged_executions
    FROM ComplianceFlags AS F
    JOIN ExecutionLogs AS L ON L.log_id = F.log_id
    JOIN Strategies AS S ON S.strategy_id = L.strategy_id
    JOIN Exchanges AS X ON X.exchange_id = L.exchange_id
    WHERE X.exchange_name = market
    GROUP BY S.strategy_name
    ORDER BY flagged_executions DESC, S.strategy_name;
END$$
DELIMITER ;

CALL audit('NASDAQ');
CALL strategy_exposure('NASDAQ');

