CREATE TABLE InverterModels (inverter_id INT PRIMARY KEY, model_name VARCHAR(60) NOT NULL);
CREATE TABLE BatteryStorage (battery_id INT PRIMARY KEY, battery_name VARCHAR(60) NOT NULL);
CREATE TABLE GridSubstations (substation_id INT PRIMARY KEY, substation_name VARCHAR(60) NOT NULL);
CREATE TABLE WeatherStations (station_id INT PRIMARY KEY, station_name VARCHAR(60) NOT NULL);
CREATE TABLE CloudCoverSensors (sensor_id INT PRIMARY KEY, station_id INT, sensor_name VARCHAR(60) NOT NULL);
CREATE TABLE RegionalDispatchers (dispatcher_id INT PRIMARY KEY, dispatcher_name VARCHAR(60) NOT NULL);
CREATE TABLE MaintenanceVehicles (vehicle_id INT PRIMARY KEY, dispatcher_id INT, vehicle_name VARCHAR(60) NOT NULL);
CREATE TABLE SolarArrays (array_id INT PRIMARY KEY, array_name VARCHAR(60) NOT NULL,
    inverter_id INT, battery_id INT, substation_id INT, station_id INT);
CREATE TABLE Technicians (technician_id INT PRIMARY KEY, technician_name VARCHAR(60) NOT NULL,
    region VARCHAR(40) NOT NULL);
CREATE TABLE DiagnosticTickets (ticket_id INT PRIMARY KEY, technician_id INT, array_id INT, dispatcher_id INT);

CREATE VIEW ArrayEquipment AS
SELECT A.array_id, A.array_name, A.station_id, I.model_name, B.battery_name, G.substation_name
FROM SolarArrays AS A
INNER JOIN InverterModels AS I ON I.inverter_id = A.inverter_id
INNER JOIN BatteryStorage AS B ON B.battery_id = A.battery_id
INNER JOIN GridSubstations AS G ON G.substation_id = A.substation_id;

CREATE VIEW StationSensors AS
SELECT W.station_id, W.station_name, C.sensor_name
FROM WeatherStations AS W
INNER JOIN CloudCoverSensors AS C ON C.station_id = W.station_id;

CREATE VIEW DispatchFleet AS
SELECT R.dispatcher_id, R.dispatcher_name, V.vehicle_name
FROM RegionalDispatchers AS R
INNER JOIN MaintenanceVehicles AS V ON V.dispatcher_id = R.dispatcher_id;

CREATE VIEW RegionalTickets AS
SELECT T.region, T.technician_name, D.ticket_id, D.array_id, D.dispatcher_id
FROM Technicians AS T
INNER JOIN DiagnosticTickets AS D ON D.technician_id = T.technician_id;

DELIMITER //
CREATE PROCEDURE diagnose(IN region VARCHAR(40))
BEGIN
    SELECT RT.technician_name, E.array_name, E.model_name, E.battery_name, E.substation_name
    FROM RegionalTickets AS RT
    INNER JOIN ArrayEquipment AS E ON E.array_id = RT.array_id
    WHERE RT.region = region
    ORDER BY RT.technician_name, E.array_name;

    SELECT S.station_name, S.sensor_name, F.dispatcher_name, F.vehicle_name
    FROM RegionalTickets AS RT
    INNER JOIN ArrayEquipment AS E ON E.array_id = RT.array_id
    INNER JOIN StationSensors AS S ON S.station_id = E.station_id
    INNER JOIN DispatchFleet AS F ON F.dispatcher_id = RT.dispatcher_id
    WHERE RT.region = region
    ORDER BY S.station_name, S.sensor_name;
END //
DELIMITER ;

