CREATE PROCEDURE diagnose(IN region VARCHAR(40))
BEGIN
    SELECT RT.technician_name, E.array_name, E.model_name, E.battery_name, E.substation_name
    FROM RegionalTickets AS RT, ArrayEquipment AS E
    WHERE E.array_id = RT.array_id
    AND RT.region = region
    ORDER BY RT.technician_name, E.array_name;

    SELECT S.station_name, S.sensor_name, F.dispatcher_name, F.vehicle_name
    FROM RegionalTickets AS RT, ArrayEquipment AS E, StationSensors AS S, DispatchFleet AS F
    WHERE E.array_id = RT.array_id
    AND S.station_id = E.station_id
    AND F.dispatcher_id = RT.dispatcher_id
    AND RT.region = region
    ORDER BY S.station_name, S.sensor_name;
END //
DELIMITER ;

