CREATE TABLE noble_houses (
    house_id INT PRIMARY KEY,
    banner   VARCHAR(60) NOT NULL
);
CREATE TABLE competing_knights (
    knight_id   INT PRIMARY KEY,
    knight_name VARCHAR(60) NOT NULL,
    house_id    INT,
    season      VARCHAR(20) NOT NULL
);
CREATE TABLE warhorses (
    horse_id  INT PRIMARY KEY,
    knight_id INT,
    breed     VARCHAR(40) NOT NULL
);
CREATE TABLE reinforced_lances (
    lance_id  INT PRIMARY KEY,
    knight_id INT,
    wood_type VARCHAR(40) NOT NULL
);
CREATE TABLE tournament_heralds (
    herald_id   INT PRIMARY KEY,
    knight_id   INT,
    herald_name VARCHAR(60) NOT NULL
);

CREATE VIEW mounted_knights AS
SELECT k.knight_id, k.knight_name, k.season, h.banner, w.breed
FROM competing_knights AS k
JOIN noble_houses AS h ON h.house_id = k.house_id
JOIN warhorses AS w ON w.knight_id = k.knight_id;

DELIMITER //

CREATE PROCEDURE joust(IN in_season VARCHAR(20))
BEGIN
    DECLARE v_fielded INT;

    SELECT COUNT(*) INTO v_fielded
    FROM competing_knights AS k
    JOIN noble_houses AS h ON h.house_id = k.house_id
    WHERE k.season = in_season;

    IF v_fielded = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'no house fielded a knight in that season';
    END IF;

    SELECT m.banner, m.knight_name, m.breed, l.wood_type
    FROM mounted_knights AS m
    JOIN reinforced_lances AS l ON l.knight_id = m.knight_id
    WHERE m.season = in_season
    ORDER BY m.banner, m.knight_name;

    SELECT m.knight_name, m.breed, t.herald_name, m.banner
    FROM mounted_knights AS m
    JOIN tournament_heralds AS t ON t.knight_id = m.knight_id
    WHERE m.season = in_season
    ORDER BY m.knight_name;

    SELECT m.banner, m.knight_name, m.breed, l.wood_type, t.herald_name
    FROM mounted_knights AS m
    JOIN reinforced_lances AS l ON l.knight_id = m.knight_id
    JOIN tournament_heralds AS t ON t.knight_id = m.knight_id
    WHERE m.season = in_season
    ORDER BY m.banner, t.herald_name;
END //

DELIMITER ;

