    FROM competing_knights AS k, noble_houses AS h
    WHERE h.house_id = k.house_id AND k.season = in_season;

    IF v_fielded = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'no house fielded a knight in that season';
