    FROM mounted_knights AS m, reinforced_lances AS l
    WHERE l.knight_id = m.knight_id AND m.season = in_season
    ORDER BY m.banner, m.knight_name;

    SELECT m.knight_name, m.breed, t.herald_name, m.banner
    FROM mounted_knights AS m, tournament_heralds AS t
