    route          VARCHAR(40) NOT NULL,
    departure_time TIME NOT NULL,
    flight_date    DATE NOT NULL,
    duration_min   INT NOT NULL,
    helicopter_id  INT REFERENCES helicopters(helicopter_id)
);

CREATE TABLE tour_groups (
    group_id     INT PRIMARY KEY,
    group_size   INT NOT NULL,
    agent_id     INT REFERENCES booking_agents(agent_id),
    itinerary_id INT REFERENCES itineraries(itinerary_id)
);

CREATE TABLE tour_guides (
    guide_id     INT PRIMARY KEY,
    guide_name   VARCHAR(60) NOT NULL,
    itinerary_id INT REFERENCES itineraries(itinerary_id)
);

CREATE VIEW crewed_flights AS
SELECT it.itinerary_id, it.route, it.departure_time, it.flight_date,
       it.duration_min, h.registration, gd.guide_name
FROM itineraries AS it, helicopters AS h, tour_guides AS gd
WHERE h.helicopter_id = it.helicopter_id AND gd.itinerary_id = it.itinerary_id;

CREATE VIEW agency_bookings AS
SELECT ba.agent_id, ba.agency, tg.group_id, tg.group_size, tg.itinerary_id
FROM booking_agents AS ba, tour_groups AS tg
WHERE tg.agent_id = ba.agent_id;

DELIMITER //

CREATE PROCEDURE fly(IN route VARCHAR(40))
BEGIN
    SELECT ab.agency, ab.group_size, it.departure_time, h.registration
    FROM agency_bookings AS ab, itineraries AS it, helicopters AS h
    WHERE it.itinerary_id = ab.itinerary_id AND h.helicopter_id = it.helicopter_id AND it.route = route
    ORDER BY it.departure_time;

    SELECT cf.registration, cf.duration_min, cf.guide_name, tg.group_size
    FROM crewed_flights AS cf, tour_groups AS tg
    WHERE tg.itinerary_id = cf.itinerary_id AND cf.route = route
    ORDER BY cf.registration, cf.guide_name;

    SELECT ab.agency, ab.group_size, cf.flight_date, cf.guide_name, cf.registration
    FROM agency_bookings AS ab, crewed_flights AS cf
    WHERE cf.itinerary_id = ab.itinerary_id AND cf.route = route
    ORDER BY cf.flight_date, ab.agency;
END //

DELIMITER ;

