CREATE TABLE Stages (
    stage_id INT PRIMARY KEY, stage_size VARCHAR(30) NOT NULL, genre VARCHAR(40) NOT NULL
);

CREATE TABLE Puppets (
    puppet_id INT PRIMARY KEY, character_name VARCHAR(60) NOT NULL, stage_id INT NOT NULL REFERENCES Stages(stage_id)
);

CREATE TABLE Strings (
    string_id INT PRIMARY KEY, tension VARCHAR(20) NOT NULL, puppet_id INT NOT NULL REFERENCES Puppets(puppet_id)
);

CREATE TABLE Backdrops (
    backdrop_id INT PRIMARY KEY, painted_scene VARCHAR(80) NOT NULL, stage_id INT NOT NULL REFERENCES Stages(stage_id)
);

CREATE TABLE Puppeteers (
    puppeteer_id INT PRIMARY KEY, puppeteer_name VARCHAR(60) NOT NULL, puppet_id INT NOT NULL REFERENCES Puppets(puppet_id)
);

DELIMITER //

CREATE PROCEDURE rehearsal_check(IN p_genre VARCHAR(40))
BEGIN
    SELECT s.stage_size, COUNT(DISTINCT p.puppet_id) AS strung_puppets
    FROM Stages AS s
    INNER JOIN Puppets AS p ON p.stage_id = s.stage_id
    INNER JOIN Strings AS t ON t.puppet_id = p.puppet_id
    WHERE s.genre = p_genre
    GROUP BY s.stage_size;

    SELECT m.puppeteer_name, COUNT(DISTINCT p.puppet_id) AS puppets_handled
    FROM Puppeteers AS m
    INNER JOIN Puppets AS p ON p.puppet_id = m.puppet_id
    INNER JOIN Stages AS s ON s.stage_id = p.stage_id
    WHERE s.genre = p_genre
    GROUP BY m.puppeteer_name;

    SELECT s.stage_size, b.painted_scene, COUNT(DISTINCT p.puppet_id) AS puppets_on_scene
    FROM Stages AS s
    INNER JOIN Backdrops AS b ON b.stage_id = s.stage_id
    INNER JOIN Puppets AS p ON p.stage_id = s.stage_id
    WHERE s.genre = p_genre
    GROUP BY s.stage_size, b.painted_scene;
END //

CREATE PROCEDURE animate(IN p_genre VARCHAR(40))
BEGIN
    SELECT s.stage_size, p.character_name, t.tension, b.painted_scene
    FROM Stages AS s
    INNER JOIN Puppets AS p ON p.stage_id = s.stage_id
    INNER JOIN Strings AS t ON t.puppet_id = p.puppet_id
    INNER JOIN Backdrops AS b ON b.stage_id = s.stage_id
    WHERE s.genre = p_genre
    ORDER BY s.stage_size, p.character_name, b.painted_scene;

    SELECT p.character_name, t.tension, m.puppeteer_name, s.stage_size
    FROM Puppets AS p
    INNER JOIN Strings AS t ON t.puppet_id = p.puppet_id
    INNER JOIN Puppeteers AS m ON m.puppet_id = p.puppet_id
    INNER JOIN Stages AS s ON s.stage_id = p.stage_id
    WHERE s.genre = p_genre
    ORDER BY m.puppeteer_name, p.character_name;

    SELECT s.stage_size, p.character_name, t.tension, b.painted_scene, m.puppeteer_name
    FROM Stages AS s
    INNER JOIN Puppets AS p ON p.stage_id = s.stage_id
    INNER JOIN Strings AS t ON t.puppet_id = p.puppet_id
    INNER JOIN Backdrops AS b ON b.stage_id = s.stage_id
    INNER JOIN Puppeteers AS m ON m.puppet_id = p.puppet_id
    WHERE s.genre = p_genre
    ORDER BY s.stage_size, p.character_name, b.painted_scene, m.puppeteer_name;
END //

DELIMITER ;

