CREATE TABLE hunters (hunter_id INT PRIMARY KEY, hunter_name VARCHAR(60) NOT NULL, license_no VARCHAR(20) NOT NULL);
CREATE TABLE dogs (dog_id INT PRIMARY KEY, dog_name VARCHAR(60) NOT NULL, breed VARCHAR(40), hunter_id INT REFERENCES hunters (hunter_id));
CREATE TABLE forests (forest_id INT PRIMARY KEY, region VARCHAR(60) NOT NULL, hectares DECIMAL(9,2));
CREATE TABLE buyers (buyer_id INT PRIMARY KEY, buyer_name VARCHAR(60) NOT NULL, city VARCHAR(60));
CREATE TABLE yields (yield_id INT AUTO_INCREMENT PRIMARY KEY, hunter_id INT REFERENCES hunters (hunter_id),
    dog_id INT REFERENCES dogs (dog_id), forest_id INT REFERENCES forests (forest_id),
    season VARCHAR(20) NOT NULL, weight_kg DECIMAL(8,2) NOT NULL);
CREATE TABLE sales (sale_id INT AUTO_INCREMENT PRIMARY KEY, yield_id INT REFERENCES yields (yield_id),
    buyer_id INT REFERENCES buyers (buyer_id), amount DECIMAL(10,2) NOT NULL,
    pay_status VARCHAR(20) NOT NULL, sold_on DATE NOT NULL);

DELIMITER $$

CREATE PROCEDURE register_catch(IN p_hunter_id INT, IN p_dog_id INT, IN p_forest_id INT,
                                IN p_season VARCHAR(20), IN p_weight DECIMAL(8,2))
BEGIN
    DECLARE v_teams INT;
    SELECT COUNT(*) INTO v_teams
    FROM dogs AS d
    JOIN hunters AS h ON h.hunter_id = d.hunter_id
    WHERE d.dog_id = p_dog_id AND h.hunter_id = p_hunter_id;
    IF v_teams = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'dog is not handled by that hunter';
    END IF;
    INSERT INTO yields (hunter_id, dog_id, forest_id, season, weight_kg)
    VALUES (p_hunter_id, p_dog_id, p_forest_id, p_season, p_weight);
END$$

CREATE PROCEDURE record_sale(IN p_yield_id INT, IN p_buyer_id INT, IN p_amount DECIMAL(10,2),
                             IN p_status VARCHAR(20), IN p_sold_on DATE)
BEGIN
    DECLARE v_traceable INT;
    SELECT COUNT(*) INTO v_traceable
    FROM yields AS y
    JOIN hunters AS h ON h.hunter_id = y.hunter_id
    WHERE y.yield_id = p_yield_id;
    IF v_traceable = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'yield has no registered hunter';
    END IF;
    INSERT INTO sales (yield_id, buyer_id, amount, pay_status, sold_on)
    VALUES (p_yield_id, p_buyer_id, p_amount, p_status, p_sold_on);
END$$

CREATE PROCEDURE summarize(IN p_season VARCHAR(20))
BEGIN
    SELECT h.hunter_name, d.dog_name, f.region, y.weight_kg
    FROM yields AS y
    JOIN hunters AS h ON h.hunter_id = y.hunter_id
    JOIN dogs AS d ON d.dog_id = y.dog_id
    JOIN forests AS f ON f.forest_id = y.forest_id
    WHERE y.season = p_season
    ORDER BY h.hunter_name, d.dog_name;

    SELECT f.region, b.buyer_name, SUM(s.amount) AS total_amount
    FROM forests AS f
    JOIN yields AS y ON y.forest_id = f.forest_id
    JOIN sales AS s ON s.yield_id = y.yield_id
    JOIN buyers AS b ON b.buyer_id = s.buyer_id
    WHERE y.season = p_season AND s.pay_status = 'cleared'
    GROUP BY f.region, b.buyer_name
    ORDER BY total_amount DESC;

    SELECT h.hunter_name, b.buyer_name, s.sold_on
    FROM hunters AS h
    JOIN yields AS y ON y.hunter_id = h.hunter_id
    JOIN sales AS s ON s.yield_id = y.yield_id
    JOIN buyers AS b ON b.buyer_id = s.buyer_id
    WHERE y.season = p_season
    ORDER BY s.sold_on, h.hunter_name;
END$$

DELIMITER ;

