CREATE TABLE dogs (dog_id INT PRIMARY KEY, dog_name VARCHAR(60) NOT NULL, breed VARCHAR(40), hunter_id INT REFERENCES hunters (hunter_id));
CREATE TABLE forests (forest_id INT PRIMARY KEY, region VARCHAR(60) NOT NULL, hectares DECIMAL(9,2));
CREATE TABLE buyers (buyer_id INT PRIMARY KEY, buyer_name VARCHAR(60) NOT NULL, city VARCHAR(60));
CREATE TABLE yields (yield_id INT AUTO_INCREMENT PRIMARY KEY, hunter_id INT REFERENCES hunters (hunter_id),
    dog_id INT REFERENCES dogs (dog_id), forest_id INT REFERENCES forests (forest_id),
    season VARCHAR(20) NOT NULL, weight_kg DECIMAL(8,2) NOT NULL);
CREATE TABLE sales (sale_id INT AUTO_INCREMENT PRIMARY KEY, yield_id INT REFERENCES yields (yield_id),
    buyer_id INT REFERENCES buyers (buyer_id), amount DECIMAL(10,2) NOT NULL,
    pay_status VARCHAR(20) NOT NULL, sold_on DATE NOT NULL);

DELIMITER $$

CREATE PROCEDURE register_catch(IN p_hunter_id INT, IN p_dog_id INT, IN p_forest_id INT,
                                IN p_season VARCHAR(20), IN p_weight DECIMAL(8,2))
BEGIN
    DECLARE v_teams INT;
    SELECT COUNT(*) INTO v_teams
    FROM dogs AS d, hunters AS h
    WHERE h.hunter_id = d.hunter_id AND d.dog_id = p_dog_id AND h.hunter_id = p_hunter_id;
