CREATE PROCEDURE summarize(IN p_season VARCHAR(20))
BEGIN
    SELECT h.hunter_name, d.dog_name, f.region, y.weight_kg
    FROM yields AS y, hunters AS h, dogs AS d, forests AS f
    WHERE h.hunter_id = y.hunter_id
      AND d.dog_id = y.dog_id
      AND f.forest_id = y.forest_id
      AND y.season = p_season
    ORDER BY h.hunter_name, d.dog_name;

    SELECT f.region, b.buyer_name, SUM(s.amount) AS total_amount
    FROM forests AS f, yields AS y, sales AS s, buyers AS b
    WHERE y.forest_id = f.forest_id
      AND s.yield_id = y.yield_id
      AND b.buyer_id = s.buyer_id
      AND y.season = p_season AND s.pay_status = 'cleared'
    GROUP BY f.region, b.buyer_name
    ORDER BY total_amount DESC;

    SELECT h.hunter_name, b.buyer_name, s.sold_on
    FROM hunters AS h, yields AS y, sales AS s, buyers AS b
    WHERE y.hunter_id = h.hunter_id
      AND s.yield_id = y.yield_id
      AND b.buyer_id = s.buyer_id
      AND y.season = p_season
    ORDER BY s.sold_on, h.hunter_name;
END$$

