CREATE TABLE Sponsors (sponsor_id INT PRIMARY KEY, brand VARCHAR(60) NOT NULL);
CREATE TABLE Events (event_id INT PRIMARY KEY, city VARCHAR(60) NOT NULL, event_year INT NOT NULL);
CREATE TABLE Obstacles (obstacle_id INT PRIMARY KEY, difficulty VARCHAR(30) NOT NULL, event_id INT REFERENCES Events(event_id));
CREATE TABLE Judges (judge_id INT PRIMARY KEY, judge_name VARCHAR(60) NOT NULL, event_id INT REFERENCES Events(event_id));

CREATE TABLE Athletes (
    athlete_id   INT PRIMARY KEY,
    athlete_name VARCHAR(60) NOT NULL,
    sponsor_id   INT REFERENCES Sponsors(sponsor_id),
    event_id     INT REFERENCES Events(event_id)
);

CREATE TABLE Scores (
    score_id    INT PRIMARY KEY,
    athlete_id  INT REFERENCES Athletes(athlete_id),
    judge_id    INT REFERENCES Judges(judge_id),
    obstacle_id INT REFERENCES Obstacles(obstacle_id),
    score_value DECIMAL(4,2) NOT NULL
);

CREATE VIEW athlete_entries AS
SELECT A.athlete_id, A.athlete_name, A.event_id, E.city, E.event_year, S.brand
FROM Athletes AS A, Events AS E, Sponsors AS S
WHERE A.event_id = E.event_id
AND S.sponsor_id = A.sponsor_id;

CREATE VIEW score_details AS
SELECT SC.score_id, SC.score_value, A.athlete_id, A.athlete_name, A.event_id,
       J.judge_id, J.judge_name, J.event_id AS judge_event_id,
       O.obstacle_id, O.difficulty
FROM Scores AS SC, Athletes AS A, Judges AS J, Obstacles AS O
WHERE SC.athlete_id = A.athlete_id
AND SC.judge_id = J.judge_id
AND SC.obstacle_id = O.obstacle_id;

DELIMITER $$

CREATE PROCEDURE `rank`(IN in_year INT)
BEGIN
    DECLARE linked_rows INT;

    SELECT COUNT(*) INTO linked_rows
    FROM Events AS E, Obstacles AS O, athlete_entries AS AE
    WHERE O.event_id = E.event_id
    AND AE.event_id = E.event_id
    AND E.event_year = in_year;

    IF linked_rows = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No linked event records for the requested year';
    END IF;

    SELECT AE.athlete_name, O.difficulty, AE.city, AE.brand
    FROM athlete_entries AS AE, Obstacles AS O
    WHERE O.event_id = AE.event_id
    AND AE.event_year = in_year
    ORDER BY AE.athlete_name, O.difficulty;

    SELECT E.city, SD.judge_name, SD.difficulty, SD.score_value
    FROM Events AS E, score_details AS SD, Obstacles AS O
    WHERE SD.judge_event_id = E.event_id
    AND O.obstacle_id = SD.obstacle_id AND O.event_id = E.event_id
    AND SD.score_value > 9
      AND E.event_year = in_year
    ORDER BY SD.score_value DESC, E.city;

    SELECT SD.athlete_name, SD.judge_name, SD.score_value
    FROM score_details AS SD, Events AS E
    WHERE SD.event_id = E.event_id AND SD.judge_event_id = E.event_id
    AND E.event_year = in_year
    ORDER BY SD.athlete_name, SD.score_value DESC;
END$$

DELIMITER ;

CALL `rank`(2023);

