-- Reporting module for the billiard parlor system.

CREATE TABLE parlor_tables (table_id INT PRIMARY KEY, table_number INT NOT NULL);
CREATE TABLE cues (cue_id INT PRIMARY KEY, brand VARCHAR(50) NOT NULL, table_id INT NOT NULL);
CREATE TABLE players (player_id INT PRIMARY KEY, player_name VARCHAR(80) NOT NULL, cue_id INT NOT NULL);
CREATE TABLE tournaments (tournament_id INT PRIMARY KEY, title VARCHAR(80) NOT NULL, week INT NOT NULL);
CREATE TABLE referees (referee_id INT PRIMARY KEY, referee_name VARCHAR(80) NOT NULL, tournament_id INT NOT NULL);
CREATE TABLE matches (
    match_id INT PRIMARY KEY, tournament_id INT NOT NULL, referee_id INT NOT NULL,
    table_id INT NOT NULL, player_id INT NOT NULL, duration_min INT NOT NULL,
    foul_called BOOLEAN NOT NULL, winner_name VARCHAR(80) NOT NULL
);

DELIMITER //

CREATE FUNCTION week_match_count(w INT) RETURNS INT
    READS SQL DATA
BEGIN
    DECLARE played INT;
    SELECT COUNT(*) INTO played
    FROM matches AS m
    JOIN tournaments AS tr ON tr.tournament_id = m.tournament_id
    WHERE tr.week = w;
    RETURN played;
END //

CREATE PROCEDURE report(IN week INT)
BEGIN
    IF week_match_count(week) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'no matches recorded for the requested week';
    END IF;

    SELECT t.table_number, c.brand, p.player_name, tr.title
    FROM parlor_tables AS t
    JOIN cues AS c ON c.table_id = t.table_id
    JOIN players AS p ON p.cue_id = c.cue_id
    JOIN matches AS m ON m.player_id = p.player_id
    JOIN tournaments AS tr ON tr.tournament_id = m.tournament_id
    WHERE tr.week = week
    ORDER BY t.table_number, p.player_name;

    SELECT tr.title, r.referee_name, m.duration_min, t.table_number
    FROM tournaments AS tr
    JOIN referees AS r ON r.tournament_id = tr.tournament_id
    JOIN matches AS m ON m.referee_id = r.referee_id AND m.tournament_id = tr.tournament_id
    JOIN parlor_tables AS t ON t.table_id = m.table_id
    WHERE m.foul_called = TRUE AND tr.week = week
    ORDER BY tr.title, m.duration_min DESC;

    SELECT p.player_name, r.referee_name, m.winner_name
    FROM players AS p
    JOIN matches AS m ON m.player_id = p.player_id
    JOIN referees AS r ON r.referee_id = m.referee_id
    JOIN tournaments AS tr ON tr.tournament_id = m.tournament_id
    WHERE tr.week = week
    ORDER BY p.player_name, m.match_id;
END //

CREATE PROCEDURE report_week_range(IN first_week INT, IN last_week INT)
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE w INT;
    DECLARE weeks CURSOR FOR
        SELECT DISTINCT tr.week
        FROM tournaments AS tr
        JOIN matches AS m ON m.tournament_id = tr.tournament_id
        WHERE tr.week BETWEEN first_week AND last_week
        ORDER BY tr.week;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN weeks;
    week_loop: LOOP
        FETCH weeks INTO w;
        IF done = 1 THEN
            LEAVE week_loop;
        END IF;
        CALL report(w);
    END LOOP;
    CLOSE weeks;
END //

DELIMITER ;

CALL report(12);
CALL report_week_range(10, 14);

