DELIMITER //
CREATE PROCEDURE sign_focus(IN in_year INT)
BEGIN
    SELECT s.element, p.planet_name, COUNT(*) AS reading_count
    FROM readings AS r
    INNER JOIN signs AS s ON s.sign_id = r.sign_id
    INNER JOIN planets AS p ON p.planet_id = r.planet_id
    WHERE YEAR(r.reading_date) = in_year
    GROUP BY s.element, p.planet_name
    ORDER BY reading_count DESC, s.element;
