CREATE PROCEDURE astrologer_revenue(IN in_year INT)
BEGIN
    SELECT a.astrologer_name, SUM(pr.amount) AS total_billed
    FROM readings AS r
    INNER JOIN astrologers AS a ON a.astrologer_id = r.astrologer_id
    INNER JOIN paid_readings AS pr ON pr.reading_id = r.reading_id
    WHERE YEAR(r.reading_date) = in_year
    GROUP BY a.astrologer_name
    ORDER BY total_billed DESC;
END //
CREATE PROCEDURE predict(IN in_year INT)
BEGIN
    SELECT a.astrologer_name, c.client_name, p.planet_name, s.element
    FROM readings AS r
    INNER JOIN astrologers AS a ON a.astrologer_id = r.astrologer_id
    INNER JOIN clients AS c ON c.client_id = r.client_id
    INNER JOIN planets AS p ON p.planet_id = r.planet_id
    INNER JOIN signs AS s ON s.sign_id = r.sign_id
    WHERE YEAR(r.reading_date) = in_year
    ORDER BY a.astrologer_name, c.client_name;

    SELECT c.client_name, r.theme, p.planet_name, pay.amount
    FROM readings AS r
    INNER JOIN clients AS c ON c.client_id = r.client_id
    INNER JOIN planets AS p ON p.planet_id = r.planet_id
    INNER JOIN payments AS pay ON pay.reading_id = r.reading_id
    WHERE YEAR(r.reading_date) = in_year
      AND pay.amount > 50
    ORDER BY pay.amount DESC;

    SELECT a.astrologer_name, r.theme, pay.amount
    FROM readings AS r
    INNER JOIN astrologers AS a ON a.astrologer_id = r.astrologer_id
    INNER JOIN clients AS c ON c.client_id = r.client_id
    INNER JOIN payments AS pay ON pay.reading_id = r.reading_id
    WHERE YEAR(r.reading_date) = in_year
    ORDER BY a.astrologer_name, pay.amount DESC;
END //
DELIMITER ;

