CREATE TABLE beaches (beach_id INT PRIMARY KEY, city VARCHAR(60) NOT NULL);

CREATE TABLE tools (tool_id INT PRIMARY KEY, tool_type VARCHAR(60) NOT NULL);

CREATE TABLE teams (team_id INT PRIMARY KEY, team_name VARCHAR(80) NOT NULL,
    beach_id INT NOT NULL REFERENCES beaches(beach_id), season_year INT NOT NULL);

CREATE TABLE builders (builder_id INT PRIMARY KEY, builder_name VARCHAR(80) NOT NULL,
    team_id INT NOT NULL REFERENCES teams(team_id), tool_id INT NOT NULL REFERENCES tools(tool_id));

CREATE TABLE judges (judge_id INT PRIMARY KEY, judge_name VARCHAR(80) NOT NULL,
    beach_id INT NOT NULL REFERENCES beaches(beach_id));

CREATE TABLE scores (score_id INT PRIMARY KEY, judge_id INT NOT NULL REFERENCES judges(judge_id),
    team_id INT NOT NULL REFERENCES teams(team_id), score_value INT NOT NULL, season_year INT NOT NULL);

DELIMITER $$

CREATE FUNCTION rostered_team_count(p_year INT) RETURNS INT
READS SQL DATA
BEGIN
    DECLARE v_total INT;
    SELECT COUNT(*) INTO v_total
    FROM teams AS t
    INNER JOIN beaches AS be ON t.beach_id = be.beach_id
    WHERE t.season_year = p_year;
    RETURN v_total;
END$$

CREATE FUNCTION linked_score_count(p_year INT) RETURNS INT
READS SQL DATA
BEGIN
    DECLARE v_total INT;
    SELECT COUNT(*) INTO v_total
    FROM scores AS s
    INNER JOIN judges AS j ON s.judge_id = j.judge_id
    INNER JOIN teams AS t ON s.team_id = t.team_id
    WHERE s.season_year = p_year
      AND t.season_year = p_year;
    RETURN v_total;
END$$

CREATE PROCEDURE roster_report(IN p_year INT)
BEGIN
    SELECT b.builder_name, t.team_name, be.city, tl.tool_type
    FROM builders AS b
    INNER JOIN teams AS t ON b.team_id = t.team_id
    INNER JOIN beaches AS be ON t.beach_id = be.beach_id
    INNER JOIN tools AS tl ON b.tool_id = tl.tool_id
    WHERE t.season_year = p_year
    ORDER BY b.builder_name;
END$$

CREATE PROCEDURE perfect_ten_report(IN p_year INT)
BEGIN
    SELECT be.city, j.judge_name, s.score_value, t.team_name
    FROM beaches AS be
    INNER JOIN judges AS j ON be.beach_id = j.beach_id
    INNER JOIN scores AS s ON j.judge_id = s.judge_id
    INNER JOIN teams AS t ON s.team_id = t.team_id
    WHERE s.score_value = 10
      AND s.season_year = p_year
      AND t.season_year = p_year
    ORDER BY be.city, t.team_name;
END$$

CREATE PROCEDURE builder_score_report(IN p_year INT)
BEGIN
    SELECT b.builder_name, j.judge_name, s.score_value
    FROM builders AS b
    INNER JOIN teams AS t ON b.team_id = t.team_id
    INNER JOIN scores AS s ON t.team_id = s.team_id
    INNER JOIN judges AS j ON s.judge_id = j.judge_id
    WHERE t.season_year = p_year
      AND s.season_year = p_year
    ORDER BY b.builder_name, j.judge_name;
END$$

CREATE PROCEDURE judge(IN p_year INT)
BEGIN
    IF rostered_team_count(p_year) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No teams registered for the requested season';
    END IF;
    IF linked_score_count(p_year) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No judged scores recorded for the requested season';
    END IF;
    CALL roster_report(p_year);
    CALL perfect_ten_report(p_year);
    CALL builder_score_report(p_year);
END$$

DELIMITER ;

CALL judge(2024);

