CREATE TABLE yoyos (yoyo_id INT PRIMARY KEY, brand VARCHAR(40) NOT NULL);
CREATE TABLE strings (string_id INT PRIMARY KEY, material VARCHAR(40) NOT NULL);
CREATE TABLE players (player_id INT PRIMARY KEY, name VARCHAR(60) NOT NULL,
    yoyo_id INT NOT NULL REFERENCES yoyos(yoyo_id), string_id INT NOT NULL REFERENCES strings(string_id));
CREATE TABLE tricks (trick_id INT PRIMARY KEY, player_id INT NOT NULL REFERENCES players(player_id),
    difficulty VARCHAR(20) NOT NULL, event_month CHAR(7) NOT NULL);
CREATE TABLE judges (judge_id INT PRIMARY KEY, name VARCHAR(60) NOT NULL);
CREATE TABLE points (point_id INT PRIMARY KEY, trick_id INT NOT NULL REFERENCES tricks(trick_id),
    judge_id INT NOT NULL REFERENCES judges(judge_id), value DECIMAL(5,2) NOT NULL, flawless TINYINT(1) NOT NULL);

DELIMITER //

CREATE FUNCTION month_scored_tricks(in_month CHAR(7)) RETURNS INT DETERMINISTIC
BEGIN
    DECLARE tally INT;
    SELECT COUNT(DISTINCT t.trick_id) INTO tally
    FROM tricks AS t
    INNER JOIN points AS pt ON pt.trick_id = t.trick_id
    WHERE t.event_month = in_month;
    RETURN tally;
END //

CREATE PROCEDURE score_equipment_digest(IN in_month CHAR(7))
BEGIN
    SELECT y.brand AS yoyo_brand, s.material AS string_material, COUNT(*) AS trick_count
    FROM players AS p
    INNER JOIN yoyos AS y ON y.yoyo_id = p.yoyo_id
    INNER JOIN strings AS s ON s.string_id = p.string_id
    INNER JOIN tricks AS t ON t.player_id = p.player_id
    WHERE t.event_month = in_month
    GROUP BY y.brand, s.material
    ORDER BY trick_count DESC, y.brand;

    SELECT j.name AS judge_name, AVG(pt.value) AS average_points, SUM(pt.flawless) AS flawless_awards
    FROM judges AS j
    INNER JOIN points AS pt ON pt.judge_id = j.judge_id
    INNER JOIN tricks AS t ON t.trick_id = pt.trick_id
    WHERE t.event_month = in_month
    GROUP BY j.name
    ORDER BY average_points DESC;
END //

CREATE PROCEDURE score(IN in_month CHAR(7))
BEGIN
    IF month_scored_tricks(in_month) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'no scored tricks for the requested month';
    END IF;

    SELECT p.name AS player_name, y.brand AS yoyo_brand, s.material AS string_material, t.difficulty
    FROM players AS p
    INNER JOIN yoyos AS y ON y.yoyo_id = p.yoyo_id
    INNER JOIN strings AS s ON s.string_id = p.string_id
    INNER JOIN tricks AS t ON t.player_id = p.player_id
    WHERE t.event_month = in_month
    ORDER BY p.name, t.difficulty;

    SELECT t.difficulty, j.name AS judge_name, pt.value AS point_value, y.brand AS yoyo_brand
    FROM tricks AS t
    INNER JOIN points AS pt ON pt.trick_id = t.trick_id
    INNER JOIN judges AS j ON j.judge_id = pt.judge_id
    INNER JOIN players AS p ON p.player_id = t.player_id
    INNER JOIN yoyos AS y ON y.yoyo_id = p.yoyo_id
    WHERE pt.flawless = 1
      AND t.event_month = in_month
    ORDER BY pt.value DESC, j.name;

    SELECT p.name AS player_name, j.name AS judge_name, pt.value AS point_value
    FROM players AS p
    INNER JOIN tricks AS t ON t.player_id = p.player_id
    INNER JOIN points AS pt ON pt.trick_id = t.trick_id
    INNER JOIN judges AS j ON j.judge_id = pt.judge_id
    WHERE t.event_month = in_month
    ORDER BY pt.value DESC, p.name;
END //

