    fighter_id INT NOT NULL REFERENCES fighters(fighter_id),
    string_id INT NOT NULL REFERENCES strings(string_id));

CREATE TABLE referees (referee_id INT PRIMARY KEY, referee_name VARCHAR(60) NOT NULL);

CREATE TABLE matches (match_id INT PRIMARY KEY, venue_id INT NOT NULL REFERENCES venues(venue_id),
    referee_id INT NOT NULL REFERENCES referees(referee_id),
    kite_id INT NOT NULL REFERENCES kites(kite_id), duration_minutes INT NOT NULL,
    ended_string_cut TINYINT NOT NULL, winner VARCHAR(60) NOT NULL, festival_season VARCHAR(10) NOT NULL);

CREATE VIEW fighter_kite_string AS
SELECT F.fighter_id, F.fighter_name, F.venue_id, F.festival_season, K.kite_id, K.shape, S.abrasive
FROM fighters AS F
INNER JOIN kites AS K ON K.fighter_id = F.fighter_id
INNER JOIN strings AS S ON S.string_id = K.string_id;

CREATE VIEW match_details AS
SELECT M.match_id, M.venue_id, M.kite_id, M.duration_minutes, M.ended_string_cut,
       M.winner, M.festival_season, R.referee_name, K.shape
FROM matches AS M
INNER JOIN referees AS R ON R.referee_id = M.referee_id
INNER JOIN kites AS K ON K.kite_id = M.kite_id;

DELIMITER $$

CREATE PROCEDURE tally(IN season VARCHAR(10))
BEGIN
    SELECT FKS.fighter_name, FKS.shape, FKS.abrasive, V.park
    FROM fighter_kite_string AS FKS
    INNER JOIN venues AS V ON V.venue_id = FKS.venue_id
    WHERE FKS.festival_season = season
      AND V.festival_season = season
    ORDER BY FKS.fighter_name;

    SELECT V.park, MD.referee_name, MD.duration_minutes, MD.shape
    FROM venues AS V
    INNER JOIN match_details AS MD ON MD.venue_id = V.venue_id
    WHERE MD.festival_season = season
      AND MD.ended_string_cut = 1
    ORDER BY MD.duration_minutes DESC;

    SELECT FKS.fighter_name, MD.referee_name, MD.winner
    FROM fighter_kite_string AS FKS
    INNER JOIN match_details AS MD ON MD.kite_id = FKS.kite_id
    WHERE MD.festival_season = season
    ORDER BY MD.match_id;
END$$

