CREATE TABLE investigators (
    investigator_id INT PRIMARY KEY,
    investigator_name VARCHAR(60) NOT NULL
);

CREATE TABLE farmers (
    farmer_id INT PRIMARY KEY,
    farmer_name VARCHAR(60) NOT NULL
);

CREATE TABLE fields (
    field_id INT PRIMARY KEY,
    farmer_id INT NOT NULL REFERENCES farmers (farmer_id),
    investigator_id INT NOT NULL REFERENCES investigators (investigator_id),
    acreage VARCHAR(30) NOT NULL,
    discovery_year INT NOT NULL
);

CREATE TABLE patterns (
    pattern_id INT PRIMARY KEY,
    field_id INT NOT NULL REFERENCES fields (field_id),
    geometry VARCHAR(40) NOT NULL
);

CREATE TABLE tools (
    tool_id INT PRIMARY KEY,
    investigator_id INT NOT NULL REFERENCES investigators (investigator_id),
    instrument VARCHAR(40) NOT NULL
);

CREATE TABLE reports (
    report_id INT PRIMARY KEY,
    pattern_id INT NOT NULL REFERENCES patterns (pattern_id),
    tool_id INT NOT NULL REFERENCES tools (tool_id),
    conclusion VARCHAR(120) NOT NULL,
    anomaly_confirmed TINYINT NOT NULL
);

CREATE VIEW field_registry AS
SELECT f.field_id, f.discovery_year, f.acreage, i.investigator_name, o.farmer_name
FROM fields AS f
INNER JOIN investigators AS i ON i.investigator_id = f.investigator_id
INNER JOIN farmers AS o ON o.farmer_id = f.farmer_id;

CREATE VIEW pattern_findings AS
SELECT p.field_id, p.geometry, t.instrument, r.conclusion, r.anomaly_confirmed
FROM reports AS r
INNER JOIN patterns AS p ON p.pattern_id = r.pattern_id
INNER JOIN tools AS t ON t.tool_id = r.tool_id;

DELIMITER //

CREATE PROCEDURE survey(IN in_year INT)
BEGIN
    SELECT fr.investigator_name, fr.acreage, fr.farmer_name, p.geometry
    FROM field_registry AS fr
    INNER JOIN patterns AS p ON p.field_id = fr.field_id
    WHERE fr.discovery_year = in_year
    ORDER BY fr.investigator_name, p.geometry;

    SELECT fr.acreage, pf.instrument, pf.conclusion, pf.geometry
    FROM field_registry AS fr
    INNER JOIN pattern_findings AS pf ON pf.field_id = fr.field_id
    WHERE fr.discovery_year = in_year
      AND pf.anomaly_confirmed = 1
    ORDER BY pf.instrument, fr.acreage;

    SELECT fr.investigator_name, fr.farmer_name, pf.conclusion
    FROM field_registry AS fr
    INNER JOIN pattern_findings AS pf ON pf.field_id = fr.field_id
    WHERE fr.discovery_year = in_year
    ORDER BY fr.investigator_name, fr.farmer_name;
END //

