SELECT f.field_id, f.discovery_year, f.acreage, i.investigator_name, o.farmer_name
FROM fields AS f, investigators AS i, farmers AS o
WHERE i.investigator_id = f.investigator_id
  AND o.farmer_id = f.farmer_id;

CREATE VIEW pattern_findings AS
SELECT p.field_id, p.geometry, t.instrument, r.conclusion, r.anomaly_confirmed
FROM reports AS r, patterns AS p, tools AS t
WHERE p.pattern_id = r.pattern_id
  AND t.tool_id = r.tool_id;

DELIMITER //

CREATE PROCEDURE survey(IN in_year INT)
BEGIN
    SELECT fr.investigator_name, fr.acreage, fr.farmer_name, p.geometry
    FROM field_registry AS fr, patterns AS p
    WHERE p.field_id = fr.field_id
      AND fr.discovery_year = in_year
    ORDER BY fr.investigator_name, p.geometry;

    SELECT fr.acreage, pf.instrument, pf.conclusion, pf.geometry
    FROM field_registry AS fr, pattern_findings AS pf
    WHERE pf.field_id = fr.field_id
      AND fr.discovery_year = in_year
      AND pf.anomaly_confirmed = 1
    ORDER BY pf.instrument, fr.acreage;

    SELECT fr.investigator_name, fr.farmer_name, pf.conclusion
    FROM field_registry AS fr, pattern_findings AS pf
    WHERE pf.field_id = fr.field_id
      AND fr.discovery_year = in_year
    ORDER BY fr.investigator_name, fr.farmer_name;
END //

