CREATE TABLE sponsors (sponsor_id INT PRIMARY KEY, brand VARCHAR(60) NOT NULL);
CREATE TABLE unicycles (unicycle_id INT PRIMARY KEY, wheel_size VARCHAR(20) NOT NULL);
CREATE TABLE tracks (track_id INT PRIMARY KEY, track_name VARCHAR(60) NOT NULL, surface VARCHAR(30) NOT NULL);
CREATE TABLE racers (racer_id INT PRIMARY KEY, racer_name VARCHAR(60) NOT NULL, season VARCHAR(9) NOT NULL,
    unicycle_id INT NOT NULL, track_id INT NOT NULL, sponsor_id INT NOT NULL);
CREATE TABLE races (race_id INT PRIMARY KEY, track_id INT NOT NULL, season VARCHAR(9) NOT NULL, distance_km DECIMAL(5,2) NOT NULL);
CREATE TABLE results (result_id INT PRIMARY KEY, race_id INT NOT NULL, racer_id INT NOT NULL, time_seconds DECIMAL(7,2) NOT NULL);

DELIMITER $$

CREATE FUNCTION season_race_count(in_season VARCHAR(9)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total
    FROM races AS rc
    INNER JOIN tracks AS t ON t.track_id = rc.track_id
    WHERE rc.season = in_season;
    RETURN total;
END$$

CREATE FUNCTION season_entrant_count(in_season VARCHAR(9)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total
    FROM racers AS ra
    INNER JOIN unicycles AS u ON u.unicycle_id = ra.unicycle_id
    INNER JOIN sponsors AS s ON s.sponsor_id = ra.sponsor_id
    WHERE ra.season = in_season;
    RETURN total;
END$$

CREATE FUNCTION season_finish_count(in_season VARCHAR(9)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total
    FROM results AS re
    INNER JOIN races AS rc ON rc.race_id = re.race_id
    WHERE rc.season = in_season;
    RETURN total;
END$$

CREATE PROCEDURE record(IN season VARCHAR(9))
BEGIN
    IF season_race_count(season) = 0 OR season_entrant_count(season) = 0
           OR season_finish_count(season) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'season has no complete race data';
    END IF;

    SELECT ra.racer_name, u.wheel_size, t.surface, s.brand
    FROM racers AS ra
    INNER JOIN unicycles AS u ON u.unicycle_id = ra.unicycle_id
    INNER JOIN tracks AS t ON t.track_id = ra.track_id
    INNER JOIN sponsors AS s ON s.sponsor_id = ra.sponsor_id
    WHERE ra.season = season
    ORDER BY ra.racer_name;

    SELECT t.surface, rc.distance_km, re.time_seconds, u.wheel_size
    FROM tracks AS t
    INNER JOIN races AS rc ON rc.track_id = t.track_id
    INNER JOIN results AS re ON re.race_id = rc.race_id
    INNER JOIN racers AS ra ON ra.racer_id = re.racer_id
    INNER JOIN unicycles AS u ON u.unicycle_id = ra.unicycle_id
    WHERE rc.season = season
      AND re.time_seconds < 120
    ORDER BY re.time_seconds;

    SELECT ra.racer_name, rc.distance_km, re.time_seconds
    FROM racers AS ra
    INNER JOIN tracks AS t ON t.track_id = ra.track_id
    INNER JOIN races AS rc ON rc.track_id = t.track_id
    INNER JOIN results AS re ON re.race_id = rc.race_id AND re.racer_id = ra.racer_id
    WHERE rc.season = season
      AND ra.season = season
    ORDER BY ra.racer_name, rc.distance_km;
END$$

DELIMITER ;

CALL record('2024');
