CREATE TABLE Breeders (breeder_id INT PRIMARY KEY, breeder_name VARCHAR(80) NOT NULL);
CREATE TABLE Lofts (loft_id INT PRIMARY KEY, breeder_id INT NOT NULL REFERENCES Breeders(breeder_id), capacity INT NOT NULL);
CREATE TABLE Birds (bird_id INT PRIMARY KEY, loft_id INT NOT NULL REFERENCES Lofts(loft_id), ring_number VARCHAR(40) NOT NULL);
CREATE TABLE Races (race_id INT PRIMARY KEY, race_month VARCHAR(20) NOT NULL, distance INT NOT NULL);
CREATE TABLE Weathers (weather_id INT PRIMARY KEY, race_id INT NOT NULL REFERENCES Races(race_id), wind_speed DECIMAL(5,2) NOT NULL);
CREATE TABLE Results (result_id INT PRIMARY KEY, race_id INT NOT NULL REFERENCES Races(race_id),
    bird_id INT NOT NULL REFERENCES Birds(bird_id), flight_time DECIMAL(8,3) NOT NULL, position INT NOT NULL);

DELIMITER $$

CREATE PROCEDURE clock_require_weather(IN p_month VARCHAR(20))
BEGIN
    DECLARE v_logged INT;
    SELECT COUNT(*) INTO v_logged
    FROM Races AS C
    INNER JOIN Weathers AS W ON W.race_id = C.race_id
    WHERE C.race_month = p_month;
    IF v_logged = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No weather logged for the requested month';
    END IF;
END$$

CREATE PROCEDURE clock_require_results(IN p_month VARCHAR(20))
BEGIN
    DECLARE v_clocked INT;
    SELECT COUNT(*) INTO v_clocked
    FROM Races AS C
    INNER JOIN Results AS S ON S.race_id = C.race_id
    INNER JOIN Birds AS R ON R.bird_id = S.bird_id
    WHERE C.race_month = p_month;
    IF v_clocked = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No clocked birds for the requested month';
    END IF;
END$$

CREATE PROCEDURE clock_loft_manifest(IN p_month VARCHAR(20))
BEGIN
    SELECT B.breeder_name, L.capacity, R.ring_number, C.distance
    FROM Breeders AS B
    INNER JOIN Lofts AS L ON L.breeder_id = B.breeder_id
    INNER JOIN Birds AS R ON R.loft_id = L.loft_id
    INNER JOIN Results AS S ON S.bird_id = R.bird_id
    INNER JOIN Races AS C ON C.race_id = S.race_id
    WHERE C.race_month = p_month
    ORDER BY B.breeder_name, R.ring_number;
END$$

CREATE PROCEDURE clock_leader_manifest(IN p_month VARCHAR(20))
BEGIN
    SELECT C.distance, W.wind_speed, S.flight_time, R.ring_number
    FROM Races AS C
    INNER JOIN Weathers AS W ON W.race_id = C.race_id
    INNER JOIN Results AS S ON S.race_id = C.race_id
    INNER JOIN Birds AS R ON R.bird_id = S.bird_id
    WHERE C.race_month = p_month
      AND S.position = 1
    ORDER BY C.distance, S.flight_time;
END$$

CREATE PROCEDURE clock_condition_manifest(IN p_month VARCHAR(20))
BEGIN
    SELECT B.breeder_name, W.wind_speed, S.flight_time
    FROM Breeders AS B
    INNER JOIN Lofts AS L ON L.breeder_id = B.breeder_id
    INNER JOIN Birds AS R ON R.loft_id = L.loft_id
    INNER JOIN Results AS S ON S.bird_id = R.bird_id
    INNER JOIN Races AS C ON C.race_id = S.race_id
    INNER JOIN Weathers AS W ON W.race_id = C.race_id
    WHERE C.race_month = p_month
    ORDER BY B.breeder_name, S.flight_time;
END$$

CREATE PROCEDURE clock(IN month VARCHAR(20))
BEGIN
    CALL clock_require_weather(month);
    CALL clock_require_results(month);
    CALL clock_loft_manifest(month);
    CALL clock_leader_manifest(month);
    CALL clock_condition_manifest(month);
END$$

DELIMITER ;

CALL clock('March');

