    INNER JOIN technicians AS t ON g.tech_id = t.tech_id
    ORDER BY a.alarm_time
    LIMIT `limit`;

    SELECT ft.description, f.filter_id, ml.log_date
    FROM filter_types AS ft
    INNER JOIN air_filters AS f ON f.type_id = ft.type_id
    INNER JOIN maintenance_logs AS ml ON ml.filter_id = f.filter_id
    ORDER BY ft.description, ml.log_date
    LIMIT `limit`;
