CREATE PROCEDURE technician_workload()
BEGIN
    SELECT t.tech_name, COUNT(*) AS service_count,
           COUNT(DISTINCT fi.module_name) AS modules_covered, MAX(ml.log_date) AS last_service
    FROM technicians AS t
    INNER JOIN maintenance_logs AS ml ON ml.tech_id = t.tech_id
    INNER JOIN filter_inventory AS fi ON fi.filter_id = ml.filter_id
    GROUP BY t.tech_name
    ORDER BY service_count DESC, t.tech_name;
END //
