CREATE TABLE inventory_categories (category_id INT PRIMARY KEY, category_name VARCHAR(50) NOT NULL);

CREATE TABLE grocery_aisles (aisle_id INT PRIMARY KEY, location VARCHAR(30) NOT NULL,
    category_id INT NOT NULL REFERENCES inventory_categories(category_id));

CREATE TABLE robotic_pickers (picker_id INT PRIMARY KEY, picker_name VARCHAR(40) NOT NULL,
    aisle_id INT NOT NULL REFERENCES grocery_aisles(aisle_id));

CREATE TABLE delivery_trucks (truck_id INT PRIMARY KEY, license VARCHAR(15) NOT NULL);

CREATE TABLE dispatch_bays (bay_id INT PRIMARY KEY, bay_number VARCHAR(10) NOT NULL,
    truck_id INT NOT NULL REFERENCES delivery_trucks(truck_id));

CREATE TABLE packaging_materials (material_id INT PRIMARY KEY, material_type VARCHAR(30) NOT NULL);

CREATE TABLE customer_orders (order_id INT PRIMARY KEY, order_number VARCHAR(15) NOT NULL,
    picker_id INT NOT NULL REFERENCES robotic_pickers(picker_id),
    bay_id INT NOT NULL REFERENCES dispatch_bays(bay_id),
    material_id INT NOT NULL REFERENCES packaging_materials(material_id));

