DELIMITER //
CREATE PROCEDURE truck_load(IN row_limit INT)
BEGIN
    SELECT dt.license, db.bay_number, COUNT(co.order_id) AS orders_queued
    FROM delivery_trucks AS dt
    JOIN dispatch_bays AS db ON db.truck_id = dt.truck_id
    JOIN customer_orders AS co ON co.bay_id = db.bay_id
    GROUP BY dt.license, db.bay_number
    ORDER BY orders_queued DESC, dt.license
    LIMIT row_limit;
END //

CREATE PROCEDURE category_coverage(IN row_limit INT)
BEGIN
    SELECT ic.category_name, COUNT(DISTINCT ga.aisle_id) AS aisles, COUNT(rp.picker_id) AS pickers
    FROM inventory_categories AS ic
    JOIN grocery_aisles AS ga ON ga.category_id = ic.category_id
    JOIN robotic_pickers AS rp ON rp.aisle_id = ga.aisle_id
    GROUP BY ic.category_name
    ORDER BY ic.category_name
    LIMIT row_limit;
END //

CREATE PROCEDURE dispatch(IN row_limit INT)
BEGIN
    SELECT rp.picker_name, ga.location, ic.category_name, co.order_number
    FROM robotic_pickers AS rp
    JOIN grocery_aisles AS ga ON ga.aisle_id = rp.aisle_id
    JOIN inventory_categories AS ic ON ic.category_id = ga.category_id
    JOIN customer_orders AS co ON co.picker_id = rp.picker_id
    ORDER BY co.order_number
    LIMIT row_limit;

    SELECT co.order_number, db.bay_number, dt.license, pm.material_type
    FROM customer_orders AS co
    JOIN dispatch_bays AS db ON db.bay_id = co.bay_id
    JOIN delivery_trucks AS dt ON dt.truck_id = db.truck_id
    JOIN packaging_materials AS pm ON pm.material_id = co.material_id
    ORDER BY co.order_number
    LIMIT row_limit;

    SELECT ic.category_name, ga.location, rp.picker_name
    FROM inventory_categories AS ic
    JOIN grocery_aisles AS ga ON ga.category_id = ic.category_id
    JOIN robotic_pickers AS rp ON rp.aisle_id = ga.aisle_id
    ORDER BY ic.category_name
    LIMIT row_limit;

    SELECT pm.material_type, co.order_number, dt.license
    FROM packaging_materials AS pm
    JOIN customer_orders AS co ON co.material_id = pm.material_id
    JOIN dispatch_bays AS db ON db.bay_id = co.bay_id
    JOIN delivery_trucks AS dt ON dt.truck_id = db.truck_id
    ORDER BY pm.material_type, co.order_number
    LIMIT row_limit;
END //
DELIMITER ;

CALL truck_load(8);
CALL category_coverage(8);
CALL dispatch(8);

