CREATE VIEW classroom_catalog AS
SELECT vc.classroom_id, vc.classroom_name, gl.lecturer_name
FROM virtual_classrooms AS vc
JOIN guest_lecturers AS gl ON gl.lecturer_id = vc.lecturer_id;

CREATE VIEW module_era_map AS
SELECT lm.module_id, lm.module_title, lm.classroom_id, he.era_focus
FROM lesson_modules AS lm
JOIN historical_eras AS he ON he.era_id = lm.era_id;

DELIMITER $$

CREATE PROCEDURE educate(IN row_limit INT)
BEGIN
    SELECT vc.classroom_name, lm.module_title, he.era_focus, gl.lecturer_name
    FROM virtual_classrooms AS vc
    JOIN lesson_modules AS lm ON lm.classroom_id = vc.classroom_id
    JOIN historical_eras AS he ON he.era_id = lm.era_id
    JOIN guest_lecturers AS gl ON gl.lecturer_id = vc.lecturer_id
    ORDER BY vc.classroom_name
    LIMIT row_limit;

    SELECT cc.certificate_date, sa.avatar_name, lm.module_title, he.era_focus
    FROM completion_certificates AS cc
    JOIN student_avatars AS sa ON sa.avatar_id = cc.avatar_id
    JOIN lesson_modules AS lm ON lm.module_id = cc.module_id
    JOIN historical_eras AS he ON he.era_id = lm.era_id
    ORDER BY cc.certificate_date
    LIMIT row_limit;

    SELECT ip.prop_name, vc.classroom_name, gl.lecturer_name
    FROM interactive_props AS ip
    JOIN virtual_classrooms AS vc ON vc.classroom_id = ip.classroom_id
    JOIN guest_lecturers AS gl ON gl.lecturer_id = vc.lecturer_id
    ORDER BY ip.prop_name
    LIMIT row_limit;

    SELECT he.era_focus, lm.module_title, cc.certificate_date
    FROM historical_eras AS he
    JOIN lesson_modules AS lm ON lm.era_id = he.era_id
    JOIN completion_certificates AS cc ON cc.module_id = lm.module_id
    ORDER BY he.era_focus
    LIMIT row_limit;
END$$

DELIMITER ;

