DELIMITER $$
CREATE FUNCTION event_headline(p_event_id INT) RETURNS VARCHAR(220) READS SQL DATA
BEGIN
    DECLARE headline VARCHAR(220);
    SELECT CONCAT(pe.event_name, ' [', ed.era_name, '] :: ', mb.summary) INTO headline
    FROM paradox_events AS pe
    INNER JOIN era_designations AS ed ON ed.era_id = pe.era_id
    INNER JOIN mission_briefings AS mb ON mb.event_id = pe.event_id
    WHERE pe.event_id = p_event_id;
    RETURN headline;
END$$

CREATE PROCEDURE resolve(IN `limit` INT)
BEGIN
    SELECT pe.event_name, ta.agent_name, tl.designation AS timeline_identifier, mb.summary
    FROM paradox_events AS pe
    INNER JOIN temporal_agents AS ta ON ta.agent_id = pe.agent_id
    INNER JOIN timelines AS tl ON tl.timeline_id = pe.timeline_id
    INNER JOIN mission_briefings AS mb ON mb.event_id = pe.event_id
    ORDER BY pe.event_id
    LIMIT `limit`;

    SELECT cs.sphere_code AS chronosphere_identifier, ed.era_name, ta.agent_name, tl.designation AS timeline_identifier
    FROM chronospheres AS cs
    INNER JOIN era_designations AS ed ON ed.era_id = cs.era_id
    INNER JOIN temporal_agents AS ta ON ta.chronosphere_id = cs.chronosphere_id
    INNER JOIN timelines AS tl ON tl.timeline_id = ta.timeline_id
    ORDER BY cs.chronosphere_id
    LIMIT `limit`;

    SELECT ts.magnitude, pe.event_name, ed.era_name
    FROM timeline_shifts AS ts
    INNER JOIN paradox_events AS pe ON pe.event_id = ts.event_id
    INNER JOIN era_designations AS ed ON ed.era_id = ts.era_id
    ORDER BY ts.magnitude DESC
    LIMIT `limit`;

    SELECT tl.designation AS timeline_identifier, ta.agent_name, cs.sphere_code AS chronosphere_identifier
    FROM timelines AS tl
    INNER JOIN temporal_agents AS ta ON ta.timeline_id = tl.timeline_id
    INNER JOIN chronospheres AS cs ON cs.chronosphere_id = ta.chronosphere_id
    ORDER BY tl.stability DESC
    LIMIT `limit`;
END$$
DELIMITER ;

