CREATE TABLE dialect_classifications (dialect_id INT PRIMARY KEY, dialect_name VARCHAR(60) NOT NULL);

CREATE TABLE botanical_linguists (linguist_id INT PRIMARY KEY, linguist_name VARCHAR(60) NOT NULL,
    dialect_id INT REFERENCES dialect_classifications(dialect_id));

CREATE TABLE translation_algorithms (algorithm_id INT PRIMARY KEY, version VARCHAR(20) NOT NULL,
    linguist_id INT REFERENCES botanical_linguists(linguist_id));

CREATE VIEW algorithm_credits AS
SELECT ta.algorithm_id, ta.version, bl.linguist_name, dc.dialect_name
FROM translation_algorithms AS ta
JOIN botanical_linguists AS bl ON ta.linguist_id = bl.linguist_id
JOIN dialect_classifications AS dc ON bl.dialect_id = dc.dialect_id;

CREATE TABLE nutrient_formulas (formula_id INT PRIMARY KEY, formula_type VARCHAR(40) NOT NULL);

CREATE TABLE greenhouse_zones (zone_id INT PRIMARY KEY, zone_identifier VARCHAR(20) NOT NULL,
    formula_id INT REFERENCES nutrient_formulas(formula_id));

CREATE TABLE sentient_flora (flora_id INT PRIMARY KEY, flora_name VARCHAR(60) NOT NULL,
    zone_id INT REFERENCES greenhouse_zones(zone_id),
    dialect_id INT REFERENCES dialect_classifications(dialect_id));

CREATE TABLE communicative_emissions (emission_id INT PRIMARY KEY, frequency_hz DECIMAL(8,2) NOT NULL,
    flora_id INT REFERENCES sentient_flora(flora_id),
    algorithm_id INT REFERENCES translation_algorithms(algorithm_id));

CREATE VIEW emission_log AS
SELECT ce.frequency_hz, sf.flora_name, ac.version, ac.linguist_name, ac.dialect_name
FROM communicative_emissions AS ce
JOIN sentient_flora AS sf ON ce.flora_id = sf.flora_id
JOIN algorithm_credits AS ac ON ce.algorithm_id = ac.algorithm_id;

