CREATE PROCEDURE translate(IN limit_rows INT)
BEGIN
    SELECT ce.frequency_hz, sf.flora_name, ta.version, bl.linguist_name
    FROM communicative_emissions AS ce
    JOIN sentient_flora AS sf ON ce.flora_id = sf.flora_id
    JOIN translation_algorithms AS ta ON ce.algorithm_id = ta.algorithm_id
    JOIN botanical_linguists AS bl ON ta.linguist_id = bl.linguist_id
