    ORDER BY ta.version LIMIT limit_rows;

    SELECT gz.zone_identifier, sf.flora_name, nf.formula_type
    FROM greenhouse_zones AS gz
    JOIN sentient_flora AS sf ON gz.zone_id = sf.zone_id
    JOIN nutrient_formulas AS nf ON gz.formula_id = nf.formula_id
    ORDER BY gz.zone_identifier, sf.flora_name LIMIT limit_rows;
END;

