CREATE PROCEDURE caseload_report()
BEGIN
    SELECT th.full_name AS therapist_name, COUNT(*) AS sessions_logged
    FROM transcripts AS t, therapists AS th
    WHERE t.therapist_id = th.therapist_id
    GROUP BY th.full_name
    ORDER BY sessions_logged DESC, therapist_name;

    SELECT m.model, SUM(c.capacity_tb) AS mounted_capacity_tb
    FROM machines AS m, crystals AS c
    WHERE c.machine_id = m.machine_id
    GROUP BY m.model
    ORDER BY mounted_capacity_tb DESC;

    SELECT p.full_name AS patient_name, COUNT(DISTINCT f.filter_type) AS filters_applied
    FROM patients AS p, filters AS f, engrams AS e
    WHERE f.patient_id = p.patient_id
      AND e.filter_id = f.filter_id
    GROUP BY p.full_name
    ORDER BY patient_name;
END //

CREATE PROCEDURE extract(IN row_limit INT)
BEGIN
    SELECT t.session_date, e.subject, p.full_name AS patient_name, th.full_name AS therapist_name
    FROM transcripts AS t, engrams AS e, patients AS p, therapists AS th
    WHERE t.engram_id = e.engram_id
      AND e.patient_id = p.patient_id
      AND t.therapist_id = th.therapist_id
    ORDER BY t.session_date
    LIMIT row_limit;

    SELECT c.capacity_tb, m.model, e.subject, f.filter_type
    FROM crystals AS c, machines AS m, engrams AS e, filters AS f
    WHERE c.machine_id = m.machine_id
      AND e.crystal_id = c.crystal_id
      AND e.filter_id = f.filter_id
    ORDER BY c.capacity_tb DESC
    LIMIT row_limit;

    SELECT f.filter_type, th.full_name AS therapist_name, p.full_name AS patient_name
    FROM filters AS f, therapists AS th, patients AS p
    WHERE f.therapist_id = th.therapist_id
      AND f.patient_id = p.patient_id
    ORDER BY f.filter_type
    LIMIT row_limit;

    SELECT m.model, c.capacity_tb, e.subject
    FROM machines AS m, crystals AS c, engrams AS e
    WHERE c.machine_id = m.machine_id
      AND e.crystal_id = c.crystal_id
    ORDER BY m.model, c.capacity_tb
    LIMIT row_limit;
END //
DELIMITER ;

