SELECT h.heat_label, f.ferret_name, e.lane_number, t.seconds, t.placing
FROM race_entries AS e
INNER JOIN ferrets AS f ON e.ferret_id = f.ferret_id
INNER JOIN heats AS h ON e.heat_id = h.heat_id
INNER JOIN finish_times AS t ON t.entry_id = e.entry_id
ORDER BY h.heat_label, t.placing;

SELECT tb.tube_code, ts.section_id, ts.length_cm, cl.cleaned_on, i.inspector_name, i.certification
FROM racing_tubes AS tb
INNER JOIN tunnel_sections AS ts ON ts.tube_id = tb.tube_id
INNER JOIN cleaning_logs AS cl ON cl.section_id = ts.section_id
INNER JOIN inspectors AS i ON i.inspector_id = cl.inspector_id
ORDER BY tb.tube_code, ts.section_id;

SELECT s.company, f.ferret_name, h.heat_label, p.amount, b.bank_name, b.account_ref
FROM sponsors AS s
INNER JOIN ferrets AS f ON s.ferret_id = f.ferret_id
INNER JOIN race_payouts AS p ON p.sponsor_id = s.sponsor_id
INNER JOIN banking_details AS b ON b.sponsor_id = s.sponsor_id
INNER JOIN heats AS h ON h.heat_id = p.heat_id
INNER JOIN race_entries AS e ON e.heat_id = p.heat_id AND e.ferret_id = f.ferret_id
INNER JOIN finish_times AS t ON t.entry_id = e.entry_id
WHERE t.placing = 1
ORDER BY p.amount DESC;

SELECT h.heat_label, h.heat_date, f.ferret_name, f.owner_name, t.seconds
FROM finish_times AS t
INNER JOIN race_entries AS e ON e.entry_id = t.entry_id
INNER JOIN ferrets AS f ON f.ferret_id = e.ferret_id
INNER JOIN heats AS h ON h.heat_id = e.heat_id
WHERE t.placing = 1
ORDER BY h.heat_date;

SELECT h.heat_label, tb.tube_code, COUNT(cl.log_id) AS sections_cleaned, MAX(cl.cleaned_on) AS last_cleaned
FROM heats AS h
INNER JOIN racing_tubes AS tb ON tb.heat_id = h.heat_id
INNER JOIN tunnel_sections AS ts ON ts.tube_id = tb.tube_id
INNER JOIN cleaning_logs AS cl ON cl.section_id = ts.section_id
WHERE cl.cleaned_on <= h.heat_date
GROUP BY h.heat_label, tb.tube_code
ORDER BY h.heat_label;

SELECT b.bank_name, b.account_ref, s.company, SUM(p.amount) AS total_paid
FROM banking_details AS b
INNER JOIN sponsors AS s ON s.sponsor_id = b.sponsor_id
INNER JOIN race_payouts AS p ON p.sponsor_id = s.sponsor_id
GROUP BY b.bank_name, b.account_ref, s.company
ORDER BY total_paid DESC;

SELECT f.ferret_name, f.owner_name, COUNT(t.entry_id) AS heats_run, AVG(t.seconds) AS avg_seconds, MIN(t.placing) AS best_placing
FROM ferrets AS f
INNER JOIN race_entries AS e ON e.ferret_id = f.ferret_id
INNER JOIN finish_times AS t ON t.entry_id = e.entry_id
GROUP BY f.ferret_name, f.owner_name
ORDER BY avg_seconds;

