SELECT v.vendor_name, md.market_date, ml.location_name, sr.gross_amount, ROUND(sr.gross_amount * (1 - tb.tax_rate), 2) AS net_revenue
FROM sales_receipts AS sr
JOIN vendors AS v ON sr.vendor_id = v.vendor_id
JOIN market_days AS md ON sr.market_day_id = md.market_day_id
JOIN tax_brackets AS tb ON v.bracket_id = tb.bracket_id
JOIN market_locations AS ml ON md.location_id = ml.location_id
ORDER BY md.market_date, v.vendor_name;

SELECT cv.variety_name, i.inspector_name, i.agency, st.residue_ppm, rc.expires_on
FROM crop_varieties AS cv
JOIN soil_tests AS st ON cv.variety_id = st.variety_id
JOIN inspectors AS i ON st.inspector_id = i.inspector_id
JOIN renewal_certificates AS rc ON st.soil_test_id = rc.soil_test_id
ORDER BY rc.expires_on;

SELECT ml.location_name, cc.council_name, hg.guideline_code, hg.max_stalls, ia.permit_number, i.inspector_name
FROM market_locations AS ml
JOIN city_councils AS cc ON ml.council_id = cc.council_id
JOIN health_guidelines AS hg ON cc.guideline_id = hg.guideline_id
JOIN inspector_approvals AS ia ON ml.location_id = ia.location_id
JOIN inspectors AS i ON ia.inspector_id = i.inspector_id
ORDER BY ml.location_name;

SELECT v.vendor_name, tb.bracket_name, SUM(sr.gross_amount) AS season_gross,
       ROUND(SUM(sr.gross_amount) * tb.tax_rate, 2) AS tax_owed
FROM sales_receipts AS sr
JOIN vendors AS v ON sr.vendor_id = v.vendor_id
JOIN tax_brackets AS tb ON v.bracket_id = tb.bracket_id
GROUP BY v.vendor_name, tb.bracket_name, tb.tax_rate
ORDER BY tax_owed DESC;

SELECT ml.location_name, cc.council_name, hg.guideline_code, md.market_date,
       COUNT(DISTINCT sr.vendor_id) AS stalls_used, hg.max_stalls
FROM market_days AS md
JOIN market_locations AS ml ON md.location_id = ml.location_id
JOIN city_councils AS cc ON ml.council_id = cc.council_id
JOIN health_guidelines AS hg ON cc.guideline_id = hg.guideline_id
JOIN sales_receipts AS sr ON md.market_day_id = sr.market_day_id
GROUP BY ml.location_name, cc.council_name, hg.guideline_code, md.market_date, hg.max_stalls
ORDER BY md.market_date;

SELECT i.inspector_name, i.agency, v.vendor_name, COUNT(st.soil_test_id) AS tests_performed,
       MAX(st.residue_ppm) AS worst_residue_ppm
FROM inspectors AS i
JOIN soil_tests AS st ON i.inspector_id = st.inspector_id
JOIN crop_varieties AS cv ON st.variety_id = cv.variety_id
JOIN vendors AS v ON cv.vendor_id = v.vendor_id
GROUP BY i.inspector_name, i.agency, v.vendor_name
ORDER BY i.inspector_name;

