SELECT v.vendor_name, md.market_date, ml.location_name, sr.gross_amount, ROUND(sr.gross_amount * (1 - tb.tax_rate), 2) AS net_revenue
FROM sales_receipts AS sr, vendors AS v, market_days AS md, tax_brackets AS tb, market_locations AS ml
WHERE sr.vendor_id = v.vendor_id
AND sr.market_day_id = md.market_day_id
AND v.bracket_id = tb.bracket_id
AND md.location_id = ml.location_id
ORDER BY md.market_date, v.vendor_name;

SELECT cv.variety_name, i.inspector_name, i.agency, st.residue_ppm, rc.expires_on
FROM crop_varieties AS cv, soil_tests AS st, inspectors AS i, renewal_certificates AS rc
WHERE cv.variety_id = st.variety_id
AND st.inspector_id = i.inspector_id
AND st.soil_test_id = rc.soil_test_id
ORDER BY rc.expires_on;

SELECT ml.location_name, cc.council_name, hg.guideline_code, hg.max_stalls, ia.permit_number, i.inspector_name
FROM market_locations AS ml, city_councils AS cc, health_guidelines AS hg, inspector_approvals AS ia, inspectors AS i
WHERE ml.council_id = cc.council_id
AND cc.guideline_id = hg.guideline_id
AND ml.location_id = ia.location_id
AND ia.inspector_id = i.inspector_id
ORDER BY ml.location_name;

SELECT v.vendor_name, tb.bracket_name, SUM(sr.gross_amount) AS season_gross,
       ROUND(SUM(sr.gross_amount) * tb.tax_rate, 2) AS tax_owed
FROM sales_receipts AS sr, vendors AS v, tax_brackets AS tb
WHERE sr.vendor_id = v.vendor_id
AND v.bracket_id = tb.bracket_id
GROUP BY v.vendor_name, tb.bracket_name, tb.tax_rate
ORDER BY tax_owed DESC;

SELECT ml.location_name, cc.council_name, hg.guideline_code, md.market_date,
       COUNT(DISTINCT sr.vendor_id) AS stalls_used, hg.max_stalls
FROM market_days AS md, market_locations AS ml, city_councils AS cc, health_guidelines AS hg, sales_receipts AS sr
WHERE md.location_id = ml.location_id
AND ml.council_id = cc.council_id
AND cc.guideline_id = hg.guideline_id
AND md.market_day_id = sr.market_day_id
GROUP BY ml.location_name, cc.council_name, hg.guideline_code, md.market_date, hg.max_stalls
ORDER BY md.market_date;

SELECT i.inspector_name, i.agency, v.vendor_name, COUNT(st.soil_test_id) AS tests_performed,
       MAX(st.residue_ppm) AS worst_residue_ppm
FROM inspectors AS i, soil_tests AS st, crop_varieties AS cv, vendors AS v
WHERE i.inspector_id = st.inspector_id
AND st.variety_id = cv.variety_id
AND cv.vendor_id = v.vendor_id
GROUP BY i.inspector_name, i.agency, v.vendor_name
ORDER BY i.inspector_name;

