SELECT d.driver_name, d.age, v.car_name, v.weight_kg,
       h.heat_number, h.lane, t.finish_seconds
FROM drivers AS d
JOIN vehicle_specs AS v ON v.driver_id = d.driver_id
JOIN race_heats AS h ON h.spec_id = v.spec_id
JOIN timing_sensors AS t ON t.heat_id = h.heat_id
ORDER BY t.finish_seconds;

SELECT h.heat_number, COUNT(DISTINCT d.driver_id) AS drivers_running,
       MIN(t.finish_seconds) AS best_seconds, ROUND(AVG(t.finish_seconds), 2) AS avg_seconds
FROM race_heats AS h
JOIN timing_sensors AS t ON t.heat_id = h.heat_id
JOIN vehicle_specs AS v ON v.spec_id = h.spec_id
JOIN drivers AS d ON d.driver_id = v.driver_id
GROUP BY h.heat_number
ORDER BY h.heat_number;

SELECT l.corner_name, l.slope_percent, hb.bale_count,
       vp.volunteer_name, ci.severity
FROM track_locations AS l
JOIN haybale_deliveries AS hb ON hb.location_id = l.location_id
JOIN volunteer_placements AS vp ON vp.delivery_id = hb.delivery_id
JOIN crash_impacts AS ci ON ci.placement_id = vp.placement_id
ORDER BY l.corner_name;

SELECT b.business_name, b.contact_phone, v.car_name, f.amount_usd,
       ds.width_cm * ds.height_cm AS decal_area_cm2, pp.file_name
FROM businesses AS b
JOIN funded_vehicles AS f ON f.business_id = b.business_id
JOIN vehicle_specs AS v ON v.spec_id = f.spec_id
JOIN decal_sizes AS ds ON ds.funding_id = f.funding_id
JOIN promo_photos AS pp ON pp.decal_id = ds.decal_id
ORDER BY f.amount_usd DESC;

SELECT d.driver_name, v.car_name, SUM(f.amount_usd) AS total_funding_usd,
       SUM(ds.width_cm * ds.height_cm) AS sponsored_area_cm2, COUNT(pp.photo_id) AS promo_photo_count
FROM drivers AS d
JOIN vehicle_specs AS v ON v.driver_id = d.driver_id
JOIN funded_vehicles AS f ON f.spec_id = v.spec_id
JOIN decal_sizes AS ds ON ds.funding_id = f.funding_id
JOIN promo_photos AS pp ON pp.decal_id = ds.decal_id
GROUP BY d.driver_name, v.car_name
ORDER BY total_funding_usd DESC;

SELECT l.corner_name, l.slope_percent, SUM(hb.bale_count) AS bales_on_site,
       COUNT(DISTINCT vp.placement_id) AS volunteers_posted, COUNT(ci.impact_id) AS logged_impacts
FROM track_locations AS l
JOIN haybale_deliveries AS hb ON hb.location_id = l.location_id
JOIN volunteer_placements AS vp ON vp.delivery_id = hb.delivery_id
JOIN crash_impacts AS ci ON ci.placement_id = vp.placement_id
GROUP BY l.corner_name, l.slope_percent
ORDER BY logged_impacts DESC, l.corner_name;

