-- Regional curling club: schema, sample data, reusable views and analytical reports.

CREATE TABLE ice_rinks (rink_id INTEGER PRIMARY KEY, rink_name TEXT NOT NULL, sheets INTEGER);
CREATE TABLE teams (team_id INTEGER PRIMARY KEY, team_name TEXT NOT NULL, rink_id INTEGER REFERENCES ice_rinks(rink_id));
CREATE TABLE roster_members (member_id INTEGER PRIMARY KEY, team_id INTEGER REFERENCES teams(team_id), member_name TEXT NOT NULL, position TEXT NOT NULL);
CREATE TABLE draw_schedule (draw_id INTEGER PRIMARY KEY, home_team_id INTEGER REFERENCES teams(team_id), away_team_id INTEGER REFERENCES teams(team_id), draw_time TEXT, rink_id INTEGER REFERENCES ice_rinks(rink_id));
CREATE TABLE final_ends (end_id INTEGER PRIMARY KEY, draw_id INTEGER REFERENCES draw_schedule(draw_id), end_number INTEGER, points_scored INTEGER, scoring_team_id INTEGER REFERENCES teams(team_id));
CREATE TABLE granite_types (granite_id INTEGER PRIMARY KEY, granite_name TEXT NOT NULL, quarry TEXT);
CREATE TABLE curling_stones (stone_id INTEGER PRIMARY KEY, granite_id INTEGER REFERENCES granite_types(granite_id), team_id INTEGER REFERENCES teams(team_id), stone_code TEXT);
CREATE TABLE equipment_managers (manager_id INTEGER PRIMARY KEY, manager_name TEXT NOT NULL, rink_id INTEGER REFERENCES ice_rinks(rink_id));
CREATE TABLE texturing_logs (log_id INTEGER PRIMARY KEY, stone_id INTEGER REFERENCES curling_stones(stone_id), manager_id INTEGER REFERENCES equipment_managers(manager_id), log_date TEXT, grit_level INTEGER);
CREATE TABLE concession_stands (stand_id INTEGER PRIMARY KEY, rink_id INTEGER REFERENCES ice_rinks(rink_id), stand_name TEXT NOT NULL);
CREATE TABLE purchased_tickets (ticket_id INTEGER PRIMARY KEY, rink_id INTEGER REFERENCES ice_rinks(rink_id), draw_id INTEGER REFERENCES draw_schedule(draw_id), price NUMERIC(6,2), purchase_date TEXT);
CREATE TABLE daily_deposits (deposit_id INTEGER PRIMARY KEY, stand_id INTEGER REFERENCES concession_stands(stand_id), deposit_date TEXT, amount NUMERIC(8,2));

INSERT INTO ice_rinks VALUES (1, 'Granite Bay Arena', 6), (2, 'North Shore Ice Centre', 4);
