CREATE VIEW team_bases AS
SELECT t.team_id, t.team_name, r.rink_id, r.rink_name, r.sheets
FROM teams AS t
INNER JOIN ice_rinks AS r ON r.rink_id = t.rink_id;

CREATE VIEW team_skips AS
SELECT m.team_id, t.team_name, m.member_name AS skip_name
FROM roster_members AS m
INNER JOIN teams AS t ON t.team_id = m.team_id
WHERE m.position = 'Skip';

CREATE VIEW stone_registry AS
SELECT s.stone_id, s.stone_code, s.team_id, g.granite_name, g.quarry
FROM curling_stones AS s
INNER JOIN granite_types AS g ON g.granite_id = s.granite_id;

CREATE VIEW stand_banking AS
SELECT cs.stand_id, cs.rink_id, cs.stand_name, dep.deposit_date, dep.amount
FROM concession_stands AS cs
INNER JOIN daily_deposits AS dep ON dep.stand_id = cs.stand_id;

-- Report 1: match outcomes with the home skip and the points the home side banked.
SELECT d.draw_id, d.draw_time, home.team_name AS home_team, away.team_name AS away_team,
       sk.skip_name AS home_skip, SUM(fe.points_scored) AS home_points
FROM draw_schedule AS d
INNER JOIN team_bases AS home ON home.team_id = d.home_team_id
INNER JOIN team_bases AS away ON away.team_id = d.away_team_id
INNER JOIN team_skips AS sk ON sk.team_id = d.home_team_id
INNER JOIN final_ends AS fe ON fe.draw_id = d.draw_id AND fe.scoring_team_id = d.home_team_id
GROUP BY d.draw_id, d.draw_time, home.team_name, away.team_name, sk.skip_name
ORDER BY d.draw_time;

-- Report 2: stone texturing history with granite provenance and the responsible manager.
SELECT sr.stone_code, sr.granite_name, sr.quarry, tb.team_name, l.log_date, l.grit_level, em.manager_name
FROM stone_registry AS sr
INNER JOIN texturing_logs AS l ON l.stone_id = sr.stone_id
INNER JOIN equipment_managers AS em ON em.manager_id = l.manager_id
INNER JOIN team_bases AS tb ON tb.team_id = sr.team_id
ORDER BY l.log_date, sr.stone_code;

-- Report 3: ticket revenue set against the concession cash banked the same day.
SELECT r.rink_name, sb.stand_name, sb.deposit_date,
       COUNT(t.ticket_id) AS tickets_sold, SUM(t.price) AS ticket_revenue, sb.amount AS stand_deposit
FROM ice_rinks AS r
INNER JOIN stand_banking AS sb ON sb.rink_id = r.rink_id
INNER JOIN purchased_tickets AS t ON t.rink_id = r.rink_id AND t.purchase_date = sb.deposit_date
GROUP BY r.rink_name, sb.stand_name, sb.deposit_date, sb.amount
ORDER BY r.rink_name, sb.stand_name;

