SELECT T.TermName, E.InstructorName, COUNT(*) AS EvaluationCount, AVG(E.Score) AS AverageScore
FROM Terms AS T
INNER JOIN Techniques AS TQ ON T.TermID = TQ.TermID
INNER JOIN Evaluations AS E ON TQ.TechniqueID = E.TechniqueID
GROUP BY T.TermName, E.InstructorName
ORDER BY T.TermName, AverageScore DESC;

SELECT C.RoomLabel, INV.SupplierName, SUM(INV.AmountDue) AS RoomSpend
FROM StorageCabinets AS C
INNER JOIN InkTypes AS I ON C.CabinetID = I.CabinetID
INNER JOIN PaperGrades AS P ON I.InkID = P.InkID
INNER JOIN SupplierInvoices AS INV ON P.PaperID = INV.PaperID
GROUP BY C.RoomLabel, INV.SupplierName
ORDER BY RoomSpend DESC;

SELECT PB.City, COUNT(DISTINCT A.ArtworkID) AS PiecesBought, SUM(B.BidAmount) AS CityRevenue
FROM PrivateBuyers AS PB
INNER JOIN AuctionBids AS B ON PB.BuyerID = B.BuyerID
INNER JOIN Artworks AS A ON B.ArtworkID = A.ArtworkID
GROUP BY PB.City
ORDER BY CityRevenue DESC;

SELECT S.FullName, MAX(TQ.DifficultyLevel) AS TopDifficulty, SUM(B.BidAmount) AS SalesTotal
FROM Students AS S
INNER JOIN Evaluations AS E ON S.StudentID = E.StudentID
INNER JOIN Techniques AS TQ ON E.TechniqueID = TQ.TechniqueID
INNER JOIN Artworks AS A ON S.StudentID = A.StudentID
INNER JOIN AuctionBids AS B ON A.ArtworkID = B.ArtworkID
GROUP BY S.FullName
ORDER BY SalesTotal DESC;

