CREATE VIEW PlayerProfiles AS
SELECT P.player_id, P.player_name, P.bracket_id, B.bracket_name, B.round_no, S.rubber_type, S.speed_rating, P.rallies_played, P.rally_points_won
FROM Players AS P
INNER JOIN Brackets AS B ON P.bracket_id = B.bracket_id
INNER JOIN PaddleSpecs AS S ON P.paddle_id = S.paddle_id;

SELECT PP.player_name, PP.bracket_name, U.umpire_name, PP.rubber_type, PP.rallies_played,
       ROUND(100.0 * PP.rally_points_won / PP.rallies_played, 1) AS rally_win_pct
FROM PlayerProfiles AS PP
INNER JOIN Umpires AS U ON PP.bracket_id = U.bracket_id
ORDER BY rally_win_pct DESC;

CREATE VIEW TableSetups AS
SELECT T.table_id, T.table_code, T.bracket_id, T.floor_id, M.manager_name, M.venue_name, N.tension_newtons, N.last_checked
FROM PlayingTables AS T
INNER JOIN FacilityManagers AS M ON T.facility_id = M.facility_id
INNER JOIN NetTensions AS N ON T.net_id = N.net_id;

SELECT TS.table_code, TS.venue_name, TS.manager_name, TS.tension_newtons, TS.last_checked, F.surface_name, F.grip_rating
FROM TableSetups AS TS
INNER JOIN FlooringTypes AS F ON TS.floor_id = F.floor_id
WHERE TS.tension_newtons BETWEEN 14.00 AND 16.00
ORDER BY TS.table_code;

SELECT B.bracket_name, B.round_no, TS.table_code, TS.venue_name, U.umpire_name, U.certified_yr
FROM TableSetups AS TS
INNER JOIN Brackets AS B ON TS.bracket_id = B.bracket_id
INNER JOIN Umpires AS U ON B.bracket_id = U.bracket_id
ORDER BY B.round_no DESC, TS.table_code;

CREATE VIEW PrizeGross AS
SELECT FS.player_id, FS.finish_rank, FS.tax_id, ST.tier_name, FS.currency_code, ROUND(FS.prize_base * ST.bonus_multiplier * CC.rate_to_usd, 2) AS gross_usd
FROM FinalStandings AS FS
INNER JOIN SponsorTiers AS ST ON FS.tier_id = ST.tier_id
INNER JOIN CurrencyConversions AS CC ON FS.currency_code = CC.currency_code;

SELECT PP.player_name, PG.finish_rank, PG.tier_name, PG.currency_code, TW.jurisdiction, PG.gross_usd,
       ROUND(PG.gross_usd * (1 - TW.withhold_pct / 100), 2) AS net_usd
FROM PrizeGross AS PG
INNER JOIN PlayerProfiles AS PP ON PG.player_id = PP.player_id
INNER JOIN TaxWithholdings AS TW ON PG.tax_id = TW.tax_id
ORDER BY PG.finish_rank;

