SELECT T.full_name, T.country, D.design_name, D.wingspan_cm, W.speed_kph, W.direction, S.accuracy_points
FROM TargetScores AS S
INNER JOIN Throwers AS T ON T.thrower_id = S.thrower_id
INNER JOIN Designs AS D ON D.design_id = S.design_id
INNER JOIN WindConditions AS W ON W.wind_id = S.wind_id AND W.thrower_id = S.thrower_id
ORDER BY S.accuracy_points DESC;

SELECT T.country, COUNT(*) AS scored_throws, ROUND(AVG(S.accuracy_points), 1) AS avg_points, MAX(W.speed_kph) AS gustiest_kph
FROM TargetScores AS S
INNER JOIN Throwers AS T ON T.thrower_id = S.thrower_id
INNER JOIN WindConditions AS W ON W.wind_id = S.wind_id
GROUP BY T.country
ORDER BY avg_points DESC;

SELECT A.artisan_name, A.workshop_city, WD.species, WD.density, CT.tool_name, D.design_name, AE.return_distance_m
FROM AeroTests AS AE
INNER JOIN CarvingTools AS CT ON CT.tool_id = AE.tool_id
INNER JOIN WoodTypes AS WD ON WD.wood_id = CT.wood_id
INNER JOIN Artisans AS A ON A.artisan_id = AE.artisan_id
INNER JOIN Designs AS D ON D.design_id = AE.design_id
ORDER BY AE.return_distance_m DESC;

SELECT D.design_name, A.artisan_name, AE.return_distance_m, T.full_name, S.accuracy_points
FROM Designs AS D
INNER JOIN AeroTests AS AE ON AE.design_id = D.design_id
INNER JOIN Artisans AS A ON A.artisan_id = AE.artisan_id
INNER JOIN TargetScores AS S ON S.design_id = D.design_id
INNER JOIN Throwers AS T ON T.thrower_id = S.thrower_id
ORDER BY AE.return_distance_m DESC, S.accuracy_points DESC;

SELECT T.full_name, P.passport_no, P.expiry_date, F.airline, F.depart_date, H.family_name, H.host_city, V.status
FROM Visas AS V
INNER JOIN Passports AS P ON P.passport_id = V.passport_id
INNER JOIN Throwers AS T ON T.thrower_id = P.thrower_id
INNER JOIN Flights AS F ON F.flight_id = V.flight_id AND F.passport_id = V.passport_id
INNER JOIN HostFamilies AS H ON H.host_id = V.host_id
WHERE V.status = 'APPROVED'
  AND P.expiry_date > F.depart_date
ORDER BY F.depart_date;

SELECT T.full_name, T.country, S.accuracy_points, F.airline, H.host_city
FROM Throwers AS T
INNER JOIN TargetScores AS S ON S.thrower_id = T.thrower_id
INNER JOIN Passports AS P ON P.thrower_id = T.thrower_id
INNER JOIN Visas AS V ON V.passport_id = P.passport_id
INNER JOIN Flights AS F ON F.flight_id = V.flight_id
INNER JOIN HostFamilies AS H ON H.host_id = V.host_id
WHERE V.status = 'APPROVED'
ORDER BY S.accuracy_points DESC;

