CREATE TABLE GroundedAircraft (aircraft_id INT PRIMARY KEY, tail_number VARCHAR(12) NOT NULL, model VARCHAR(40) NOT NULL, grounded_since DATE NOT NULL);

CREATE TABLE Mechanics (mechanic_id INT PRIMARY KEY, full_name VARCHAR(60) NOT NULL, license_class VARCHAR(10) NOT NULL);

CREATE TABLE FlightLogs (log_id INT PRIMARY KEY, aircraft_id INT NOT NULL, mechanic_id INT NOT NULL, flight_hours DECIMAL(6,1) NOT NULL, logged_on DATE NOT NULL);

CREATE TABLE DefectReports (defect_id INT PRIMARY KEY, log_id INT NOT NULL, aircraft_id INT NOT NULL, severity VARCHAR(12) NOT NULL, description VARCHAR(120) NOT NULL);

CREATE TABLE PartSuppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(60) NOT NULL, country VARCHAR(40) NOT NULL, audit_rating VARCHAR(4) NOT NULL);

CREATE TABLE ReplacementParts (part_id INT PRIMARY KEY, defect_id INT NOT NULL, supplier_id INT NOT NULL, part_name VARCHAR(50) NOT NULL, installed_on DATE NOT NULL);

CREATE VIEW ValidatedDefects AS
SELECT D.defect_id, D.severity, D.description, L.log_id, L.mechanic_id, L.flight_hours, L.logged_on,
       A.aircraft_id, A.tail_number, A.model, A.grounded_since
FROM DefectReports AS D
INNER JOIN FlightLogs AS L ON L.log_id = D.log_id
INNER JOIN GroundedAircraft AS A ON A.aircraft_id = D.aircraft_id
WHERE L.aircraft_id = D.aircraft_id;

CREATE VIEW PartOrigins AS
SELECT P.part_id, P.defect_id, P.part_name, P.installed_on,
       S.supplier_id, S.supplier_name, S.country, S.audit_rating
FROM ReplacementParts AS P
INNER JOIN PartSuppliers AS S ON S.supplier_id = P.supplier_id;

DELIMITER //

CREATE PROCEDURE inspect()
BEGIN
    SELECT V.tail_number, V.defect_id, V.severity, O.part_name, O.supplier_name, O.country, O.audit_rating
    FROM ValidatedDefects AS V
    INNER JOIN PartOrigins AS O ON O.defect_id = V.defect_id
    ORDER BY V.tail_number, O.part_id;

    SELECT M.mechanic_id, M.full_name, M.license_class,
           COUNT(DISTINCT V.defect_id) AS defects_raised,
           COUNT(DISTINCT V.aircraft_id) AS aircraft_touched,
           SUM(V.flight_hours) AS hours_reviewed
    FROM Mechanics AS M
    INNER JOIN ValidatedDefects AS V ON V.mechanic_id = M.mechanic_id
    GROUP BY M.mechanic_id, M.full_name, M.license_class
    ORDER BY defects_raised DESC, M.full_name;

    SELECT V.tail_number, V.model, V.grounded_since, V.logged_on, V.flight_hours,
           M.full_name AS inspecting_mechanic, V.severity, V.description,
           O.part_name, O.installed_on, O.supplier_name, O.audit_rating
    FROM ValidatedDefects AS V
    INNER JOIN Mechanics AS M ON M.mechanic_id = V.mechanic_id
    INNER JOIN PartOrigins AS O ON O.defect_id = V.defect_id
    ORDER BY V.tail_number, V.defect_id, O.part_id;
END //

DELIMITER ;

