CREATE TABLE countries (country_id INT PRIMARY KEY, country_name VARCHAR(80) NOT NULL);
CREATE TABLE owners (owner_id INT PRIMARY KEY, owner_name VARCHAR(120) NOT NULL);
CREATE TABLE vehicles (vehicle_id INT PRIMARY KEY, license_plate VARCHAR(20) NOT NULL, owner_id INT NOT NULL, origin_country_id INT NOT NULL);
CREATE TABLE districts (district_id INT PRIMARY KEY, district_name VARCHAR(80) NOT NULL);
CREATE TABLE checkpoints (checkpoint_id INT PRIMARY KEY, checkpoint_name VARCHAR(80) NOT NULL, district_id INT NOT NULL);
CREATE TABLE officers (officer_id INT PRIMARY KEY, officer_name VARCHAR(120) NOT NULL, badge_number VARCHAR(20) NOT NULL);
CREATE TABLE crossings (crossing_id INT PRIMARY KEY, crossing_date DATE NOT NULL, vehicle_id INT NOT NULL, checkpoint_id INT NOT NULL, officer_id INT NOT NULL);
CREATE TABLE agents (agent_id INT PRIMARY KEY, agent_name VARCHAR(120) NOT NULL, certification VARCHAR(40) NOT NULL);
CREATE TABLE manifests (manifest_id INT PRIMARY KEY, crossing_id INT NOT NULL, cargo_description VARCHAR(200) NOT NULL, declared_weight_kg DECIMAL(10,2) NOT NULL);
CREATE TABLE inspections (inspection_id INT PRIMARY KEY, manifest_id INT NOT NULL, agent_id INT NOT NULL, inspected_at DATETIME NOT NULL);
CREATE TABLE violations (violation_id INT PRIMARY KEY, inspection_id INT NOT NULL, penalty_amount DECIMAL(12,2) NOT NULL, contraband_type VARCHAR(80) NOT NULL);

CREATE VIEW v_vehicle_registry AS
SELECT v.vehicle_id, v.license_plate, ow.owner_name, ctry.country_name AS origin_country
FROM vehicles AS v
JOIN owners AS ow ON ow.owner_id = v.owner_id
JOIN countries AS ctry ON ctry.country_id = v.origin_country_id;

CREATE VIEW v_checkpoint_location AS
SELECT cp.checkpoint_id, cp.checkpoint_name, d.district_name
FROM checkpoints AS cp
JOIN districts AS d ON d.district_id = cp.district_id;

CREATE VIEW v_crossing_detail AS
SELECT c.crossing_id, c.crossing_date, c.vehicle_id, loc.district_name, loc.checkpoint_name, o.officer_name
FROM crossings AS c
JOIN v_checkpoint_location AS loc ON loc.checkpoint_id = c.checkpoint_id
JOIN officers AS o ON o.officer_id = c.officer_id;

CREATE VIEW v_cargo_violation AS
SELECT m.crossing_id, m.cargo_description, m.declared_weight_kg, a.agent_name, a.certification,
       vi.contraband_type, vi.penalty_amount
FROM violations AS vi
JOIN inspections AS i ON i.inspection_id = vi.inspection_id
JOIN manifests AS m ON m.manifest_id = i.manifest_id
JOIN agents AS a ON a.agent_id = i.agent_id;

DELIMITER $$

CREATE PROCEDURE district_crossing_summary(IN in_year INT)
BEGIN
    SELECT cd.district_name, cd.checkpoint_name, cd.officer_name, reg.origin_country,
           COUNT(*) AS total_crossings
    FROM v_crossing_detail AS cd
    JOIN v_vehicle_registry AS reg ON reg.vehicle_id = cd.vehicle_id
    WHERE YEAR(cd.crossing_date) = in_year
    GROUP BY cd.district_name, cd.checkpoint_name, cd.officer_name, reg.origin_country
    ORDER BY cd.district_name, cd.checkpoint_name, total_crossings DESC;
END$$

CREATE PROCEDURE high_penalty_cargo(IN in_year INT, IN in_penalty_floor DECIMAL(12,2))
BEGIN
    SELECT reg.owner_name, reg.license_plate, cv.cargo_description, cv.declared_weight_kg,
           cv.agent_name, cv.certification, cv.contraband_type, cv.penalty_amount
    FROM v_cargo_violation AS cv
    JOIN v_crossing_detail AS cd ON cd.crossing_id = cv.crossing_id
    JOIN v_vehicle_registry AS reg ON reg.vehicle_id = cd.vehicle_id
    WHERE YEAR(cd.crossing_date) = in_year
      AND cv.penalty_amount > in_penalty_floor
    ORDER BY cv.penalty_amount DESC, reg.owner_name;
END$$

CREATE PROCEDURE evaluate(IN in_year INT)
BEGIN
    CALL district_crossing_summary(in_year);
    CALL high_penalty_cargo(in_year, 1000.00);
END$$

DELIMITER ;

CALL evaluate(2023);

