CREATE TABLE billing_tiers (tier_id int PRIMARY KEY, tier_name text, monthly_rate numeric(8,2));
CREATE TABLE customers (customer_id int PRIMARY KEY, customer_name text, tier_id int REFERENCES billing_tiers);
CREATE TABLE vendors (vendor_id int PRIMARY KEY, vendor_name text);
CREATE TABLE chemicals (chemical_id int PRIMARY KEY, description text, vendor_id int REFERENCES vendors);
CREATE TABLE fabrics (fabric_id int PRIMARY KEY, fabric_type text, chemical_id int REFERENCES chemicals);
CREATE TABLE machines (machine_id int PRIMARY KEY, serial_number text);
CREATE TABLE workers (worker_id int PRIMARY KEY, worker_name text, shift text);
CREATE TABLE billing_periods (period_id int PRIMARY KEY, month_name text, period_start date, period_end date);
CREATE TABLE orders (order_id int PRIMARY KEY, customer_id int REFERENCES customers, order_date date,
                     machine_id int REFERENCES machines, worker_id int REFERENCES workers);
CREATE TABLE garments (garment_id int PRIMARY KEY, order_id int REFERENCES orders, fabric_id int REFERENCES fabrics);

CREATE VIEW garment_chemistry AS
    SELECT g.garment_id, g.order_id, f.fabric_type, ch.description AS chemical_applied, v.vendor_name
    FROM garments g
    JOIN fabrics f ON f.fabric_id = g.fabric_id
    JOIN chemicals ch ON ch.chemical_id = f.chemical_id
    JOIN vendors v ON v.vendor_id = ch.vendor_id;

CREATE VIEW order_context AS
    SELECT o.order_id, o.order_date, c.customer_name, t.tier_name, m.serial_number, w.worker_name
    FROM orders o
    JOIN customers c ON c.customer_id = o.customer_id
    JOIN billing_tiers t ON t.tier_id = c.tier_id
    JOIN machines m ON m.machine_id = o.machine_id
    JOIN workers w ON w.worker_id = o.worker_id;

