CREATE FUNCTION period_orders(p_month text) RETURNS TABLE (order_id int) AS $$
    SELECT o.order_id
    FROM billing_periods p
    JOIN orders o ON o.order_date BETWEEN p.period_start AND p.period_end
    WHERE lower(p.month_name) = lower(p_month);
$$ LANGUAGE sql;

CREATE FUNCTION customer_garment_lines(p_month text)
RETURNS TABLE (customer_name text, tier_name text, order_date date, fabric_type text, chemical_applied text) AS $$
    SELECT oc.customer_name, oc.tier_name, oc.order_date, gc.fabric_type, gc.chemical_applied
    FROM period_orders(p_month) po
    JOIN order_context oc ON oc.order_id = po.order_id
    JOIN garment_chemistry gc ON gc.order_id = po.order_id
    ORDER BY oc.customer_name, oc.order_date, gc.fabric_type;
$$ LANGUAGE sql;

CREATE FUNCTION machine_month_stats(p_month text)
RETURNS TABLE (serial_number text, worker_name text, vendor_name text, garments_processed bigint) AS $$
