    FROM period_orders(p_month) po
    JOIN order_context oc ON oc.order_id = po.order_id
    JOIN garment_chemistry gc ON gc.order_id = po.order_id
    GROUP BY oc.serial_number, oc.worker_name, gc.vendor_name
    ORDER BY oc.serial_number, gc.vendor_name;
$$ LANGUAGE sql;

CREATE FUNCTION invoice(month text) RETURNS SETOF refcursor AS $$
DECLARE
    lines refcursor := 'customer_invoices';
    utilization refcursor := 'machine_utilization';
BEGIN
    IF NOT EXISTS (SELECT 1 FROM billing_periods WHERE lower(month_name) = lower(month)) THEN
        RAISE EXCEPTION 'unknown billing period: %', month;
    END IF;
    OPEN lines FOR SELECT * FROM customer_garment_lines(month);
    RETURN NEXT lines;
    OPEN utilization FOR SELECT * FROM machine_month_stats(month);
    RETURN NEXT utilization;
END;
$$ LANGUAGE plpgsql;

BEGIN;
SELECT invoice('november');
FETCH ALL FROM customer_invoices;
FETCH ALL FROM machine_utilization;
COMMIT;

