CREATE TABLE ocean_regions (region_id INT PRIMARY KEY, region_name VARCHAR(60));
CREATE TABLE species (species_id INT PRIMARY KEY, description VARCHAR(120), region_id INT);
CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(80));
CREATE TABLE filters (filter_id INT PRIMARY KEY, model VARCHAR(60), supplier_id INT);
CREATE TABLE tanks (tank_id INT PRIMARY KEY, tank_name VARCHAR(80), species_id INT, filter_id INT);
CREATE TABLE technicians (tech_id INT PRIMARY KEY, tech_name VARCHAR(80));
CREATE TABLE maintenance_rounds (round_id INT PRIMARY KEY, filter_id INT, tech_id INT, maint_date DATE);
CREATE TABLE biologists (bio_id INT PRIMARY KEY, bio_name VARCHAR(80));
CREATE TABLE readings (reading_id INT PRIMARY KEY, tank_id INT, bio_id INT, week_no INT, reading_date DATE, quality DECIMAL(5,2));
CREATE TABLE vendors (vendor_id INT PRIMARY KEY, vendor_name VARCHAR(80));
CREATE TABLE treatments (treatment_id INT PRIMARY KEY, description VARCHAR(120), vendor_id INT);
CREATE TABLE administrations (admin_id INT PRIMARY KEY, tank_id INT, bio_id INT, treatment_id INT, admin_date DATE);

CREATE VIEW species_habitat AS
SELECT sp.species_id, sp.description, orx.region_name
FROM species AS sp
JOIN ocean_regions AS orx ON orx.region_id = sp.region_id;

CREATE VIEW filter_supply AS
SELECT f.filter_id, f.model, s.supplier_name
FROM filters AS f
JOIN suppliers AS s ON s.supplier_id = f.supplier_id;

CREATE VIEW tank_profile AS
SELECT t.tank_id, t.tank_name, t.filter_id,
       sh.description AS species_description,
       sh.region_name AS ocean_region,
       fs.model AS filter_model,
       fs.supplier_name
FROM tanks AS t
JOIN species_habitat AS sh ON sh.species_id = t.species_id
JOIN filter_supply AS fs ON fs.filter_id = t.filter_id;

CREATE VIEW maintenance_log AS
SELECT mr.filter_id, mr.maint_date, tech.tech_name
FROM maintenance_rounds AS mr
JOIN technicians AS tech ON tech.tech_id = mr.tech_id;

CREATE VIEW treatment_log AS
SELECT a.tank_id, a.admin_date, b.bio_name, tr.description, v.vendor_name
FROM administrations AS a
JOIN biologists AS b ON b.bio_id = a.bio_id
JOIN treatments AS tr ON tr.treatment_id = a.treatment_id
JOIN vendors AS v ON v.vendor_id = tr.vendor_id;

CREATE VIEW weekly_tank_quality AS
SELECT week_no, tank_id, AVG(quality) AS avg_quality
FROM readings
GROUP BY week_no, tank_id;

DELIMITER $$
CREATE PROCEDURE monitor(IN week INT)
BEGIN
    DECLARE quality_floor DECIMAL(5,2) DEFAULT 6.00;

    SELECT tp.tank_name,
           tp.species_description,
           tp.ocean_region,
           tp.filter_model,
           tp.supplier_name,
           ROUND(q.avg_quality, 2) AS weekly_avg_quality
    FROM weekly_tank_quality AS q
    JOIN tank_profile AS tp ON tp.tank_id = q.tank_id
    WHERE q.week_no = week
    ORDER BY q.avg_quality ASC, tp.tank_name ASC;

    SELECT ml.tech_name AS pump_technician,
           ml.maint_date AS maintenance_date,
           tl.bio_name AS marine_biologist,
           tl.description AS treatment_description,
           tl.vendor_name AS pharmaceutical_vendor
    FROM weekly_tank_quality AS q
    JOIN tank_profile AS tp ON tp.tank_id = q.tank_id
    JOIN maintenance_log AS ml ON ml.filter_id = tp.filter_id
    JOIN treatment_log AS tl ON tl.tank_id = tp.tank_id
    WHERE q.week_no = week
      AND q.avg_quality < quality_floor
      AND WEEK(ml.maint_date) = week
      AND WEEK(tl.admin_date) = week
    ORDER BY ml.maint_date ASC, ml.tech_name ASC;
END$$
DELIMITER ;

CALL monitor(42);

