           ROUND(q.avg_quality, 2) AS weekly_avg_quality
    FROM weekly_tank_quality AS q, tank_profile AS tp
    WHERE tp.tank_id = q.tank_id
      AND q.week_no = week
    ORDER BY q.avg_quality ASC, tp.tank_name ASC;

    SELECT ml.tech_name AS pump_technician,
           ml.maint_date AS maintenance_date,
           tl.bio_name AS marine_biologist,
           tl.description AS treatment_description,
           tl.vendor_name AS pharmaceutical_vendor
    FROM weekly_tank_quality AS q, tank_profile AS tp, maintenance_log AS ml, treatment_log AS tl
    WHERE tp.tank_id = q.tank_id
      AND ml.filter_id = tp.filter_id
      AND tl.tank_id = tp.tank_id
      AND q.week_no = week
      AND q.avg_quality < quality_floor
      AND WEEK(ml.maint_date) = week
      AND WEEK(tl.admin_date) = week
    ORDER BY ml.maint_date ASC, ml.tech_name ASC;
END$$
DELIMITER ;

