CREATE TABLE zones (zone_id integer PRIMARY KEY, zone_name text NOT NULL);
CREATE TABLE grow_rooms (room_id integer PRIMARY KEY, room_number text NOT NULL, zone_id integer REFERENCES zones (zone_id));
CREATE TABLE technicians (tech_id integer PRIMARY KEY, tech_name text NOT NULL);
CREATE TABLE substrates (substrate_id integer PRIMARY KEY, room_id integer REFERENCES grow_rooms (room_id), tech_id integer REFERENCES technicians (tech_id), substrate_type text NOT NULL);
CREATE TABLE labs (lab_id integer PRIMARY KEY, lab_name text NOT NULL);
CREATE TABLE engineers (engineer_id integer PRIMARY KEY, engineer_name text NOT NULL);
CREATE TABLE climate_profiles (climate_id integer PRIMARY KEY, engineer_id integer REFERENCES engineers (engineer_id), profile_name text NOT NULL);
CREATE TABLE spawn_batches (batch_id integer PRIMARY KEY, lab_id integer REFERENCES labs (lab_id), substrate_id integer REFERENCES substrates (substrate_id), climate_id integer REFERENCES climate_profiles (climate_id));
CREATE TABLE harvesters (harvester_id integer PRIMARY KEY, harvester_name text NOT NULL);
CREATE TABLE yields (yield_id integer PRIMARY KEY, batch_id integer REFERENCES spawn_batches (batch_id), harvester_id integer REFERENCES harvesters (harvester_id), weight_kg numeric(10,2) NOT NULL);
CREATE TABLE inspectors (inspector_id integer PRIMARY KEY, inspector_name text NOT NULL);
CREATE TABLE gradings (grading_id integer PRIMARY KEY, yield_id integer REFERENCES yields (yield_id), inspector_id integer REFERENCES inspectors (inspector_id), grade text NOT NULL);
CREATE TABLE buyers (buyer_id integer PRIMARY KEY, buyer_name text NOT NULL);
CREATE TABLE sales (sale_id integer PRIMARY KEY, grading_id integer REFERENCES gradings (grading_id), buyer_id integer REFERENCES buyers (buyer_id), kg_sold numeric(10,2) NOT NULL);

CREATE FUNCTION batch_header(batch integer) RETURNS text
LANGUAGE sql AS $$
    SELECT format('Batch %s from lab %s under profile %s managed by %s',
                  b.batch_id, l.lab_name, cp.profile_name, e.engineer_name)
      FROM spawn_batches AS b
      JOIN labs AS l ON l.lab_id = b.lab_id
      JOIN climate_profiles AS cp ON cp.climate_id = b.climate_id
      JOIN engineers AS e ON e.engineer_id = cp.engineer_id
     WHERE b.batch_id = batch;
$$;

CREATE FUNCTION harvest_rooms(batch integer)
RETURNS TABLE (zone_name text, room_number text, tech_name text,
               substrate_type text, total_yield numeric)
LANGUAGE sql AS $$
    SELECT z.zone_name, r.room_number, t.tech_name, s.substrate_type,
           COALESCE((SELECT SUM(y.weight_kg) FROM yields AS y
                      WHERE y.batch_id = b.batch_id), 0)
      FROM spawn_batches AS b
      JOIN substrates AS s ON s.substrate_id = b.substrate_id
      JOIN grow_rooms AS r ON r.room_id = s.room_id
      JOIN zones AS z ON z.zone_id = r.zone_id
      JOIN technicians AS t ON t.tech_id = s.tech_id
     WHERE b.batch_id = batch
     ORDER BY z.zone_name, r.room_number;
$$;

CREATE FUNCTION harvest_chain(batch integer)
RETURNS TABLE (harvester_name text, grade text, inspector_name text,
               buyer_name text, kg_sold numeric)
LANGUAGE sql AS $$
    SELECT h.harvester_name, g.grade, i.inspector_name, bu.buyer_name, sa.kg_sold
      FROM yields AS y
      JOIN harvesters AS h ON h.harvester_id = y.harvester_id
      JOIN gradings AS g ON g.yield_id = y.yield_id
      JOIN inspectors AS i ON i.inspector_id = g.inspector_id
      JOIN sales AS sa ON sa.grading_id = g.grading_id
      JOIN buyers AS bu ON bu.buyer_id = sa.buyer_id
     WHERE y.batch_id = batch
     ORDER BY h.harvester_name, g.grade, bu.buyer_name;
$$;

CREATE FUNCTION buyer_totals(batch integer)
RETURNS TABLE (buyer_name text, kg_bought numeric)
LANGUAGE sql AS $$
    SELECT bu.buyer_name, SUM(sa.kg_sold)
      FROM sales AS sa
      JOIN gradings AS g ON g.grading_id = sa.grading_id
      JOIN yields AS y ON y.yield_id = g.yield_id
      JOIN buyers AS bu ON bu.buyer_id = sa.buyer_id
     WHERE y.batch_id = batch
     GROUP BY bu.buyer_name
     ORDER BY SUM(sa.kg_sold) DESC, bu.buyer_name;
$$;

CREATE FUNCTION grade_totals(batch integer)
RETURNS TABLE (grade text, inspector_name text, kg_graded numeric)
LANGUAGE sql AS $$
    SELECT g.grade, i.inspector_name, SUM(y.weight_kg)
      FROM gradings AS g
      JOIN yields AS y ON y.yield_id = g.yield_id
      JOIN inspectors AS i ON i.inspector_id = g.inspector_id
     WHERE y.batch_id = batch
     GROUP BY g.grade, i.inspector_name
     ORDER BY g.grade, i.inspector_name;
$$;

CREATE FUNCTION harvest(batch integer)
RETURNS SETOF text
LANGUAGE plpgsql AS $$
DECLARE
    rec record;
BEGIN
    RETURN NEXT COALESCE(batch_header(batch), format('Batch %s not found', batch));
    FOR rec IN SELECT * FROM harvest_rooms(batch) LOOP
        RETURN NEXT format('  zone %s / room %s / tech %s / %s / %s kg',
                           rec.zone_name, rec.room_number, rec.tech_name,
                           rec.substrate_type, rec.total_yield);
    END LOOP;
    FOR rec IN SELECT * FROM harvest_chain(batch) LOOP
        RETURN NEXT format('  harvester %s / grade %s by %s / buyer %s (%s kg)',
                           rec.harvester_name, rec.grade, rec.inspector_name,
                           rec.buyer_name, rec.kg_sold);
    END LOOP;
    FOR rec IN SELECT * FROM grade_totals(batch) LOOP
        RETURN NEXT format('  grade %s inspected by %s: %s kg',
                           rec.grade, rec.inspector_name, rec.kg_graded);
    END LOOP;
    FOR rec IN SELECT * FROM buyer_totals(batch) LOOP
        RETURN NEXT format('  buyer %s purchased %s kg', rec.buyer_name, rec.kg_bought);
    END LOOP;
END;
$$;

SELECT * FROM harvest(700);

