CREATE TABLE AviationAuthorities (authority_id INT PRIMARY KEY, authority_name VARCHAR(80));
CREATE TABLE RegionalSectors (sector_id INT PRIMARY KEY, sector_name VARCHAR(80), authority_id INT);
CREATE TABLE ControlTowers (tower_id INT PRIMARY KEY, tower_name VARCHAR(80), sector_id INT, shift VARCHAR(20));
CREATE TABLE Technicians (technician_id INT PRIMARY KEY, technician_name VARCHAR(80));
CREATE TABLE RadarAntennas (antenna_id INT PRIMARY KEY, antenna_model VARCHAR(60), tower_id INT, technician_id INT);
CREATE TABLE Rosters (roster_id INT PRIMARY KEY, shift VARCHAR(20));
CREATE TABLE Controllers (controller_id INT PRIMARY KEY, controller_name VARCHAR(80), roster_id INT, tower_id INT);
CREATE TABLE PassengerAirlines (airline_id INT PRIMARY KEY, airline_name VARCHAR(80));
CREATE TABLE CommercialFlights (flight_id INT PRIMARY KEY, flight_number VARCHAR(12), airline_id INT);
CREATE TABLE Handoffs (handoff_id INT PRIMARY KEY, flight_id INT, from_sector_id INT, to_sector_id INT,
                       handoff_time DATETIME, delay_minutes INT);
CREATE TABLE CommsLogs (log_id INT PRIMARY KEY, handoff_id INT, controller_id INT, investigator_id INT,
                        audit_notes VARCHAR(200));
CREATE TABLE SafetyInvestigators (investigator_id INT PRIMARY KEY, investigator_name VARCHAR(80));

DELIMITER $$

CREATE FUNCTION staffed_towers(p_shift VARCHAR(20)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total
    FROM ControlTowers AS T
    JOIN RegionalSectors AS S ON T.sector_id = S.sector_id
    WHERE T.shift = p_shift;
    RETURN total;
END$$

CREATE FUNCTION delayed_handoffs(p_shift VARCHAR(20)) RETURNS INT READS SQL DATA
BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total
    FROM CommsLogs AS L
    JOIN Handoffs AS H ON L.handoff_id = H.handoff_id
    JOIN Controllers AS C ON L.controller_id = C.controller_id
    JOIN Rosters AS O ON C.roster_id = O.roster_id
    WHERE O.shift = p_shift AND H.delay_minutes > 0;
    RETURN total;
END$$

CREATE PROCEDURE tower_radar_report(IN p_shift VARCHAR(20))
BEGIN
    SELECT T.tower_name, S.sector_name, A.authority_name, R.antenna_model, E.technician_name
    FROM ControlTowers AS T
    JOIN RegionalSectors AS S ON T.sector_id = S.sector_id
    JOIN AviationAuthorities AS A ON S.authority_id = A.authority_id
    JOIN RadarAntennas AS R ON R.tower_id = T.tower_id
    JOIN Technicians AS E ON R.technician_id = E.technician_id
    WHERE T.shift = p_shift
    ORDER BY T.tower_name, R.antenna_model;
END$$

CREATE PROCEDURE delayed_comms_report(IN p_shift VARCHAR(20))
BEGIN
    SELECT C.controller_name, F.flight_number, P.airline_name, H.handoff_time, I.investigator_name,
           L.audit_notes, FromSector.sector_name AS handed_from, ToSector.sector_name AS handed_to
    FROM CommsLogs AS L
    JOIN Handoffs AS H ON L.handoff_id = H.handoff_id
    JOIN CommercialFlights AS F ON H.flight_id = F.flight_id
    JOIN PassengerAirlines AS P ON F.airline_id = P.airline_id
    JOIN Controllers AS C ON L.controller_id = C.controller_id
    JOIN Rosters AS O ON C.roster_id = O.roster_id
    JOIN SafetyInvestigators AS I ON L.investigator_id = I.investigator_id
    JOIN RegionalSectors AS FromSector ON H.from_sector_id = FromSector.sector_id
    JOIN RegionalSectors AS ToSector ON H.to_sector_id = ToSector.sector_id
    WHERE O.shift = p_shift AND H.delay_minutes > 0
    ORDER BY H.delay_minutes DESC, H.handoff_time;
END$$

CREATE PROCEDURE authority_delay_summary(IN p_shift VARCHAR(20))
BEGIN
    SELECT A.authority_name, S.sector_name, COUNT(*) AS delayed_count, MAX(H.delay_minutes) AS worst_delay
    FROM Handoffs AS H
    JOIN RegionalSectors AS S ON H.from_sector_id = S.sector_id
    JOIN AviationAuthorities AS A ON S.authority_id = A.authority_id
    JOIN ControlTowers AS T ON T.sector_id = S.sector_id
    WHERE T.shift = p_shift AND H.delay_minutes > 0
    GROUP BY A.authority_name, S.sector_name
    ORDER BY worst_delay DESC;
END$$

CREATE PROCEDURE trace(IN shift VARCHAR(20))
BEGIN
    IF staffed_towers(shift) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No control towers staffed for the requested shift';
    END IF;

    CALL tower_radar_report(shift);

    IF delayed_handoffs(shift) > 0 THEN
        CALL delayed_comms_report(shift);
        CALL authority_delay_summary(shift);
    END IF;
END$$

DELIMITER ;

CALL trace('night');

