CREATE TABLE shipping_lines (line_id INT PRIMARY KEY, line_name VARCHAR(80) NOT NULL);
CREATE TABLE marine_steelworks (works_id INT PRIMARY KEY, works_name VARCHAR(80) NOT NULL);
CREATE TABLE cargo_ships (ship_id INT PRIMARY KEY, ship_name VARCHAR(80) NOT NULL, line_id INT NOT NULL);
CREATE TABLE ballast_tanks (tank_id INT PRIMARY KEY, ship_id INT NOT NULL, works_id INT NOT NULL, capacity_liters DECIMAL(12,1) NOT NULL);
CREATE TABLE coastal_authorities (authority_id INT PRIMARY KEY, authority_name VARCHAR(80) NOT NULL);
CREATE TABLE ports (port_id INT PRIMARY KEY, port_name VARCHAR(80) NOT NULL, authority_id INT NOT NULL);
CREATE TABLE oceanographers (oceanographer_id INT PRIMARY KEY, oceanographer_name VARCHAR(80) NOT NULL);
CREATE TABLE salinity_readings (reading_id INT PRIMARY KEY, port_id INT NOT NULL, oceanographer_id INT NOT NULL, salinity_ppt DECIMAL(5,2) NOT NULL, reading_time DATETIME NOT NULL);
CREATE TABLE chief_engineers (engineer_id INT PRIMARY KEY, engineer_name VARCHAR(80) NOT NULL);
CREATE TABLE voyages (voyage_id INT PRIMARY KEY, voyage_name VARCHAR(80) NOT NULL, ship_id INT NOT NULL);
CREATE TABLE pump_logs (log_id INT PRIMARY KEY, voyage_id INT NOT NULL, tank_id INT NOT NULL, intake_port_id INT NOT NULL, discharge_port_id INT NOT NULL, engineer_id INT NOT NULL, intake_volume_liters DECIMAL(12,1) NOT NULL, discharge_volume_liters DECIMAL(12,1) NOT NULL, log_note VARCHAR(200) NOT NULL);
CREATE TABLE maritime_agencies (agency_id INT PRIMARY KEY, agency_name VARCHAR(80) NOT NULL);
CREATE TABLE environmental_inspectors (inspector_id INT PRIMARY KEY, inspector_name VARCHAR(80) NOT NULL, agency_id INT NOT NULL);
CREATE TABLE verifications (verification_id INT PRIMARY KEY, log_id INT NOT NULL, inspector_id INT NOT NULL, verification_status VARCHAR(40) NOT NULL);

CREATE VIEW tank_provenance AS
SELECT s.ship_id, s.ship_name, l.line_name, t.tank_id, t.capacity_liters, w.works_name
FROM cargo_ships AS s
JOIN shipping_lines AS l ON s.line_id = l.line_id
JOIN ballast_tanks AS t ON t.ship_id = s.ship_id
JOIN marine_steelworks AS w ON t.works_id = w.works_id;

CREATE VIEW port_salinity AS
SELECT p.port_id, p.port_name, a.authority_name, r.salinity_ppt, o.oceanographer_name, r.reading_time
FROM ports AS p
JOIN coastal_authorities AS a ON p.authority_id = a.authority_id
JOIN salinity_readings AS r ON r.port_id = p.port_id
JOIN oceanographers AS o ON r.oceanographer_id = o.oceanographer_id;

CREATE VIEW latest_port_salinity AS
SELECT ps.port_id, ps.port_name, ps.authority_name, ps.salinity_ppt, ps.oceanographer_name
FROM port_salinity AS ps
JOIN (SELECT port_id, MAX(reading_time) AS newest FROM port_salinity GROUP BY port_id) AS m
  ON m.port_id = ps.port_id AND m.newest = ps.reading_time;

CREATE VIEW inspector_authority AS
SELECT i.inspector_id, i.inspector_name, g.agency_name
FROM environmental_inspectors AS i
JOIN maritime_agencies AS g ON i.agency_id = g.agency_id;

DELIMITER $$

CREATE PROCEDURE discharge(IN voyage VARCHAR(80))
BEGIN
    SELECT tp.ship_name, tp.line_name, tp.capacity_liters, tp.works_name,
           SUM(pl.intake_volume_liters) AS total_intake_liters
    FROM voyages AS v
    JOIN pump_logs AS pl ON pl.voyage_id = v.voyage_id
    JOIN tank_provenance AS tp ON tp.tank_id = pl.tank_id AND tp.ship_id = v.ship_id
    WHERE v.voyage_name = voyage
    GROUP BY tp.ship_name, tp.line_name, tp.capacity_liters, tp.works_name
    ORDER BY tp.ship_name, tp.works_name;

    SELECT lps.port_name AS discharge_port, lps.authority_name, lps.oceanographer_name,
           lps.salinity_ppt, ce.engineer_name, pl.log_note, pl.discharge_volume_liters,
           ia.inspector_name, ia.agency_name, ver.verification_status
    FROM voyages AS v
    JOIN pump_logs AS pl ON pl.voyage_id = v.voyage_id
    JOIN latest_port_salinity AS lps ON lps.port_id = pl.discharge_port_id
    JOIN chief_engineers AS ce ON ce.engineer_id = pl.engineer_id
    JOIN verifications AS ver ON ver.log_id = pl.log_id
    JOIN inspector_authority AS ia ON ia.inspector_id = ver.inspector_id
    WHERE v.voyage_name = voyage
    ORDER BY lps.port_name, ver.verification_id;
END$$

DELIMITER ;

CALL discharge('pacific crossing seven');

