CREATE VIEW tank_provenance AS
SELECT s.ship_id, s.ship_name, l.line_name, t.tank_id, t.capacity_liters, w.works_name
FROM cargo_ships AS s, shipping_lines AS l, ballast_tanks AS t, marine_steelworks AS w
WHERE s.line_id = l.line_id AND t.ship_id = s.ship_id AND t.works_id = w.works_id;

CREATE VIEW port_salinity AS
SELECT p.port_id, p.port_name, a.authority_name, r.salinity_ppt, o.oceanographer_name, r.reading_time
FROM ports AS p, coastal_authorities AS a, salinity_readings AS r, oceanographers AS o
WHERE p.authority_id = a.authority_id AND r.port_id = p.port_id AND r.oceanographer_id = o.oceanographer_id;

CREATE VIEW latest_port_salinity AS
SELECT ps.port_id, ps.port_name, ps.authority_name, ps.salinity_ppt, ps.oceanographer_name
FROM port_salinity AS ps, (SELECT port_id, MAX(reading_time) AS newest FROM port_salinity GROUP BY port_id) AS m
WHERE m.port_id = ps.port_id AND m.newest = ps.reading_time;

CREATE VIEW inspector_authority AS
SELECT i.inspector_id, i.inspector_name, g.agency_name
FROM environmental_inspectors AS i, maritime_agencies AS g
WHERE i.agency_id = g.agency_id;

DELIMITER $$

CREATE PROCEDURE discharge(IN voyage VARCHAR(80))
BEGIN
    SELECT tp.ship_name, tp.line_name, tp.capacity_liters, tp.works_name,
           SUM(pl.intake_volume_liters) AS total_intake_liters
    FROM voyages AS v, pump_logs AS pl, tank_provenance AS tp
    WHERE pl.voyage_id = v.voyage_id AND tp.tank_id = pl.tank_id AND tp.ship_id = v.ship_id AND v.voyage_name = voyage
    GROUP BY tp.ship_name, tp.line_name, tp.capacity_liters, tp.works_name
    ORDER BY tp.ship_name, tp.works_name;

    SELECT lps.port_name AS discharge_port, lps.authority_name, lps.oceanographer_name,
           lps.salinity_ppt, ce.engineer_name, pl.log_note, pl.discharge_volume_liters,
           ia.inspector_name, ia.agency_name, ver.verification_status
    FROM voyages AS v, pump_logs AS pl, latest_port_salinity AS lps, chief_engineers AS ce, verifications AS ver, inspector_authority AS ia
    WHERE pl.voyage_id = v.voyage_id AND lps.port_id = pl.discharge_port_id AND ce.engineer_id = pl.engineer_id AND ver.log_id = pl.log_id AND ia.inspector_id = ver.inspector_id AND v.voyage_name = voyage
    ORDER BY lps.port_name, ver.verification_id;
END$$

DELIMITER ;

