DROP PROCEDURE IF EXISTS broadcast;
DROP FUNCTION IF EXISTS mapped_site_count;
DROP FUNCTION IF EXISTS low_signal_threshold;
DROP FUNCTION IF EXISTS site_regulators;
DROP FUNCTION IF EXISTS last_inspection_tech;

CREATE TABLE IF NOT EXISTS mapping_agencies (agency_id INT PRIMARY KEY, agency_name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS zones (zone_id INT PRIMARY KEY, zone_name VARCHAR(80) NOT NULL, agency_id INT NOT NULL);
CREATE TABLE IF NOT EXISTS vendors (vendor_id INT PRIMARY KEY, vendor_name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS antennas (antenna_id INT PRIMARY KEY, model VARCHAR(60) NOT NULL, vendor_id INT NOT NULL);
CREATE TABLE IF NOT EXISTS sites (site_id INT PRIMARY KEY, site_name VARCHAR(80) NOT NULL, region VARCHAR(80) NOT NULL, zone_id INT NOT NULL, antenna_id INT NOT NULL);
CREATE TABLE IF NOT EXISTS regulators (regulator_id INT PRIMARY KEY, regulator_name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS frequencies (freq_id INT PRIMARY KEY, site_id INT NOT NULL, freq_mhz DECIMAL(8,3) NOT NULL, regulator_id INT NOT NULL);
CREATE TABLE IF NOT EXISTS technicians (technician_id INT PRIMARY KEY, tech_name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS signal_logs (log_id INT PRIMARY KEY, site_id INT NOT NULL, technician_id INT NOT NULL, signal_strength_db DECIMAL(6,2) NOT NULL, logged_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS hubs (hub_id INT PRIMARY KEY, hub_location VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS crews (crew_id INT PRIMARY KEY, crew_name VARCHAR(80) NOT NULL, hub_id INT NOT NULL);
CREATE TABLE IF NOT EXISTS work_orders (order_id INT PRIMARY KEY, site_id INT NOT NULL, crew_id INT NOT NULL, status VARCHAR(30) NOT NULL);

DELIMITER $$

CREATE FUNCTION mapped_site_count(p_region VARCHAR(80)) RETURNS INT
READS SQL DATA
BEGIN
    DECLARE v_count INT;
    SELECT COUNT(*) INTO v_count
    FROM sites AS S
    JOIN zones AS Z ON S.zone_id = Z.zone_id
    JOIN mapping_agencies AS M ON Z.agency_id = M.agency_id
    WHERE S.region = p_region;
    RETURN v_count;
END$$

CREATE FUNCTION low_signal_threshold(p_region VARCHAR(80)) RETURNS DECIMAL(6,2)
READS SQL DATA
BEGIN
    DECLARE v_threshold DECIMAL(6,2);
    SELECT AVG(L.signal_strength_db) - 10.00 INTO v_threshold
    FROM signal_logs AS L
    JOIN sites AS S ON L.site_id = S.site_id
    WHERE S.region = p_region;
    RETURN IFNULL(v_threshold, -100.00);
END$$

CREATE FUNCTION site_regulators(p_site_id INT) RETURNS VARCHAR(255)
READS SQL DATA
BEGIN
    DECLARE v_names VARCHAR(255);
    SELECT GROUP_CONCAT(DISTINCT R.regulator_name ORDER BY R.regulator_name SEPARATOR ', ') INTO v_names
    FROM frequencies AS F
    JOIN regulators AS R ON F.regulator_id = R.regulator_id
    WHERE F.site_id = p_site_id;
    RETURN IFNULL(v_names, 'unallocated');
END$$

CREATE FUNCTION last_inspection_tech(p_site_id INT) RETURNS VARCHAR(80)
READS SQL DATA
BEGIN
    DECLARE v_tech VARCHAR(80);
    SELECT T.tech_name INTO v_tech
    FROM signal_logs AS L
    JOIN technicians AS T ON L.technician_id = T.technician_id
    WHERE L.site_id = p_site_id
    ORDER BY L.logged_at DESC
    LIMIT 1;
    RETURN IFNULL(v_tech, 'never inspected');
END$$

CREATE PROCEDURE broadcast(IN p_region VARCHAR(80))
BEGIN
    DECLARE v_limit DECIMAL(6,2);
    IF mapped_site_count(p_region) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'no mapped transmitter sites for region';
    END IF;
    SET v_limit = low_signal_threshold(p_region);

    SELECT S.site_name, Z.zone_name, M.agency_name, A.model AS antenna_model, V.vendor_name,
           site_regulators(S.site_id) AS allocating_regulators,
           last_inspection_tech(S.site_id) AS last_technician
    FROM sites AS S
    JOIN zones AS Z ON S.zone_id = Z.zone_id
    JOIN mapping_agencies AS M ON Z.agency_id = M.agency_id
    JOIN antennas AS A ON S.antenna_id = A.antenna_id
    JOIN vendors AS V ON A.vendor_id = V.vendor_id
    WHERE S.region = p_region
    ORDER BY Z.zone_name, S.site_name;

    SELECT S.site_name, F.freq_mhz, R.regulator_name, T.tech_name,
           L.signal_strength_db, L.logged_at, C.crew_name, H.hub_location, W.status
    FROM sites AS S
    JOIN frequencies AS F ON S.site_id = F.site_id
    JOIN regulators AS R ON F.regulator_id = R.regulator_id
    JOIN signal_logs AS L ON S.site_id = L.site_id
    JOIN technicians AS T ON L.technician_id = T.technician_id
    JOIN work_orders AS W ON S.site_id = W.site_id
    JOIN crews AS C ON W.crew_id = C.crew_id
    JOIN hubs AS H ON C.hub_id = H.hub_id
    WHERE S.region = p_region
      AND L.signal_strength_db < v_limit
    ORDER BY L.signal_strength_db ASC, S.site_name, F.freq_mhz;
END$$

DELIMITER ;

CALL broadcast('northern valley');

