CREATE TABLE counties (county_id INT PRIMARY KEY, county_name VARCHAR(60));
CREATE TABLE firms (firm_id INT PRIMARY KEY, firm_name VARCHAR(80));
CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(80));
CREATE TABLE gantries (gantry_id INT PRIMARY KEY, location VARCHAR(80), firm_id INT, county_id INT);
CREATE TABLE readers (reader_id INT PRIMARY KEY, gantry_id INT, model VARCHAR(40), supplier_id INT);
CREATE TABLE authorities (authority_id INT PRIMARY KEY, authority_name VARCHAR(80));
CREATE TABLE weight_classes (class_id INT PRIMARY KEY, class_name VARCHAR(40), authority_id INT, toll_rate DECIMAL(6,2));
CREATE TABLE motorists (motorist_id INT PRIMARY KEY, motorist_name VARCHAR(80));
CREATE TABLE accounts (account_id INT PRIMARY KEY, motorist_id INT, balance DECIMAL(10,2));
CREATE TABLE agents (agent_id INT PRIMARY KEY, agent_name VARCHAR(80));
CREATE TABLE crossings (crossing_id INT PRIMARY KEY, gantry_id INT, reader_id INT, account_id INT, class_id INT, crossed_at DATE, billed TINYINT DEFAULT 0);
CREATE TABLE disputes (dispute_id INT PRIMARY KEY, crossing_id INT, agent_id INT, resolution VARCHAR(120), refunded TINYINT DEFAULT 0);

DELIMITER //

CREATE PROCEDURE gantry_hardware_deployment()
BEGIN
    SELECT g.location, f.firm_name, c.county_name, r.model, s.supplier_name
    FROM gantries AS g
    JOIN firms AS f ON g.firm_id = f.firm_id
    JOIN counties AS c ON g.county_id = c.county_id
    JOIN readers AS r ON r.gantry_id = g.gantry_id
    JOIN suppliers AS s ON r.supplier_id = s.supplier_id
    ORDER BY c.county_name, g.location, r.model;
END //

CREATE PROCEDURE apply_charges(IN p_month VARCHAR(20))
BEGIN
    UPDATE accounts AS ac
    JOIN crossings AS x ON x.account_id = ac.account_id
    JOIN weight_classes AS w ON x.class_id = w.class_id
    SET ac.balance = ac.balance + w.toll_rate, x.billed = 1
    WHERE x.billed = 0
      AND MONTH(x.crossed_at) = MONTH(STR_TO_DATE(p_month, '%M'));
END //

CREATE PROCEDURE apply_dispute_credits(IN p_month VARCHAR(20))
BEGIN
    UPDATE accounts AS ac
    JOIN crossings AS x ON x.account_id = ac.account_id
    JOIN weight_classes AS w ON x.class_id = w.class_id
    JOIN disputes AS d ON d.crossing_id = x.crossing_id
    SET ac.balance = ac.balance - w.toll_rate, d.refunded = 1
    WHERE d.refunded = 0
      AND d.resolution LIKE 'refund%'
      AND MONTH(x.crossed_at) = MONTH(STR_TO_DATE(p_month, '%M'));
END //

CREATE PROCEDURE motorist_toll_billing(IN p_month VARCHAR(20))
BEGIN
    SELECT w.class_name, w.toll_rate, ta.authority_name, m.motorist_name,
           ac.balance, ag.agent_name, d.resolution
    FROM crossings AS x
    JOIN weight_classes AS w ON x.class_id = w.class_id
    JOIN authorities AS ta ON w.authority_id = ta.authority_id
    JOIN accounts AS ac ON x.account_id = ac.account_id
    JOIN motorists AS m ON ac.motorist_id = m.motorist_id
    JOIN disputes AS d ON d.crossing_id = x.crossing_id
    JOIN agents AS ag ON d.agent_id = ag.agent_id
    WHERE MONTH(x.crossed_at) = MONTH(STR_TO_DATE(p_month, '%M'))
    ORDER BY m.motorist_name, w.class_name;
END //

CREATE PROCEDURE county_revenue_summary(IN p_month VARCHAR(20))
BEGIN
    SELECT c.county_name, COUNT(*) AS crossings_billed, SUM(w.toll_rate) AS gross_tolls
    FROM crossings AS x
    JOIN gantries AS g ON x.gantry_id = g.gantry_id
    JOIN counties AS c ON g.county_id = c.county_id
    JOIN weight_classes AS w ON x.class_id = w.class_id
    WHERE x.billed = 1
      AND MONTH(x.crossed_at) = MONTH(STR_TO_DATE(p_month, '%M'))
    GROUP BY c.county_name
    ORDER BY gross_tolls DESC;
END //

CREATE PROCEDURE bill(IN p_month VARCHAR(20))
BEGIN
    IF STR_TO_DATE(p_month, '%M') IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'bill: month name not recognised';
    END IF;
    CALL gantry_hardware_deployment();
    CALL apply_charges(p_month);
    CALL apply_dispute_credits(p_month);
    CALL motorist_toll_billing(p_month);
    CALL county_revenue_summary(p_month);
END //

DELIMITER ;

CALL bill('october');

