      AND x.account_id = ac.account_id
      AND ac.motorist_id = m.motorist_id
      AND d.crossing_id = x.crossing_id
      AND d.agent_id = ag.agent_id
      AND MONTH(x.crossed_at) = MONTH(STR_TO_DATE(p_month, '%M'))
