CREATE TABLE transit_lines (line_id INT PRIMARY KEY, line_name VARCHAR(80) NOT NULL);
CREATE TABLE district_planners (planner_id INT PRIMARY KEY, planner_name VARCHAR(80) NOT NULL);
CREATE TABLE city_boroughs (borough_id INT PRIMARY KEY, borough_name VARCHAR(80) NOT NULL, planner_id INT REFERENCES district_planners (planner_id));
CREATE TABLE tunnel_segments (segment_id INT PRIMARY KEY, segment_name VARCHAR(80) NOT NULL, line_id INT REFERENCES transit_lines (line_id), borough_id INT REFERENCES city_boroughs (borough_id));
CREATE TABLE construction_contractors (contractor_id INT PRIMARY KEY, contractor_name VARCHAR(80) NOT NULL);
CREATE TABLE ventilation_shafts (shaft_id INT PRIMARY KEY, segment_id INT REFERENCES tunnel_segments (segment_id), depth_m DECIMAL(6,2), contractor_id INT REFERENCES construction_contractors (contractor_id));
CREATE TABLE motor_suppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(80) NOT NULL);
CREATE TABLE extraction_fans (fan_id INT PRIMARY KEY, shaft_id INT REFERENCES ventilation_shafts (shaft_id), fan_model VARCHAR(80), supplier_id INT REFERENCES motor_suppliers (supplier_id));
CREATE TABLE environmental_technicians (technician_id INT PRIMARY KEY, technician_name VARCHAR(80) NOT NULL);
CREATE TABLE air_quality_sensors (sensor_id INT PRIMARY KEY, fan_id INT REFERENCES extraction_fans (fan_id), reading_ppm DECIMAL(8,2), technician_id INT REFERENCES environmental_technicians (technician_id));
CREATE TABLE subway_mechanics (mechanic_id INT PRIMARY KEY, mechanic_name VARCHAR(80) NOT NULL);
CREATE TABLE maintenance_routines (routine_id INT PRIMARY KEY, fan_id INT REFERENCES extraction_fans (fan_id), mechanic_id INT REFERENCES subway_mechanics (mechanic_id));
CREATE TABLE fire_marshals (marshal_id INT PRIMARY KEY, marshal_name VARCHAR(80) NOT NULL);
CREATE TABLE emergency_tests (test_id INT PRIMARY KEY, routine_id INT REFERENCES maintenance_routines (routine_id), marshal_id INT REFERENCES fire_marshals (marshal_id), test_result VARCHAR(40));

DELIMITER $$
CREATE PROCEDURE ventilate (IN line VARCHAR(80))
BEGIN
    DECLARE segment_count INT;
    SELECT COUNT(*) INTO segment_count
      FROM tunnel_segments AS ts
      JOIN transit_lines AS tl ON tl.line_id = ts.line_id
     WHERE tl.line_name = line;
    IF segment_count = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No tunnel segments recorded for the requested transit line';
    END IF;

    SELECT ts.segment_name, cb.borough_name, dp.planner_name, vs.depth_m, cc.contractor_name
      FROM tunnel_segments AS ts
      JOIN transit_lines AS tl ON tl.line_id = ts.line_id
      JOIN city_boroughs AS cb ON cb.borough_id = ts.borough_id
      JOIN district_planners AS dp ON dp.planner_id = cb.planner_id
      JOIN ventilation_shafts AS vs ON vs.segment_id = ts.segment_id
      JOIN construction_contractors AS cc ON cc.contractor_id = vs.contractor_id
     WHERE tl.line_name = line
     ORDER BY ts.segment_name, vs.depth_m DESC;

    SELECT ts.segment_name, vs.depth_m, ef.fan_model, ms.supplier_name
      FROM extraction_fans AS ef
      JOIN ventilation_shafts AS vs ON vs.shaft_id = ef.shaft_id
      JOIN tunnel_segments AS ts ON ts.segment_id = vs.segment_id
      JOIN transit_lines AS tl ON tl.line_id = ts.line_id
      JOIN motor_suppliers AS ms ON ms.supplier_id = ef.supplier_id
     WHERE tl.line_name = line
     ORDER BY ts.segment_name, ef.fan_model;

    SELECT ts.segment_name, ef.fan_model, aqs.reading_ppm, et.technician_name
      FROM air_quality_sensors AS aqs
      JOIN extraction_fans AS ef ON ef.fan_id = aqs.fan_id
      JOIN ventilation_shafts AS vs ON vs.shaft_id = ef.shaft_id
      JOIN tunnel_segments AS ts ON ts.segment_id = vs.segment_id
      JOIN transit_lines AS tl ON tl.line_id = ts.line_id
      JOIN environmental_technicians AS et ON et.technician_id = aqs.technician_id
     WHERE tl.line_name = line
     ORDER BY aqs.reading_ppm DESC, ef.fan_model;

    SELECT ts.segment_name, AVG(aqs.reading_ppm) AS mean_ppm, MAX(aqs.reading_ppm) AS peak_ppm
      FROM air_quality_sensors AS aqs
      JOIN extraction_fans AS ef ON ef.fan_id = aqs.fan_id
      JOIN ventilation_shafts AS vs ON vs.shaft_id = ef.shaft_id
      JOIN tunnel_segments AS ts ON ts.segment_id = vs.segment_id
      JOIN transit_lines AS tl ON tl.line_id = ts.line_id
     WHERE tl.line_name = line
     GROUP BY ts.segment_name
     ORDER BY peak_ppm DESC;

    SELECT ts.segment_name, ef.fan_model, sm.mechanic_name, fm.marshal_name, tst.test_result
      FROM emergency_tests AS tst
      JOIN maintenance_routines AS mr ON mr.routine_id = tst.routine_id
      JOIN fire_marshals AS fm ON fm.marshal_id = tst.marshal_id
      JOIN subway_mechanics AS sm ON sm.mechanic_id = mr.mechanic_id
      JOIN extraction_fans AS ef ON ef.fan_id = mr.fan_id
      JOIN ventilation_shafts AS vs ON vs.shaft_id = ef.shaft_id
      JOIN tunnel_segments AS ts ON ts.segment_id = vs.segment_id
      JOIN transit_lines AS tl ON tl.line_id = ts.line_id
     WHERE tl.line_name = line
     ORDER BY tst.test_result, ef.fan_model;
END$$
DELIMITER ;

CALL ventilate('blue line south');

