     ORDER BY ts.segment_name, vs.depth_m DESC;

    SELECT ts.segment_name, vs.depth_m, ef.fan_model, ms.supplier_name
      FROM extraction_fans AS ef, ventilation_shafts AS vs, tunnel_segments AS ts, transit_lines AS tl, motor_suppliers AS ms
     WHERE vs.shaft_id = ef.shaft_id AND ts.segment_id = vs.segment_id AND tl.line_id = ts.line_id AND ms.supplier_id = ef.supplier_id AND tl.line_name = line
     ORDER BY ts.segment_name, ef.fan_model;

