     WHERE ef.fan_id = aqs.fan_id AND vs.shaft_id = ef.shaft_id AND ts.segment_id = vs.segment_id AND tl.line_id = ts.line_id AND et.technician_id = aqs.technician_id AND tl.line_name = line
