CREATE TABLE radar_networks (network_id INT PRIMARY KEY, region VARCHAR(60));
CREATE TABLE radars (radar_id INT PRIMARY KEY, network_id INT, location VARCHAR(60));
CREATE TABLE tracking_sessions (session_id INT PRIMARY KEY, radar_id INT, operator_name VARCHAR(60), session_ts DATETIME);
CREATE TABLE object_classifications (class_id INT PRIMARY KEY, class_name VARCHAR(60), is_debris TINYINT);
CREATE TABLE detected_objects (object_id INT PRIMARY KEY, session_id INT, class_id INT, mass_kg DECIMAL(10,2), telemetry VARCHAR(200));
CREATE TABLE constellations (constellation_id INT PRIMARY KEY, owner VARCHAR(60), operator VARCHAR(60));
CREATE TABLE satellites (satellite_id INT PRIMARY KEY, constellation_id INT, designation VARCHAR(60));
CREATE TABLE collision_warnings (warning_id INT PRIMARY KEY, object_id INT, satellite_id INT, status VARCHAR(20), evasion_escalated TINYINT);

DELIMITER //

CREATE FUNCTION session_count(p_date DATE) RETURNS INT READS SQL DATA
BEGIN
    DECLARE v_count INT;
    SELECT COUNT(*) INTO v_count
    FROM tracking_sessions AS ts
    JOIN radars AS r ON r.radar_id = ts.radar_id
    WHERE DATE(ts.session_ts) = p_date;
    RETURN v_count;
END //

CREATE FUNCTION escalated_mass(p_date DATE) RETURNS DECIMAL(12,2) READS SQL DATA
BEGIN
    DECLARE v_mass DECIMAL(12,2);
    SELECT COALESCE(SUM(d.mass_kg), 0) INTO v_mass
    FROM collision_warnings AS cw
    JOIN detected_objects AS d ON d.object_id = cw.object_id
    JOIN tracking_sessions AS ts ON ts.session_id = d.session_id
    WHERE cw.evasion_escalated = 1 AND DATE(ts.session_ts) = p_date;
    RETURN v_mass;
END //

CREATE PROCEDURE report_active_warnings(IN p_date DATE)
BEGIN
    SELECT r.location AS radar_location, DATE(ts.session_ts) AS session_date, oc.class_name AS classification, c.owner AS satellite_owner
    FROM detected_objects AS d
    JOIN tracking_sessions AS ts ON ts.session_id = d.session_id
    JOIN radars AS r ON r.radar_id = ts.radar_id
    JOIN object_classifications AS oc ON oc.class_id = d.class_id
    JOIN collision_warnings AS cw ON cw.object_id = d.object_id
    JOIN satellites AS s ON s.satellite_id = cw.satellite_id
    JOIN constellations AS c ON c.constellation_id = s.constellation_id
    WHERE cw.status = 'ACTIVE' AND DATE(ts.session_ts) = p_date
    ORDER BY r.location, oc.class_name;
END //

CREATE PROCEDURE report_debris_mass(IN p_date DATE)
BEGIN
    SELECT r.location AS radar_location, SUM(d.mass_kg) AS total_debris_mass_kg
    FROM radars AS r
    JOIN tracking_sessions AS ts ON ts.radar_id = r.radar_id
    JOIN detected_objects AS d ON d.session_id = ts.session_id
    JOIN object_classifications AS oc ON oc.class_id = d.class_id
    WHERE oc.is_debris = 1 AND DATE(ts.session_ts) = p_date
    GROUP BY r.location
    ORDER BY total_debris_mass_kg DESC;
END //

CREATE PROCEDURE report_evasion_orders(IN p_date DATE)
BEGIN
    SELECT rn.region AS network_region, ts.operator_name AS tracking_operator, d.telemetry AS object_telemetry,
           s.designation AS satellite_designation, c.operator AS constellation_operator
    FROM collision_warnings AS cw
    JOIN detected_objects AS d ON d.object_id = cw.object_id
    JOIN tracking_sessions AS ts ON ts.session_id = d.session_id
    JOIN radars AS r ON r.radar_id = ts.radar_id
    JOIN radar_networks AS rn ON rn.network_id = r.network_id
    JOIN satellites AS s ON s.satellite_id = cw.satellite_id
    JOIN constellations AS c ON c.constellation_id = s.constellation_id
    WHERE cw.evasion_escalated = 1 AND DATE(ts.session_ts) = p_date
    ORDER BY rn.region, s.designation;
END //

CREATE PROCEDURE analyze(IN p_date DATE)
BEGIN
    IF session_count(p_date) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'no tracking sessions recorded for the requested date';
    END IF;
    CALL report_active_warnings(p_date);
    CALL report_debris_mass(p_date);
    CALL report_evasion_orders(p_date);
    SELECT p_date AS run_date, escalated_mass(p_date) AS escalated_mass_kg;
END //

DELIMITER ;

CALL analyze('2023-10-12');

