JOIN sectors AS s ON s.reserve_id = r.reserve_id;

CREATE VIEW hole_sightings AS
SELECT w.hole_id, w.capacity, si.sighting_id, si.sector_id, si.guide_id,
       si.booking_id, si.species, si.endangered, si.seen_on
FROM watering_holes AS w
JOIN sightings AS si ON si.hole_id = w.hole_id;

CREATE VIEW booking_crew AS
SELECT b.booking_id, b.guest_name, b.season, v.vehicle_id, v.vehicle_type,
       v.last_service, g.guide_id, g.guide_name, g.employed
FROM bookings AS b
JOIN vehicles AS v ON v.vehicle_id = b.vehicle_id
JOIN guides AS g ON g.guide_id = b.guide_id;

DELIMITER //

CREATE PROCEDURE guide(IN season VARCHAR(20))
BEGIN
    DECLARE sel_season VARCHAR(20) DEFAULT season;

    SELECT rs.sector_name, hs.capacity, hs.species, g.guide_name
    FROM reserve_sectors AS rs
    JOIN hole_sightings AS hs ON hs.sector_id = rs.sector_id
    JOIN guides AS g ON g.guide_id = hs.guide_id
    WHERE rs.season = sel_season
      AND hs.endangered = 1
      AND g.employed = 1
      AND hs.seen_on >= CURRENT_DATE - INTERVAL 7 DAY
    ORDER BY rs.sector_name, hs.species;

    SELECT bc.guest_name, bc.vehicle_type, bc.guide_name,
           GROUP_CONCAT(DISTINCT hs.species ORDER BY hs.species) AS animals_seen
    FROM booking_crew AS bc
    JOIN hole_sightings AS hs ON hs.booking_id = bc.booking_id
    JOIN reserve_sectors AS rs ON rs.sector_id = hs.sector_id
    WHERE bc.season = sel_season
    GROUP BY bc.booking_id, bc.guest_name, bc.vehicle_type, bc.guide_name
    ORDER BY bc.guest_name;

    SELECT DISTINCT bc.vehicle_id, bc.vehicle_type, bc.last_service,
           rs.reserve_name, rs.sector_name, w.capacity
    FROM booking_crew AS bc
    JOIN hole_sightings AS hs ON hs.booking_id = bc.booking_id
    JOIN reserve_sectors AS rs ON rs.sector_id = hs.sector_id
    JOIN watering_holes AS w ON w.sector_id = rs.sector_id
    WHERE bc.season = sel_season
      AND rs.off_road = 1
      AND rs.terrain = 'muddy'
      AND bc.employed = 1
    ORDER BY bc.last_service;
END //

DELIMITER ;

CALL guide('wet');
CALL guide('dry');

