WHERE v.vehicle_id = b.vehicle_id
  AND g.guide_id = b.guide_id;

DELIMITER //

CREATE PROCEDURE guide(IN season VARCHAR(20))
BEGIN
    DECLARE sel_season VARCHAR(20) DEFAULT season;

    SELECT rs.sector_name, hs.capacity, hs.species, g.guide_name
    FROM reserve_sectors AS rs, hole_sightings AS hs, guides AS g
    WHERE hs.sector_id = rs.sector_id
      AND g.guide_id = hs.guide_id
      AND rs.season = sel_season
      AND hs.endangered = 1
      AND g.employed = 1
      AND hs.seen_on >= CURRENT_DATE - INTERVAL 7 DAY
    ORDER BY rs.sector_name, hs.species;

    SELECT bc.guest_name, bc.vehicle_type, bc.guide_name,
           GROUP_CONCAT(DISTINCT hs.species ORDER BY hs.species) AS animals_seen
    FROM booking_crew AS bc, hole_sightings AS hs, reserve_sectors AS rs
    WHERE hs.booking_id = bc.booking_id
      AND rs.sector_id = hs.sector_id
      AND bc.season = sel_season
    GROUP BY bc.booking_id, bc.guest_name, bc.vehicle_type, bc.guide_name
    ORDER BY bc.guest_name;

    SELECT DISTINCT bc.vehicle_id, bc.vehicle_type, bc.last_service,
           rs.reserve_name, rs.sector_name, w.capacity
    FROM booking_crew AS bc, hole_sightings AS hs, reserve_sectors AS rs, watering_holes AS w
    WHERE hs.booking_id = bc.booking_id
      AND rs.sector_id = hs.sector_id
      AND w.sector_id = rs.sector_id
      AND bc.season = sel_season
      AND rs.off_road = 1
      AND rs.terrain = 'muddy'
      AND bc.employed = 1
