CREATE TABLE Expeditions (
    expedition_id INTEGER PRIMARY KEY,
    expedition_name TEXT NOT NULL
);
CREATE TABLE ResearchVessels (
    vessel_id INTEGER PRIMARY KEY, vessel_name TEXT NOT NULL,
    expedition_id INTEGER NOT NULL REFERENCES Expeditions (expedition_id)
);
CREATE TABLE Submersibles (
    sub_id INTEGER PRIMARY KEY, sub_name TEXT NOT NULL, max_pressure_bar INTEGER NOT NULL,
    vessel_id INTEGER NOT NULL REFERENCES ResearchVessels (vessel_id)
);
CREATE TABLE SonarArrays (
    array_id INTEGER PRIMARY KEY, frequency_khz REAL NOT NULL,
    sub_id INTEGER NOT NULL REFERENCES Submersibles (sub_id)
);
CREATE TABLE DiveTracks (
    track_id INTEGER PRIMARY KEY, dive_date DATE NOT NULL, max_pressure_bar INTEGER NOT NULL,
    sub_id INTEGER NOT NULL REFERENCES Submersibles (sub_id)
);
CREATE TABLE GridCells (
    cell_id INTEGER PRIMARY KEY, latitude REAL NOT NULL, longitude REAL NOT NULL, area_km2 INTEGER NOT NULL,
    track_id INTEGER NOT NULL REFERENCES DiveTracks (track_id)
);
CREATE TABLE ThermalVents (
    vent_id INTEGER PRIMARY KEY, temperature_c INTEGER NOT NULL, status TEXT NOT NULL,
    cell_id INTEGER NOT NULL REFERENCES GridCells (cell_id)
);
CREATE TABLE MarineBiologists (
    biologist_id INTEGER PRIMARY KEY, biologist_name TEXT NOT NULL
);
CREATE TABLE GeologicalSamples (
    sample_id INTEGER PRIMARY KEY, sample_type TEXT NOT NULL, mineral_composition TEXT NOT NULL,
    cell_id INTEGER NOT NULL REFERENCES GridCells (cell_id),
    biologist_id INTEGER NOT NULL REFERENCES MarineBiologists (biologist_id)
);

CREATE VIEW expedition_fleet AS
SELECT e.expedition_name, v.vessel_name, s.sub_id, s.sub_name, s.max_pressure_bar AS rated_pressure_bar
FROM Expeditions AS e
JOIN ResearchVessels AS v ON v.expedition_id = e.expedition_id
JOIN Submersibles AS s ON s.vessel_id = v.vessel_id;

CREATE VIEW dive_coverage AS
SELECT t.track_id, t.sub_id, t.dive_date, t.max_pressure_bar, g.cell_id, g.latitude, g.longitude, g.area_km2
FROM DiveTracks AS t
JOIN GridCells AS g ON g.track_id = t.track_id;

CREATE VIEW vent_sample_cells AS
SELECT DISTINCT f.expedition_name, f.vessel_name, d.cell_id, d.area_km2
FROM expedition_fleet AS f
JOIN dive_coverage AS d ON d.sub_id = f.sub_id
JOIN ThermalVents AS tv ON tv.cell_id = d.cell_id
JOIN GeologicalSamples AS gs ON gs.cell_id = d.cell_id;

SELECT f.vessel_name, f.sub_name, sa.frequency_khz, d.latitude, d.longitude
FROM expedition_fleet AS f
JOIN SonarArrays AS sa ON sa.sub_id = f.sub_id
JOIN dive_coverage AS d ON d.sub_id = f.sub_id
WHERE f.expedition_name = :expedition
  AND d.max_pressure_bar >= f.rated_pressure_bar
ORDER BY f.sub_name, d.track_id, d.cell_id;

SELECT tv.temperature_c, gs.mineral_composition, mb.biologist_name
FROM expedition_fleet AS f
JOIN dive_coverage AS d ON d.sub_id = f.sub_id
JOIN ThermalVents AS tv ON tv.cell_id = d.cell_id
JOIN GeologicalSamples AS gs ON gs.cell_id = d.cell_id
JOIN MarineBiologists AS mb ON mb.biologist_id = gs.biologist_id
WHERE f.expedition_name = :expedition
  AND tv.status = 'active' AND gs.sample_type = 'rock'
ORDER BY tv.temperature_c DESC, mb.biologist_name;

SELECT vessel_name, SUM(area_km2) AS total_area_km2
FROM vent_sample_cells
WHERE expedition_name = :expedition
GROUP BY vessel_name
ORDER BY total_area_km2 DESC;

