CREATE TABLE cooperatives (coop_id INT PRIMARY KEY, coop_name VARCHAR(60), region VARCHAR(60), certification VARCHAR(40));
CREATE TABLE fermentation_crates (crate_id INT PRIMARY KEY, coop_id INT, fermentation_days INT);
CREATE TABLE shipping_containers (container_id INT PRIMARY KEY, crate_id INT, port VARCHAR(60));
CREATE TABLE roasting_ovens (oven_id INT PRIMARY KEY, container_id INT, roast_temp_c INT, operator VARCHAR(60));
CREATE TABLE melangeurs (melangeur_id INT PRIMARY KEY, oven_id INT, grinding_hours DECIMAL(5,2));
CREATE TABLE batches (batch_id INT PRIMARY KEY, oven_id INT, melangeur_id INT, product_name VARCHAR(80), flavor_test_result VARCHAR(10));
CREATE TABLE wrappers (wrapper_id INT PRIMARY KEY, batch_id INT, design VARCHAR(60), bars_count INT);
CREATE TABLE tasters (taster_id INT PRIMARY KEY, batch_id INT, taster_name VARCHAR(60), notes VARCHAR(200));
