DELIMITER $$
CREATE PROCEDURE trace_origin(IN batch INT)
BEGIN
    SELECT c.region, fc.fermentation_days, sc.port, ro.roast_temp_c
    FROM batches AS b
    JOIN roasting_ovens AS ro ON ro.oven_id = b.oven_id
    JOIN shipping_containers AS sc ON sc.container_id = ro.container_id
    JOIN fermentation_crates AS fc ON fc.crate_id = sc.crate_id
    JOIN cooperatives AS c ON c.coop_id = fc.coop_id
    WHERE b.batch_id = batch AND b.product_name LIKE 'Dark Chocolate%';
END$$
CREATE PROCEDURE batch_label(IN batch INT)
BEGIN
    SELECT b.product_name, w.design, w.bars_count, m.grinding_hours, ro.operator
    FROM batches AS b
    JOIN wrappers AS w ON w.batch_id = b.batch_id
    JOIN melangeurs AS m ON m.melangeur_id = b.melangeur_id
    JOIN roasting_ovens AS ro ON ro.oven_id = b.oven_id
    WHERE b.batch_id = batch;
END$$
CREATE PROCEDURE failed_flavor_profiles()
BEGIN
    SELECT b.batch_id, m.grinding_hours, w.design, t.notes, ro.operator
    FROM batches AS b
    JOIN melangeurs AS m ON m.melangeur_id = b.melangeur_id
    JOIN roasting_ovens AS ro ON ro.oven_id = m.oven_id
    JOIN wrappers AS w ON w.batch_id = b.batch_id
    JOIN tasters AS t ON t.batch_id = b.batch_id
    WHERE b.flavor_test_result = 'FAIL'
    ORDER BY b.batch_id;
END$$
CREATE PROCEDURE incoming_lots()
BEGIN
    SELECT c.coop_name, c.certification, fc.fermentation_days, sc.port
    FROM cooperatives AS c
    JOIN fermentation_crates AS fc ON fc.coop_id = c.coop_id
    JOIN shipping_containers AS sc ON sc.crate_id = fc.crate_id
    ORDER BY c.coop_name, sc.port;
END$$
CREATE PROCEDURE single_origin_totals()
BEGIN
    SELECT c.coop_name, SUM(w.bars_count) AS total_bars
    FROM cooperatives AS c
    JOIN fermentation_crates AS fc ON fc.coop_id = c.coop_id
    JOIN shipping_containers AS sc ON sc.crate_id = fc.crate_id
    JOIN roasting_ovens AS ro ON ro.container_id = sc.container_id
    JOIN batches AS b ON b.oven_id = ro.oven_id
    JOIN melangeurs AS m ON m.melangeur_id = b.melangeur_id
    JOIN wrappers AS w ON w.batch_id = b.batch_id
    WHERE c.certification = 'Single Origin Organic'
    GROUP BY c.coop_name
    ORDER BY total_bars DESC;
END$$
CREATE PROCEDURE process(IN batch INT)
BEGIN
    CALL trace_origin(batch);
    CALL batch_label(batch);
    CALL incoming_lots();
    CALL failed_flavor_profiles();
    CALL single_origin_totals();
END$$
DELIMITER ;
CALL process(1001);
CALL process(1002);

