CREATE TABLE cgm_readings (reading_id INT PRIMARY KEY, patient_id INT, taken_at DATETIME, glucose DECIMAL(6,2));
CREATE TABLE boluses (bolus_id INT PRIMARY KEY, pump_id INT, injected_at DATETIME, units DECIMAL(5,2));
