DELIMITER $$

CREATE PROCEDURE evaluate(IN patient INT)
BEGIN
    DECLARE alert_count INT;
    DECLARE avg_minutes DECIMAL(6,2);
    DROP TEMPORARY TABLE IF EXISTS safety_alerts;
    CREATE TEMPORARY TABLE safety_alerts (alert_kind VARCHAR(30), detail VARCHAR(160), response_minutes DECIMAL(6,2));
    INSERT INTO safety_alerts (alert_kind, detail, response_minutes)
    SELECT 'unprofiled_patient', CONCAT('incomplete care links for patient ', pt.patient_id), NULL
    FROM patients AS pt
    WHERE pt.patient_id = patient
      AND NOT EXISTS (SELECT 1
                      FROM physicians AS ph, clinics AS cl, insurers AS ins
                      WHERE cl.clinic_id = pt.clinic_id
                        AND ins.insurer_id = pt.insurer_id
                        AND ph.physician_id = pt.physician_id);
    INSERT INTO safety_alerts (alert_kind, detail, response_minutes)
    SELECT 'high_glucose_bolus',
           CONCAT('reading ', r.reading_id, ' answered by bolus ', b.bolus_id),
           TIMESTAMPDIFF(SECOND, r.taken_at, b.injected_at) / 60.0
    FROM cgm_readings AS r, pumps AS p, boluses AS b
    WHERE p.patient_id = r.patient_id
      AND b.pump_id = p.pump_id
      AND r.patient_id = patient
      AND b.injected_at BETWEEN r.taken_at AND r.taken_at + INTERVAL 5 MINUTE
      AND r.glucose >= 180;
    INSERT INTO safety_alerts (alert_kind, detail, response_minutes)
    SELECT 'meal_spike',
           CONCAT('meal ', m.meal_id, ' followed by glucose ', r.glucose),
           TIMESTAMPDIFF(SECOND, m.eaten_at, r.taken_at) / 60.0
    FROM meals AS m, cgm_readings AS r
    WHERE r.patient_id = m.patient_id
      AND m.patient_id = patient
      AND r.taken_at > m.eaten_at
      AND r.taken_at <= m.eaten_at + INTERVAL 2 HOUR
      AND r.glucose >= 250;
    INSERT INTO safety_alerts (alert_kind, detail, response_minutes)
    SELECT 'firmware_error',
           CONCAT('version ', f.version, ' produced error ', e.code),
           TIMESTAMPDIFF(SECOND, f.applied_at, e.logged_at) / 60.0
    FROM pumps AS p, firmware_updates AS f, pump_errors AS e
    WHERE f.pump_id = p.pump_id
      AND e.pump_id = f.pump_id
      AND p.patient_id = patient
      AND e.logged_at >= f.applied_at
      AND e.logged_at < f.applied_at + INTERVAL 24 HOUR;
    INSERT INTO safety_alerts (alert_kind, detail, response_minutes)
    SELECT 'battery_service',
           CONCAT('pump ', p.serial_no, ' serviced by ', t.full_name),
           TIMESTAMPDIFF(SECOND, c.logged_at, br.replaced_at) / 60.0
    FROM pumps AS p, battery_replacements AS br, technicians AS t, calibration_logs AS c
    WHERE br.pump_id = p.pump_id
      AND t.technician_id = br.technician_id
      AND c.pump_id = p.pump_id
      AND p.patient_id = patient
      AND c.logged_at <= br.replaced_at
      AND ABS(c.deviation) >= 15;
    INSERT INTO safety_alerts (alert_kind, detail, response_minutes)
    SELECT 'physician_adjustment',
           CONCAT('adjustment ', a.adjustment_id, ' entered by ', ph.full_name),
           TIMESTAMPDIFF(SECOND, r.taken_at, a.made_at) / 60.0
    FROM adjustments AS a, physicians AS ph, cgm_readings AS r
    WHERE ph.physician_id = a.physician_id
      AND r.patient_id = a.patient_id
      AND a.patient_id = patient
      AND a.made_at BETWEEN r.taken_at AND r.taken_at + INTERVAL 30 MINUTE
      AND r.glucose >= 300;
    SELECT COUNT(*), ROUND(AVG(response_minutes), 1) INTO alert_count, avg_minutes FROM safety_alerts;
    SELECT ph.full_name AS primary_physician, cl.city AS clinic_city, ins.plan_name AS insurance_plan,
           alert_count AS alerts, avg_minutes AS avg_response_minutes
    FROM patients AS pt, physicians AS ph, clinics AS cl, insurers AS ins
    WHERE ph.physician_id = pt.physician_id
      AND cl.clinic_id = pt.clinic_id
      AND ins.insurer_id = pt.insurer_id
      AND pt.patient_id = patient;
END$$

