CREATE TABLE growth_chambers (chamber_id INT PRIMARY KEY, label TEXT, floor_area_m2 NUMERIC);
CREATE TABLE led_arrays (array_id INT PRIMARY KEY, chamber_id INT, spectrum TEXT, watts INT);
CREATE TABLE nutrient_reservoirs (reservoir_id INT PRIMARY KEY, chamber_id INT, formula TEXT);
CREATE TABLE nutrient_draws (draw_id INT PRIMARY KEY, reservoir_id INT, draw_date DATE, liters NUMERIC);
CREATE TABLE crop_varieties (crop_id INT PRIMARY KEY, crop_name TEXT, cycle_days INT);
CREATE TABLE chamber_plantings (planting_id INT PRIMARY KEY, chamber_id INT, crop_id INT, sown_on DATE, closed_on DATE);
CREATE TABLE harvest_yields (harvest_id INT PRIMARY KEY, planting_id INT, harvest_date DATE, mass_kg NUMERIC);
CREATE TABLE climate_sensors (sensor_id INT PRIMARY KEY, chamber_id INT, installed_on DATE, retired_on DATE, metric TEXT);
CREATE TABLE filtration_units (unit_id INT PRIMARY KEY, chamber_id INT, commissioned_on DATE, decommissioned_on DATE, throughput_lph NUMERIC);
CREATE TABLE chemical_suppliers (supplier_id INT PRIMARY KEY, supplier_name TEXT);
CREATE TABLE pest_interventions (intervention_id INT PRIMARY KEY, chamber_id INT, supplier_id INT, applied_on DATE, agent TEXT);
CREATE TABLE distribution_trucks (truck_id INT PRIMARY KEY, plate TEXT, capacity_kg NUMERIC);
CREATE TABLE retail_destinations (destination_id INT PRIMARY KEY, store_name TEXT, city TEXT);
CREATE TABLE truck_loads (load_id INT PRIMARY KEY, truck_id INT, harvest_id INT, destination_id INT, loaded_on DATE);

CREATE VIEW chamber_setup AS
SELECT gc.chamber_id, gc.label, la.spectrum, la.watts, nr.reservoir_id, nr.formula,
       cp.planting_id, cv.crop_name, cp.sown_on, cp.closed_on
FROM growth_chambers AS gc
JOIN led_arrays AS la ON la.chamber_id = gc.chamber_id
JOIN nutrient_reservoirs AS nr ON nr.chamber_id = gc.chamber_id
JOIN chamber_plantings AS cp ON cp.chamber_id = gc.chamber_id
JOIN crop_varieties AS cv ON cv.crop_id = cp.crop_id;

CREATE VIEW harvest_conditions AS
SELECT hy.harvest_id, hy.harvest_date, hy.mass_kg, cs.chamber_id, cs.crop_name,
       sen.sensor_id, sen.metric, fu.unit_id, fu.throughput_lph
FROM harvest_yields AS hy
JOIN chamber_setup AS cs ON cs.planting_id = hy.planting_id
JOIN climate_sensors AS sen ON sen.chamber_id = cs.chamber_id
   AND sen.installed_on <= hy.harvest_date
   AND COALESCE(sen.retired_on, DATE '9999-12-31') >= cs.sown_on
JOIN filtration_units AS fu ON fu.chamber_id = cs.chamber_id
   AND fu.commissioned_on <= hy.harvest_date
   AND COALESCE(fu.decommissioned_on, DATE '9999-12-31') >= cs.sown_on;

CREATE VIEW pest_actions AS
SELECT pi.intervention_id, pi.applied_on, pi.agent, gc.chamber_id, gc.label, sup.supplier_name
FROM pest_interventions AS pi
JOIN growth_chambers AS gc ON gc.chamber_id = pi.chamber_id
JOIN chemical_suppliers AS sup ON sup.supplier_id = pi.supplier_id;

CREATE VIEW distribution_plan AS
SELECT tl.load_id, tl.loaded_on, dt.plate, dt.capacity_kg, hy.harvest_id, hy.mass_kg,
       rd.store_name, rd.city
FROM truck_loads AS tl
JOIN distribution_trucks AS dt ON dt.truck_id = tl.truck_id
JOIN harvest_yields AS hy ON hy.harvest_id = tl.harvest_id
JOIN retail_destinations AS rd ON rd.destination_id = tl.destination_id;

CREATE VIEW chamber_harvest_mass AS
SELECT chamber_id, crop_name, SUM(mass_kg) AS total_mass_kg
FROM (SELECT DISTINCT harvest_id, chamber_id, crop_name, mass_kg FROM harvest_conditions) AS monitored
GROUP BY chamber_id, crop_name;

CREATE VIEW chamber_nutrient_use AS
SELECT cs.chamber_id, cs.crop_name, AVG(nd.liters) AS avg_nutrient_liters
FROM chamber_setup AS cs
JOIN nutrient_draws AS nd ON nd.reservoir_id = cs.reservoir_id
   AND nd.draw_date BETWEEN cs.sown_on AND COALESCE(cs.closed_on, CURRENT_DATE)
GROUP BY cs.chamber_id, cs.crop_name;

CREATE FUNCTION "yield"(crop TEXT)
RETURNS TABLE (chamber_id INT, total_mass_kg NUMERIC, avg_nutrient_liters NUMERIC) AS $$
  SELECT chm.chamber_id, chm.total_mass_kg, ROUND(nut.avg_nutrient_liters, 2)
  FROM chamber_harvest_mass AS chm
  JOIN chamber_nutrient_use AS nut ON nut.chamber_id = chm.chamber_id
     AND nut.crop_name = chm.crop_name
  WHERE chm.crop_name = crop
  ORDER BY chm.chamber_id;
$$ LANGUAGE SQL;

CREATE FUNCTION pipeline_trace(crop TEXT)
RETURNS TABLE (label TEXT, agent TEXT, supplier_name TEXT, store_name TEXT, mass_kg NUMERIC) AS $$
  SELECT cs.label, pa.agent, pa.supplier_name, dp.store_name, dp.mass_kg
  FROM chamber_setup AS cs
  JOIN harvest_yields AS hy ON hy.planting_id = cs.planting_id
  JOIN distribution_plan AS dp ON dp.harvest_id = hy.harvest_id
  JOIN pest_actions AS pa ON pa.chamber_id = cs.chamber_id
     AND pa.applied_on BETWEEN cs.sown_on AND hy.harvest_date
  WHERE cs.crop_name = crop
  ORDER BY dp.loaded_on;
$$ LANGUAGE SQL;

SELECT chamber_id, total_mass_kg, avg_nutrient_liters FROM "yield"('lettuce');
SELECT label, agent, supplier_name, store_name, mass_kg FROM pipeline_trace('lettuce');

