CREATE TABLE Supervisors (supervisor_id INT PRIMARY KEY, supervisor_name VARCHAR(60), shift VARCHAR(12));
CREATE TABLE PackagingLines (line_id INT PRIMARY KEY, line_code VARCHAR(20), scanner_id INT, supervisor_id INT);
CREATE TABLE Carriers (carrier_id INT PRIMARY KEY, carrier_name VARCHAR(60));
CREATE TABLE Regions (region_id INT PRIMARY KEY, region_name VARCHAR(60));
CREATE TABLE Orders (order_id INT PRIMARY KEY, category_id INT, rack_id INT, line_id INT, region_id INT);
CREATE TABLE Retrievals (order_id INT PRIMARY KEY, robot_id INT, retrieved_at DATETIME, battery_level TINYINT);
CREATE TABLE Handoffs (order_id INT PRIMARY KEY, carrier_id INT, handed_off_at DATETIME);

DELIMITER $$

CREATE FUNCTION fulfillment_minutes(p_order INT) RETURNS INT DETERMINISTIC READS SQL DATA
BEGIN
    DECLARE v_minutes INT;
    SELECT TIMESTAMPDIFF(MINUTE, r.retrieved_at, h.handed_off_at) INTO v_minutes
    FROM Retrievals AS r
    JOIN Handoffs AS h ON h.order_id = r.order_id
    WHERE r.order_id = p_order;
    RETURN v_minutes;
END$$

CREATE PROCEDURE trace(IN p_order INT)
BEGIN
    SELECT o.order_id, c.category_name, rk.rack_code, z.zone_name AS storage_zone
    FROM Orders AS o
    JOIN Categories AS c ON c.category_id = o.category_id
    JOIN Racks AS rk ON rk.rack_id = o.rack_id
    JOIN Zones AS z ON z.zone_id = rk.zone_id
    WHERE o.order_id = p_order;

    SELECT rb.robot_name, cs.station_code, z.zone_name AS patrolled_zone, rt.retrieved_at
    FROM Retrievals AS rt
    JOIN Robots AS rb ON rb.robot_id = rt.robot_id
    JOIN ChargingStations AS cs ON cs.station_id = rb.station_id
    JOIN Zones AS z ON z.zone_id = rb.patrol_zone_id
    WHERE rt.order_id = p_order;

    SELECT pl.line_code, sc.scanner_serial, sv.supervisor_name, sv.shift
    FROM Orders AS o
    JOIN PackagingLines AS pl ON pl.line_id = o.line_id
    JOIN Scanners AS sc ON sc.scanner_id = pl.scanner_id
    JOIN Supervisors AS sv ON sv.supervisor_id = pl.supervisor_id
    WHERE o.order_id = p_order;

    SELECT ca.carrier_name, rg.region_name AS destination_region, h.handed_off_at
    FROM Handoffs AS h
    JOIN Carriers AS ca ON ca.carrier_id = h.carrier_id
    JOIN Orders AS o ON o.order_id = h.order_id
    JOIN Regions AS rg ON rg.region_id = o.region_id
    WHERE h.order_id = p_order;

    SELECT fulfillment_minutes(p_order) AS fulfillment_minutes,
           rt.battery_level AS battery_percent_at_retrieval,
           rb.robot_name
    FROM Retrievals AS rt
    JOIN Robots AS rb ON rb.robot_id = rt.robot_id
    WHERE rt.order_id = p_order;
END$$

