CREATE PROCEDURE trace(IN p_order INT)
BEGIN
    SELECT o.order_id, c.category_name, rk.rack_code, z.zone_name AS storage_zone
    FROM Orders AS o, Categories AS c, Racks AS rk, Zones AS z
    WHERE c.category_id = o.category_id
    AND rk.rack_id = o.rack_id
    AND z.zone_id = rk.zone_id
    AND o.order_id = p_order;

    SELECT rb.robot_name, cs.station_code, z.zone_name AS patrolled_zone, rt.retrieved_at
    FROM Retrievals AS rt, Robots AS rb, ChargingStations AS cs, Zones AS z
    WHERE rb.robot_id = rt.robot_id
    AND cs.station_id = rb.station_id
    AND z.zone_id = rb.patrol_zone_id
    AND rt.order_id = p_order;

    SELECT pl.line_code, sc.scanner_serial, sv.supervisor_name, sv.shift
    FROM Orders AS o, PackagingLines AS pl, Scanners AS sc, Supervisors AS sv
    WHERE pl.line_id = o.line_id
    AND sc.scanner_id = pl.scanner_id
    AND sv.supervisor_id = pl.supervisor_id
    AND o.order_id = p_order;

    SELECT ca.carrier_name, rg.region_name AS destination_region, h.handed_off_at
    FROM Handoffs AS h, Carriers AS ca, Orders AS o, Regions AS rg
    WHERE ca.carrier_id = h.carrier_id
    AND o.order_id = h.order_id
    AND rg.region_id = o.region_id
    AND h.order_id = p_order;

    SELECT fulfillment_minutes(p_order) AS fulfillment_minutes,
           rt.battery_level AS battery_percent_at_retrieval,
           rb.robot_name
    FROM Retrievals AS rt, Robots AS rb
    WHERE rb.robot_id = rt.robot_id
    AND rt.order_id = p_order;
END$$

