CREATE TABLE contractors (id INT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE launch_vehicles (id INT PRIMARY KEY, name TEXT NOT NULL, contractor_id INT REFERENCES contractors(id));
CREATE TABLE orbits (id INT PRIMARY KEY, satellite INT NOT NULL, vehicle_id INT REFERENCES launch_vehicles(id), altitude_km NUMERIC);
CREATE TABLE orbital_lasers (id INT PRIMARY KEY, satellite INT NOT NULL, wavelength_nm NUMERIC);
CREATE TABLE control_stations (id INT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE receivers (id INT PRIMARY KEY, site TEXT NOT NULL, station_id INT REFERENCES control_stations(id));
CREATE TABLE commanders (id INT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE shifts (id INT PRIMARY KEY, station_id INT REFERENCES control_stations(id), commander_id INT REFERENCES commanders(id), started_at TIMESTAMP, ended_at TIMESTAMP);
CREATE TABLE distortion_models (id INT PRIMARY KEY, receiver_id INT REFERENCES receivers(id), level NUMERIC, valid_from TIMESTAMP, valid_to TIMESTAMP);
CREATE TABLE packets (id INT PRIMARY KEY, laser_id INT REFERENCES orbital_lasers(id), receiver_id INT REFERENCES receivers(id), sent_at TIMESTAMP, sent_count INT, dropped_count INT);
CREATE TABLE error_algorithms (id INT PRIMARY KEY, name TEXT NOT NULL, station_id INT REFERENCES control_stations(id));
CREATE TABLE packet_corrections (packet_id INT REFERENCES packets(id), algorithm_id INT REFERENCES error_algorithms(id), recovered_count INT, PRIMARY KEY (packet_id, algorithm_id));

CREATE FUNCTION recovered_packets(satellite INT) RETURNS INT AS $$
    SELECT COALESCE(SUM(c.recovered_count), 0)
    FROM packet_corrections AS c
    JOIN packets AS p ON c.packet_id = p.id
    JOIN orbital_lasers AS l ON p.laser_id = l.id
    WHERE l.satellite = satellite;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION packet_loss_pct(satellite INT) RETURNS NUMERIC AS $$
    SELECT ROUND(100.0 * (SUM(p.dropped_count) - recovered_packets(satellite)) / NULLIF(SUM(p.sent_count), 0))
    FROM packets AS p
    JOIN orbital_lasers AS l ON p.laser_id = l.id
    WHERE l.satellite = satellite;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION avg_distortion(satellite INT) RETURNS NUMERIC AS $$
    SELECT AVG(d.level)
    FROM packets AS p
    JOIN orbital_lasers AS l ON p.laser_id = l.id
    JOIN receivers AS r ON p.receiver_id = r.id
    JOIN distortion_models AS d ON d.receiver_id = r.id
        AND p.sent_at >= d.valid_from AND p.sent_at < d.valid_to
    WHERE l.satellite = satellite;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION distortion_label(level NUMERIC) RETURNS TEXT AS $$
    SELECT CASE WHEN level IS NULL THEN 'unknown' WHEN level < 0.3 THEN 'low'
        WHEN level < 0.7 THEN 'moderate' ELSE 'severe' END;
$$ LANGUAGE sql IMMUTABLE;

CREATE FUNCTION peak_loss_commander(satellite INT) RETURNS TEXT AS $$
    SELECT cm.name
    FROM packets AS p
    JOIN orbital_lasers AS l ON p.laser_id = l.id
    JOIN receivers AS r ON p.receiver_id = r.id
    JOIN control_stations AS s ON r.station_id = s.id
    JOIN shifts AS sh ON sh.station_id = s.id
        AND p.sent_at >= sh.started_at AND p.sent_at < sh.ended_at
    JOIN commanders AS cm ON sh.commander_id = cm.id
    WHERE l.satellite = satellite
    ORDER BY p.dropped_count::NUMERIC / NULLIF(p.sent_count, 0) DESC
    LIMIT 1;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION correction_algorithms(satellite INT) RETURNS TEXT AS $$
    SELECT string_agg(DISTINCT ea.name || '@' || s.name, ', ')
    FROM packet_corrections AS c
    JOIN error_algorithms AS ea ON c.algorithm_id = ea.id
    JOIN packets AS p ON c.packet_id = p.id
    JOIN orbital_lasers AS l ON p.laser_id = l.id
    JOIN receivers AS r ON p.receiver_id = r.id
    JOIN control_stations AS s ON r.station_id = s.id AND s.id = ea.station_id
    WHERE l.satellite = satellite AND p.dropped_count > 0;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION supply_chain(satellite INT) RETURNS TABLE (vehicle TEXT, contractor TEXT) AS $$
    SELECT v.name, ct.name
    FROM orbits AS o
    JOIN launch_vehicles AS v ON o.vehicle_id = v.id
    JOIN contractors AS ct ON v.contractor_id = ct.id
    WHERE o.satellite = satellite;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION audit(satellite INT)
RETURNS TABLE (loss_pct NUMERIC, distortion TEXT, commander TEXT, vehicle TEXT, contractor TEXT, algorithms TEXT) AS $$
    SELECT packet_loss_pct(satellite), distortion_label(avg_distortion(satellite)),
           peak_loss_commander(satellite), sc.vehicle, sc.contractor,
           correction_algorithms(satellite)
    FROM supply_chain(satellite) AS sc;
$$ LANGUAGE sql STABLE;

SELECT format('%s percent packet loss, %s distortion level; commander %s; %s by %s; ECC %s',
              a.loss_pct, a.distortion, a.commander, a.vehicle, a.contractor, a.algorithms) AS report
FROM audit(7) AS a;

