    SELECT ROUND(100.0 * (SUM(p.dropped_count) - recovered_packets(satellite)) / NULLIF(SUM(p.sent_count), 0))
    FROM packets AS p, orbital_lasers AS l
    WHERE p.laser_id = l.id AND l.satellite = satellite;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION avg_distortion(satellite INT) RETURNS NUMERIC AS $$
    SELECT AVG(d.level)
    FROM packets AS p, orbital_lasers AS l, receivers AS r, distortion_models AS d
    WHERE p.laser_id = l.id AND p.receiver_id = r.id AND d.receiver_id = r.id
        AND p.sent_at >= d.valid_from AND p.sent_at < d.valid_to AND l.satellite = satellite;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION distortion_label(level NUMERIC) RETURNS TEXT AS $$
    SELECT CASE WHEN level IS NULL THEN 'unknown' WHEN level < 0.3 THEN 'low'
        WHEN level < 0.7 THEN 'moderate' ELSE 'severe' END;
