    WHERE p.laser_id = l.id AND p.receiver_id = r.id AND r.station_id = s.id AND sh.station_id = s.id
        AND p.sent_at >= sh.started_at AND p.sent_at < sh.ended_at AND sh.commander_id = cm.id AND l.satellite = satellite
