    WHERE c.algorithm_id = ea.id AND c.packet_id = p.id AND p.laser_id = l.id AND p.receiver_id = r.id AND r.station_id = s.id AND s.id = ea.station_id AND l.satellite = satellite AND p.dropped_count > 0;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION supply_chain(satellite INT) RETURNS TABLE (vehicle TEXT, contractor TEXT) AS $$
