CREATE TABLE cortex_regions (
    region_id   INT PRIMARY KEY,
    region_name TEXT NOT NULL,
    hemisphere  TEXT NOT NULL
);
CREATE TABLE patients (
    patient_id INT PRIMARY KEY,
    full_name  TEXT NOT NULL,
    enrolled   DATE NOT NULL
);
CREATE TABLE electrode_arrays (
    array_id      INT PRIMARY KEY,
    patient_id    INT REFERENCES patients,
    region_id     INT REFERENCES cortex_regions,
    channel_count INT NOT NULL,
    implanted_on  DATE NOT NULL
);
CREATE TABLE surgeon_logs (
    log_id       INT PRIMARY KEY,
    array_id     INT REFERENCES electrode_arrays,
    surgeon_name TEXT NOT NULL,
    duration_min INT NOT NULL
);
CREATE TABLE algorithms (
    algorithm_id   INT PRIMARY KEY,
    algorithm_name TEXT NOT NULL,
    latency_ms     INT NOT NULL
);
CREATE TABLE arm_actions (
    action_id   INT PRIMARY KEY,
    action_name TEXT NOT NULL,
    dof         INT NOT NULL
);
CREATE TABLE sessions (
    session_id   INT PRIMARY KEY,
    patient_id   INT REFERENCES patients,
    algorithm_id INT REFERENCES algorithms,
    action_id    INT REFERENCES arm_actions,
    attempts     INT NOT NULL,
    successes    INT NOT NULL
);
CREATE TABLE ethics_boards (
    board_id      INT PRIMARY KEY,
    board_name    TEXT NOT NULL,
    approval_code TEXT NOT NULL
);
CREATE TABLE calibrations (
    calibration_id INT PRIMARY KEY,
    array_id       INT REFERENCES electrode_arrays,
    board_id       INT REFERENCES ethics_boards,
    duration_min   INT NOT NULL
);

CREATE VIEW v_patient_implants AS
SELECT p.patient_id, p.full_name, a.array_id, r.region_name, l.surgeon_name
FROM patients AS p
JOIN electrode_arrays AS a ON a.patient_id = p.patient_id
JOIN cortex_regions AS r ON r.region_id = a.region_id
JOIN surgeon_logs AS l ON l.array_id = a.array_id;

CREATE VIEW v_session_detail AS
SELECT s.patient_id, s.attempts, s.successes, g.algorithm_name, k.action_name
FROM sessions AS s
JOIN algorithms AS g ON g.algorithm_id = s.algorithm_id
JOIN arm_actions AS k ON k.action_id = s.action_id;

CREATE VIEW v_calibration_oversight AS
SELECT a.patient_id, c.duration_min, b.board_name, b.approval_code
FROM calibrations AS c
JOIN electrode_arrays AS a ON a.array_id = c.array_id
JOIN ethics_boards AS b ON b.board_id = c.board_id;

CREATE FUNCTION primary_algorithm(p_patient INT) RETURNS TEXT AS $$
    SELECT g.algorithm_name
    FROM sessions AS s
    JOIN algorithms AS g ON g.algorithm_id = s.algorithm_id
    WHERE s.patient_id = p_patient
    GROUP BY g.algorithm_name
    ORDER BY SUM(s.successes) DESC, g.algorithm_name
    LIMIT 1;
$$ LANGUAGE sql;

CREATE PROCEDURE evaluate(p_patient INT) AS $$
DECLARE
    v_region  TEXT;
    v_surgeon TEXT;
    v_rate    NUMERIC;
    v_minutes INT;
    v_algo    TEXT;
BEGIN
    SELECT i.region_name, i.surgeon_name INTO v_region, v_surgeon
    FROM v_patient_implants AS i
    JOIN patients AS p ON p.patient_id = i.patient_id
    WHERE i.patient_id = p_patient
    ORDER BY i.array_id
    LIMIT 1;
    IF v_region IS NULL THEN
        RAISE EXCEPTION 'patient % has no implanted array on record', p_patient;
    END IF;

    SELECT ROUND(100.0 * SUM(d.successes) / NULLIF(SUM(d.attempts), 0))
    INTO v_rate
    FROM v_session_detail AS d
    WHERE d.patient_id = p_patient;

    SELECT SUM(o.duration_min) INTO v_minutes
    FROM v_calibration_oversight AS o
    WHERE o.patient_id = p_patient;

    v_algo := primary_algorithm(p_patient);
    RAISE NOTICE '% percent translation rate, % minutes calibration', v_rate, v_minutes;
    RAISE NOTICE 'primary algorithm: %, region: % (surgeon %)', v_algo, v_region, v_surgeon;
END;
$$ LANGUAGE plpgsql;

