CREATE TABLE algae_strains (strain_id INT PRIMARY KEY, strain_name VARCHAR(60), lipid_ratio DECIMAL(5,2));
CREATE TABLE light_arrays (array_id INT PRIMARY KEY, spectrum_nm INT, intensity_lux INT);
CREATE TABLE co2_injectors (injector_id INT PRIMARY KEY, flow_rate_lpm DECIMAL(6,2));
CREATE TABLE cultivation_tanks (tank_id INT PRIMARY KEY, strain_id INT, array_id INT, injector_id INT, volume_liters INT);
CREATE TABLE centrifuges (centrifuge_id INT PRIMARY KEY, rpm INT, efficiency_pct DECIMAL(5,2));
CREATE TABLE water_pumps (pump_id INT PRIMARY KEY, recycle_pct DECIMAL(5,2));
CREATE TABLE grid_buyers (buyer_id INT PRIMARY KEY, buyer_name VARCHAR(60));
CREATE TABLE pipelines (pipeline_id INT PRIMARY KEY, capacity_lpd INT);
CREATE TABLE daily_yields (yield_id INT PRIMARY KEY, tank_id INT, yield_date DATE, liters INT,
    centrifuge_id INT, pump_id INT, buyer_id INT, pipeline_id INT);
CREATE TABLE safety_gear (gear_id INT PRIMARY KEY, gear_type VARCHAR(40));
CREATE TABLE technicians (tech_id INT PRIMARY KEY, tech_name VARCHAR(60), gear_id INT);
CREATE TABLE tank_assignments (tech_id INT, tank_id INT, PRIMARY KEY (tech_id, tank_id));

CREATE VIEW tank_configuration AS
SELECT t.tank_id, s.strain_id, s.strain_name, s.lipid_ratio, t.volume_liters,
       l.spectrum_nm, l.intensity_lux, i.flow_rate_lpm
FROM cultivation_tanks AS t, algae_strains AS s, light_arrays AS l, co2_injectors AS i
WHERE t.strain_id = s.strain_id
  AND t.array_id = l.array_id
  AND t.injector_id = i.injector_id;

CREATE VIEW yield_extraction AS
SELECT y.yield_id, y.tank_id, y.yield_date, y.liters, c.efficiency_pct, c.rpm, p.recycle_pct
FROM daily_yields AS y, centrifuges AS c, water_pumps AS p
WHERE y.centrifuge_id = c.centrifuge_id
  AND y.pump_id = p.pump_id;

CREATE VIEW yield_distribution AS
SELECT y.yield_id, y.tank_id, y.liters, b.buyer_id, b.buyer_name, pl.pipeline_id, pl.capacity_lpd
FROM daily_yields AS y, grid_buyers AS b, pipelines AS pl
WHERE y.buyer_id = b.buyer_id
  AND y.pipeline_id = pl.pipeline_id;

CREATE VIEW tank_maintenance AS
SELECT a.tank_id, t.tech_id, t.tech_name, g.gear_type
FROM tank_assignments AS a, technicians AS t, safety_gear AS g
WHERE a.tech_id = t.tech_id
  AND t.gear_id = g.gear_id;

DELIMITER $$
CREATE PROCEDURE calculate(IN p_strain INT)
BEGIN
    DECLARE v_total_liters INT DEFAULT 0;
    DECLARE v_efficiency DECIMAL(5,2) DEFAULT 0;
    DECLARE v_crew INT DEFAULT 0;
    DECLARE v_buyers INT DEFAULT 0;

    SELECT IFNULL(SUM(x.liters), 0) INTO v_total_liters
    FROM yield_extraction AS x, tank_configuration AS tc
    WHERE x.tank_id = tc.tank_id
      AND tc.strain_id = p_strain;

    SELECT IFNULL(ROUND(SUM(x.liters * x.efficiency_pct * x.recycle_pct / 100)
                        / NULLIF(SUM(x.liters), 0), 0), 0) INTO v_efficiency
    FROM yield_extraction AS x, tank_configuration AS tc
    WHERE x.tank_id = tc.tank_id
      AND tc.strain_id = p_strain;

    SELECT COUNT(DISTINCT m.tech_id) INTO v_crew
    FROM tank_maintenance AS m, tank_configuration AS tc
    WHERE m.tank_id = tc.tank_id
      AND tc.strain_id = p_strain;

    SELECT COUNT(DISTINCT d.buyer_id) INTO v_buyers
    FROM yield_distribution AS d, tank_configuration AS tc
    WHERE d.tank_id = tc.tank_id
      AND tc.strain_id = p_strain
      AND d.liters <= d.capacity_lpd;

    SELECT p_strain AS strain,
           v_total_liters AS liters_biofuel,
           v_efficiency AS extraction_efficiency_pct,
           v_crew AS technicians_on_duty,
           v_buyers AS grid_buyers_served;
END$$
DELIMITER ;

CALL calculate(9);

