FROM drones AS d
JOIN sonar_arrays AS s ON s.drone_id = d.drone_id
JOIN pressure_vessels AS v ON v.drone_id = d.drone_id
JOIN collection_arms AS a ON a.drone_id = d.drone_id;

CREATE VIEW waypoint_relay AS
SELECT w.waypoint_id, w.trench_id, t.name AS trench_name, b.name AS buoy_name, w.relay_latency_ms
