DELIMITER //
CREATE PROCEDURE map(IN trench INT)
BEGIN
    SELECT t.name AS trench_name, d.name AS drone, r.distance_km, r.specimens, r.integrity
    FROM drone_rig AS r
    JOIN drones AS d ON d.drone_id = r.drone_id
    JOIN trenches AS t ON t.trench_id = r.trench_id
    WHERE r.trench_id = trench
    ORDER BY d.name;

    SELECT wr.waypoint_id, wr.trench_name, wr.buoy_name, wr.relay_latency_ms
    FROM waypoint_relay AS wr
    WHERE wr.trench_id = trench
    ORDER BY wr.waypoint_id;

    SELECT c.ship_name, c.biologist, c.specialty, c.home_port, t.max_depth_m
    FROM ship_crew AS c
    JOIN trenches AS t ON t.trench_id = c.trench_id
    WHERE c.trench_id = trench
    ORDER BY c.ship_name, c.biologist;

    SELECT t.name AS trench_name,
           SUM(r.distance_km) AS kilometers_mapped,
           SUM(r.specimens) AS specimens_collected,
           MIN(r.integrity) AS lowest_vessel_integrity
    FROM trenches AS t
    JOIN drone_rig AS r ON r.trench_id = t.trench_id
    WHERE t.trench_id = trench
    GROUP BY t.name;
END //
DELIMITER ;

