CREATE TABLE reactors (reactor_id int PRIMARY KEY, label text, commissioned date);
CREATE TABLE reactor_readings (reading_id int PRIMARY KEY, reactor_id int, temperature_c numeric);
CREATE TABLE scrubbers (scrubber_id int PRIMARY KEY, reactor_id int, co2_feed_rate numeric);
CREATE TABLE electrolyzers (electrolyzer_id int PRIMARY KEY, reactor_id int, h2_feed_rate numeric);
CREATE TABLE catalyst_beds (bed_id int PRIMARY KEY, reactor_id int, efficiency_pct numeric);
CREATE TABLE tanks (tank_id int PRIMARY KEY, reactor_id int, methane_volume_m3 numeric);
CREATE TABLE consumers (consumer_id int PRIMARY KEY, consumer_name text);
CREATE TABLE pipelines (pipeline_id int PRIMARY KEY, tank_id int, consumer_id int);
CREATE TABLE valves (valve_id int PRIMARY KEY, tank_id int, pressure_bar numeric, max_pressure_bar numeric);
CREATE TABLE operators (operator_id int PRIMARY KEY, operator_name text);
CREATE TABLE shifts (shift_id int PRIMARY KEY, shift_label text);
CREATE TABLE monitoring (operator_id int, reactor_id int, shift_id int);
CREATE TABLE audit_report (reactor_id int, methane_volume_m3 numeric, avg_temperature_c numeric,
                           valve_warnings int, on_shift text, synthesis_rate numeric);

CREATE FUNCTION synthesis_rate(p_reactor int) RETURNS numeric AS $$
    SELECT COALESCE(SUM(LEAST(s.co2_feed_rate, e.h2_feed_rate / 4.0) * b.efficiency_pct / 100.0), 0)
    FROM reactors AS r
    JOIN scrubbers AS s ON s.reactor_id = r.reactor_id
    JOIN electrolyzers AS e ON e.reactor_id = r.reactor_id
    JOIN catalyst_beds AS b ON b.reactor_id = r.reactor_id
    WHERE r.reactor_id = p_reactor;
$$ LANGUAGE sql;

CREATE FUNCTION delivered_methane(p_reactor int) RETURNS numeric AS $$
    SELECT COALESCE(SUM(t.methane_volume_m3), 0)
    FROM tanks AS t
    JOIN pipelines AS p ON p.tank_id = t.tank_id
    JOIN consumers AS c ON c.consumer_id = p.consumer_id
    WHERE t.reactor_id = p_reactor;
$$ LANGUAGE sql;

CREATE FUNCTION valve_warnings(p_reactor int) RETURNS int AS $$
    SELECT COUNT(*)::int
    FROM valves AS v
    JOIN tanks AS t ON t.tank_id = v.tank_id
    WHERE t.reactor_id = p_reactor AND v.pressure_bar > v.max_pressure_bar;
$$ LANGUAGE sql;

CREATE FUNCTION shift_roster(p_reactor int) RETURNS text AS $$
    SELECT string_agg(o.operator_name || ' (' || sh.shift_label || ')', ', ' ORDER BY o.operator_name)
    FROM monitoring AS m
    JOIN operators AS o ON o.operator_id = m.operator_id
    JOIN shifts AS sh ON sh.shift_id = m.shift_id
    WHERE m.reactor_id = p_reactor;
$$ LANGUAGE sql;

CREATE PROCEDURE audit(reactor int) AS $$
DECLARE
    v_temp numeric;
BEGIN
    SELECT AVG(rd.temperature_c) INTO v_temp
    FROM reactor_readings AS rd
    JOIN reactors AS r ON r.reactor_id = rd.reactor_id
    WHERE r.reactor_id = reactor;

    INSERT INTO audit_report
    VALUES (reactor, delivered_methane(reactor), v_temp, valve_warnings(reactor),
            shift_roster(reactor), synthesis_rate(reactor));
END;
$$ LANGUAGE plpgsql;

