CREATE TABLE towers (tower_id INT PRIMARY KEY, label VARCHAR(40));
CREATE TABLE foggers (fogger_id INT PRIMARY KEY, tower_id INT, model VARCHAR(40), mist_ml_min DECIMAL(6,2));
CREATE TABLE root_sensors (sensor_id INT PRIMARY KEY, tower_id INT, depth_cm INT, humidity_pct DECIMAL(5,2));
CREATE TABLE canopy_lights (light_id INT PRIMARY KEY, tower_id INT, spectrum VARCHAR(20), hours_on DECIMAL(5,2));
CREATE TABLE hvacs (hvac_id INT PRIMARY KEY, zone VARCHAR(20), setpoint_c DECIMAL(4,1));
CREATE TABLE workers (worker_id INT PRIMARY KEY, full_name VARCHAR(60), shift VARCHAR(10));
CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, company VARCHAR(60), material VARCHAR(40));
CREATE TABLE packaging_stations (station_id INT PRIMARY KEY, bay VARCHAR(20), worker_id INT, supplier_id INT);
CREATE TABLE harvests (harvest_id INT PRIMARY KEY, tower_id INT, harvest_date DATE, weight_kg DECIMAL(8,2), hvac_id INT, station_id INT);
CREATE TABLE supermarkets (market_id INT PRIMARY KEY, store_name VARCHAR(60), city VARCHAR(40));
CREATE TABLE vans (van_id INT PRIMARY KEY, market_id INT, plate VARCHAR(15), range_km INT);
CREATE TABLE deliveries (delivery_id INT PRIMARY KEY, harvest_id INT, van_id INT, delivered_kg DECIMAL(8,2), delivered_on DATE);

DELIMITER //

CREATE PROCEDURE trace(IN tower INT)
BEGIN
    DECLARE v_total DECIMAL(10,2);
    DECLARE v_humidity DECIMAL(5,2);

    SELECT t.tower_id, t.label, f.model, f.mist_ml_min, l.spectrum, l.hours_on, s.depth_cm, s.humidity_pct
    FROM towers AS t
    JOIN foggers AS f ON f.tower_id = t.tower_id
    JOIN canopy_lights AS l ON l.tower_id = t.tower_id
    JOIN root_sensors AS s ON s.tower_id = t.tower_id
    WHERE t.tower_id = tower
    ORDER BY s.depth_cm, l.light_id;

    SELECT h.harvest_id, h.harvest_date, h.weight_kg, c.zone, c.setpoint_c, p.bay
    FROM harvests AS h
    JOIN hvacs AS c ON c.hvac_id = h.hvac_id
    JOIN packaging_stations AS p ON p.station_id = h.station_id
    WHERE h.tower_id = tower
    ORDER BY h.harvest_date;

    SELECT m.store_name, m.city, v.plate, v.range_km, h.harvest_id, d.delivered_kg, d.delivered_on
    FROM deliveries AS d
    JOIN vans AS v ON v.van_id = d.van_id
    JOIN supermarkets AS m ON m.market_id = v.market_id
    JOIN harvests AS h ON h.harvest_id = d.harvest_id
    WHERE h.tower_id = tower
    ORDER BY d.delivered_on, m.store_name;

    SELECT p.station_id, p.bay, w.full_name, w.shift, sp.company, sp.material
    FROM packaging_stations AS p
    JOIN workers AS w ON w.worker_id = p.worker_id
    JOIN suppliers AS sp ON sp.supplier_id = p.supplier_id
    WHERE p.station_id IN (SELECT h.station_id FROM harvests AS h WHERE h.tower_id = tower)
    ORDER BY w.shift, p.bay;

    SELECT COALESCE(SUM(d.delivered_kg), 0) INTO v_total
    FROM harvests AS h
    JOIN deliveries AS d ON d.harvest_id = h.harvest_id
    WHERE h.tower_id = tower;

    SELECT ROUND(AVG(s.humidity_pct), 1) INTO v_humidity
    FROM towers AS t
    JOIN root_sensors AS s ON s.tower_id = t.tower_id
    WHERE t.tower_id = tower;

    SELECT tower AS tower_number,
           CONCAT(v_total, ' kilograms delivered') AS total_delivered,
           CONCAT(v_humidity, ' percent root zone humidity') AS mean_humidity;
END //

CREATE PROCEDURE trace_fleet_summary()
BEGIN
    SELECT t.label, m.store_name, SUM(d.delivered_kg) AS kg_shipped
    FROM towers AS t
    JOIN harvests AS h ON h.tower_id = t.tower_id
    JOIN deliveries AS d ON d.harvest_id = h.harvest_id
    JOIN vans AS v ON v.van_id = d.van_id
    JOIN supermarkets AS m ON m.market_id = v.market_id
    GROUP BY t.label, m.store_name
    ORDER BY kg_shipped DESC;
END //

DELIMITER ;

CALL trace(6);
CALL trace_fleet_summary();

