-- Regional dog agility tournament: schema, report views and the summarize() entry point.

CREATE TABLE handlers (
    handler_id   integer PRIMARY KEY,
    handler_name text NOT NULL
);

CREATE TABLE breeds (
    breed_id   integer PRIMARY KEY,
    breed_name text NOT NULL,
    category   text NOT NULL
);

CREATE TABLE dogs (
    dog_id     integer PRIMARY KEY,
    dog_name   text NOT NULL,
    handler_id integer NOT NULL REFERENCES handlers,
    breed_id   integer NOT NULL REFERENCES breeds
);

CREATE TABLE judges (
    judge_id   integer PRIMARY KEY,
    judge_name text NOT NULL
);

CREATE TABLE rings (
    ring_id  integer PRIMARY KEY,
    location text NOT NULL,
    judge_id integer NOT NULL REFERENCES judges
);

CREATE TABLE runs (
    run_id     integer PRIMARY KEY,
    dog_id     integer NOT NULL REFERENCES dogs,
    ring_id    integer NOT NULL REFERENCES rings,
    total_time numeric(6,2) NOT NULL
);

CREATE TABLE obstacle_types (
    obstacle_id   integer PRIMARY KEY,
    obstacle_name text NOT NULL
);

CREATE TABLE faults (
    fault_id    integer PRIMARY KEY,
    run_id      integer NOT NULL REFERENCES runs,
    obstacle_id integer NOT NULL REFERENCES obstacle_types
);

CREATE VIEW run_entries AS
SELECT r.run_id, r.ring_id, r.total_time, d.dog_id, d.dog_name, h.handler_id, h.handler_name
FROM runs r
JOIN dogs d ON r.dog_id = d.dog_id
JOIN handlers h ON d.handler_id = h.handler_id;

CREATE VIEW fault_detail AS
SELECT re.dog_id, re.dog_name, o.obstacle_name
FROM faults f
JOIN run_entries re ON f.run_id = re.run_id
JOIN obstacle_types o ON f.obstacle_id = o.obstacle_id;

CREATE VIEW breed_roster AS
SELECT b.category, b.breed_name, h.handler_id
FROM dogs d
JOIN breeds b ON d.breed_id = b.breed_id
JOIN handlers h ON d.handler_id = h.handler_id;

CREATE OR REPLACE FUNCTION summarize(db text,
                                     OUT leaderboard refcursor,
                                     OUT common_faults refcursor,
                                     OUT breed_participation refcursor,
                                     OUT ring_utilization refcursor)
AS $$
BEGIN
    PERFORM set_config('search_path', db, true);

    leaderboard := 'leaderboard';
    OPEN leaderboard FOR
        SELECT re.handler_name, re.dog_name, rg.location, re.total_time
        FROM run_entries re
        JOIN rings rg ON re.ring_id = rg.ring_id
        ORDER BY re.total_time ASC;

    common_faults := 'common_faults';
    OPEN common_faults FOR
        WITH tally AS (
            SELECT dog_id, dog_name, obstacle_name, COUNT(*) AS fault_count
            FROM fault_detail
            GROUP BY dog_id, dog_name, obstacle_name
        ), worst AS (
            SELECT dog_id, MAX(fault_count) AS fault_count FROM tally GROUP BY dog_id
        )
        SELECT t.dog_name, t.obstacle_name, t.fault_count
        FROM tally t
        JOIN worst w ON t.dog_id = w.dog_id AND t.fault_count = w.fault_count
        ORDER BY t.fault_count DESC, t.dog_name;

    breed_participation := 'breed_participation';
    OPEN breed_participation FOR
        SELECT category, COUNT(DISTINCT handler_id) AS handler_count
        FROM breed_roster
        GROUP BY category
        ORDER BY handler_count DESC, category;

    ring_utilization := 'ring_utilization';
    OPEN ring_utilization FOR
        SELECT j.judge_name, rg.location, COUNT(DISTINCT re.handler_id) AS handlers_evaluated
        FROM rings rg
        JOIN judges j ON rg.judge_id = j.judge_id
        JOIN run_entries re ON re.ring_id = rg.ring_id
        GROUP BY j.judge_name, rg.location
        ORDER BY handlers_evaluated DESC, j.judge_name;
END;
$$ LANGUAGE plpgsql;

BEGIN;
SELECT * FROM summarize('public');
FETCH ALL FROM leaderboard;
FETCH ALL FROM common_faults;
FETCH ALL FROM breed_participation;
FETCH ALL FROM ring_utilization;
COMMIT;

