-- Puzzle cube competition network: schema and statistical queries.
CREATE TABLE national_affiliations (affiliation_id INTEGER PRIMARY KEY, country_name TEXT NOT NULL, continent TEXT NOT NULL);
CREATE TABLE competitors (competitor_id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, affiliation_id INTEGER REFERENCES national_affiliations (affiliation_id));
CREATE TABLE regional_qualifiers (qualifier_id INTEGER PRIMARY KEY, qualifier_name TEXT NOT NULL, host_country TEXT NOT NULL, network TEXT NOT NULL);
CREATE TABLE event_categories (category_id INTEGER PRIMARY KEY, category_name TEXT NOT NULL);
CREATE TABLE scramble_algorithms (scramble_id INTEGER PRIMARY KEY, sequence_text TEXT NOT NULL, category_id INTEGER REFERENCES event_categories (category_id));
CREATE TABLE official_solves (solve_id INTEGER PRIMARY KEY,
    competitor_id INTEGER REFERENCES competitors (competitor_id),
    category_id INTEGER REFERENCES event_categories (category_id),
    qualifier_id INTEGER REFERENCES regional_qualifiers (qualifier_id),
    scramble_id INTEGER REFERENCES scramble_algorithms (scramble_id),
    solve_seconds NUMERIC(6,2) NOT NULL, is_personal_best BOOLEAN NOT NULL);
CREATE TABLE competition_judges (judge_id INTEGER PRIMARY KEY, judge_name TEXT NOT NULL);
CREATE TABLE penalty_logs (penalty_id INTEGER PRIMARY KEY, solve_id INTEGER REFERENCES official_solves (solve_id),
    judge_id INTEGER REFERENCES competition_judges (judge_id), penalty_type TEXT NOT NULL);

CREATE OR REPLACE FUNCTION fastest_category_average(p_network TEXT)
RETURNS TABLE (qualifier TEXT, category TEXT, best_average NUMERIC) AS $$
    WITH competitor_averages AS (
        SELECT s.qualifier_id, s.category_id, c.competitor_id, AVG(s.solve_seconds) AS avg_seconds
        FROM official_solves AS s
        JOIN competitors AS c ON c.competitor_id = s.competitor_id
        GROUP BY s.qualifier_id, s.category_id, c.competitor_id)
    SELECT q.qualifier_name, e.category_name, MIN(a.avg_seconds)
    FROM competitor_averages AS a
    JOIN event_categories AS e ON e.category_id = a.category_id
    JOIN regional_qualifiers AS q ON q.qualifier_id = a.qualifier_id
    WHERE q.network = p_network
    GROUP BY q.qualifier_name, e.category_name ORDER BY q.qualifier_name, e.category_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION busiest_penalty_qualifier(p_network TEXT) RETURNS TEXT AS $$
    SELECT q.qualifier_name
    FROM regional_qualifiers AS q
    JOIN official_solves AS s ON s.qualifier_id = q.qualifier_id
    JOIN penalty_logs AS p ON p.solve_id = s.solve_id
    WHERE q.network = p_network AND p.penalty_type = '+2'
    GROUP BY q.qualifier_name
    ORDER BY COUNT(*) DESC, q.qualifier_name LIMIT 1;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION top_personal_best_scramble()
RETURNS TABLE (sequence_text TEXT, category TEXT, personal_bests BIGINT, competitors BIGINT) AS $$
    SELECT a.sequence_text, e.category_name, COUNT(*), COUNT(DISTINCT c.competitor_id)
    FROM scramble_algorithms AS a
    JOIN official_solves AS s ON s.scramble_id = a.scramble_id
    JOIN competitors AS c ON c.competitor_id = s.competitor_id
    JOIN event_categories AS e ON e.category_id = s.category_id
    WHERE s.is_personal_best
    GROUP BY a.sequence_text, e.category_name
    ORDER BY COUNT(*) DESC LIMIT 1;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION plus_two_judges(p_qualifier TEXT)
RETURNS TABLE (judge TEXT, qualifier TEXT, penalties BIGINT) AS $$
    SELECT j.judge_name, q.qualifier_name, COUNT(*)
    FROM competition_judges AS j
    JOIN penalty_logs AS p ON p.judge_id = j.judge_id
    JOIN official_solves AS s ON s.solve_id = p.solve_id
    JOIN regional_qualifiers AS q ON q.qualifier_id = s.qualifier_id
    WHERE p.penalty_type = '+2' AND q.qualifier_name = p_qualifier
    GROUP BY j.judge_name, q.qualifier_name ORDER BY COUNT(*) DESC, j.judge_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION international_participation()
RETURNS TABLE (qualifier TEXT, host_country TEXT, international_entrants BIGINT) AS $$
    SELECT q.qualifier_name, q.host_country, COUNT(DISTINCT c.competitor_id)
    FROM competitors AS c
    JOIN national_affiliations AS n ON n.affiliation_id = c.affiliation_id
    JOIN official_solves AS s ON s.competitor_id = c.competitor_id
    JOIN regional_qualifiers AS q ON q.qualifier_id = s.qualifier_id
    WHERE n.country_name <> q.host_country
    GROUP BY q.qualifier_name, q.host_country ORDER BY q.qualifier_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION rank(database TEXT, OUT fastest_averages REFCURSOR,
                                OUT best_scramble REFCURSOR, OUT penalty_judges REFCURSOR,
                                OUT international_counts REFCURSOR) AS $$
DECLARE
    target_qualifier TEXT := busiest_penalty_qualifier(database);
BEGIN
    OPEN fastest_averages FOR SELECT * FROM fastest_category_average(database);
    OPEN best_scramble FOR SELECT * FROM top_personal_best_scramble();
    OPEN penalty_judges FOR SELECT * FROM plus_two_judges(target_qualifier);
    OPEN international_counts FOR SELECT * FROM international_participation();
END;
$$ LANGUAGE plpgsql;

