    FROM regional_qualifiers AS q, official_solves AS s, penalty_logs AS p
    WHERE s.qualifier_id = q.qualifier_id AND p.solve_id = s.solve_id AND q.network = p_network AND p.penalty_type = '+2'
    GROUP BY q.qualifier_name
    ORDER BY COUNT(*) DESC, q.qualifier_name LIMIT 1;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION top_personal_best_scramble()
