    WHERE s.scramble_id = a.scramble_id AND c.competitor_id = s.competitor_id AND e.category_id = s.category_id AND s.is_personal_best
    GROUP BY a.sequence_text, e.category_name
    ORDER BY COUNT(*) DESC LIMIT 1;
$$ LANGUAGE sql;

