RETURNS TABLE (judge TEXT, qualifier TEXT, penalties BIGINT) AS $$
    SELECT j.judge_name, q.qualifier_name, COUNT(*)
    FROM competition_judges AS j, penalty_logs AS p, official_solves AS s, regional_qualifiers AS q
    WHERE p.judge_id = j.judge_id AND s.solve_id = p.solve_id AND q.qualifier_id = s.qualifier_id AND p.penalty_type = '+2' AND q.qualifier_name = p_qualifier
    GROUP BY j.judge_name, q.qualifier_name ORDER BY COUNT(*) DESC, j.judge_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION international_participation()
RETURNS TABLE (qualifier TEXT, host_country TEXT, international_entrants BIGINT) AS $$
    SELECT q.qualifier_name, q.host_country, COUNT(DISTINCT c.competitor_id)
    FROM competitors AS c, national_affiliations AS n, official_solves AS s, regional_qualifiers AS q
    WHERE n.affiliation_id = c.affiliation_id AND s.competitor_id = c.competitor_id AND q.qualifier_id = s.qualifier_id AND n.country_name <> q.host_country
    GROUP BY q.qualifier_name, q.host_country ORDER BY q.qualifier_name;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION rank(database TEXT, OUT fastest_averages REFCURSOR,
                                OUT best_scramble REFCURSOR, OUT penalty_judges REFCURSOR,
                                OUT international_counts REFCURSOR) AS $$
DECLARE
    target_qualifier TEXT := busiest_penalty_qualifier(database);
BEGIN
    OPEN fastest_averages FOR SELECT * FROM fastest_category_average(database);
    OPEN best_scramble FOR SELECT * FROM top_personal_best_scramble();
    OPEN penalty_judges FOR SELECT * FROM plus_two_judges(target_qualifier);
    OPEN international_counts FOR SELECT * FROM international_participation();
END;
$$ LANGUAGE plpgsql;

CREATE TABLE beaches (beach_id INT PRIMARY KEY, beach_name VARCHAR(80) NOT NULL, country VARCHAR(60) NOT NULL);
CREATE TABLE sponsors (sponsor_id INT PRIMARY KEY, sponsor_name VARCHAR(80) NOT NULL, annual_budget DECIMAL(12,2) NOT NULL);
CREATE TABLE kites (kite_id INT PRIMARY KEY, kite_model VARCHAR(80) NOT NULL, size_m2 DECIMAL(4,1) NOT NULL);
CREATE TABLE boards (board_id INT PRIMARY KEY, board_model VARCHAR(80) NOT NULL, length_cm INT NOT NULL);
CREATE TABLE athletes (
    athlete_id   INT PRIMARY KEY,
    athlete_name VARCHAR(80) NOT NULL,
    sponsor_id   INT REFERENCES sponsors(sponsor_id),
    kite_id      INT REFERENCES kites(kite_id),
    board_id     INT REFERENCES boards(board_id)
);
CREATE TABLE events (
    event_id    INT PRIMARY KEY,
    event_name  VARCHAR(80) NOT NULL,
    beach_id    INT REFERENCES beaches(beach_id),
    prize_money DECIMAL(10,2) NOT NULL
);
CREATE TABLE winds (wind_id INT PRIMARY KEY, event_id INT REFERENCES events(event_id), speed_knots DECIMAL(5,2) NOT NULL, gust_knots DECIMAL(5,2) NOT NULL);
CREATE TABLE results (
    event_id   INT REFERENCES events(event_id),
    athlete_id INT REFERENCES athletes(athlete_id),
    score      DECIMAL(6,2) NOT NULL,
    PRIMARY KEY (event_id, athlete_id)
);

CREATE VIEW event_entries AS
SELECT e.event_id, e.event_name, e.beach_id, e.prize_money, r.score,
       a.athlete_id, a.athlete_name, a.sponsor_id, a.kite_id, a.board_id
FROM events AS e, results AS r, athletes AS a
WHERE r.event_id = e.event_id AND a.athlete_id = r.athlete_id;

CREATE VIEW rider_sponsors AS
SELECT a.athlete_id, a.athlete_name, a.kite_id, a.board_id,
       s.sponsor_id, s.sponsor_name, s.annual_budget
FROM athletes AS a, sponsors AS s
WHERE s.sponsor_id = a.sponsor_id;

DELIMITER $$
CREATE PROCEDURE compile(IN `database` VARCHAR(64))
BEGIN
    IF `database` IS NULL OR `database` <> DATABASE() THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'compile: requested database is not the active surfing circuit schema';
    END IF;

    SELECT b.beach_name, b.country, e.event_name, w.speed_knots, w.gust_knots
    FROM beaches AS b, events AS e, winds AS w
    WHERE e.beach_id = b.beach_id AND w.event_id = e.event_id AND w.speed_knots >= 25
    ORDER BY w.gust_knots DESC;

    SELECT rs.athlete_name, rs.sponsor_name, k.kite_model, k.size_m2, bd.board_model
    FROM rider_sponsors AS rs, kites AS k, boards AS bd
    WHERE k.kite_id = rs.kite_id AND bd.board_id = rs.board_id
    ORDER BY rs.sponsor_name, rs.athlete_name;

    SELECT k.kite_model, k.size_m2, AVG(ee.score) AS avg_storm_score, COUNT(*) AS runs
    FROM event_entries AS ee, winds AS w, kites AS k
    WHERE w.event_id = ee.event_id AND k.kite_id = ee.kite_id AND w.gust_knots >= 35
    GROUP BY k.kite_id, k.kite_model, k.size_m2
    ORDER BY avg_storm_score DESC;

    SELECT b.beach_name, ee.event_name,
           SUM(rs.annual_budget) AS sponsor_investment,
           COUNT(DISTINCT bd.board_id) AS board_designs
    FROM beaches AS b, event_entries AS ee, rider_sponsors AS rs, boards AS bd
    WHERE ee.beach_id = b.beach_id AND rs.athlete_id = ee.athlete_id AND bd.board_id = rs.board_id
    GROUP BY b.beach_id, b.beach_name, ee.event_id, ee.event_name
    ORDER BY sponsor_investment DESC;
END$$
DELIMITER ;

CALL compile(DATABASE());

