CREATE TABLE coaches (coach_id INTEGER PRIMARY KEY, coach_name TEXT NOT NULL, years_active INTEGER);

CREATE TABLE rinks (rink_id INTEGER PRIMARY KEY, rink_name TEXT NOT NULL, city TEXT);

CREATE TABLE teams (team_id INTEGER PRIMARY KEY, team_name TEXT NOT NULL,
    coach_id INTEGER REFERENCES coaches(coach_id), rink_id INTEGER REFERENCES rinks(rink_id));

CREATE TABLE skaters (skater_id INTEGER PRIMARY KEY, skater_name TEXT NOT NULL, age INTEGER,
    team_id INTEGER REFERENCES teams(team_id));

CREATE TABLE costumes (costume_id INTEGER PRIMARY KEY, color TEXT, cost NUMERIC(10,2));

CREATE TABLE routines (routine_id INTEGER PRIMARY KEY, routine_title TEXT NOT NULL,
    team_id INTEGER REFERENCES teams(team_id), costume_id INTEGER REFERENCES costumes(costume_id));

CREATE TABLE competitions (competition_id INTEGER PRIMARY KEY, event_name TEXT NOT NULL,
    routine_id INTEGER REFERENCES routines(routine_id), medal TEXT, score NUMERIC(5,2));

CREATE VIEW medal_results AS
    SELECT comp.competition_id, comp.event_name, comp.medal, comp.score,
           r.routine_id, r.routine_title, r.costume_id,
           t.team_id, t.team_name, t.coach_id, t.rink_id
    FROM competitions AS comp
    JOIN routines AS r ON r.routine_id = comp.routine_id
    JOIN teams AS t ON t.team_id = r.team_id;

CREATE FUNCTION coach_age_profile()
RETURNS TABLE (coach TEXT, team TEXT, average_age NUMERIC) AS $$
    SELECT c.coach_name, t.team_name, ROUND(AVG(s.age), 2)
    FROM coaches AS c
    JOIN teams AS t ON t.coach_id = c.coach_id
    JOIN skaters AS s ON s.team_id = t.team_id
    GROUP BY c.coach_name, t.team_name
    ORDER BY c.coach_name, 3 DESC;
$$ LANGUAGE sql;

CREATE FUNCTION medal_costume_palette()
RETURNS TABLE (color TEXT, routine TEXT, team TEXT, medal TEXT) AS $$
    SELECT cs.color, mr.routine_title, mr.team_name, mr.medal
    FROM medal_results AS mr
    JOIN costumes AS cs ON cs.costume_id = mr.costume_id
    WHERE mr.medal IS NOT NULL
    ORDER BY mr.medal, cs.color;
$$ LANGUAGE sql;

CREATE FUNCTION gold_medal_rinks()
RETURNS TABLE (rink TEXT, city TEXT, skater TEXT, event TEXT) AS $$
    SELECT DISTINCT ri.rink_name, ri.city, s.skater_name, mr.event_name
    FROM medal_results AS mr
    JOIN rinks AS ri ON ri.rink_id = mr.rink_id
    JOIN skaters AS s ON s.team_id = mr.team_id
    WHERE mr.medal = 'gold'
    ORDER BY 1, 3;
$$ LANGUAGE sql;

CREATE FUNCTION costume_value_effect()
RETURNS TABLE (coach TEXT, average_cost NUMERIC, average_score NUMERIC, cost_score_corr NUMERIC) AS $$
    SELECT c.coach_name,
           ROUND(AVG(cs.cost), 2),
           ROUND(AVG(mr.score), 2),
           ROUND(CORR(cs.cost, mr.score)::NUMERIC, 3)
    FROM medal_results AS mr
    JOIN coaches AS c ON c.coach_id = mr.coach_id
    JOIN costumes AS cs ON cs.costume_id = mr.costume_id
    GROUP BY c.coach_name
    HAVING COUNT(mr.competition_id) > 1
    ORDER BY 4 DESC NULLS LAST;
$$ LANGUAGE sql;

CREATE FUNCTION evaluate(database TEXT)
RETURNS TABLE (coach_ages JSONB, medal_colors JSONB, gold_rinks JSONB, cost_scores JSONB) AS $$
BEGIN
    IF database <> current_database() THEN
        RAISE EXCEPTION 'evaluate(): skating data is not hosted in %', database;
    END IF;

    RETURN QUERY
    SELECT COALESCE((SELECT JSONB_AGG(TO_JSONB(a)) FROM coach_age_profile() AS a), '[]'::JSONB),
           COALESCE((SELECT JSONB_AGG(TO_JSONB(p)) FROM medal_costume_palette() AS p), '[]'::JSONB),
           COALESCE((SELECT JSONB_AGG(TO_JSONB(g)) FROM gold_medal_rinks() AS g), '[]'::JSONB),
           COALESCE((SELECT JSONB_AGG(TO_JSONB(v)) FROM costume_value_effect() AS v), '[]'::JSONB);
END;
$$ LANGUAGE plpgsql;

SELECT coach_ages, medal_colors, gold_rinks, cost_scores
FROM evaluate(current_database());

