DROP VIEW IF EXISTS survey_credit_list;
DROP VIEW IF EXISTS survey_permitted_clashes;
DROP VIEW IF EXISTS survey_cover_gear;
DROP VIEW IF EXISTS survey_trespass_warnings;
DROP VIEW IF EXISTS explorer_warning_totals;

CREATE VIEW explorer_warning_totals AS
SELECT e.explorer_id,
       COUNT(i.incident_id) AS total_warnings
FROM incidents AS i
JOIN explorers AS e ON e.explorer_id = i.explorer_id
WHERE i.incident_type = 'trespassing warning'
GROUP BY e.explorer_id;

CREATE VIEW survey_trespass_warnings AS
SELECT e.explorer_name,
       s.site_name,
       COUNT(i.incident_id) AS warnings_at_site,
       t.total_warnings
FROM incidents AS i
JOIN sites AS s ON s.site_id = i.site_id
JOIN explorers AS e ON e.explorer_id = i.explorer_id
JOIN explorer_warning_totals AS t ON t.explorer_id = e.explorer_id
WHERE i.incident_type = 'trespassing warning'
GROUP BY e.explorer_name, s.site_name, t.total_warnings
ORDER BY t.total_warnings DESC, e.explorer_name, warnings_at_site DESC;

CREATE VIEW survey_cover_gear AS
SELECT p.publication_id,
       p.magazine,
       e.explorer_name,
       c.model AS camera_model,
       l.lens_name
FROM publications AS p
JOIN explorers AS e ON e.explorer_id = p.explorer_id
JOIN cameras AS c ON c.camera_id = p.camera_id
JOIN lenses AS l ON l.lens_id = p.lens_id
WHERE p.is_cover
ORDER BY p.magazine, p.publication_id;

CREATE VIEW survey_permitted_clashes AS
SELECT pm.permit_id,
       e.explorer_name,
       s.site_name,
       i.incident_date,
       i.incident_type
FROM permits AS pm
JOIN sites AS s ON s.site_id = pm.site_id
JOIN explorers AS e ON e.explorer_id = pm.explorer_id
JOIN incidents AS i ON i.site_id = pm.site_id AND i.explorer_id = pm.explorer_id
WHERE i.incident_date BETWEEN pm.issue_date AND pm.valid_until
ORDER BY i.incident_date, pm.permit_id;

CREATE VIEW survey_credit_list AS
SELECT p.publication_id,
       p.magazine,
       e.explorer_name,
       s.site_name,
       s.city,
       c.model AS camera_model,
       l.lens_name
FROM publications AS p
JOIN explorers AS e ON e.explorer_id = p.explorer_id
JOIN sites AS s ON s.site_id = p.site_id
JOIN cameras AS c ON c.camera_id = p.camera_id
JOIN lenses AS l ON l.lens_id = p.lens_id
ORDER BY e.explorer_name, p.publication_id;

CREATE OR REPLACE FUNCTION survey(database TEXT)
RETURNS SETOF REFCURSOR AS $$
DECLARE
    warnings REFCURSOR := 'survey_warnings';
    cover    REFCURSOR := 'survey_cover';
    clashes  REFCURSOR := 'survey_clashes';
    credits  REFCURSOR := 'survey_credits';
BEGIN
    EXECUTE format('SET LOCAL search_path TO %I', database);
    OPEN warnings FOR SELECT * FROM survey_trespass_warnings;
    RETURN NEXT warnings;
    OPEN cover FOR SELECT * FROM survey_cover_gear;
    RETURN NEXT cover;
    OPEN clashes FOR SELECT * FROM survey_permitted_clashes;
    RETURN NEXT clashes;
    OPEN credits FOR SELECT * FROM survey_credit_list;
    RETURN NEXT credits;
END;
$$ LANGUAGE plpgsql;

BEGIN;
SELECT survey('urbex');
FETCH ALL FROM survey_warnings;
FETCH ALL FROM survey_cover;
FETCH ALL FROM survey_clashes;
FETCH ALL FROM survey_credits;
COMMIT;

