CREATE OR REPLACE FUNCTION event_roster(p_event text)
RETURNS TABLE (jack_name text, sponsor_name text, brand text, saw_model text) AS $$
    SELECT DISTINCT l.jack_name, sp.sponsor_name, a.brand, s.model
    FROM lumberjacks AS l
    JOIN sponsors AS sp ON sp.sponsor_id = l.sponsor_id
    JOIN axes AS a ON a.jack_id = l.jack_id
    JOIN saws AS s ON s.jack_id = l.jack_id
    JOIN timers AS t ON t.jack_id = l.jack_id
    JOIN stages AS g ON g.stage_id = t.stage_id
    WHERE g.event_name = p_event
    ORDER BY sp.sponsor_name, l.jack_name;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION axe_brand_oak_success(p_event text)
RETURNS TABLE (brand text, oak_blocks bigint, avg_seconds numeric, best_seconds numeric) AS $$
    SELECT a.brand,
           COUNT(DISTINCT b.block_id),
           ROUND(AVG(t.seconds), 2),
           MIN(t.seconds)
    FROM axes AS a
    JOIN lumberjacks AS l ON l.jack_id = a.jack_id
    JOIN timers AS t ON t.jack_id = l.jack_id AND t.tool_id = a.axe_id
    JOIN blocks AS b ON b.block_id = t.block_id
    JOIN stages AS g ON g.stage_id = t.stage_id
    WHERE t.tool_type = 'axe'
      AND b.wood_type = 'oak'
      AND b.hardness = 'hard'
      AND g.event_name = p_event
    GROUP BY a.brand
    ORDER BY ROUND(AVG(t.seconds), 2) ASC, COUNT(DISTINCT b.block_id) DESC;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION fastest_final_saw_times(p_event text)
RETURNS TABLE (stage_name text, jack_name text, saw_model text, best_seconds numeric) AS $$
    SELECT g.stage_name, l.jack_name, s.model, MIN(t.seconds)
    FROM timers AS t
    JOIN stages AS g ON g.stage_id = t.stage_id
    JOIN lumberjacks AS l ON l.jack_id = t.jack_id
    JOIN saws AS s ON s.saw_id = t.tool_id AND s.jack_id = l.jack_id
    WHERE t.tool_type = 'saw'
      AND g.is_final
      AND g.event_name = p_event
    GROUP BY g.stage_name, l.jack_name, s.model
    ORDER BY MIN(t.seconds) ASC;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION sponsor_block_payouts(p_event text)
RETURNS TABLE (sponsor_name text, jacks bigint, blocks_chopped bigint, payout numeric) AS $$
    SELECT sp.sponsor_name,
           COUNT(DISTINCT l.jack_id),
           COUNT(DISTINCT b.block_id),
           ROUND(COUNT(DISTINCT b.block_id) * sp.rate_per_block, 2)
    FROM sponsors AS sp
    JOIN lumberjacks AS l ON l.sponsor_id = sp.sponsor_id
    JOIN timers AS t ON t.jack_id = l.jack_id
    JOIN stages AS g ON g.stage_id = t.stage_id
    JOIN blocks AS b ON b.block_id = t.block_id
    WHERE g.event_name = p_event
    GROUP BY sp.sponsor_name, sp.rate_per_block
    ORDER BY 4 DESC;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION tool_switch_efficiency(p_event text)
RETURNS TABLE (jack_name text, brand text, saw_model text,
               axe_avg numeric, saw_avg numeric, axe_to_saw_ratio numeric) AS $$
    SELECT l.jack_name, a.brand, s.model,
           ROUND(AVG(CASE WHEN t.tool_type = 'axe' THEN t.seconds END), 2),
           ROUND(AVG(CASE WHEN t.tool_type = 'saw' THEN t.seconds END), 2),
           ROUND(AVG(CASE WHEN t.tool_type = 'axe' THEN t.seconds END)
               / NULLIF(AVG(CASE WHEN t.tool_type = 'saw' THEN t.seconds END), 0), 3)
    FROM saws AS s
    JOIN lumberjacks AS l ON l.jack_id = s.jack_id
    JOIN axes AS a ON a.jack_id = l.jack_id
    JOIN timers AS t ON t.jack_id = l.jack_id
    JOIN blocks AS b ON b.block_id = t.block_id
    JOIN stages AS g ON g.stage_id = t.stage_id
    WHERE b.standardized
      AND g.event_name = p_event
      AND ((t.tool_type = 'axe' AND t.tool_id = a.axe_id)
           OR (t.tool_type = 'saw' AND t.tool_id = s.saw_id))
    GROUP BY l.jack_name, a.brand, s.model
    HAVING COUNT(DISTINCT t.tool_type) = 2
    ORDER BY 6 ASC;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION chop(database text) RETURNS SETOF refcursor AS $$
DECLARE
    entrants integer;
    oak_cur refcursor := 'oak_brand_results';
    saw_cur refcursor := 'final_saw_results';
    pay_cur refcursor := 'sponsor_payout_results';
    eff_cur refcursor := 'tool_switch_results';
BEGIN
    SELECT COUNT(*) INTO entrants FROM event_roster(database);
    IF entrants = 0 THEN
        RAISE EXCEPTION 'no timed lumberjacks registered for event %', database;
    END IF;
    OPEN oak_cur FOR SELECT * FROM axe_brand_oak_success(database);
    RETURN NEXT oak_cur;
    OPEN saw_cur FOR SELECT * FROM fastest_final_saw_times(database);
    RETURN NEXT saw_cur;
    OPEN pay_cur FOR SELECT * FROM sponsor_block_payouts(database);
    RETURN NEXT pay_cur;
    OPEN eff_cur FOR SELECT * FROM tool_switch_efficiency(database);
    RETURN NEXT eff_cur;
END;
$$ LANGUAGE plpgsql;

BEGIN;
SELECT chop('Timbersports World Final');
FETCH ALL FROM oak_brand_results;
FETCH ALL FROM final_saw_results;
FETCH ALL FROM sponsor_payout_results;
FETCH ALL FROM tool_switch_results;
COMMIT;

