CREATE TABLE programs (program_id int PRIMARY KEY, title text NOT NULL);
CREATE TABLE hosts (host_id int PRIMARY KEY, host_name text NOT NULL);
CREATE TABLE program_hosts (program_id int, host_id int, is_current boolean NOT NULL);
CREATE TABLE episodes (episode_id int PRIMARY KEY, program_id int, release_date date NOT NULL);
CREATE TABLE sponsors (sponsor_id int PRIMARY KEY, sponsor_name text NOT NULL);
CREATE TABLE contracts (contract_id int PRIMARY KEY, sponsor_id int, rate_per_read numeric(10,2) NOT NULL);
CREATE TABLE ad_reads (read_id int PRIMARY KEY, episode_id int, sponsor_id int, contract_id int);
CREATE TABLE regions (region_id int PRIMARY KEY, region_name text NOT NULL);
CREATE TABLE platforms (platform_id int PRIMARY KEY, platform_name text NOT NULL);
CREATE TABLE listeners (listener_id int PRIMARY KEY, age_bracket text, region_id int, platform_id int);
CREATE TABLE plays (play_id int PRIMARY KEY, episode_id int, listener_id int);

CREATE OR REPLACE FUNCTION program_age_profile(p_program_id integer) RETURNS jsonb AS $$
    SELECT COALESCE(jsonb_object_agg(age_bracket, listener_total), '{}'::jsonb)
      FROM (SELECT COALESCE(l.age_bracket, 'unknown') AS age_bracket,
                   COUNT(DISTINCT l.listener_id) AS listener_total
              FROM episodes AS e
              JOIN plays AS pl ON pl.episode_id = e.episode_id
              JOIN listeners AS l ON l.listener_id = pl.listener_id
             WHERE e.program_id = p_program_id
             GROUP BY 1) AS profile;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION network_listener_total() RETURNS bigint AS $$
    SELECT COUNT(DISTINCT pl.listener_id)
      FROM episodes AS e
      JOIN plays AS pl ON pl.episode_id = e.episode_id
     WHERE EXTRACT(YEAR FROM e.release_date) = EXTRACT(YEAR FROM CURRENT_DATE);
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION mismatched_read_count() RETURNS bigint AS $$
    SELECT COUNT(*)
      FROM ad_reads AS ar
      JOIN contracts AS c ON c.contract_id = ar.contract_id
     WHERE c.sponsor_id <> ar.sponsor_id;
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION "analyze"(threshold integer) RETURNS jsonb AS $$
DECLARE
    net bigint := network_listener_total();
    top_programs jsonb;
    revenue_totals jsonb;
    region_counts jsonb;
BEGIN
    SELECT jsonb_agg(jsonb_build_object('program', title, 'host', host_name,
                                        'listeners', listener_total, 'sponsors', sponsor_total,
                                        'share_pct', ROUND(100.0 * listener_total / NULLIF(net, 0), 2),
                                        'age_profile', program_age_profile(program_id))
                     ORDER BY listener_total DESC)
      INTO top_programs
      FROM (SELECT p.program_id, p.title, h.host_name,
                   COUNT(DISTINCT l.listener_id) AS listener_total,
                   COUNT(DISTINCT s.sponsor_id) AS sponsor_total
              FROM programs AS p
              JOIN program_hosts AS ph ON ph.program_id = p.program_id
              JOIN hosts AS h ON h.host_id = ph.host_id
              JOIN episodes AS e ON e.program_id = p.program_id
              JOIN ad_reads AS ar ON ar.episode_id = e.episode_id
              JOIN sponsors AS s ON s.sponsor_id = ar.sponsor_id
              JOIN plays AS pl ON pl.episode_id = e.episode_id
              JOIN listeners AS l ON l.listener_id = pl.listener_id
             WHERE ph.is_current
               AND EXTRACT(YEAR FROM e.release_date) = EXTRACT(YEAR FROM CURRENT_DATE)
             GROUP BY p.program_id, p.title, h.host_name
            HAVING COUNT(DISTINCT l.listener_id) > threshold) AS ranked;

    SELECT jsonb_agg(jsonb_build_object('program', title, 'sponsor', sponsor_name,
                                        'reads', read_count, 'revenue', gross)
                     ORDER BY gross DESC)
      INTO revenue_totals
      FROM (SELECT p.title, s.sponsor_name,
                   COUNT(ar.read_id) AS read_count,
                   SUM(c.rate_per_read) AS gross
              FROM ad_reads AS ar
              JOIN episodes AS e ON e.episode_id = ar.episode_id
              JOIN sponsors AS s ON s.sponsor_id = ar.sponsor_id
              JOIN contracts AS c ON c.contract_id = ar.contract_id AND c.sponsor_id = s.sponsor_id
              JOIN programs AS p ON p.program_id = e.program_id
             GROUP BY p.program_id, p.title, s.sponsor_name) AS billed;

    SELECT jsonb_agg(jsonb_build_object('program', p.title, 'region', r.region_name,
                                        'platform', pf.platform_name,
                                        'listeners', COUNT(DISTINCT l.listener_id))
                     ORDER BY p.title, r.region_name, pf.platform_name)
      INTO region_counts
      FROM programs AS p
      JOIN episodes AS e ON e.program_id = p.program_id
      JOIN plays AS pl ON pl.episode_id = e.episode_id
      JOIN listeners AS l ON l.listener_id = pl.listener_id
      JOIN platforms AS pf ON pf.platform_id = l.platform_id
      JOIN regions AS r ON r.region_id = l.region_id
     GROUP BY p.program_id, p.title, r.region_name, pf.platform_name;

    RETURN jsonb_build_object('top_programs', COALESCE(top_programs, '[]'::jsonb),
                              'revenue_totals', COALESCE(revenue_totals, '[]'::jsonb),
                              'region_counts', COALESCE(region_counts, '[]'::jsonb),
                              'unbilled_reads', mismatched_read_count());
END;
$$ LANGUAGE plpgsql;

SELECT "analyze"(10000) AS network_summary;

CREATE TABLE trucks (truck_id INT PRIMARY KEY, plate TEXT, depot_id INT);
CREATE TABLE drivers (driver_id INT PRIMARY KEY, full_name TEXT, truck_id INT);
CREATE TABLE zones (zone_id INT PRIMARY KEY, zone_name TEXT);
CREATE TABLE segments (segment_id INT PRIMARY KEY, street_name TEXT, zone_id INT);
CREATE TABLE clearings (clearing_id INT PRIMARY KEY, truck_id INT, segment_id INT, season TEXT, length_km NUMERIC);
CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, supplier_name TEXT);
CREATE TABLE depots (depot_id INT PRIMARY KEY, depot_name TEXT, supplier_id INT);
CREATE TABLE manifests (manifest_id INT PRIMARY KEY, depot_id INT, supplier_id INT, season TEXT, tons_delivered NUMERIC);
CREATE TABLE restocks (restock_id INT PRIMARY KEY, truck_id INT, depot_id INT, season TEXT, tons NUMERIC);
CREATE TABLE maintenance (log_id INT PRIMARY KEY, truck_id INT, season TEXT, cost NUMERIC, hours_down NUMERIC);
CREATE TABLE complaints (complaint_id INT PRIMARY KEY, zone_id INT, season TEXT, resolved BOOLEAN);
CREATE TABLE tickets (ticket_id INT PRIMARY KEY, complaint_id INT, truck_id INT, response_min NUMERIC);

CREATE VIEW cleared_segments AS
SELECT c.season, c.truck_id, c.segment_id, c.length_km, s.zone_id, z.zone_name FROM clearings c
JOIN segments s ON s.segment_id = c.segment_id
JOIN zones z ON z.zone_id = s.zone_id;
CREATE VIEW driver_fleet AS
SELECT d.driver_id, d.full_name, t.truck_id, t.plate, t.depot_id FROM drivers d
JOIN trucks t ON t.truck_id = d.truck_id;
CREATE VIEW restock_ledger AS
SELECT r.season, r.truck_id, r.depot_id, r.tons, dp.depot_name FROM restocks r
JOIN depots dp ON dp.depot_id = r.depot_id;
CREATE VIEW dispatch_response AS
SELECT cp.season, cp.zone_id, cp.resolved, tk.ticket_id, tk.response_min, tr.truck_id FROM complaints cp
JOIN tickets tk ON tk.complaint_id = cp.complaint_id
JOIN trucks tr ON tr.truck_id = tk.truck_id;
CREATE VIEW depot_supply AS
SELECT mf.season, mf.depot_id, mf.tons_delivered, dp.depot_name, sp.supplier_name FROM manifests mf
JOIN depots dp ON dp.depot_id = mf.depot_id
JOIN suppliers sp ON sp.supplier_id = mf.supplier_id;

CREATE OR REPLACE FUNCTION evaluate(p_season TEXT,
    OUT driver_stats REFCURSOR, OUT zone_coverage REFCURSOR, OUT salt_usage REFCURSOR)
LANGUAGE plpgsql AS $$
BEGIN
  driver_stats := 'driver_stats';
  OPEN driver_stats FOR
  WITH cleared AS (
      SELECT truck_id, COUNT(DISTINCT segment_id) AS segments, SUM(length_km) AS km
      FROM cleared_segments WHERE season = p_season GROUP BY truck_id
  )
  SELECT df.driver_id, df.full_name, df.plate, cl.segments, cl.km, rs.stops AS depot_stops,
         rs.tons AS salt_tons, dt.hours AS downtime_hours, dt.cost AS repair_cost,
         ROUND(cl.km / (dt.hours + 1), 2) AS efficiency_index
  FROM driver_fleet df
  JOIN cleared cl ON cl.truck_id = df.truck_id
  JOIN LATERAL (SELECT COUNT(*) AS stops, COALESCE(SUM(tons), 0) AS tons FROM restock_ledger r WHERE r.season = p_season AND r.truck_id = df.truck_id) rs ON TRUE
  JOIN LATERAL (SELECT COALESCE(SUM(hours_down), 0) AS hours, COALESCE(SUM(cost), 0) AS cost FROM maintenance m WHERE m.season = p_season AND m.truck_id = df.truck_id) dt ON TRUE
  ORDER BY cl.km DESC;

  zone_coverage := 'zone_coverage';
  OPEN zone_coverage FOR
  SELECT z.zone_id, z.zone_name, cv.total_segments, cv.done AS cleared_segments,
         ROUND(100.0 * cv.done / NULLIF(cv.total_segments, 0), 1) AS coverage_pct,
         rp.tickets AS dispatch_tickets, rp.resolved, ROUND(rp.avg_response, 1) AS avg_response_min,
         rp.trucks AS responding_trucks
  FROM zones z
  JOIN LATERAL (SELECT COUNT(*) AS total_segments, COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM cleared_segments cs WHERE cs.segment_id = s.segment_id AND cs.season = p_season)) AS done FROM segments s WHERE s.zone_id = z.zone_id) cv ON TRUE
  JOIN LATERAL (SELECT COUNT(ticket_id) AS tickets, COALESCE(AVG(response_min), 0) AS avg_response,
                       COUNT(DISTINCT truck_id) AS trucks, COUNT(*) FILTER (WHERE resolved) AS resolved
                FROM dispatch_response dr WHERE dr.season = p_season AND dr.zone_id = z.zone_id) rp ON TRUE
  ORDER BY coverage_pct;

  salt_usage := 'salt_usage';
  OPEN salt_usage FOR
  WITH delivered AS (
      SELECT depot_id, depot_name, supplier_name, COUNT(*) AS manifests, SUM(tons_delivered) AS tons_in
      FROM depot_supply WHERE season = p_season GROUP BY depot_id, depot_name, supplier_name
  )
  SELECT dl.depot_id, dl.depot_name, dl.supplier_name, dl.manifests, dl.tons_in,
         pk.tons_out, pk.trucks AS trucks_served, dl.tons_in - pk.tons_out AS tons_remaining
  FROM delivered dl
  JOIN LATERAL (SELECT COALESCE(SUM(tons), 0) AS tons_out, COUNT(DISTINCT truck_id) AS trucks FROM restock_ledger r WHERE r.season = p_season AND r.depot_id = dl.depot_id) pk ON TRUE
  ORDER BY pk.tons_out DESC;
END;
$$;

BEGIN;
SELECT evaluate('winter twenty twenty three');
FETCH ALL FROM driver_stats;
FETCH ALL FROM zone_coverage;
FETCH ALL FROM salt_usage;
COMMIT;

