CREATE TABLE air_bases (base_id INTEGER PRIMARY KEY, base_name TEXT NOT NULL, region TEXT NOT NULL);
CREATE TABLE aircraft (aircraft_id INTEGER PRIMARY KEY, base_id INTEGER REFERENCES air_bases(base_id), tail_number TEXT NOT NULL, jump_seats INTEGER NOT NULL, status TEXT NOT NULL);
CREATE TABLE smokejumpers (jumper_id INTEGER PRIMARY KEY, base_id INTEGER REFERENCES air_bases(base_id), full_name TEXT NOT NULL, jump_rating TEXT NOT NULL);
CREATE TABLE equipment_caches (cache_id INTEGER PRIMARY KEY, jumper_id INTEGER REFERENCES smokejumpers(jumper_id), cache_type TEXT NOT NULL, packed_on DATE NOT NULL);
CREATE TABLE medical_evals (eval_id INTEGER PRIMARY KEY, jumper_id INTEGER REFERENCES smokejumpers(jumper_id), eval_date DATE NOT NULL, cleared BOOLEAN NOT NULL);
CREATE TABLE wildfires (fire_id INTEGER PRIMARY KEY, fire_name TEXT NOT NULL, region TEXT NOT NULL, status TEXT NOT NULL, acreage NUMERIC NOT NULL);
CREATE TABLE dispatch_orders (order_id INTEGER PRIMARY KEY, fire_id INTEGER REFERENCES wildfires(fire_id), aircraft_id INTEGER REFERENCES aircraft(aircraft_id), issued_at TIMESTAMP NOT NULL);
CREATE TABLE drop_zones (zone_id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES dispatch_orders(order_id), zone_name TEXT NOT NULL, terrain TEXT NOT NULL);
CREATE TABLE deployments (deployment_id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES dispatch_orders(order_id), jumper_id INTEGER REFERENCES smokejumpers(jumper_id), jumped_at TIMESTAMP NOT NULL);
CREATE TABLE weather_stations (station_id INTEGER PRIMARY KEY, station_name TEXT NOT NULL, region TEXT NOT NULL);
CREATE TABLE fire_station_proximity (fire_id INTEGER REFERENCES wildfires(fire_id), station_id INTEGER REFERENCES weather_stations(station_id), distance_km NUMERIC NOT NULL, PRIMARY KEY (fire_id, station_id));
CREATE TABLE wind_logs (log_id INTEGER PRIMARY KEY, station_id INTEGER REFERENCES weather_stations(station_id), logged_at TIMESTAMP NOT NULL, wind_speed_kph NUMERIC NOT NULL, gust_kph NUMERIC NOT NULL);
CREATE TABLE fire_perimeters (perimeter_id INTEGER PRIMARY KEY, fire_id INTEGER REFERENCES wildfires(fire_id), mapped_on DATE NOT NULL, perimeter_acres NUMERIC NOT NULL);

CREATE FUNCTION available_aircraft(p_region TEXT)
RETURNS TABLE (base_id INTEGER, base_name TEXT, tail_number TEXT, jump_seats INTEGER) AS $$
    SELECT b.base_id, b.base_name, a.tail_number, a.jump_seats
      FROM air_bases AS b, aircraft AS a
     WHERE a.base_id = b.base_id
       AND lower(trim(b.region)) = lower(trim(p_region))
       AND a.status = 'available';
$$ LANGUAGE sql STABLE;

CREATE FUNCTION cleared_jumpers(p_region TEXT)
RETURNS TABLE (base_id INTEGER, jumper_id INTEGER, full_name TEXT, last_eval DATE) AS $$
    SELECT b.base_id, s.jumper_id, s.full_name, MAX(m.eval_date)
      FROM air_bases AS b, smokejumpers AS s, medical_evals AS m
     WHERE s.base_id = b.base_id
       AND m.jumper_id = s.jumper_id
       AND lower(trim(b.region)) = lower(trim(p_region))
       AND m.cleared
     GROUP BY b.base_id, s.jumper_id, s.full_name;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION squad_readiness(p_region TEXT)
RETURNS TABLE (base_name TEXT, tail_number TEXT, full_name TEXT,
               cache_type TEXT, last_eval DATE, seats INTEGER) AS $$
    SELECT ac.base_name, ac.tail_number, j.full_name, c.cache_type, j.last_eval, ac.jump_seats
      FROM available_aircraft(p_region) AS ac, cleared_jumpers(p_region) AS j, equipment_caches AS c
     WHERE j.base_id = ac.base_id
       AND c.jumper_id = j.jumper_id
     ORDER BY ac.base_name, j.full_name, c.cache_type;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION weather_risks(p_region TEXT)
RETURNS TABLE (fire_name TEXT, station_name TEXT, distance_km NUMERIC,
               peak_gust NUMERIC, mapped_on DATE, perimeter_acres NUMERIC) AS $$
    SELECT f.fire_name, w.station_name, p.distance_km,
           MAX(l.gust_kph), fp.mapped_on, fp.perimeter_acres
      FROM wildfires AS f, fire_station_proximity AS p, weather_stations AS w, wind_logs AS l, fire_perimeters AS fp
     WHERE p.fire_id = f.fire_id
       AND w.station_id = p.station_id
       AND l.station_id = w.station_id
       AND fp.fire_id = f.fire_id
       AND lower(trim(f.region)) = lower(trim(p_region))
       AND p.distance_km <= 50
       AND l.logged_at >= now() - INTERVAL '24 hours'
     GROUP BY f.fire_name, w.station_name, p.distance_km, fp.mapped_on, fp.perimeter_acres
    HAVING MAX(l.wind_speed_kph) >= 20
     ORDER BY 4 DESC;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION active_deployments(p_region TEXT)
RETURNS TABLE (fire_name TEXT, tail_number TEXT, zone_name TEXT,
               terrain TEXT, jumper_name TEXT, jumped_at TIMESTAMP) AS $$
    SELECT f.fire_name, a.tail_number, z.zone_name, z.terrain, s.full_name, d.jumped_at
      FROM wildfires AS f, dispatch_orders AS o, aircraft AS a, drop_zones AS z, deployments AS d, smokejumpers AS s
     WHERE o.fire_id = f.fire_id
       AND a.aircraft_id = o.aircraft_id
       AND z.order_id = o.order_id
       AND d.order_id = o.order_id
       AND s.jumper_id = d.jumper_id
       AND lower(trim(f.region)) = lower(trim(p_region))
       AND f.status = 'active'
     ORDER BY f.fire_name, d.jumped_at;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION deploy(region TEXT) RETURNS SETOF refcursor AS $$
DECLARE
    roster refcursor := 'squad_readiness_cur';
    missions refcursor := 'active_deployments_cur';
    risks refcursor := 'weather_risks_cur';
BEGIN
    IF region IS NULL OR trim(region) = '' THEN
        RAISE EXCEPTION 'deploy() requires a region name';
    END IF;
    OPEN roster FOR SELECT * FROM squad_readiness(region);
    RETURN NEXT roster;
    OPEN missions FOR SELECT * FROM active_deployments(region);
    RETURN NEXT missions;
    OPEN risks FOR SELECT * FROM weather_risks(region);
    RETURN NEXT risks;
END;
$$ LANGUAGE plpgsql;

BEGIN;
SELECT * FROM deploy('pacific northwest');
FETCH ALL FROM squad_readiness_cur;
FETCH ALL FROM active_deployments_cur;
FETCH ALL FROM weather_risks_cur;
COMMIT;

