-- Environmental impact audit module for a recycling facility.

CREATE TABLE facilities (facility_id int PRIMARY KEY, name text);
CREATE TABLE routes (route_id int PRIMARY KEY, driver text, facility_id int);
CREATE TABLE bins (bin_id int PRIMARY KEY, route_id int, material text, gross_kg numeric);
CREATE TABLE workers (worker_id int PRIMARY KEY, full_name text, facility_id int);
CREATE TABLE batches (batch_id int PRIMARY KEY, bin_id int, worker_id int, processed_on date);
CREATE TABLE metals (metal_id int PRIMARY KEY, batch_id int, metal text, recovered_kg numeric);
CREATE TABLE contracts (contract_id int PRIMARY KEY, metal_id int, buyer text, price_per_kg numeric);
CREATE TABLE smelters (smelter_id int PRIMARY KEY, smelter_name text, country text);
CREATE TABLE manifests (manifest_id int PRIMARY KEY, contract_id int, smelter_id int, shipped_on date);
CREATE TABLE invoices (invoice_id int PRIMARY KEY, manifest_id int, amount_usd numeric, paid boolean);
CREATE TABLE ppe_logs (ppe_log_id int PRIMARY KEY, worker_id int, gear text, compliant boolean, logged_on date);
CREATE TABLE sensors (sensor_id int PRIMARY KEY, ppe_log_id int, hazard text, ppm numeric);
CREATE TABLE inspections (inspection_id int PRIMARY KEY, worker_id int, month date, score numeric);

CREATE VIEW facility_intake AS
    SELECT f.name AS facility, r.driver, b.bin_id
    FROM facilities AS f
    JOIN routes AS r ON r.facility_id = f.facility_id
    JOIN bins AS b ON b.route_id = r.route_id;

CREATE VIEW processed_metals AS
    SELECT i.facility, i.driver, w.full_name AS processor,
           m.metal_id, m.metal, m.recovered_kg
    FROM facility_intake AS i
    JOIN batches AS ba ON ba.bin_id = i.bin_id
    JOIN metals AS m ON m.batch_id = ba.batch_id
    JOIN workers AS w ON w.worker_id = ba.worker_id;

CREATE FUNCTION recovery_report(p_facility text)
RETURNS TABLE (metal text, driver text, processor text, recovered_kg numeric) AS $$
    SELECT pm.metal, pm.driver, pm.processor, SUM(pm.recovered_kg)
    FROM processed_metals AS pm
    WHERE lower(pm.facility) = lower(p_facility)
    GROUP BY pm.metal, pm.driver, pm.processor;
$$ LANGUAGE sql;

CREATE FUNCTION revenue_report(p_facility text)
RETURNS TABLE (buyer text, smelter_name text, revenue_usd numeric) AS $$
    SELECT c.buyer, s.smelter_name, SUM(iv.amount_usd)
    FROM processed_metals AS pm
    JOIN contracts AS c ON c.metal_id = pm.metal_id
    JOIN manifests AS mf ON mf.contract_id = c.contract_id
    JOIN smelters AS s ON s.smelter_id = mf.smelter_id
    JOIN invoices AS iv ON iv.manifest_id = mf.manifest_id
    WHERE lower(pm.facility) = lower(p_facility)
      AND iv.paid
    GROUP BY c.buyer, s.smelter_name;
$$ LANGUAGE sql;

CREATE VIEW ppe_exposure AS
    SELECT w.facility_id, w.worker_id, w.full_name, p.logged_on, p.compliant, s.ppm
    FROM workers AS w
    JOIN ppe_logs AS p ON p.worker_id = w.worker_id
    JOIN sensors AS s ON s.ppe_log_id = p.ppe_log_id;

CREATE FUNCTION safety_report(p_facility text)
RETURNS TABLE (full_name text, compliance_score numeric) AS $$
    SELECT e.full_name,
           ROUND(AVG(insp.score) * AVG(CASE WHEN e.compliant THEN 1.0 ELSE 0.5 END)
                 - AVG(e.ppm) / 10, 2)
    FROM facilities AS f
    JOIN ppe_exposure AS e ON e.facility_id = f.facility_id
    JOIN inspections AS insp ON insp.worker_id = e.worker_id
    WHERE lower(f.name) = lower(p_facility)
      AND date_trunc('month', e.logged_on) = date_trunc('month', insp.month)
    GROUP BY e.full_name;
$$ LANGUAGE sql;

CREATE FUNCTION audit(facility text)
RETURNS TABLE (report text, subject text, metric numeric) AS $$
    SELECT 'material recovery', metal || ' via ' || driver || ' / ' || processor, recovered_kg
    FROM recovery_report(facility)
    UNION ALL
    SELECT 'financial return', buyer || ' -> ' || smelter_name, revenue_usd
    FROM revenue_report(facility)
    UNION ALL
    SELECT 'safety compliance', full_name, compliance_score
    FROM safety_report(facility);
$$ LANGUAGE sql;

SELECT report, subject, metric
FROM audit('northside recycling center')
ORDER BY report, metric DESC, subject;

