CREATE TABLE Ranchers (rancher_id INTEGER PRIMARY KEY, ranch_name TEXT NOT NULL, county TEXT NOT NULL);
CREATE TABLE CattleLots (lot_id INTEGER PRIMARY KEY, rancher_id INTEGER NOT NULL REFERENCES Ranchers(rancher_id), head_count INTEGER NOT NULL, avg_weight_kg NUMERIC NOT NULL);
CREATE TABLE Auctioneers (auctioneer_id INTEGER PRIMARY KEY, auctioneer_name TEXT NOT NULL, license_no TEXT NOT NULL);
CREATE TABLE Buyers (buyer_id INTEGER PRIMARY KEY, company_name TEXT NOT NULL, market_segment TEXT NOT NULL);
CREATE TABLE ShippingCompanies (company_id INTEGER PRIMARY KEY, company_name TEXT NOT NULL, home_depot TEXT NOT NULL);
CREATE TABLE Trucks (truck_id INTEGER PRIMARY KEY, plate_no TEXT NOT NULL, company_id INTEGER NOT NULL REFERENCES ShippingCompanies(company_id), capacity_head INTEGER NOT NULL);
CREATE TABLE Sales (sale_id INTEGER PRIMARY KEY, lot_id INTEGER NOT NULL REFERENCES CattleLots(lot_id), auctioneer_id INTEGER NOT NULL REFERENCES Auctioneers(auctioneer_id), buyer_id INTEGER NOT NULL REFERENCES Buyers(buyer_id), truck_id INTEGER NOT NULL REFERENCES Trucks(truck_id), sale_month TEXT NOT NULL, price_per_head NUMERIC NOT NULL);
CREATE TABLE Inspectors (inspector_id INTEGER PRIMARY KEY, inspector_name TEXT NOT NULL, state_badge TEXT NOT NULL);
CREATE TABLE VetCertificates (certificate_id INTEGER PRIMARY KEY, lot_id INTEGER NOT NULL REFERENCES CattleLots(lot_id), inspector_id INTEGER NOT NULL REFERENCES Inspectors(inspector_id), issue_month TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE Vaccinations (vaccination_id INTEGER PRIMARY KEY, certificate_id INTEGER NOT NULL REFERENCES VetCertificates(certificate_id), vaccine_name TEXT NOT NULL, doses_given INTEGER NOT NULL);
CREATE TABLE QuarantinePens (pen_id INTEGER PRIMARY KEY, lot_id INTEGER NOT NULL REFERENCES CattleLots(lot_id), pen_code TEXT NOT NULL, days_held INTEGER NOT NULL);
CREATE TABLE WeighReceipts (receipt_id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES Sales(sale_id), station_name TEXT NOT NULL, gross_kg NUMERIC NOT NULL);
CREATE TABLE Abattoirs (abattoir_id INTEGER PRIMARY KEY, abattoir_name TEXT NOT NULL, region TEXT NOT NULL);
CREATE TABLE Deliveries (delivery_id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES Sales(sale_id), abattoir_id INTEGER NOT NULL REFERENCES Abattoirs(abattoir_id), arrival_day INTEGER NOT NULL);

CREATE VIEW lot_origin AS
SELECT L.lot_id, L.head_count, L.avg_weight_kg, R.ranch_name, R.county
FROM CattleLots AS L
JOIN Ranchers AS R ON R.rancher_id = L.rancher_id;

CREATE VIEW truck_fleet AS
SELECT T.truck_id, T.plate_no, T.capacity_head, SC.company_name AS carrier, SC.home_depot
FROM Trucks AS T
JOIN ShippingCompanies AS SC ON SC.company_id = T.company_id;

CREATE VIEW certificate_health AS
SELECT C.certificate_id, C.lot_id, C.issue_month, C.status, I.inspector_name,
       COALESCE((SELECT SUM(V.doses_given) FROM Vaccinations AS V
                 WHERE V.certificate_id = C.certificate_id), 0) AS doses_given
FROM VetCertificates AS C
JOIN Inspectors AS I ON I.inspector_id = C.inspector_id;

CREATE VIEW shipment_leg AS
SELECT S.sale_id, S.sale_month, S.truck_id, W.station_name, W.gross_kg,
       AB.abattoir_name, AB.region, D.arrival_day
FROM Sales AS S
JOIN WeighReceipts AS W ON W.sale_id = S.sale_id
JOIN Deliveries AS D ON D.sale_id = S.sale_id
JOIN Abattoirs AS AB ON AB.abattoir_id = D.abattoir_id;

CREATE VIEW sales_volume_report AS
SELECT O.ranch_name, A.auctioneer_name, B.company_name AS buyer_name, F.plate_no, S.sale_month,
       SUM(O.head_count) AS head_sold,
       SUM(O.head_count * S.price_per_head) AS gross_receipts
FROM Sales AS S
JOIN lot_origin AS O ON O.lot_id = S.lot_id
JOIN Auctioneers AS A ON A.auctioneer_id = S.auctioneer_id
JOIN Buyers AS B ON B.buyer_id = S.buyer_id
JOIN truck_fleet AS F ON F.truck_id = S.truck_id
GROUP BY O.ranch_name, A.auctioneer_name, B.company_name, F.plate_no, S.sale_month;

CREATE VIEW health_compliance_report AS
SELECT O.ranch_name, H.inspector_name, H.issue_month,
       COUNT(DISTINCT H.certificate_id) AS certificates,
       SUM(H.doses_given) AS total_doses,
       MAX(COALESCE((SELECT MAX(Q.days_held) FROM QuarantinePens AS Q
                     WHERE Q.lot_id = H.lot_id), 0)) AS longest_hold,
       ROUND(100.0 * SUM(CASE WHEN H.status = 'CLEARED' THEN 1 ELSE 0 END)
             / COUNT(H.certificate_id), 1) AS clearance_pct
FROM certificate_health AS H
JOIN lot_origin AS O ON O.lot_id = H.lot_id
GROUP BY O.ranch_name, H.inspector_name, H.issue_month;

CREATE VIEW transport_route_report AS
SELECT F.carrier, F.plate_no, G.station_name, G.abattoir_name, G.region, G.sale_month,
       SUM(G.gross_kg) AS hauled_kg,
       AVG(G.arrival_day) AS avg_arrival_day
FROM shipment_leg AS G
JOIN truck_fleet AS F ON F.truck_id = G.truck_id
GROUP BY F.carrier, F.plate_no, G.station_name, G.abattoir_name, G.region, G.sale_month;

CREATE PROCEDURE tally(IN month TEXT)
BEGIN
    SELECT ranch_name, auctioneer_name, buyer_name, plate_no, head_sold, gross_receipts
    FROM sales_volume_report
    WHERE LOWER(sale_month) = LOWER(month)
    ORDER BY gross_receipts DESC;

    SELECT ranch_name, inspector_name, certificates, total_doses, longest_hold, clearance_pct
    FROM health_compliance_report
    WHERE LOWER(issue_month) = LOWER(month)
    ORDER BY clearance_pct ASC, ranch_name;

    SELECT carrier, plate_no, station_name, abattoir_name, region, hauled_kg, avg_arrival_day
    FROM transport_route_report
    WHERE LOWER(sale_month) = LOWER(month)
    ORDER BY hauled_kg DESC;
END;

CALL tally('october');

