WHERE R.rancher_id = L.rancher_id;

CREATE VIEW truck_fleet AS
SELECT T.truck_id, T.plate_no, T.capacity_head, SC.company_name AS carrier, SC.home_depot
FROM Trucks AS T, ShippingCompanies AS SC
WHERE SC.company_id = T.company_id;

CREATE VIEW certificate_health AS
SELECT C.certificate_id, C.lot_id, C.issue_month, C.status, I.inspector_name,
       COALESCE((SELECT SUM(V.doses_given) FROM Vaccinations AS V
                 WHERE V.certificate_id = C.certificate_id), 0) AS doses_given
FROM VetCertificates AS C, Inspectors AS I
WHERE I.inspector_id = C.inspector_id;

CREATE VIEW shipment_leg AS
SELECT S.sale_id, S.sale_month, S.truck_id, W.station_name, W.gross_kg,
       AB.abattoir_name, AB.region, D.arrival_day
FROM Sales AS S, WeighReceipts AS W, Deliveries AS D, Abattoirs AS AB
WHERE W.sale_id = S.sale_id
AND D.sale_id = S.sale_id
AND AB.abattoir_id = D.abattoir_id;

CREATE VIEW sales_volume_report AS
SELECT O.ranch_name, A.auctioneer_name, B.company_name AS buyer_name, F.plate_no, S.sale_month,
       SUM(O.head_count) AS head_sold,
       SUM(O.head_count * S.price_per_head) AS gross_receipts
FROM Sales AS S, lot_origin AS O, Auctioneers AS A, Buyers AS B, truck_fleet AS F
WHERE O.lot_id = S.lot_id
AND A.auctioneer_id = S.auctioneer_id
AND B.buyer_id = S.buyer_id
AND F.truck_id = S.truck_id
GROUP BY O.ranch_name, A.auctioneer_name, B.company_name, F.plate_no, S.sale_month;

CREATE VIEW health_compliance_report AS
SELECT O.ranch_name, H.inspector_name, H.issue_month,
       COUNT(DISTINCT H.certificate_id) AS certificates,
       SUM(H.doses_given) AS total_doses,
       MAX(COALESCE((SELECT MAX(Q.days_held) FROM QuarantinePens AS Q
                     WHERE Q.lot_id = H.lot_id), 0)) AS longest_hold,
       ROUND(100.0 * SUM(CASE WHEN H.status = 'CLEARED' THEN 1 ELSE 0 END)
             / COUNT(H.certificate_id), 1) AS clearance_pct
FROM certificate_health AS H, lot_origin AS O
WHERE O.lot_id = H.lot_id
GROUP BY O.ranch_name, H.inspector_name, H.issue_month;

CREATE VIEW transport_route_report AS
SELECT F.carrier, F.plate_no, G.station_name, G.abattoir_name, G.region, G.sale_month,
       SUM(G.gross_kg) AS hauled_kg,
       AVG(G.arrival_day) AS avg_arrival_day
FROM shipment_leg AS G, truck_fleet AS F
WHERE F.truck_id = G.truck_id
GROUP BY F.carrier, F.plate_no, G.station_name, G.abattoir_name, G.region, G.sale_month;

CREATE PROCEDURE tally(IN month TEXT)
BEGIN
    SELECT ranch_name, auctioneer_name, buyer_name, plate_no, head_sold, gross_receipts
    FROM sales_volume_report
    WHERE LOWER(sale_month) = LOWER(month)
    ORDER BY gross_receipts DESC;

    SELECT ranch_name, inspector_name, certificates, total_doses, longest_hold, clearance_pct
    FROM health_compliance_report
    WHERE LOWER(issue_month) = LOWER(month)
    ORDER BY clearance_pct ASC, ranch_name;

    SELECT carrier, plate_no, station_name, abattoir_name, region, hauled_kg, avg_arrival_day
    FROM transport_route_report
    WHERE LOWER(sale_month) = LOWER(month)
    ORDER BY hauled_kg DESC;
END;

CALL tally('october');

