CREATE TABLE checkpoints (checkpoint_id INTEGER PRIMARY KEY, race_id INTEGER NOT NULL REFERENCES races, checkpoint_name TEXT NOT NULL);
CREATE TABLE rest_stops (rest_id INTEGER PRIMARY KEY, musher_id INTEGER NOT NULL REFERENCES mushers, checkpoint_id INTEGER NOT NULL REFERENCES checkpoints, rest_hours NUMERIC(5,2) NOT NULL);
CREATE TABLE stage_times (stage_id INTEGER PRIMARY KEY, musher_id INTEGER NOT NULL REFERENCES mushers, checkpoint_id INTEGER NOT NULL REFERENCES checkpoints, elapsed_minutes INTEGER NOT NULL);
CREATE TABLE weather (weather_id INTEGER PRIMARY KEY, checkpoint_id INTEGER NOT NULL REFERENCES checkpoints, wind_chill_c NUMERIC(5,1) NOT NULL, storm_level INTEGER NOT NULL);
CREATE TABLE veterinarians (vet_id INTEGER PRIMARY KEY, vet_name TEXT NOT NULL);
CREATE TABLE vet_exams (exam_id INTEGER PRIMARY KEY, dog_id INTEGER NOT NULL REFERENCES dogs, checkpoint_id INTEGER NOT NULL REFERENCES checkpoints, vet_id INTEGER NOT NULL REFERENCES veterinarians, exam_status TEXT NOT NULL);
CREATE TABLE supply_drops (drop_id INTEGER PRIMARY KEY, team_id INTEGER NOT NULL REFERENCES dog_teams, checkpoint_id INTEGER NOT NULL REFERENCES checkpoints, food_kg NUMERIC(6,2) NOT NULL);
CREATE TABLE volunteer_coordinators (coord_id INTEGER PRIMARY KEY, checkpoint_id INTEGER NOT NULL REFERENCES checkpoints, coord_name TEXT NOT NULL);
CREATE TABLE snowmobiles (sled_id INTEGER PRIMARY KEY, checkpoint_id INTEGER NOT NULL REFERENCES checkpoints, unit_code TEXT NOT NULL, seat_capacity INTEGER NOT NULL);
CREATE TABLE medical_tents (tent_id INTEGER PRIMARY KEY, checkpoint_id INTEGER NOT NULL REFERENCES checkpoints, supply_level INTEGER NOT NULL);

CREATE FUNCTION race_checkpoints(race TEXT) RETURNS TABLE (checkpoint_id INTEGER, checkpoint_name TEXT) AS $$
    SELECT c.checkpoint_id, c.checkpoint_name
    FROM checkpoints c
    JOIN races r ON r.race_id = c.race_id
    WHERE r.race_name = race;
$$ LANGUAGE SQL STABLE;

CREATE FUNCTION checkpoint_conditions(race TEXT) RETURNS TABLE (checkpoint_id INTEGER, checkpoint_name TEXT, wind_chill_c NUMERIC, storm_level INTEGER) AS $$
    SELECT rc.checkpoint_id, rc.checkpoint_name, w.wind_chill_c, w.storm_level
    FROM race_checkpoints(race) rc
    JOIN weather w ON w.checkpoint_id = rc.checkpoint_id;
$$ LANGUAGE SQL STABLE;

CREATE FUNCTION musher_standings(race TEXT) RETURNS TABLE (musher TEXT, team TEXT, race_minutes BIGINT, rest_hours NUMERIC, worst_chill NUMERIC, worst_storm INTEGER) AS $$
    SELECT m.musher_name, t.team_name, SUM(st.elapsed_minutes), SUM(rs.rest_hours),
           MIN(cc.wind_chill_c), MAX(cc.storm_level)
    FROM mushers m
    JOIN races r ON r.race_id = m.race_id
    JOIN dog_teams t ON t.musher_id = m.musher_id
    JOIN stage_times st ON st.musher_id = m.musher_id
    JOIN checkpoint_conditions(race) cc ON cc.checkpoint_id = st.checkpoint_id
    JOIN rest_stops rs ON rs.musher_id = m.musher_id AND rs.checkpoint_id = cc.checkpoint_id
    WHERE r.race_name = race
    GROUP BY m.musher_name, t.team_name
    ORDER BY SUM(st.elapsed_minutes);
$$ LANGUAGE SQL STABLE;

CREATE FUNCTION dog_welfare(race TEXT) RETURNS TABLE (dog TEXT, checkpoint TEXT, health_status TEXT, vet TEXT, food_kg NUMERIC) AS $$
    SELECT d.dog_name, rc.checkpoint_name, e.exam_status, v.vet_name, sd.food_kg
    FROM dogs d
    JOIN dog_teams t ON t.team_id = d.team_id
    JOIN mushers m ON m.musher_id = t.musher_id
    JOIN races r ON r.race_id = m.race_id
    JOIN vet_exams e ON e.dog_id = d.dog_id
    JOIN race_checkpoints(race) rc ON rc.checkpoint_id = e.checkpoint_id
    JOIN veterinarians v ON v.vet_id = e.vet_id
    JOIN supply_drops sd ON sd.team_id = t.team_id AND sd.checkpoint_id = rc.checkpoint_id
    WHERE r.race_name = race
    ORDER BY rc.checkpoint_name, d.dog_name;
$$ LANGUAGE SQL STABLE;

CREATE FUNCTION checkpoint_logistics(race TEXT) RETURNS TABLE (checkpoint TEXT, coordinator TEXT, evac_units BIGINT, evac_seats BIGINT, supply_level BIGINT) AS $$
    SELECT rc.checkpoint_name, vc.coord_name, sm.units, sm.seats, SUM(mt.supply_level)
    FROM race_checkpoints(race) rc
    JOIN volunteer_coordinators vc ON vc.checkpoint_id = rc.checkpoint_id
    JOIN (SELECT checkpoint_id, COUNT(*) AS units, SUM(seat_capacity) AS seats
          FROM snowmobiles GROUP BY checkpoint_id) sm ON sm.checkpoint_id = rc.checkpoint_id
    JOIN medical_tents mt ON mt.checkpoint_id = rc.checkpoint_id
    GROUP BY rc.checkpoint_name, vc.coord_name, sm.units, sm.seats
    ORDER BY rc.checkpoint_name;
$$ LANGUAGE SQL STABLE;

CREATE FUNCTION rank(race TEXT) RETURNS TABLE (metric TEXT, subject TEXT, detail TEXT) AS $$
    SELECT 'musher_time', s.musher || ' / ' || s.team, s.race_minutes || ' min, rest ' ||
           s.rest_hours || ' h, chill ' || s.worst_chill || ' C, storm ' || s.worst_storm
    FROM musher_standings(race) s
    UNION ALL
    SELECT 'dog_health', w.dog || ' @ ' || w.checkpoint,
           w.health_status || ' (vet ' || w.vet || '), food ' || w.food_kg || ' kg'
    FROM dog_welfare(race) w
    UNION ALL
    SELECT 'checkpoint_supply', l.checkpoint || ' / ' || l.coordinator, 'supply ' || l.supply_level ||
           ', ' || l.evac_units || ' snowmobiles, ' || l.evac_seats || ' seats'
    FROM checkpoint_logistics(race) l;
$$ LANGUAGE SQL STABLE;

SELECT metric, subject, detail FROM rank('northern iditarod')
ORDER BY metric, subject;

