CREATE TABLE mine_sites (site_id integer PRIMARY KEY, site_name text NOT NULL, county text NOT NULL, ore_type text);
CREATE TABLE hazmat_teams (team_id integer PRIMARY KEY, site_id integer REFERENCES mine_sites, team_name text, dispatched_on date);
CREATE TABLE soil_samples (sample_id integer PRIMARY KEY, site_id integer REFERENCES mine_sites, lead_ppm numeric, arsenic_ppm numeric);
CREATE TABLE engineering_firms (firm_id integer PRIMARY KEY, site_id integer REFERENCES mine_sites, firm_name text);
CREATE TABLE watersheds (watershed_id integer PRIMARY KEY, site_id integer REFERENCES mine_sites, watershed_name text);
CREATE TABLE funding_grants (grant_id integer PRIMARY KEY, firm_id integer REFERENCES engineering_firms, agency text, amount numeric);
CREATE TABLE budget_approvals (approval_id integer PRIMARY KEY, grant_id integer REFERENCES funding_grants, fiscal_year integer, approved_amount numeric);
CREATE TABLE impact_assessments (assessment_id integer PRIMARY KEY, firm_id integer REFERENCES engineering_firms, risk_rating text);
CREATE TABLE oversight_committees (committee_id integer PRIMARY KEY, assessment_id integer REFERENCES impact_assessments, committee_name text, region text);
CREATE TABLE fish_populations (population_id integer PRIMARY KEY, watershed_id integer REFERENCES watersheds, species text, released integer);
CREATE TABLE quality_buoys (buoy_id integer PRIMARY KEY, watershed_id integer REFERENCES watersheds, ph numeric, dissolved_oxygen numeric);
CREATE TABLE farms (farm_id integer PRIMARY KEY, watershed_id integer REFERENCES watersheds, farm_name text, irrigated_acres numeric);

CREATE VIEW site_contamination AS
    SELECT ms.site_id, ms.county, ms.site_name, ht.team_name, ss.lead_ppm, ss.arsenic_ppm
    FROM mine_sites AS ms
    JOIN hazmat_teams AS ht ON ht.site_id = ms.site_id
    JOIN soil_samples AS ss ON ss.site_id = ms.site_id;

CREATE VIEW firm_budgets AS
    SELECT ef.firm_id, ef.site_id, ef.firm_name, fg.agency, fg.amount, ba.fiscal_year, ba.approved_amount
    FROM engineering_firms AS ef
    JOIN funding_grants AS fg ON fg.firm_id = ef.firm_id
    JOIN budget_approvals AS ba ON ba.grant_id = fg.grant_id;

CREATE VIEW watershed_biology AS
    SELECT ws.watershed_id, ws.site_id, ws.watershed_name, fp.species, fp.released, qb.ph, qb.dissolved_oxygen
    FROM watersheds AS ws
    JOIN fish_populations AS fp ON fp.watershed_id = ws.watershed_id
    JOIN quality_buoys AS qb ON qb.watershed_id = ws.watershed_id;

CREATE FUNCTION site_hazards(county text)
RETURNS TABLE (site_name text, team_name text, lead_ppm numeric,
               arsenic_ppm numeric, firm_name text, watershed_name text) AS $$
    SELECT sc.site_name, sc.team_name, sc.lead_ppm, sc.arsenic_ppm, ef.firm_name, ws.watershed_name
    FROM site_contamination AS sc
    JOIN engineering_firms AS ef ON ef.site_id = sc.site_id
    JOIN watersheds AS ws ON ws.site_id = sc.site_id
    WHERE lower(sc.county) = lower($1)
    ORDER BY sc.lead_ppm DESC;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION funding_flow(county text)
RETURNS TABLE (firm_name text, agency text, amount numeric, fiscal_year integer,
               approved_amount numeric, risk_rating text, committee_name text, region text) AS $$
    SELECT fb.firm_name, fb.agency, fb.amount, fb.fiscal_year,
           fb.approved_amount, ia.risk_rating, oc.committee_name, oc.region
    FROM firm_budgets AS fb
    JOIN mine_sites AS ms ON ms.site_id = fb.site_id
    JOIN impact_assessments AS ia ON ia.firm_id = fb.firm_id
    JOIN oversight_committees AS oc ON oc.assessment_id = ia.assessment_id
    WHERE lower(ms.county) = lower($1)
    ORDER BY fb.fiscal_year, fb.approved_amount DESC;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION ecological_recovery(county text)
RETURNS TABLE (watershed_name text, species text, released integer, ph numeric,
               dissolved_oxygen numeric, farm_name text, irrigated_acres numeric) AS $$
    SELECT wb.watershed_name, wb.species, wb.released, wb.ph,
           wb.dissolved_oxygen, fm.farm_name, fm.irrigated_acres
    FROM watershed_biology AS wb
    JOIN mine_sites AS ms ON ms.site_id = wb.site_id
    JOIN farms AS fm ON fm.watershed_id = wb.watershed_id
    WHERE lower(ms.county) = lower($1)
    ORDER BY wb.watershed_name, wb.species;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION assess(county text) RETURNS SETOF refcursor AS $$
DECLARE
    hazards  refcursor := 'hazard_report';
    funding  refcursor := 'funding_report';
    recovery refcursor := 'recovery_report';
BEGIN
    IF county IS NULL OR btrim(county) = '' THEN
        RAISE EXCEPTION 'a county name is required for assessment';
    END IF;
    OPEN hazards FOR SELECT * FROM site_hazards(county);
    RETURN NEXT hazards;
    OPEN funding FOR SELECT * FROM funding_flow(county);
    RETURN NEXT funding;
    OPEN recovery FOR SELECT * FROM ecological_recovery(county);
    RETURN NEXT recovery;
END;
$$ LANGUAGE plpgsql;

BEGIN;
SELECT * FROM assess('silver bow');
FETCH ALL FROM hazard_report;
FETCH ALL FROM funding_report;
FETCH ALL FROM recovery_report;
COMMIT;

