      AND lower(ms.county) = lower($1)
    ORDER BY wb.watershed_name, wb.species;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION assess(county text) RETURNS SETOF refcursor AS $$
DECLARE
    hazards  refcursor := 'hazard_report';
    funding  refcursor := 'funding_report';
    recovery refcursor := 'recovery_report';
BEGIN
    IF county IS NULL OR btrim(county) = '' THEN
        RAISE EXCEPTION 'a county name is required for assessment';
    END IF;
    OPEN hazards FOR SELECT * FROM site_hazards(county);
    RETURN NEXT hazards;
    OPEN funding FOR SELECT * FROM funding_flow(county);
    RETURN NEXT funding;
    OPEN recovery FOR SELECT * FROM ecological_recovery(county);
    RETURN NEXT recovery;
END;
$$ LANGUAGE plpgsql;

BEGIN;
SELECT * FROM assess('silver bow');
FETCH ALL FROM hazard_report;
FETCH ALL FROM funding_report;
FETCH ALL FROM recovery_report;
COMMIT;

