                                      engineer_id INTEGER REFERENCES engineers, queued_on DATE, priority INTEGER);
CREATE TABLE transfers (transfer_id INTEGER PRIMARY KEY, cylinder_id INTEGER REFERENCES cylinders,
                        file_path TEXT, sample_rate_khz NUMERIC, transferred_on DATE);
CREATE TABLE donations (donation_id INTEGER PRIMARY KEY, cylinder_id INTEGER REFERENCES cylinders,
                        collector_id INTEGER REFERENCES collectors, auction_id INTEGER REFERENCES auction_catalogs, donated_on DATE);
CREATE TABLE phonographs (phonograph_id INTEGER PRIMARY KEY, model TEXT, build_year INTEGER, horn_type TEXT);
CREATE TABLE cylinder_phonographs (cylinder_id INTEGER REFERENCES cylinders, phonograph_id INTEGER REFERENCES phonographs,
                                   last_played_on DATE, PRIMARY KEY (cylinder_id, phonograph_id));
CREATE TABLE listening_stations (station_id INTEGER PRIMARY KEY, gallery TEXT, headphone_model TEXT);
CREATE TABLE station_playlist (station_id INTEGER REFERENCES listening_stations, transfer_id INTEGER REFERENCES transfers,
                               slot INTEGER, PRIMARY KEY (station_id, transfer_id));
CREATE TABLE playback_logs (log_id INTEGER PRIMARY KEY, station_id INTEGER REFERENCES listening_stations,
                            transfer_id INTEGER REFERENCES transfers, visitor_ticket TEXT, played_at TIMESTAMP);
CREATE TABLE podcast_episodes (episode_id INTEGER PRIMARY KEY, title TEXT, air_date DATE);
CREATE TABLE podcast_features (feature_id INTEGER PRIMARY KEY, episode_id INTEGER REFERENCES podcast_episodes,
                               transfer_id INTEGER REFERENCES transfers, segment_minutes NUMERIC);

CREATE VIEW cylinder_condition AS
SELECT c.cylinder_id, c.title, c.genre, c.manufacturer_id, a.name AS artist,
       cr.wax_integrity, cr.mould_present, cr.inspected_on
  FROM cylinders AS c
  JOIN artists AS a ON a.artist_id = c.artist_id
  JOIN condition_reports AS cr ON cr.cylinder_id = c.cylinder_id;

CREATE VIEW restoration_queue_v AS
SELECT cc.cylinder_id, cc.title, cc.genre, cc.artist, cc.wax_integrity, cc.mould_present, cc.inspected_on,
       e.name AS engineer, ra.priority, t.file_path, t.sample_rate_khz
  FROM cylinder_condition AS cc
  JOIN restoration_assignments AS ra ON ra.cylinder_id = cc.cylinder_id
  JOIN engineers AS e ON e.engineer_id = ra.engineer_id
  JOIN transfers AS t ON t.cylinder_id = cc.cylinder_id;

CREATE VIEW provenance_v AS
SELECT c.cylinder_id, c.title, c.genre, col.name AS donor, col.country, d.donated_on,
       ac.catalog_name, ac.auction_year, ac.lot_number, m.company AS maker
  FROM cylinders AS c
  JOIN donations AS d ON d.cylinder_id = c.cylinder_id
  JOIN collectors AS col ON col.collector_id = d.collector_id
  JOIN auction_catalogs AS ac ON ac.auction_id = d.auction_id
  JOIN manufacturers AS m ON m.manufacturer_id = c.manufacturer_id;

CREATE VIEW station_playback_v AS
SELECT t.transfer_id, t.file_path, c.title, c.genre, ls.gallery, ls.headphone_model, pl.visitor_ticket
  FROM transfers AS t
  JOIN cylinders AS c ON c.cylinder_id = t.cylinder_id
  JOIN station_playlist AS sp ON sp.transfer_id = t.transfer_id
  JOIN listening_stations AS ls ON ls.station_id = sp.station_id
  JOIN playback_logs AS pl ON pl.transfer_id = t.transfer_id AND pl.station_id = ls.station_id;

CREATE OR REPLACE FUNCTION catalog(genre TEXT) RETURNS SETOF REFCURSOR AS $$
DECLARE
    queue_cur   REFCURSOR := 'restoration_queue';
    prov_cur    REFCURSOR := 'artifact_provenance';
    listen_cur  REFCURSOR := 'visitor_listening';
BEGIN
    OPEN queue_cur FOR
        SELECT cylinder_id, title, artist, wax_integrity, mould_present, engineer,
               priority, file_path, sample_rate_khz
          FROM restoration_queue_v
         WHERE genre = catalog.genre
         ORDER BY priority, inspected_on;
    RETURN NEXT queue_cur;

    OPEN prov_cur FOR
        SELECT pv.cylinder_id, pv.title, pv.donor, pv.country, pv.donated_on, pv.catalog_name,
               pv.auction_year, pv.lot_number, pv.maker, p.model AS phonograph, p.horn_type, cp.last_played_on
          FROM provenance_v AS pv
          JOIN cylinder_phonographs AS cp ON cp.cylinder_id = pv.cylinder_id
          JOIN phonographs AS p ON p.phonograph_id = cp.phonograph_id
         WHERE pv.genre = catalog.genre
         ORDER BY pv.auction_year, pv.title;
    RETURN NEXT prov_cur;

    OPEN listen_cur FOR
        SELECT spv.title, spv.file_path, spv.gallery, spv.headphone_model,
               COUNT(DISTINCT spv.visitor_ticket) AS visitor_count,
               pe.title AS episode, pe.air_date, SUM(pf.segment_minutes) AS podcast_minutes
          FROM station_playback_v AS spv
          JOIN podcast_features AS pf ON pf.transfer_id = spv.transfer_id
          JOIN podcast_episodes AS pe ON pe.episode_id = pf.episode_id
         WHERE spv.genre = catalog.genre
         GROUP BY spv.title, spv.file_path, spv.gallery, spv.headphone_model, pe.title, pe.air_date
         ORDER BY visitor_count DESC;
    RETURN NEXT listen_cur;
END;
$$ LANGUAGE plpgsql;

BEGIN;
SELECT catalog('classical opera');
FETCH ALL IN restoration_queue;
FETCH ALL IN artifact_provenance;
FETCH ALL IN visitor_listening;
COMMIT;

