CREATE TABLE troupes (
    troupe_id   INT PRIMARY KEY,
    troupe_name VARCHAR(80) NOT NULL
);
CREATE TABLE jugglers (
    juggler_id   INT PRIMARY KEY,
    juggler_name VARCHAR(80) NOT NULL,
    troupe_id    INT REFERENCES troupes(troupe_id)
);
CREATE TABLE festivals (
    festival_id   INT PRIMARY KEY,
    festival_name VARCHAR(80) NOT NULL,
    location      VARCHAR(80) NOT NULL,
    festival_date DATE        NOT NULL
);
CREATE TABLE performances (
    performance_id   INT PRIMARY KEY,
    troupe_id        INT REFERENCES troupes(troupe_id),
    festival_id      INT REFERENCES festivals(festival_id),
    duration_minutes INT NOT NULL,
    performance_type VARCHAR(40) NOT NULL
);
CREATE TABLE sponsors (
    sponsor_id   INT PRIMARY KEY,
    company_name VARCHAR(80) NOT NULL
);
CREATE TABLE sponsorships (
    sponsorship_id      INT PRIMARY KEY,
    sponsor_id          INT REFERENCES sponsors(sponsor_id),
    festival_id         INT REFERENCES festivals(festival_id),
    contribution_amount DECIMAL(10,2) NOT NULL
);

CREATE VIEW juggler_rosters AS
SELECT j.juggler_id, j.juggler_name, t.troupe_id, t.troupe_name
FROM jugglers AS j
JOIN troupes AS t ON j.troupe_id = t.troupe_id;

CREATE VIEW troupe_appearances AS
SELECT p.performance_id, t.troupe_id, t.troupe_name, f.festival_id,
       f.festival_name, f.location, f.festival_date,
       p.duration_minutes, p.performance_type
FROM performances AS p
JOIN troupes AS t ON p.troupe_id = t.troupe_id
JOIN festivals AS f ON p.festival_id = f.festival_id;

CREATE VIEW festival_funding AS
SELECT sh.festival_id, s.company_name, sh.contribution_amount
FROM sponsorships AS sh
JOIN sponsors AS s ON sh.sponsor_id = s.sponsor_id;

DELIMITER $$

CREATE PROCEDURE report_appearances()
BEGIN
    SELECT r.juggler_name, r.troupe_name, a.location
    FROM juggler_rosters AS r
    JOIN troupe_appearances AS a ON r.troupe_id = a.troupe_id
    ORDER BY r.juggler_name, a.location;
END$$

CREATE PROCEDURE report_funding()
BEGIN
    SELECT a.festival_name, a.duration_minutes, g.company_name
    FROM troupe_appearances AS a
    JOIN festival_funding AS g ON a.festival_id = g.festival_id
    ORDER BY a.festival_name, g.company_name;
END$$

CREATE PROCEDURE report_billing()
BEGIN
    SELECT a.troupe_name, a.festival_date, a.performance_type, g.contribution_amount
    FROM troupe_appearances AS a
    JOIN festival_funding AS g ON a.festival_id = g.festival_id
    ORDER BY a.festival_date, a.troupe_name;
END$$

CREATE PROCEDURE summarize()
BEGIN
    CALL report_appearances();
    CALL report_funding();
    CALL report_billing();
END$$

DELIMITER ;

